-- Hungarian translation: quest_greeting (NPC/GO greeting text), quest_offer_reward, quest_request_items
-- Follow-up to rev_2026_08_11_20_hungarian_quest_translation.sql (quest_template). Same conventions:
-- proper nouns (NPC/place/faction names) kept English, prose translated, $-tokens preserved verbatim.
-- Batch 1: quest_greeting, IDs 234-1343 (type=0, creature greetings)

UPDATE quest_greeting SET Greeting='Aljas romlás terjedt el Westfallban. Míg én a lordaeroni csatatereken teljesítettem kötelességemet, ezeket a becsületes gazdaságokat elfoglalták, és útonállók, gyilkosok búvóhelyévé tették. A Népi Milíciának szüksége van a segítségedre.' WHERE ID=234 AND type=0;
UPDATE quest_greeting SET Greeting='Üdvözlünk szerény hajlékunkban! Mindig jó egy barátságos arcot látni. És micsoda erős karjaid vannak! A férjemmel mindig segítséget keresünk a gazdaság körül. Most, hogy a legtöbb rendes ember elment, nehéz munkabíró kezet találni.' WHERE ID=235 AND type=0;
UPDATE quest_greeting SET Greeting='Errefelé csak baj van. Próbáltam mondani annak a bolond Saldeannek, hogy menjen el, amíg még lehet, de hallani sem akar róla. De én nem vagyok bolond. Vernával elhúzunk innen, amint megjavítjuk ezt a szekeret.' WHERE ID=237 AND type=0;
UPDATE quest_greeting SET Greeting='Néha úgy érzem, egy nagy szürke felhő lóg felettünk az égen, csak úgy záporozza ránk a balszerencsét. Előbb elüldöztek a földünkről, most meg még Westfallból sem tudunk kijutni. Minden csupa zűrzavar. Tenni kellene valamit.' WHERE ID=238 AND type=0;
UPDATE quest_greeting SET Greeting='Kaland vár messzi és közeli tájakon,$bFurcsa, különös népekkel találkozom,$bDe ha kérdésed van hozzám, jól figyelj,$bElőbb egy egyszerű feladatot teljesíts!' WHERE ID=239 AND type=0;
UPDATE quest_greeting SET Greeting='Ah, épp elég nehéz itt rendet tartani anélkül is, hogy folyton új bajok bukkannának fel! Remélem, jó híreket hoztál, $n...' WHERE ID=240 AND type=0;
UPDATE quest_greeting SET Greeting='Hé, barátom. Remy vagyok. Keletről, Redridge-ből jöttem, üzletet keresek, üzletet keresek. Van valamid... van valamid?' WHERE ID=241 AND type=0;
UPDATE quest_greeting SET Greeting='Aha! Jó napot, jó napot, Mester $C! Gyere, ülj le, igyál valamit. Vállalkozó szellemű pillantást látok a szemedben, és úgy vélem, megéri majd az idődet, ha szóba állsz velem...' WHERE ID=253 AND type=0;
UPDATE quest_greeting SET Greeting='Üdv, polgár. Úgy nézel ki, mint akinek célja van - van dolgod a Stormwindi Hadsereggel?' WHERE ID=261 AND type=0;
UPDATE quest_greeting SET Greeting='Pihenj, $C. Ha csak átutazóban vagy, javaslom, maradj az utakon, és csak nappal utazz. Ha itt van dolgod Darkshire-ben, fontold meg, hogy felajánlod a képességeidet az Éjjeli Őrségnek. A tudásunk kétségtelen, de kevesen vagyunk.' WHERE ID=264 AND type=0;
UPDATE quest_greeting SET Greeting='Már jó ideje éreztem, hogy közeledsz, $n. Meg volt írva a csillagok állásában.' WHERE ID=265 AND type=0;
UPDATE quest_greeting SET Greeting='Üdvözöllek Darkshire városában. Daltry hivatalnok szolgálatodra. Segíthetek valamiben?' WHERE ID=267 AND type=0;
UPDATE quest_greeting SET Greeting='Helló, helló! Üdvözöllek a konyhámban, $g uram : hölgyem;! Itt készül a Scarlet Raven Tavern minden legfinomabb csemegéje. Ó, csak szagold ezt a csodás illatot!' WHERE ID=272 AND type=0;
UPDATE quest_greeting SET Greeting='Tartsd zárva az ajtót, $C. Sosem tudni, mikor jönnek megint erre a Sötét Lovasok.' WHERE ID=273 AND type=0;
UPDATE quest_greeting SET Greeting='Üdv, kedves $gúr:hölgy;. Foglalj helyet, egyél is, ha éhes vagy. Ne aggódj, ha elfoglaltnak tűnök a kézimunkámmal - figyelek rád...' WHERE ID=278 AND type=0;
UPDATE quest_greeting SET Greeting='Hä?!? Ó. Nem úgy nézel ki, mint egy Defias-tolvaj... vagy az Éjjeli Őrség tagja. Könyörülj egy szegény lelken, jó?' WHERE ID=288 AND type=0;
UPDATE quest_greeting SET Greeting='Eh? Üdvözöllek, ifjú $C. Bátor vagy, hogy idetaláltál a sok kóborló szörnnyel!$B$BNos, most hogy itt vagy, talán segíthetsz egy öreg remetének...' WHERE ID=289 AND type=0;
UPDATE quest_greeting SET Greeting='Üdv, utazó. A szemem talán gyenge, de egy mérföldről megérzem egy $c lépteit. Éveken át védtem Stormwindot büszkén, de mikor cserben hagyott a látásom, nyugdíjba kellett vonulnom.' WHERE ID=294 AND type=0;
UPDATE quest_greeting SET Greeting='Üdvözöllek az Azora Toronyban, ifjú $C. Theocritus vagyok.$B$BVan dolgod velem? Vagy... talán nekem van dolgom veled?' WHERE ID=313 AND type=0;
UPDATE quest_greeting SET Greeting='Nincs sok időm üres fecsegésre, $N. Meg kell építenem ezt a hidat, mielőtt jönnek az esők. Minden projektemet időben és a költségvetésen belül fejeztem be, és most nem fogok kicsúszni belőle.' WHERE ID=341 AND type=0;
UPDATE quest_greeting SET Greeting='Üdv, $N! Üdvözöllek szerény kertemben. Az időjárás remek volt mostanában. Reméljük, kitart a bő termésig.' WHERE ID=342 AND type=0;
UPDATE quest_greeting SET Greeting='Ki ez a $c, aki a Lakshire-i Bíróság elé áll a Stormwindi Királyságban? Add elő a dolgodat ebben a városban, $R. Az ork fenyegetés túl nagy ahhoz, hogy üres fecsegéssel vesztegessük az időt.' WHERE ID=344 AND type=0;
UPDATE quest_greeting SET Greeting='Üdv, $C. Ha üzleti ügyben jársz itt, szerezz magadnak egy sört, és beszélgessünk.' WHERE ID=381 AND type=0;
UPDATE quest_greeting SET Greeting='Nincs időm csevegni, polgár, de ha hajlandó vagy segíteni nekünk az orkok ellen, akkor találok neked feladatot.' WHERE ID=382 AND type=0;
UPDATE quest_greeting SET Greeting='Ne ijedj meg, $r. Régen eltávoztam már erről a földről, de nem áll szándékomban ártani a fajtádnak. Túl sok halált láttam életemben. Most már csak a békét kívánom. Talán segíthetsz az ügyemben.' WHERE ID=392 AND type=0;
UPDATE quest_greeting SET Greeting='Hé, $Gcimbora:asszonyom;, nem adnál egy kezet valamiben? Igazán nagy bajban vagyok...' WHERE ID=415 AND type=0;
UPDATE quest_greeting SET Greeting='Üdv, $C. Rossz időket élünk, barátom, mert városunkat ostrom alatt tartják! A Blackrock orkok Stonewatch Keepből támadnak, a Shadowhide-ok az Ilgalar-torony fölött lebegnek, a Redridge-i gnollfalka pedig erőre kap. Remélem, nem üdülni jöttél...' WHERE ID=464 AND type=0;
UPDATE quest_greeting SET Greeting='Üdvözöllek, $c. Ha Kurzen ezredes barátja vagy, ott vágatlak le, ahol állsz! De ha segíteni jöttél, hallgass meg...' WHERE ID=469 AND type=0;
UPDATE quest_greeting SET Greeting='Sötét idők jöttek el, $c... Hamarosan mindent elveszítünk... Amikor a Fény mindenkit elhagy, kivéve azokat, akik valóban a Fény útját járják.' WHERE ID=633 AND type=0;
UPDATE quest_greeting SET Greeting='Tolvajok voltak mindenütt! $b$bSzörnyű volt. Ránk omlott a barlang. Azt hiszem, a bányavállalat összes embere meghalt, a bátyám, a művezető is.' WHERE ID=656 AND type=0;
UPDATE quest_greeting SET Greeting='Üdvözöllek. Mi dolgod van a Carevin családdal? A Carevineket akarod segíteni a harcukban az élőholtak ellen?' WHERE ID=661 AND type=0;
UPDATE quest_greeting SET Greeting='A Carevin család a győzelemért harcol a Fény alatt. Az én feladatom a Fény szolgálatában, hogy az életemet adjam a harcukban az élőholtak ellen. Carevin mester megbízott, hogy irtsam ki az aljas worgeneket Duskwoodban. Talán segítenél nekem?' WHERE ID=663 AND type=0;
UPDATE quest_greeting SET Greeting='Üdvözöllek, $c! Szép nap ez a vadászathoz, nem gondolod? Nekem magamnak elég jó szerencsém volt a vadkanokkal. Talán te is kipróbálnád?' WHERE ID=714 AND type=0;
UPDATE quest_greeting SET Greeting='Megint egy szép nap a dzsungelben! Remek vadászat lesz, ezt érzem. Amint Barnil végzett a fegyverek tisztításával, mélyen a kúszónövények közé viszem a vadászcsapatot. Nem is olyan rossz módja ez annak, hogy egy öreg háborús veterán töltse a nyugdíjas éveit, mi?' WHERE ID=715 AND type=0;
UPDATE quest_greeting SET Greeting='Vigyázz, hova lépsz errefelé, $Gfiam:lányom;. Lehet, hogy nem tartozol az alakulatunkhoz, de ez nem jelenti azt, hogy ne kapnál botütést, ha kilógsz a sorból!' WHERE ID=733 AND type=0;
UPDATE quest_greeting SET Greeting='Nos, helló. Úgy tűnik, nem lennél ellene, ha egy kis pénzt kereshetnél, hm? Látom a szemedben. Mogul Kebok vagyok, az azerothi műveletek felügyelője, és ha gazdagságot keresel, talán tudok megegyezni veled.' WHERE ID=737 AND type=0;
UPDATE quest_greeting SET Greeting='$C, eh? Krazek vagyok, Revilgaz báró titkára. Mindent tudok, ami ebben a dzsungelben és azon túl történik. Talán érdekelne az olaj aktuális ára Ratchetben? Nem? Munkát keresel esetleg? Abban tudok segíteni.' WHERE ID=773 AND type=0;
UPDATE quest_greeting SET Greeting='Üdvözöllek, $g fiam : lányom;. Grelin Whitebeard vagyok. Azért vagyok itt, hogy megvizsgáljam a Coldridge-völgyben egyre szaporodó trollok jelentette veszélyt. Mit találtam? Kissé aggasztó...' WHERE ID=786 AND type=0;
UPDATE quest_greeting SET Greeting='Helló, $c. Rendes körülmények között kint őrjáratoznék, vigyázva Stormwind népére, de a stormwindi őrök nagy része más földeken harcol. Így hát itt vagyok, helyettesként vérdíjakat kínálva, pedig inkább járőröznék...' WHERE ID=823 AND type=0;
UPDATE quest_greeting SET Greeting='Milyen ügyben jöttél a Lakeshire-i Bíróság és a tiszteletreméltó Solomon bíró elé?' WHERE ID=900 AND type=0;
UPDATE quest_greeting SET Greeting='Ha egy dolgot megtanított az idő, az az, hogy sosincs unalmas feladat. A Thandol Span védelmének könnyű dolognak kellett volna lennie. De mivel a hadsereg zöme a Szövetség oldalán harcol, itt túlerőbe kerültek ellenünk, és Dun Modr elesett.' WHERE ID=1071 AND type=0;
UPDATE quest_greeting SET Greeting='Üdvözöllek, $n.' WHERE ID=1092 AND type=0;
UPDATE quest_greeting SET Greeting='Tudod, mindig kutató akartam lenni, de számokra való érzékkel születtem, és a céh úgy döntött, jobban illek a könyvelésbe! Tanulás, tanulás, ifjúságom minden napján...' WHERE ID=1105 AND type=0;
UPDATE quest_greeting SET Greeting='Nos, helló, polgár. A nevem Bluntnose, pontosabban Bluntnose bíró. Az én feladatom Thelsamar jólétének felügyelete, és hidd el, mindig jól jön egy újabb erős kéz errefelé!' WHERE ID=1139 AND type=0;
UPDATE quest_greeting SET Greeting='Ha az étel miatt jöttél, akkor üdvözöllek! Ennél finomabb vacsorát nem találsz egész Stormwindban... sőt, egész Azerothban sem!$B$BHa más ügyben jársz itt, kérlek, légy rövid. Egy tucat étel készül éppen, mindegyikre figyelnem kell.' WHERE ID=1141 AND type=0;
UPDATE quest_greeting SET Greeting='Ha elviselsz olyan történeteket, amitől megreccsen a gerinced és bevizesedik az alsóneműd, akkor tölts magadnak egy italt, és ülj le egy kicsit...' WHERE ID=1239 AND type=0;
UPDATE quest_greeting SET Greeting='Troggok! Esküszöm, az istenek csak azért tették őket erre a földre, hogy engem kínozzanak! Négy hüvelykkel mélyebbre ások a bányában, aztán két lábbal hátrébb szorulok a troggok miatt!' WHERE ID=1254 AND type=0;
UPDATE quest_greeting SET Greeting='Üdvözöllek a Thunderbrew Főzdében, amelyet drága öreg apám, Arkilus Thunderbrew alapított. Én tartom életben a helyet, mióta a bátyám, Grimbooze néhány szüret óta részeg ködben eltűnt.' WHERE ID=1267 AND type=0;
UPDATE quest_greeting SET Greeting='Üdvözöllek, $n.' WHERE ID=1284 AND type=0;
UPDATE quest_greeting SET Greeting='Nocsak, ha ez nem egy fiatal, harcra kész $c, akit kétségkívül a csatatéri hőstetteimről szóló mesék vonzottak ide!$B$BMost nincs idő történetekre, mert nagy, fontos tettekre van szükség! Szóval ha dicsőséget keresel, ma rád mosolyog a szerencse...' WHERE ID=1343 AND type=0;
-- Batch 2: quest_greeting, IDs 1344-2981 (type=0, creature greetings)

UPDATE quest_greeting SET Greeting='Bár most lassú időszakon megyünk keresztül ezekben a romokban, biztos vagyok benne, hogy nem tart sokáig. De addig is jól jönne valaki, mint te. Segítenél a Törp Felfedezők Céhének?' WHERE ID=1344 AND type=0;
UPDATE quest_greeting SET Greeting='Épp egy nagyon fontos feladat közepén vagyok. Kutatói ügy. Hacsak nincs valami hasonlóan fontos mondanivalód, amit kétlek, akkor kérlek, bocsáss meg.' WHERE ID=1356 AND type=0;
UPDATE quest_greeting SET Greeting='Átkozott legyen a Sörfőzők Ligája! Ők hozzáférnek minden legjobb alapanyaghoz, míg mi itt ragadtunk gabonáért és komlóért kutakodva!$B$BSzívesen adnék nekik egy kis keserű ízű igazságszolgáltatást...' WHERE ID=1374 AND type=0;
UPDATE quest_greeting SET Greeting='Egy gőztankot vezetni nem mindenkinek való. Vasmarok és acélidegek kellenek hozzá... szerencsére nekem mindkettő megvan! És neked? Milyen az állóképességed? Be akarod bizonyítani nekem?' WHERE ID=1377 AND type=0;
UPDATE quest_greeting SET Greeting='Üdvözöllek, $n.' WHERE ID=1428 AND type=0;
UPDATE quest_greeting SET Greeting='Nem találsz nagyobb tudástárat, mint a Stormwindi Királyi Könyvtárban!' WHERE ID=1440 AND type=0;
UPDATE quest_greeting SET Greeting='Üdvözöllek, $C. Légy óvatos, ha kelet felé utazol a The Bulwark irányába. A friss felderítési jelentések fokozott Csapás-aktivitást jeleznek arrafelé, ezért légy körültekintő.' WHERE ID=1495 AND type=0;
UPDATE quest_greeting SET Greeting='Ó, te ott! Van feladatom számodra, és nincs időm elmagyarázni, mennyire lényegesek. Figyelj jól.' WHERE ID=1499 AND type=0;
UPDATE quest_greeting SET Greeting='Remélem, jól vagy, mindent egybevetve.$B$BÜlj le egy kicsit, és hallgasd meg a történetemet. Tragédia, természetesen, de remélem, bosszúval végződik majd!' WHERE ID=1500 AND type=0;
UPDATE quest_greeting SET Greeting='A Skarlát Kereszteslovagok betolakodnak a hazánkba. Az ostoba fanatikusok nem veszik észre, hogy a Sötét Úrnő hű szolgái majd gondoskodnak a végzetükről.' WHERE ID=1515 AND type=0;
UPDATE quest_greeting SET Greeting='A Sötét Úrnő kihívást intézett hozzánk. Rajtunk múlik, hogy megfeleljünk neki.' WHERE ID=1518 AND type=0;
UPDATE quest_greeting SET Greeting='Üdvözöllek, Baros Alexston vagyok, Stormwind városépítésze.' WHERE ID=1646 AND type=0;
UPDATE quest_greeting SET Greeting='Ide nézz, te haszontalan...! Ha valami hasznosat akarsz csinálni, figyelj gyorsan!' WHERE ID=1719 AND type=0;
UPDATE quest_greeting SET Greeting='Bolvar Fordragon vagyok, Stormwind Főura.' WHERE ID=1748 AND type=0;
UPDATE quest_greeting SET Greeting='Annyi időt töltöttünk menekülésben, hogy a békés idők emlékei egyre távolabbra tűnnek.' WHERE ID=1776 AND type=0;
UPDATE quest_greeting SET Greeting='A Sötét Úrnő kihívást intézett hozzánk. Most a Királyi Alkimista Társaságon múlik, hogy kifejlesszen egy új pestist. Térdre kényszerítjük Arthast és nyomorult seregét.' WHERE ID=1937 AND type=0;
UPDATE quest_greeting SET Greeting='A Kirin Tor nem hallgatott a figyelmeztetéseimre! A Szövetség csak látszat. Arugal egy meggondolatlan bolond.' WHERE ID=1938 AND type=0;
UPDATE quest_greeting SET Greeting='A bátyámmal létfontosságú küldetésen vagyunk, de itt rekedtünk ebben a tanyaházban. A Halálleselkedőknek szükségük van a segítségedre.' WHERE ID=1950 AND type=0;
UPDATE quest_greeting SET Greeting='Üdv, $C. Ha itt vagy, akkor biztosan tudod, hogy Silverpine tele van az ellenségeinkkel. A túléléshez az Elhagyatottaknak vissza kell szorítaniuk őket!' WHERE ID=1952 AND type=0;
UPDATE quest_greeting SET Greeting='Közszolgálatra neveltek és képeztek ki. A nép képviselőjeként. Az én tehetségem nem a fegyverekben vagy a kézművességben rejlik, hanem a szavakban és a meggyőzésben.' WHERE ID=1977 AND type=0;
UPDATE quest_greeting SET Greeting='A Királyi Alkimista Társaság meghallja a Sötét Úrnő hívását, hogy felfedezze az Új Pestist, és egyszer s mindenkorra kiűzze Arthast és pogány Csapás-hadseregét a világból.' WHERE ID=2055 AND type=0;
UPDATE quest_greeting SET Greeting='Teldrassil megteremtése nagyszerű tett volt, de most a világnak változnia kell, hogy visszanyerje egyensúlyát.' WHERE ID=2080 AND type=0;
UPDATE quest_greeting SET Greeting='Üdvözöllek, $n.' WHERE ID=2086 AND type=0;
UPDATE quest_greeting SET Greeting='Az ostromgépek minden pilóta büszkeségei!' WHERE ID=2092 AND type=0;
UPDATE quest_greeting SET Greeting='Üdvözöllek, $c. Épp szorult helyzetben vagyok, nagyon fogytán vannak a bőreim.' WHERE ID=2094 AND type=0;
UPDATE quest_greeting SET Greeting='Információ... A felderítőinkkel és ügynökeinkkel az információáramlást irányítjuk Lordaeronban. A Csapás mozgásai, birtokaik, mind az éber szemünk alatt vannak...' WHERE ID=2121 AND type=0;
UPDATE quest_greeting SET Greeting='Hogy szolgáljuk a Sötét Úrnőt és Varimathrast, előre kell tolnunk a frontot az emberi fertőzés ellen.' WHERE ID=2215 AND type=0;
UPDATE quest_greeting SET Greeting='Már egészen közel járunk az Új Pestis kifejlesztéséhez, amelyet Sötét Úrnőnk oly hevesen kíván.' WHERE ID=2216 AND type=0;
UPDATE quest_greeting SET Greeting='Ha belegondolok, a hely, ahol a Hadúr született és felnőtt, ilyen közel van.' WHERE ID=2229 AND type=0;
UPDATE quest_greeting SET Greeting='Remélem, dolgozni jöttél, $C. Sok tennivalónk van, és a Horda, a Syndicate meg az ogrék nem fognak segíteni nekünk.' WHERE ID=2263 AND type=0;
UPDATE quest_greeting SET Greeting='Amikor először ajánlották fel nekem a Southshore-i bíró címet, boldog voltam, hogy ilyen korán elértem ezt a pozíciót a pályafutásomban.$B$BDe most, hogy itt vagyok, azon tűnődöm, jobban jártam volna-e, ha Stormwindban tologatom a papírokat.' WHERE ID=2276 AND type=0;
UPDATE quest_greeting SET Greeting='Rengeteg dolgom van. Azért jöttél, hogy segíts a kutatásaimban?' WHERE ID=2277 AND type=0;
UPDATE quest_greeting SET Greeting='A családom büszkélkedhet a legfinomabb ékszer- és műkincsgyűjteménnyel Stormwind minden nemese közül!$B$BÉs mindig szeretnénk növelni a gyűjteményünk méretét...' WHERE ID=2285 AND type=0;
UPDATE quest_greeting SET Greeting='Ah, érezd a finom sós levegőt! Mindig jó visszatérni Booty Bay-be, a hazai kikötőnkbe.' WHERE ID=2487 AND type=0;
UPDATE quest_greeting SET Greeting='Eh? Van dolgod Nimboyával?' WHERE ID=2497 AND type=0;
UPDATE quest_greeting SET Greeting='Mi mi?!? Mindannyiunknak profitot kell termelnünk... és ezt nem tétlenkedve érjük el.' WHERE ID=2498 AND type=0;
UPDATE quest_greeting SET Greeting='Hé! Egy körre jöttél a kockajátékhoz?' WHERE ID=2501 AND type=0;
UPDATE quest_greeting SET Greeting='Helló! A szellemek azt mondják, azért vagy itt, hogy segíts a főnökömnek. Hangosan mondják, bizony.' WHERE ID=2519 AND type=0;
UPDATE quest_greeting SET Greeting='Yarrr... jobb, ha nem vesztegeted az időmet, cimbora!' WHERE ID=2546 AND type=0;
UPDATE quest_greeting SET Greeting='Mi, itt Refuge Pointe-nál, tartjuk Stromgarde egyik utolsó megmaradt területfoltját az Arathi-felföldön. És egyre veszítünk teret...$B$BHa mondanivalód van számomra, remélem, jó hírek.' WHERE ID=2700 AND type=0;
UPDATE quest_greeting SET Greeting='A Hadúrnak köszönhetően még itt, egykori börtönünk romjai közt is marad remény, és a Horda újra felemelkedik.' WHERE ID=2706 AND type=0;
UPDATE quest_greeting SET Greeting='Hátrébb! Maradj hátra! Tele van a zsákom robbanóporral, és nem félek használni! Mindannyiunkat felrobbantok!$B$BÓ, mindegy. Azt hittem, valaki más vagy...' WHERE ID=2785 AND type=0;
UPDATE quest_greeting SET Greeting='Üdvözöllek Bonegrip Rúnák és Végzetek boltjában, $c. Nézelődhetsz, de ne érj hozzá semmihez.$B$BAz itteni tudás egy része nem a... beavatatlanoknak való.' WHERE ID=2786 AND type=0;
