-- quest_offer_reward.RewardText (reward-window turn-in text). Batch 1: quest IDs 2-57.

UPDATE quest_offer_reward SET RewardText='Igazán lenyűgöző, $N... Sharptalon karmát nem lehetett könnyű megszerezni! Az Ashenvale-i Vadászat jól alakul számodra!$B$BSharptalon régóta rettegésben tartotta a favágótáborok robotosait, akik megpróbáltak errefelé eljutni Splintertree Postba. Ha híre megy, hogy te ejtetted el a fenevadat, kétségkívül sok lelkesítő dal fog szólni bátorságodról a tábortüzeknél és fűrésztelepeken szerte Ashenvale-ben!' WHERE ID=2;
UPDATE quest_offer_reward SET RewardText='Rákpogácsára van szükséged, ugye? Nos, talán tudok sütni párat neked...' WHERE ID=5;
UPDATE quest_offer_reward SET RewardText='Hah - elkaptad! Nagy szolgálatot tettél Elwynnnek, és szép vérdíjat érdemeltél ki!' WHERE ID=6;
UPDATE quest_offer_reward SET RewardText='Szép munka, polgár. Azok a koboldok tolvajok és gyávák, de nagy számban veszélyt jelentenek ránk. Stormwind embereinek pedig nincs szüksége még egy fenyegetésre.$B$BAmiért legyőzted őket, hálás vagyok.' WHERE ID=7;
UPDATE quest_offer_reward SET RewardText='Ó? Egy levél? Csodás hír! Vártam már a híreket drága öreg édesanyámtól Deathknellből. Micsoda szent asszony. Vajon hogy boldogul.$B$BMi az? Túl vidám? Nem veszed be, mi?$B$BNos, akkor tűnés... valójában nem a te dolgod, hogy kitől jött a levél. Menj csak! Tűnés!$B$BGyere vissza, ha van némi pénzed elkölteni... naplopó.$B$BLegközelebb még azzal jössz, hogy pihenni akarsz egy hosszú kalandozás után, vagy valami hasonló hülyeséggel.' WHERE ID=8;
UPDATE quest_offer_reward SET RewardText='Szép munka, barátom. Jól kiérdemelted a fizetségedet. Ki tudja, talán Westfall egyszer újra virágzik majd.' WHERE ID=9;
UPDATE quest_offer_reward SET RewardText='Jó goblin volt az ifjú Scrimshank. Reméljük, halála nem volt hiábavaló, azok után, amit fel tudott jegyezni a földmérő eszközeivel.$B$BÚgy tűnik, komoly helyzettel állunk szemben ezekkel a bogarakkal. Túlságosan is ravaszak a saját érdekükben, és az eddigi kutatásaink arra utalnak, hogy talán egy harmadik fél irányítása alatt állnak! Ha ez így van, az nemcsak Gadgetzannek, hanem az egész sivatagnak rossz előjel!' WHERE ID=10;
UPDATE quest_offer_reward SET RewardText='Látom, szorgoskodtál! Köszönetünket fejezzük ki, $N.' WHERE ID=11;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N. Felderítőm szemtanúja volt vitéz tetteidnek. Eddig igazán jól bizonyítasz.' WHERE ID=12;
UPDATE quest_offer_reward SET RewardText='Bátor tetteid eddig igazolták, mennyit érsz a Népi Milíciának.' WHERE ID=13;
UPDATE quest_offer_reward SET RewardText='Amikor elhagytam Lordaeron beszennyezett földjeit, komor állapotokat találtam itthon, a szülőföldemen. De Westfall számára még van remény. Csatabeli vitézséged bizonyítja, hogy becsülettel szolgálod ügyünket. Nagy büszkeséggel avatlak be a Népi Milíciába. Ragyogjon rád a Fény.' WHERE ID=14;
UPDATE quest_offer_reward SET RewardText='Nem tetszik, amit hallok, ennyi kobold a bányánkban. Ebből nem lehet jó vége. Tessék, fogadd el ezt fizetségül, és ha készen állsz, keress meg újra. Szeretném, ha visszamennél a bányákba még egyszer...' WHERE ID=15;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N! És gyere vissza, ha megint kereskedni szeretnél.' WHERE ID=16;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N, ismét bebizonyítottad, mit érsz! A kupakok igazán érdekes tanulmány tárgyai lesznek!$B$BÉs most, ahogy ígértem, kóstolj bele az egyik erősebb erősítő főzetembe a személyes készletemből...$B$BHa ügyes alkimista vagy, talán további üzletet is köthetünk. Mindenesetre köszönöm a segítségedet!' WHERE ID=17;
UPDATE quest_offer_reward SET RewardText='Látom, visszahoztad a fejkendőket. A Stormwindi Hadsereg hálás a segítségedért.' WHERE ID=18;
UPDATE quest_offer_reward SET RewardText='Tharil''zun kegyetlen, ravasz ork volt. Szép munka - biztos vagyok benne, hogy nem adta könnyen magát. Itt a jutalmad, $N.' WHERE ID=19;
UPDATE quest_offer_reward SET RewardText='Ez így sokkal kevesebb orkkal kell törődnünk, köszönöm.' WHERE ID=20;
UPDATE quest_offer_reward SET RewardText='Ismét kiérdemelted a tiszteletemet, és a Stormwindi Hadsereg háláját. Talán még mindig maradtak koboldok a bányában, de másokat is felsorakoztatok majd ellenük. Van még feladatunk számodra.' WHERE ID=21;
UPDATE quest_offer_reward SET RewardText='Ezek tökéletesek, $N! Nagyon köszönöm. Saldean gazdával ma este nagy lakomát csapunk. És itt van neked is valami kis apróság a kemény munkádért. Csak nem hitted, hogy hagynám, hogy egy ilyen $c éhen maradjon?' WHERE ID=22;
UPDATE quest_offer_reward SET RewardText='Ó, Ursangous mancsa! Lenyűgöző a tudásod, $c; sok gyilkosság fűződik a nevéhez. A mancsán lévő félhold kétségkívül annak jele, hogy az Ashenvale-ben ólálkodó éjelfek idomították. Ursangous... az egyik leghatalmasabb medve volt, amit errefelé találni. Hogy le tudtál győzni egy ilyen fenevadat, akaraterődről és eltökéltségedről tanúskodik.$b$bŐseid büszkék lennének rád!' WHERE ID=23;
UPDATE quest_offer_reward SET RewardText='Győzelem $N számára az Ashenvale-i Vadászatban! Szép munka - Shadumbra feje méltó trófea egy ilyen lenyűgöző küzdelemért, kétségkívül.$b$bShadumbra vadsága jól ismert volt errefelé az őrhelyen. Bármilyen nyugati út, különösen gyalog a Zoram-part felé, veszélyes volt emiatt a tigris miatt. Neked köszönhetően ez a veszély most elmúlt.' WHERE ID=24;
UPDATE quest_offer_reward SET RewardText='Ja, hallottam, hogy valaki felforgatta azt a tavat, mint egy porördög a Barrensben. Úgy hangzik, talán fel tudnánk állítani ott egy megfigyelőpontot, hogy szemmel tartsuk a szövetséges barátainkat. Persze, ha titokban tudjuk tartani...$B$BÚgy tűnik, mégiscsak hasznosnak bizonyultál; a szállítmányoknak innen Stonetalonig könnyebb dolguk lesz. Fogd ezt - kiérdemelted.' WHERE ID=25;
UPDATE quest_offer_reward SET RewardText='Üdvözlet, ifjú $c; eljött az idő, hogy megismerd a vízi alakunkat. Ez az az alak, amellyel szabadon és korlátlanul mozoghatsz a vízben. Hasznos eszköznek és áldásnak fogod találni ezt a képességet... de ki kell érdemelni, mielőtt elsajátítanád.$B$BKét próbát kell legyőznöd. Az első a víz alatti, nyomás alatti munkabírásodat teszi próbára. A második az eltökéltségedet, hogy megértsd magának az alaknak a lényegét.$B$BÁllj készen, mert eljött a próbatétel ideje.' WHERE ID=26;
UPDATE quest_offer_reward SET RewardText='Üdvözlet, ifjú $c; eljött az idő, hogy megismerd a vízi alakunkat. Ez az az alak, amellyel szabadon és korlátlanul mozoghatsz a vízben. Hasznos eszköznek és áldásnak fogod találni ezt a képességet... de ki kell érdemelni, mielőtt elsajátítanád.$B$BKét próbát kell legyőznöd. Az első a víz alatti, nyomás alatti munkabírásodat teszi próbára. A második az eltökéltségedet, hogy megértsd magának az alaknak a lényegét.$B$BÁllj készen, mert eljött a próbatétel ideje.' WHERE ID=27;
UPDATE quest_offer_reward SET RewardText='Nos hát, úgy tűnik, egy újabb druida sikeresen teljesítette a Tó Próbáját! Szép munka, ifjú barátom - szép munka.$B$BAhogy mondtam, Tajarri vagyok. Kötelességem és kiváltságom, hogy Moonglade, pontosabban ez a szentély őrzőjeként szolgáljak. Remulos Őrző vezeti a Cenarion Kört a természet és az egyensúly megőrzésében, és ez a szentély is ennek maradandó emléke. Az itteni csecsebecse használata is ennek a helynek a Körön belüli fontosságára utal.' WHERE ID=28;
UPDATE quest_offer_reward SET RewardText='Nos hát, úgy tűnik, egy újabb druida sikeresen teljesítette a Tó Próbáját! Szép munka, ifjú barátom - szép munka.$B$BAhogy mondtam, Tajarri vagyok. Kötelességem és kiváltságom, hogy Moonglade, pontosabban ez a szentély őrzőjeként szolgáljak. Remulos Őrző vezeti a Cenarion Kört a természet és az egyensúly megőrzésében, és ez a szentély is ennek maradandó emléke. Az itteni csecsebecse használata is ennek a helynek a Körön belüli fontosságára utal.' WHERE ID=29;
UPDATE quest_offer_reward SET RewardText='Teljesítetted a Tengerioroszlán Próbáját, $N - gratulálok.$B$BA medál megszerzésének minden feladata megmutatja, hogy mind a fürgeség, mind az állóképesség szükséges ahhoz, hogy összhangban cselekedj a víz alatt kívánt dolgokkal. Egyik sem létezhet a másik nélkül, és egyik sem valósítható meg anélkül, hogy hajlandó lennél magadévá tenni a tengerioroszlán alakját.$B$BJegyezd meg jól ezeket a leckéket, és számíts rájuk, ha megszerezted a vízi alakodat.' WHERE ID=30;
UPDATE quest_offer_reward SET RewardText='Igazán lenyűgöző, $N. Őseid elégedettek lennének a fejlődéseddel! Készen állsz, hogy megtanuld a vízi alakodat, és örömömre szolgál, hogy megtaníthatom neked.$B$BEmellett, a két próbában elért teljesítményed elismeréseként, neked adom ezt a tárgyat. Remélem, szívesen fogadod majd felszerelésedbe, mint a természet védelmezője és az egyensúly őrzője.' WHERE ID=31;
UPDATE quest_offer_reward SET RewardText='Ez a jelentés... már volt dolgom ezekkel a fenevadakkal. Fizzledowser bölcsen tette, hogy elküldte ezt, téged pedig hozzám.$b$bEzek a lények gyorsan felemésztik a Tanaris-sivatagot; nem kevesebbek, mint az egyik legnagyobb fenyegetés, amivel valaha szembe fogunk nézni. Jegyezd meg ezt a nevet, $N: silithid. Az itt említett rovarok silithidek, és egyike a legnagyobb veszélyeknek, amivel a Horda és a Szövetség egyaránt szembenéz.$b$bBárcsak elég okosak lettünk volna, hogy ezt korábban észrevegyük.' WHERE ID=32;
UPDATE quest_offer_reward SET RewardText='Szorgoskodtál! Alig várom, hogy megfőzzem azt a farkashúst...$b$bVan itt néhány dolog, ami érdekelhet - válassz!' WHERE ID=33;
UPDATE quest_offer_reward SET RewardText='Végre nyugalomra tért a fenyegetés! Köszönöm, $N, nagy szolgálatot tettél nekem. A kert idén teljes pompájában fog virágozni!' WHERE ID=34;
UPDATE quest_offer_reward SET RewardText='Igen, murlocok telepedtek le Kelet-Elwynn patakjai körül. Nem tudjuk, miért vannak itt, de agresszívak, és legalább félig intelligensek.' WHERE ID=35;
UPDATE quest_offer_reward SET RewardText='Az a Verna mindig is olyan édes teremtés volt. Hiányozni fog itt Westfallban, de köztünk szólva, szíve mélyén városi lány, és Stormwind pont neki való lesz. De elég a pletykából! Most már megfőzhetjük a Westfall Stew-t!' WHERE ID=36;
UPDATE quest_offer_reward SET RewardText='Bár sok mindent elvettek a holttestről, a közelben egy medál hever, rávésve: „Malakai Stone gyalogos”.' WHERE ID=37;
UPDATE quest_offer_reward SET RewardText='Az az okra szépen besűríti majd ezt a levest! Most már csak hozzáadjuk a rostos keselyűhúst, néhány murlocszemet és azokat a finom vadkanorrokat. És kész is vagyunk! A segítségedért, $N, szeretném, ha elvinnéd a mai első adag Westfall Stew-t!' WHERE ID=38;
UPDATE quest_offer_reward SET RewardText='Hmm, ez a hír aggasztó. A védelmünk már így is túl van feszítve, és hogy elvesztettük Rolfot és Malakait azoknak a murlocoknak, csak rontott a helyzetünkön.$B$BHa nem javul a helyzet, hét végére harcok törnek ki Goldshire-ban!' WHERE ID=39;
UPDATE quest_offer_reward SET RewardText='Igen, beszéltem Remyvel. Kereskedőként tisztelem, bár a keleti murlocokról szóló jelentések legjobb esetben is homályosak.$B$BAz aggodalmaidat feljegyeztem, de amíg nem kapok katonai jelentést a murloc-fenyegetésről, nem engedhetjük meg magunknak, hogy több csapatot küldjünk keletre.' WHERE ID=40;
UPDATE quest_offer_reward SET RewardText='A holttest nyaka körül egy fém medált találsz, rávésve: „Rolf Hartford gyalogos”.' WHERE ID=45;
UPDATE quest_offer_reward SET RewardText='Megvannak az uszonyok? Remek! Dughan marsall aggódik a kelet-elwynni murloc-helyzet miatt, és szeretném megnyugtatni, hogy kezd kontroll alá kerülni.$b$bA tetteid segítettek ebben.' WHERE ID=46;
UPDATE quest_offer_reward SET RewardText='Köszönöm a port, $N. Itt a pénzed, és... itt egy jelvény néhány üzlettársamtól. Talán hasznosnak találod majd... hasznosnak.' WHERE ID=47;
UPDATE quest_offer_reward SET RewardText='Csuklás! Ho ho!' WHERE ID=48;
UPDATE quest_offer_reward SET RewardText='Csuklás! Ho ho!' WHERE ID=49;
UPDATE quest_offer_reward SET RewardText='Csuklás! Ho ho!' WHERE ID=50;
UPDATE quest_offer_reward SET RewardText='Csuklás! Ho ho!' WHERE ID=51;
UPDATE quest_offer_reward SET RewardText='Nagyon köszönöm a segítséget, $N. Valaminek az erdőben ilyen vakmerővé kell tennie ezeket az állatokat.$B$BBármi is az, remélem, ott is marad.' WHERE ID=52;
UPDATE quest_offer_reward SET RewardText='Hordóban érlelve, szénen átszűrve,$BÁtjár az ajkaidon, egyenest a lelkedbe.$BSzóval igyunk hát, egy pohárköszöntőt rád,$BÉs rám is, amíg itt vagyunk, Grimbooze Thunderbrew-ra!' WHERE ID=53;
UPDATE quest_offer_reward SET RewardText='Nos, itt az áll, hogy megkaptad a megbízott helyettes rangot a Stormwindi Marsalloknál. Gratulálok.$b$bÉs sok szerencsét - Elwynn biztonságban tartása nem piknik... hiszen a hadsereg nagy része isten tudja mit csinál isten tudja melyik nemesnek!$b$bNehéz nyomon követni a politikát ezekben a sötét időkben...' WHERE ID=54;
UPDATE quest_offer_reward SET RewardText='Morbent Felt legyőzték. A sötét lovasok még szabadon vannak, de egy kis darabja annak, amiben minden reményem ellenére reménykedtem, valóra vált.$b$bLehetetlent tettél, és tetteid örökké élni fognak Duskwood legendáiban.$b$bMenj, $N. És talán, egy napon, a sors visszahoz hozzám...' WHERE ID=55;
UPDATE quest_offer_reward SET RewardText='Kiváló, $N. Darkshire népének tett szolgálatodért jutalmat érdemelsz.' WHERE ID=56;
UPDATE quest_offer_reward SET RewardText='Darkshire népe köszöni, $N. Bebizonyítottad, hogy az Éjjeli Őrség nagyszerű szövetségese vagy.' WHERE ID=57;
-- quest_offer_reward.RewardText. Batch 2: quest IDs 58-109.

UPDATE quest_offer_reward SET RewardText='Darkshire népe nevében, és mint az Éjjeli Őrség vezetője, köszönöm neked, $N, a bátorságodat és elhivatottságodat. Ragyogjon rád a Fény utaidon.' WHERE ID=58;
UPDATE quest_offer_reward SET RewardText='Ó, köszönöm a jelzést. Nyugodtan válaszd ki, melyik páncélt szeretnéd.$b$bSok szerencsét, bátor $c. És szolgáljon jól ez a páncél.' WHERE ID=59;
UPDATE quest_offer_reward SET RewardText='Koboldokra vadásztál, mi? Köszönöm a gyertyákat, $N, és itt a jutalmad...' WHERE ID=60;
UPDATE quest_offer_reward SET RewardText='Itt a fizetséged... és ha már itt vagy, nézz körül! Biztos van itt egy bájital vagy más apróság, ami hasznodra válhat.' WHERE ID=61;
UPDATE quest_offer_reward SET RewardText='Ez rossz hír. Mi jön még, sárkányok?!? Meg kell erősítenünk az őrjáratokat a bánya közelében. Köszönöm az erőfeszítéseidet, $N. És várj egy pillanatot... talán van még egy feladatom számodra.' WHERE ID=62;
UPDATE quest_offer_reward SET RewardText='A karvédőket a parázstartó tetejére helyezed, majd Brine bájitalának maradék cseppjeit a lángba öntöd. A cseppek sisteregnek, ahogy elérik a lángot, és elkezded elmondani azokat az egyszerű szavakat, amelyeket Islen tanított neked...' WHERE ID=63;
UPDATE quest_offer_reward SET RewardText='Az órám! Nagyon köszönöm, kedves uram!$b$bCsak szegény parasztok vagyunk, elvesztettük a földünket, de kérlek, fogadd el ezt a jutalmat hálánk jeléül.' WHERE ID=64;
UPDATE quest_offer_reward SET RewardText='Szóval Stoutmantle küldött? Nos, tartozom neki.' WHERE ID=65;
UPDATE quest_offer_reward SET RewardText='Ó, szóval Eva asszony küldött...' WHERE ID=66;
UPDATE quest_offer_reward SET RewardText='A régi láda csikorogva kinyílik...' WHERE ID=67;
UPDATE quest_offer_reward SET RewardText='Érdekes. Szóval a fickó mégis töltött időt Moonbrookban. Elég furcsa, hogy a levél sosem lett kézbesítve. Mindenesetre frissítem a nyilvántartást.' WHERE ID=68;
UPDATE quest_offer_reward SET RewardText='Stalvan? Igen, ismerősen hangzik.' WHERE ID=69;
UPDATE quest_offer_reward SET RewardText='Van merszed ezt idehozni.' WHERE ID=70;
UPDATE quest_offer_reward SET RewardText='Beigazoltad a félelmeimet, $N. A murlocok olyan fenyegetést jelentenek, amit nem hagyhatunk figyelmen kívül.' WHERE ID=71;
UPDATE quest_offer_reward SET RewardText='Lassan lecsúsztatod a láda fedelét...' WHERE ID=72;
UPDATE quest_offer_reward SET RewardText='Alig tudom kivenni ezeket a betűket. De ez az írásstílus emlékeztet valamire, amit egyszer láttam, mielőtt ilyen gyenge lett a látásom.' WHERE ID=74;
UPDATE quest_offer_reward SET RewardText='Megtaláltad!' WHERE ID=75;
UPDATE quest_offer_reward SET RewardText='Koboldok a Jasperlode-bányában, azt mondod? A fenébe! A helyzet percről percre romlik!$B$BKöszönöm a jelentést, $N. De bárcsak jó hírt hoztál volna.' WHERE ID=76;
UPDATE quest_offer_reward SET RewardText='Kiválóan végrehajtva, $N. Örülök, hogy volt annyi előrelátásod, hogy nem zúztad össze a ripple finomságát. Nincs rosszabb, mint egy feleslegesen összerázott ripple aromája.$b$bEgy pillanatig tart majd, amíg a varázslat átjárja ezt a becses szállítmányt. Igazából nem is varázslat ez; csak van néhány üres csomagolásom a Hinterlands mézes ripple-höz. A csalafintaságunk korszakos alkoholos kinccsé változtatja majd ezeket az üvegeket.$b$bElőre - a nagyszerű piáért!' WHERE ID=77;
UPDATE quest_offer_reward SET RewardText='A Fényre! Hát persze, hogy felismerem ezt a kézírást.' WHERE ID=78;
UPDATE quest_offer_reward SET RewardText='Nahát, bebizonyítottad, hogy igazi detektív vagy, $c.' WHERE ID=79;
UPDATE quest_offer_reward SET RewardText='Hát persze! Az ezen az oldalon lévő írás valóban megegyezik a nyilvántartás aláírásaival.' WHERE ID=80;
UPDATE quest_offer_reward SET RewardText='Nos, lássuk, mi van ebben a hordóban!$b$bIgen, igen, úgy tűnik, minden megvan. Itt a fizetséged a csomagért, szép munka volt. Ötszörös hasznot csinálok majd, amikor eladom a kocsmának! Har har!$b$bEzeket a plusz üveg Hinterlands mézes ripple-t egy különleges alkalomra tartogatom. Azt hiszem, iszom belőle pezsgővel. Elnevezem majd... champipple-nek.' WHERE ID=81;
UPDATE quest_offer_reward SET RewardText='Szép munka - most rögtön elkezdem elemezni ezeket! De már most elmondhatom... ezek egyáltalán nem hasonlítanak semmilyen rovarformára, amit valaha láttam. Szinte úgy tűnik, mintha ezeket a bogarakat valami külső erő irányítaná.$b$bAzonnal beszélned kell Fizzledowserrel; úgy tűnik, sürgős segítségre van szüksége! Nem vagyok biztos benne, de azt hiszem, ez is a Tanaris-sivatagbeli bogarakkal kapcsolatos!' WHERE ID=82;
UPDATE quest_offer_reward SET RewardText='Ó, ezek szép fejkendők, bár kissé darabosak...$b$bTessék!' WHERE ID=83;
UPDATE quest_offer_reward SET RewardText='Mm, nyami! Ez a pite a legjobb!$b$bAzt hiszem, kezd visszatérni az emlékezetem...' WHERE ID=84;
UPDATE quest_offer_reward SET RewardText='Mit vesztettél el? Hát én nem vettem el semmiféle nyakláncot, mert nem vagyok tolvaj!$b$bTalán tudom, ki tette, de...<vigyorog>...túl éhes vagyok, hogy emlékezzek.' WHERE ID=85;
UPDATE quest_offer_reward SET RewardText='Bár ez a vadkanhús kemény, ha eleget párolod, biztos finom pitét lehet belőle csinálni!' WHERE ID=86;
UPDATE quest_offer_reward SET RewardText='Ó, megtaláltad! Köszönöm, köszönöm, drágám!$B$BTessék, fogadd el ezt. A férjemé volt, és mindig azt mondta, szerencsét hoz. Bárcsak ne felejtette volna el az utolsó hadjáratán! *szipog*' WHERE ID=87;
UPDATE quest_offer_reward SET RewardText='Hála az égnek! Az a disznó már olyan nagyra nőtt, hogy megette volna az egész termésünket! Köszönöm, $N.$b$bNos, megfelel neked ezek közül valamelyik?' WHERE ID=88;
UPDATE quest_offer_reward SET RewardText='Nagyszerű munka, $N. Ez az ellátmány rengeteget segít a híd építésén. Hamarosan megerősítjük ezt a szépséget.' WHERE ID=89;
UPDATE quest_offer_reward SET RewardText='Nagyon szép munka, $N! Élvezd a Fűszeres farkas kebab nevű ínyencséget!' WHERE ID=90;
UPDATE quest_offer_reward SET RewardText='A Lakeshire-i Bíróság elismeri az igazságosság iránti elköteleződésedet, $N. A Királyság törvényeinek betartatásával segítettél fenntartani a föld igazságosságát.' WHERE ID=91;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N. Micsoda kiváló példányok! És itt a finom ínyencséged, a Redridge gulyás!' WHERE ID=92;
UPDATE quest_offer_reward SET RewardText='Ó igen, szép kis csomó lábad van ott! Hadd fűszerezzem meg őket a titkos fűszereimmel (ne nézz oda!), és pattogtassam meg őket egy kicsit a serpenyőben...$B$BÉs bár a Dusky Crab Cakes a specialitásom, és nem adom ki a receptjét, itt egy majdnem ugyanolyan jó étel receptje.' WHERE ID=93;
UPDATE quest_offer_reward SET RewardText='Az Azora Glyph-et a kőre helyezed. Az magától rátapad... és Theocritus testetlen hangját hallod belőle:$B$BHálás vagyok neked, ifjú $N. Mostantól ezen a Glyph-en keresztül beszélhetsz velem, és talán lesz még számodra jövőbeli feladatom... miután kikérdeztem a vetélytársam gondolatait.' WHERE ID=94;
UPDATE quest_offer_reward SET RewardText='Egy földkupac hever itt, sietősen felhalmozva, mintha valakinek el kellett volna rejtenie valamit... nem sok idő alatt.' WHERE ID=95;
UPDATE quest_offer_reward SET RewardText='Ez az a bizonyíték, amit kértem. Jól teljesítettél, $N.$B$BÖröm számomra, hogy elsőként gratulálhatok, és átadhatom neked ezt... a víztotemedet.$B$BHasználd bölcsen, és sok szerencsét.$B$BA következő próbád még várat magára, szóval tanuld meg jól a leckéidet. A tiszta víz nemcsak életet ad vissza a sérülteknek, hanem sok más hatása is lehet. Javaslom, keress fel egy sámán-oktatót, ha lesz időd. Talán további varázslatokat is taníthatnak neked.' WHERE ID=96;
UPDATE quest_offer_reward SET RewardText='Tudtam! Remek munka, $N.' WHERE ID=97;
UPDATE quest_offer_reward SET RewardText='Tudom, $N: Stalvan halott. Éreztem, hogy a remény hulláma söpör végig a beszennyezett erdőn. Duskwood egyszer s mindenkorra megszabadult vérszomjától. Örömömet beárnyékolja a gondolat azokra, akik e szörnyű fenevad áldozatául estek. Mindazonáltal bátor és ravasz $c vagy.' WHERE ID=98;
UPDATE quest_offer_reward SET RewardText='Kitartásod dicséretes. A tudás segítségével, amit összegyűjteni segítettél, Arugal el fog bukni, és meggondolatlan mágiája semmivé válik. Egészségedre, $N.' WHERE ID=99;
UPDATE quest_offer_reward SET RewardText='Köszönet neked. Köszönet a sámánoknak.$B$BA romlás apad, de az élet továbbra is fogy. A sámánokon múlik, hogy megvédjék az életet.' WHERE ID=100;
UPDATE quest_offer_reward SET RewardText='Nagyon bölcs tőled, $N. Ez a Csapás Totemje segít megvédeni téged a gonosztól, amely Azeroth-szerte és azon túl is leselkedik. Ha fenyegetve érzed magad, tartsd ezt a totemet, és merülj el mágikus aurájában. Légy bátor, kedves $c. Minden bátorságra szükséged lesz, amit csak össze tudsz gyűjteni, mert sok vérontást látok a jövődben.' WHERE ID=101;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N. Ha hozzád hasonló bátor kalandozók harcolnak a Népi Milícia oldalán, Westfall talán visszatérhet ahhoz a virágzó éléstárhoz, amely egykor volt. Kérlek, fogadd ezt fáradhatatlan erőfeszítéseid elismeréseként.' WHERE ID=102;
UPDATE quest_offer_reward SET RewardText='Dicséret neked, bátor $c. Westfall partjának sziklái világítani fognak kemény munkádnak köszönhetően. Sok élet menekül meg, amíg a fáklya égve marad.$B$BÉn feleslegesen haltam meg épp ezen a parton. Túlvilági sorsom, hogy vigyázzak, ne kövesse senki más a végzetemet.' WHERE ID=103;
UPDATE quest_offer_reward SET RewardText='Szóval az aljas pogány, Murk-Eye halott. Szép munka, $N. A kezed által egy élet nyugalomra tért, de talán sok másik megmenekült. A Nagy Tenger, amilyen veszélyekkel teli, ma éjjel egy kicsit biztonságosabb lesz hőstetteidnek köszönhetően.' WHERE ID=104;
UPDATE quest_offer_reward SET RewardText='Sikerült! Araj... a lich végre legyőzetett!$B$BHatalmas szolgálatot tettél a Hordának ezen a napon, $N. Bátorságod és kitartásod bizonyítja, mit jelent igazi hősnek lenni. Kérlek - fogadd ezt jelként, hogy mindenki lássa és tudja, hogy örök időkre szóló győzelmet szereztél a Hordának!' WHERE ID=105;
UPDATE quest_offer_reward SET RewardText='Ó! Nem bírom elviselni, hogy külön vagyunk. Látnom kell őt!!' WHERE ID=106;
UPDATE quest_offer_reward SET RewardText='A szívem megesik azon a két szegény léleken, Maybellen és Tommy Joe-n. Emlékszem, egykor magam is fiatal voltam és szerelmes.$b$bBiztos tehetek valamit, hogy segítsek nekik! Hadd gondolkodjam...' WHERE ID=107;
UPDATE quest_offer_reward SET RewardText='Ó, szóval a barátom küldött ide? Milyen kedves.$B$BNos, a Stormwindi Monarchia elhagyta ügyünket. Most a Népi Milícián múlik, hogy a föld mentes maradjon a romlástól. Ha érdekel az ügyünk, harci képességeidet a szabadság nevében hasznosíthatom.' WHERE ID=109;
-- quest_offer_reward.RewardText. Batch 3: quest IDs 110-160.

UPDATE quest_offer_reward SET RewardText='Igen, itt vannak nálam az eredmények. Enyhén szólva is... nyugtalanítóak.$B$BKezdeti gyanúnk, hogy a bogarakat egy külső erő irányítja, úgy tűnik, helyesnek bizonyult. Ha ez igaz, akkor nemcsak egy nagyon hatalmas ismeretlen erővel állunk szemben, hanem egy rosszindulatúval is. Ezeket a bogarakat tiszta pusztítókká változtatták. Sosem láttam még ehhez foghatót.' WHERE ID=110;
UPDATE quest_offer_reward SET RewardText='Amíg a családjaink viszályban állnak, Tommy Joe-nak és Maybellnek nincs sok jövője, de... talán összehozhatjuk őket egy kis időre.$B$BHm, mit tehetnénk...' WHERE ID=111;
UPDATE quest_offer_reward SET RewardText='Megvannak. Szép munka! Most csak egy pillanat, amíg elkészítem a bájitalt...' WHERE ID=112;
UPDATE quest_offer_reward SET RewardText='Köszönöm, hogy elhoztad a jelentést, $N ifjú földmérő; itt a fizetséged a Gadgetzani Vízműveknek tett szorgalmas szolgálatodért.$B$BBár általában nem lelkesedem azért, hogy ingyen kiadjam az értékes információinkat azoknak, akik különben jó pénzt fizetnének érte, Pestlezuggot már jó néhány éve ismerem. Ha ő azt javasolja, hogy mindenki tudjon róla, akkor legyen úgy. Adj egy pillanatot, és készítek neked egy másolatot.' WHERE ID=113;
UPDATE quest_offer_reward SET RewardText='Ó... istenem! Bűntudatot érzek, amiért becsapom a családomat, de az érzéseim Tommy Joe iránt túl erősek ahhoz, hogy figyelmen kívül hagyjam.$b$bKöszönöm, $N. Megiszom ezt az italt, amint lehetőségem nyílik rá, és kiosonok a szerelmemhez.$b$bNeked pedig... kérlek, fogadd el ezt.' WHERE ID=114;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Azonnal elküldöm ezeket megsemmisítésre.' WHERE ID=115;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N! Jól tudom, milyen utakat kellett bejárnod, hogy megszerezd ezt a finom italválasztékot. De a vendégeim ismét boldogok lesznek!$b$bA feleségem igazi mesterszabó. Kérlek, fogadd el ezt a köpenyt, amit ő készített, szolgálataidért cserébe.' WHERE ID=116;
UPDATE quest_offer_reward SET RewardText='Komló és árpa, élesztő és maláta,$bAz ízlelőbimbók valóságos rohamba,$bNincs szükség könyörgésre, kunyerálásra sem,$bA Thunderbrew Lager hordóban érkezik, jelen!' WHERE ID=117;
UPDATE quest_offer_reward SET RewardText='Heh, szóval az öreg Vernernek patkó kell, mi!?!' WHERE ID=118;
UPDATE quest_offer_reward SET RewardText='Köszönöm, ez tényleg sokat segít.$b$bDe mi ez itt? Argus üzenetet küldött a ládával... Mi?? Argus azt akarja, hogy FIZESSEK neki? Fú!$b$bNos, $N, köszönöm a segítségedet.' WHERE ID=119;
UPDATE quest_offer_reward SET RewardText='Pihenj, $c.$b$bSolomon bíró nemes vezető. A szavai nagy súllyal bírnak nálam. Kikérem a Király tanácsát, és tisztázom vele a helyzetet. Biztosítsd a jó bírót, hogy élvezi a Stormwindi Hadsereg támogatását. Az erősítés útnak indul, amint Őfelsége szava megérkezik.' WHERE ID=120;
UPDATE quest_offer_reward SET RewardText='Köszönöm az idődet, $c. A Lakeshire-nek és Stormwindnak tett szolgálatodért ezekkel az érmékkel jutalmazlak.$b$bMost pedig, ha megbocsátasz, ezt a levelezést kissé rejtélyesnek találom. Valami nincs rendben a Királyságunkban. Attól tartok, ez egy konfliktus kezdete, nem a vége.' WHERE ID=121;
UPDATE quest_offer_reward SET RewardText='Köszönöm! Ezekkel kifizetem az adósságomat Argusnak...' WHERE ID=122;
UPDATE quest_offer_reward SET RewardText='Hm... hallottam már erről a „Gyűjtőről”, de nem tudom, kinek dolgozik. Köszönöm a menetrendet. Segít majd megoldani ezt a rejtélyt.' WHERE ID=123;
UPDATE quest_offer_reward SET RewardText='Köszönöm minden segítségedet, $N.' WHERE ID=124;
UPDATE quest_offer_reward SET RewardText='Kiváló munka, $N! Sosem hittem volna, hogy még egyszer látom ezeket a szerszámokat.' WHERE ID=125;
UPDATE quest_offer_reward SET RewardText='Ismét köszönöm a segítségedet. A Stormwindi Hadsereg annyira el van foglalva az orkokkal, hogy nincs elég csapata megvédeni Redridge-t a helyi fenyegetésektől, mint amilyenek a gnollok.' WHERE ID=126;
UPDATE quest_offer_reward SET RewardText='Öröm veled üzletelni, cimbora!' WHERE ID=127;
UPDATE quest_offer_reward SET RewardText='Látom, vitézül harcoltál a Blackrock klán ellen, $c. Szolgálatod városunknak valóban nagyszerű.' WHERE ID=128;
UPDATE quest_offer_reward SET RewardText='Köszönöm, tényleg jól jön ez az étel. Lakeshire-t védeni az orkoktól és gnolloktól kemény munka!' WHERE ID=129;
UPDATE quest_offer_reward SET RewardText='Egy csokor virágra van szükséged? Nem vagy itt régóta a városban... máris találtál magadnak kedvest?$B$BTudom, nem kéne kíváncsiskodnom, de jó látni, hogy szerelem van a levegőben... különösen ilyen veszélyes időkben.' WHERE ID=130;
UPDATE quest_offer_reward SET RewardText='Ó, ezek gyönyörűek! Alig várom, hogy vízbe tegyem őket!$b$bDe... ezek Martie kedvenc virágai. Csak nem Parker küldött el ehhez a féltékeny rókához ezért a csokorért? Ugye nem mondtad meg neki, kinek szánod? Ha igen, nem lepne meg, ha megmérgezte volna őket.$b$bDe hát nem a te hibád. Köszönöm, és itt az ételed.' WHERE ID=131;
UPDATE quest_offer_reward SET RewardText='Fú! Hagynom kellett volna, hogy az a csirkefogó rohadjon meg, amikor lehetőségem volt rá. De ez az információ létfontosságú. Szép munka.' WHERE ID=132;
UPDATE quest_offer_reward SET RewardText='Ó, köszönöm. Ezek pont megteszik!' WHERE ID=133;
UPDATE quest_offer_reward SET RewardText='Hála a Nec-... nos, hála NEKED, $N! Bőven kiérdemelted a jutalmadat.$B$BAha! Boldog! Boldog éjszakák várnak ránk!!' WHERE ID=134;
UPDATE quest_offer_reward SET RewardText='Ez az ügy talán bonyolultabb, mint amit Stoutmantle gondol.' WHERE ID=135;
UPDATE quest_offer_reward SET RewardText='A láda lassan, csikorogva kinyílik. Úgy tűnik, csak homok és víz van benne. De várj csak! Egy apró rák szalad ki, ollójában a kincs nyomával!' WHERE ID=136;
UPDATE quest_offer_reward SET RewardText='Szép munka, kincsvadász!' WHERE ID=138;
UPDATE quest_offer_reward SET RewardText='Úton vagy a főnyeremény felé, kincskereső!' WHERE ID=139;
UPDATE quest_offer_reward SET RewardText='A régi láda pántjai berozsdásodtak, de még működnek. Erővel kinyitod a ládát, és megkaparintod a zsákmányt.$B$BGratulálok!' WHERE ID=140;
UPDATE quest_offer_reward SET RewardText='Edwin VanCleef... jól ismerem ezt a nevet. Nyugtalanít a gondolat, hogy egy ilyen szorgalmas és tehetséges ember ilyen gazemberré válhatott. További bizonyítékra lesz szükségem, mielőtt elhinném.' WHERE ID=141;
UPDATE quest_offer_reward SET RewardText='Ez valóban szilárd bizonyíték arra, hogy VanCleef irányít. Most már csak azt kell megtudnunk, hol rejtőzik a Defias banda.$b$bSzerencsénk volt, amíg távol voltál. Elfogtunk egy tolvajt, aki Saldean szekerét próbálta ellopni. Megígérte, hogy elvezet minket a rejtekhelyre az életéért cserébe. Azt akarom, hogy védd meg az árulót, hogy felfedhesse a rejtekhelyet. Térj vissza hozzám, ha megtaláltad a helyet.' WHERE ID=142;
UPDATE quest_offer_reward SET RewardText='Derék hírnök, jól szolgáltad gazdádat.' WHERE ID=143;
UPDATE quest_offer_reward SET RewardText='Meg kell mondjam, ez egyáltalán nem jó. Nem is gondoltam volna, hogy Stoutmantle helyzete annyira hasonlít a miénkhez itt Lakeshire-ben. Milyen ügy olyan fontos, hogy elvonja a Stormwindi Hadsereget a népétől? Fú, nem kéne hangosan töprengenem.$b$bTessék, hírnök. Fogadd el ezeket az érméket a Városnak tett szolgálatodért. Talán még szükségem lesz rád.' WHERE ID=144;
UPDATE quest_offer_reward SET RewardText='Köszönöm, hogy megtetted ezt a hosszú utat idáig. Ez valóban fontos információ.' WHERE ID=145;
UPDATE quest_offer_reward SET RewardText='A Fényre! A Stormwindi Hadsereg visszavonult Westfallból. És az Őrség többé nem védi Darkshire-t? Valamiféle árulás történik. Hogy lehet ez? $b$bÓ, elfelejtettem megjutalmazni a szolgálatodat, $c. Tessék, néhány érme. Most pedig bocsáss meg. Valami nincs rendben Stormwindban, és a végére kell járnom.' WHERE ID=146;
UPDATE quest_offer_reward SET RewardText='Megtaláltad? Szép munka, $N. Nem fog többé „beszedni” az Elwynn-bányáktól!$B$BÉs ez a gyűrű, amit találtál, érdekes... ez a régi Stormwindi Kőműves Céh tagsági gyűrűje. Miért lenne egy alantas tolvajnak egy mesterember-céh gyűrűje, és miért szednek pénzt a Defias tolvajok a bányáinktól?$B$BNehéz kérdések. Remélem, egy nap választ kapunk.' WHERE ID=147;
UPDATE quest_offer_reward SET RewardText='Ó, szellemhaj-fonalra van szükséged, igaz? Attól tartok, nincs raktáron, de tudok készíteni neked... ha te hozol nekem szellemhajat.' WHERE ID=148;
UPDATE quest_offer_reward SET RewardText='Ez meg mi? Egy fésű? Gyönyörű! És úgy siklik át a hajamon, mintha nem is az a merev, kócos rémség lenne, ami valójában.$B$BÓ, bárcsak lenne tükröm...' WHERE ID=149;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N. Remélem, nem volt túl sok gondod azokkal a murlocokkal.$B$BFurcsa őket ilyen messze látni a tengertől. Vajon azért vannak itt, mert menekülnek valami elől...' WHERE ID=150;
UPDATE quest_offer_reward SET RewardText='Nagyon köszönöm, $N! A szegény öreg Blanchy nagyon boldog lesz!' WHERE ID=151;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N. Igazi tehetséged van a harchoz. Neked köszönhetően Westfall partja biztonságosabb hely.' WHERE ID=152;
UPDATE quest_offer_reward SET RewardText='Szép munka, $R. Kérlek, fogadd el az egyik tárgyat fizetségül kemény munkádért.' WHERE ID=153;
UPDATE quest_offer_reward SET RewardText='Ebből tudok készíteni egy orsó szellemhaj-fonalat, és marad is néhány szál fölöslegben. Itt van néhány érme azokért az extra szálakért.' WHERE ID=154;
UPDATE quest_offer_reward SET RewardText='Kiváló, $N! VanCleef gyakorlatilag a miénk, most hogy tudjuk, hol rejtőzik.' WHERE ID=155;
UPDATE quest_offer_reward SET RewardText='Jó, megvannak a rothadó virágok. És elmondom Althea Ebonlocke-nak az Éjjeli Őrségtől, hogy csontvázakat öltél.$B$BDarkshire népének biztonságban tartása komor teher az Éjjeli Őrség számára, és üdvözlendő hír, hogy mások is segítenek megállítani a démonok áradatát Duskwoodban.' WHERE ID=156;
UPDATE quest_offer_reward SET RewardText='Elragadó! Ez pompásan megteszi majd...$b$bTessék, derék $N, fogadd el ezt fizetségül becsületes tettedért.' WHERE ID=157;
UPDATE quest_offer_reward SET RewardText='Zombilére van szükséged, ugye? Hmm... ez elég erős cucc - nem szokott gyakran kérni belőle senki.' WHERE ID=158;
UPDATE quest_offer_reward SET RewardText='Ezer köszönet, $N. Felmelegíted egy öregember szívét a bolond-... úgy értem... a kedvességeddel!$b$bTessék, barátom. Fogadd el hálám jeléül.' WHERE ID=159;
UPDATE quest_offer_reward SET RewardText='<Ello a levelet nézi...>$B$BMilyen nyelv ez? Ősinek tűnik... nem tudom elolvasni.' WHERE ID=160;
-- quest_offer_reward.RewardText. Batch 4: quest IDs 161-210.

UPDATE quest_offer_reward SET RewardText='Ó, hát az öreg Hinderweirnek van oka az aggodalomra.' WHERE ID=161;
UPDATE quest_offer_reward SET RewardText='Ez a jelentés... mi, éjelfek ismerjük az itt említett rémséget. Fizzledowser bölcsen tette, hogy elküldte ezt, téged pedig hozzám.$B$BEzek a lények gyorsan felemésztik a Tanaris-sivatagot; nem kevesebbek, mint az egyik legnagyobb fenyegetés, amivel valaha szembe fogunk nézni. Jegyezd meg ezt a nevet, $N: silithid. Az itt említett rovarok silithidek, és egyike a legnagyobb veszélyeknek, amivel a Horda és a Szövetség egyaránt szembenéz.$B$BBárcsak elég okosak lettünk volna, hogy ezt korábban észrevegyük.' WHERE ID=162;
UPDATE quest_offer_reward SET RewardText='Ne! Kérlek, ne ölj meg! Csak én vagyok az... Jitters!! Mindenhol ott vannak... nem tudok elmenekülni előlük! Szörnyek Raven Hillben? N-n-n-em... nem lehet. Csak az ártalmatlan Jitters.' WHERE ID=163;
UPDATE quest_offer_reward SET RewardText='Ez az ellátmány nagyon hasznos lesz. A Carevin család segítségét mindig nagyra értékeljük. Itt egy kis apróság a fáradozásodért.' WHERE ID=164;
UPDATE quest_offer_reward SET RewardText='Hehe, ó igen... persze, a Carevinek.$B$BNem, nincs semmi baj, csak nehezemre esik bemenni a városba mostanában. Az utak veszélyesek, és nem leszek fiatalabb. Talán tehetnél néhány szívességet egy öregembernek?' WHERE ID=165;
UPDATE quest_offer_reward SET RewardText='$N, a bátorságod figyelemre méltó. A Népi Milícia köszöni a Westfall népének tett szolgálatodat. VanCleef halálával elkezdődött a Defias Testvériség vége. Reméljük, hamarosan újra béke honol majd e szép föld síkságain.$B$BTisztelettel adózom neked, $gUram:Úrnőm;!' WHERE ID=166;
UPDATE quest_offer_reward SET RewardText='A gyanúm beigazolódott. Szegény bátyám... Nos, köszönöm, hogy lezártad ezt a rejtélyt, még ha komor is a végkifejlet.' WHERE ID=167;
UPDATE quest_offer_reward SET RewardText='Köszönöm, hogy összegyűjtötted ezeket, $N. Erőfeszítéseid segítenek nyugalmat hozni a halottaknak e tragédia után. Gondoskodom róla, hogy a családokat értesítsék.' WHERE ID=168;
UPDATE quest_offer_reward SET RewardText='Fantasztikus munka, $N! Gath''Ilzogg vezette csatába azokat a barbárokat, akik sok ártatlan embert öltek meg. Az igazságszolgáltatás a miénk. Ez az első lépés afelé, hogy visszaszerezzük a várat a Stormwindi Királyságnak!' WHERE ID=169;
UPDATE quest_offer_reward SET RewardText='Ha az itteni problémáink jelzik, mi történik másutt a földjeinken, Magni szakállára, nagy bajok várnak ránk! Csak remélhetem, hogy a király és a szenátus lépéseket tesz a troggok jelentette fenyegetés ellen.' WHERE ID=170;
UPDATE quest_offer_reward SET RewardText='Áldjon meg az ég, $N. Többet tettél Randisért, mint amire a legtöbben valaha is gondolnának. Köszönöm - ragyogó csillag vagy a Szövetség egén.$b$bKérlek - ha van rá időd, gyere vissza meglátogatni minket. Tudom, hogy Randis örülne neki, akárcsak én.' WHERE ID=171;
UPDATE quest_offer_reward SET RewardText='Zug zug! Grunth vagyok, és gondolom, te vigyázol rám? Kalandozó vagy, mint anyukám és apukám voltak. A gondviselőm szerint becsülettel haltak meg a csatában. Örülök, hogy megismerhetlek.$B$BRemélem, sok mindent csinálunk majd együtt. Van pár dolog, amit szeretnék csinálni, és a gondviselőm szerint olyan leszel nekem, mint egy nagy testvér ezen a héten. Nagyon tetszene.' WHERE ID=172;
UPDATE quest_offer_reward SET RewardText='Lenyűgöző, $N. Úgy tűnik, elég ügyes vagy, hogy boldogulj magadtól. Talán egy hozzád méltóbb kihívást is találhatnánk a képességeidhez.$b$bDe furcsa... a worgenek szinte a semmiből tűntek fel. De hát a sok más furcsa lénnyel, amik átjöttek a határainkon, gondolom, ez csak egy a sok gond közül.' WHERE ID=173;
UPDATE quest_offer_reward SET RewardText='Ez tökéletes, $N. Az első lépés kész!' WHERE ID=174;
UPDATE quest_offer_reward SET RewardText='Hát persze, régen volt egy távcsövem.' WHERE ID=175;
UPDATE quest_offer_reward SET RewardText='Hah! Szép munka! Már kezdtem azt hinni, senki sem fogja legyőzni azt a szörnyeteget!$B$BTessék, $N. És köszönöm - az a gnoll akkora fejfájást okozott nekem, mint a Blackrock Spire!' WHERE ID=176;
UPDATE quest_offer_reward SET RewardText='Egyszerűen lenyűgöző! Ez tökéletesen fog működni. Sok köszönet!' WHERE ID=177;
UPDATE quest_offer_reward SET RewardText='Hálás vagyok neked, $N. Hetekkel ezelőtt küldtem el azt az üzenetet a Shadowhide medálokhoz, és kudarcnak hittem. De úgy tűnik, a varázslat mégis elért legalább néhány medált, jelentős késéssel.$B$BIdővel remélem megtanulom, hogyan küldjek támadást a medálokon keresztül, hogy megbénítsam azokat a Shadowhide gnollokat, akik viselik őket.$B$BDe mielőtt ez lehetségessé válna, attól tartok, sokkal több kutatásra lesz szükség.' WHERE ID=178;
UPDATE quest_offer_reward SET RewardText='Ó! Csodálatos. A farkashús pont megteszi. Ó, ne aggódj, $N, nem felejtenék el a magam részéről az alkuból. Tessék, ezek közül az egyik pont jó lesz neked.' WHERE ID=179;
UPDATE quest_offer_reward SET RewardText='Szóval a gonosz Fangore hadnagy halott? Jó, hogy megszabadultunk attól az aljas teremtménytől. Nagyon bátor vagy, $c. Lakeshire Városa köszöni a segítségedet.' WHERE ID=180;
UPDATE quest_offer_reward SET RewardText='Végre! A csillagvizsgáló eszköz elkészült! Köszönöm, $N. Most már folytathatom a kutatásomat...' WHERE ID=181;
UPDATE quest_offer_reward SET RewardText='Argh! Azok az istenverte trollok!$B$B<Vesz néhány mély levegőt, és úgy tűnik, kicsit megnyugszik.>$B$BÉjjel jött egy csoportjuk, és ellopták a naplómat! Tudhattam volna, hogy ne bízzak abban a semmirekellő tanonc...' WHERE ID=182;
UPDATE quest_offer_reward SET RewardText='Kiváló! Most már visszatérhetek a... nyugodt... vadászatomhoz. Köszönöm, $N.' WHERE ID=183;
UPDATE quest_offer_reward SET RewardText='Rengeteg köszönet, $N! Ahogy mondtam, ezek a vidékek már nem valók becsületes embereknek, de ha jobbra fordulnak a dolgok, ez a birtoklevél lehetővé teszi, hogy visszaszerezzük a földünket.$b$bNincs sok mit kínálnom neked, de tessék -- fogadd el ezt.' WHERE ID=184;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N. Készen állsz továbblépni.' WHERE ID=185;
UPDATE quest_offer_reward SET RewardText='Lenyűgözve vagyok, $c. Egészen jól haladsz.' WHERE ID=186;
UPDATE quest_offer_reward SET RewardText='Igazán lenyűgöző. Úgy vélem, majdnem készen állsz.' WHERE ID=187;
UPDATE quest_offer_reward SET RewardText='Igazán lenyűgöző, meg kell mondjam! Igazi Tigrisvadász Mester vagy, $N!' WHERE ID=188;
UPDATE quest_offer_reward SET RewardText='Ó, kiváló, kiváló. Ez most egy kicsit segít...$b$b<Elhallgat, és a profitrésekről meg a költségekről morog...>$b$bMi? Még mindig itt vagy? Jutalom? Ó, igen... persze, tessék, fogd ezt... több mint elég lesz.' WHERE ID=189;
UPDATE quest_offer_reward SET RewardText='Szép kezdés, $N!' WHERE ID=190;
UPDATE quest_offer_reward SET RewardText='Tökéletesen végrehajtva, $N!' WHERE ID=191;
UPDATE quest_offer_reward SET RewardText='Jól teljesítettél, $N!' WHERE ID=192;
UPDATE quest_offer_reward SET RewardText='Szóval a nagy Bhag''thera halott! Egészségedre, $N. Valóban hatalmas $c vagy!' WHERE ID=193;
UPDATE quest_offer_reward SET RewardText='Szép munka, $g pajtás : hölgyem;!' WHERE ID=194;
UPDATE quest_offer_reward SET RewardText='Így kell trófeákat szerezni a kandalló fölé! Szép ölés, $N!' WHERE ID=195;
UPDATE quest_offer_reward SET RewardText='Ho ho!! Igazi raptorölőnk van! Szép munka, $g pajtás : szép hölgy;!' WHERE ID=196;
UPDATE quest_offer_reward SET RewardText='$G Mester : Úrnő; $N, a raptorölő!$b$bJól hangzik, mi?' WHERE ID=197;
UPDATE quest_offer_reward SET RewardText='Ezek az aknák segítenek megvédeni magunkat attól a vadállattól, Kurzentől és embereitől. Köszönöm, hogy elhoztad őket. Ha további munkára van szükséged, valószínűleg találok neked feladatot. És nem kell azokkal a goblinokkal foglalkoznod, hm?' WHERE ID=198;
UPDATE quest_offer_reward SET RewardText='Enyhén szólva is riasztó felfedezés!' WHERE ID=199;
UPDATE quest_offer_reward SET RewardText='Ezek Bookie Herod feljegyzései és nyilvántartásai.$b$bKözöttük van: a tábor ellátmányának listája, Kurzen ezredes anyagigénylései, és különféle levelek és levelezések.' WHERE ID=200;
UPDATE quest_offer_reward SET RewardText='Hmmm, szóval az információm helyes volt, mint mindig. Érdekes. Nos, nem hiszem, hogy bármilyen fenyegetést jelentenének a működésünkre nézve, de talán szükségük van néhány kiváló termékünkre. Hmmm...' WHERE ID=201;
UPDATE quest_offer_reward SET RewardText='Nem mertem hinni a jelentéseknek, de te bizonyítékot hoztál arra, hogy... Kurzent és vezéreit legyőzték. Megmentettél minket!$B$BEzek a dzsungelek tele vannak mindenféle fenyegetéssel, de egyiknek sem volt Kurzen kegyetlen esze. Most, hogy eltűnt, mindannyian fellélegezhetünk.' WHERE ID=202;
UPDATE quest_offer_reward SET RewardText='Szép munka. Azoknak a dzsungelharcosoknak az elvesztése enyhít valamit a táborunkra nehezedő nyomáson.$b$bDe most, hogy kóstolót kaptál az erőkből, amikkel szembenézünk, még mindig velünk akarod vetni sorsod??' WHERE ID=203;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N. Ezek a gyógyszerek életben és harcképes állapotban tartanak közülünk többeket. A kivonatok pedig segítenek saját gyógyszereink elkészítésében.' WHERE ID=204;
UPDATE quest_offer_reward SET RewardText='Köszönöm. Tanulmányozni fogom ezeket a bálványokat, hátha rejtik Kurzen gonoszságba süllyedésének titkát.' WHERE ID=205;
UPDATE quest_offer_reward SET RewardText='Aha! Sikerült! Nagy erő vagy a jó oldalán, $N, sose fogyjon el az erőd!$B$BTanulmányozni fogom ezt az Elmeszemet, és eldöntöm, hasznosítható-e a jó ügyért. Ha nem... akkor el kell pusztítani.' WHERE ID=206;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Tanulmányozni fogom ezeket a legendákat, hátha van kapcsolat a trollok és a gonosz között, amely megszállta Kurzen ezredest.' WHERE ID=207;
UPDATE quest_offer_reward SET RewardText='Átkozottul szép munka! Így ám! Gratulálok, $N, hogy sikerrel jártál, ahol mások kudarcot vallottak.$b$bMegtiszteltetés, hogy bajtársamnak mondhatlak ebben a nagyszerű vadásztársaságban. Senki sem fogja kétségbe vonni a vadászatban és nyomkövetésben szerzett tudásodat!$b$bEgészségedre, mondom! Egészségedre!' WHERE ID=208;
UPDATE quest_offer_reward SET RewardText='Ó, szép munka, szép munka! Ugh, bár jobban is meg tudtad volna tisztítani a-- Nos, mindegy, mindegy! Köszönet neked, $N, a mi működésünk kétségkívül nagyobb kibocsátást és termelékenységet lát majd a segítségednek köszönhetően! Jó, jó, most pedig térjünk át más ügyekre...' WHERE ID=209;
UPDATE quest_offer_reward SET RewardText='Ó, értem, ez egy Krazek-féle cserépfazék! Zseniális alkotás, de néha eltörhet egy rugója, vagy kieshet egy fogaskereke. Hadd nézzem meg, mi baja ennek...$b$bAha! A gőztöltője berozsdásodott, repedt a csuklótömítése, és hiányzik pár fog a fobulátoráról. Meglepő, hogy ilyen állapotban egyáltalán meg tudott forralni akár egy répát is!$b$bMeg tudom javítani? Persze hogy meg tudom javítani!$b$bDe van ára. Ó igen, mindig van ára...' WHERE ID=210;
-- quest_offer_reward.RewardText. Batch 5: quest IDs 211-264.

UPDATE quest_offer_reward SET RewardText='Sikerült! Araj... a lich végre legyőzetett!$B$BHatalmas szolgálatot tettél a Szövetségnek ezen a napon, $N. Bátorságod és kitartásod bizonyítja, mit jelent igazi hősnek lenni. Kérlek - fogadd ezt jelként, hogy mindenki lássa és tudja, hogy örök időkre szóló győzelmet szereztél a Szövetségnek!' WHERE ID=211;
UPDATE quest_offer_reward SET RewardText='Ó, ez pont megteszi! Nagyon, nagyon köszönöm!$b$bMost pedig, ha megbocsátasz, fel kell aprítanom, pácolnom és díszítenem a combot a lakomához.' WHERE ID=212;
UPDATE quest_offer_reward SET RewardText='Lenyűgöző. Hogy a kristályokat ezzel a folyamattal koptatták, az csak arra utalhat, hogy valamiféle üzemanyagként vagy katalizátorként akarják felhasználni őket. Ennél többet nem tudok. Mintákat kell küldeni Gigglefont vegyészfőnöknek.' WHERE ID=213;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N! A Népi Milícia nevében tisztelgek erőfeszítéseid előtt. Hamarosan visszaadjuk ezt a földet a népnek, olyan bátor lelkek segítségével, mint te.' WHERE ID=214;
UPDATE quest_offer_reward SET RewardText='Igen, amit Thorsen mondott neked, igaz. Diszkrétnek kell lenned ezzel kapcsolatban. Egykor mi, lázadók, hűségesen szolgáltuk Kurzen ezredest. De Kurzen romlottsága olyan volt, hogy a szenvedélyünk dühbe fordult. Ha kiderülne, hogy Thorsen közlegénynek nemrég dolga volt Kurzen embereivel, egy éjjel elvágott torokkal találná magát.$b$bTudomásom szerint csak Yohwa őrmester, Thorsen és én voltunk beavatva Thorsen küldetésébe. De kell lennie még valakinek. Egy árulónak.' WHERE ID=215;
UPDATE quest_offer_reward SET RewardText='Szép munka, $c, szép munka! Továbbra is küldök erőket, hogy megritkítsuk a furbolgokat, de legalább számíthatok egy másik útra, ami mentes a Szövetség beavatkozásától. A Horda Ashenvale meghódítása most van teljes lendületben!$b$bMa kiérdemelted a fizetségedet, hős. Tisztelgek előtted!' WHERE ID=216;
UPDATE quest_offer_reward SET RewardText='Igazán kiváló, $N! Reményt hoztál Loch Modannak. Grawmug halálával jobb esélyünk van rá, hogy a troggokat kiirtsuk a földről.' WHERE ID=217;
UPDATE quest_offer_reward SET RewardText='Csodálatos, $N! Nagyon köszönöm, hogy visszahoztad a jegyzetfüzetemet. Nos, úgy tűnik, a trollhelyzet itt Coldridge-völgyben kontroll alatt van, és nem sok ok van aggodalomra.$b$bMiután befejezem a jelentésemet, valakire szükségem lesz, aki elviszi a bátyámnak, Senirnek.' WHERE ID=218;
UPDATE quest_offer_reward SET RewardText='Jól szolgáltad a Királyságot, $c. Köszönöm, hogy segítettél Keeshan tizedesnek megszökni azoktól a rettegett Blackrock orkoktól. Jutalmat kapsz ma bátor tetteidért.' WHERE ID=219;
UPDATE quest_offer_reward SET RewardText='Ó, egy fiola víz, amit Brine készített és áldott meg, és amit te gyűjtöttél össze, ráadásul.$B$BAz ebben a fiolában lévő folyadék kulcsfontosságú lesz egy sapta elkészítéséhez neked, de egy másik feladathoz is felhasználjuk.$B$BAz általam neked készített saptát arra kell használnod, hogy lásd a vízi szellemeket a Silverpine-erdő szentélyénél, az Alvárostól délre. A maradék cseppekről, nos, a maradék cseppekről akkor mesélek, ha úgy érzed, készen állsz.$B$BFelkészültél még egy útra, $N?' WHERE ID=220;
UPDATE quest_offer_reward SET RewardText='Jól teljesítettél a Sötét Futárok ellen, $N. De úgy tűnik, a számuk kimeríthetetlen. Minden alkalommal, amikor előrelépünk, újabbak lépnek elő, hogy feltöltsék soraikat.$b$bMi az a gonosz erő, ami idevonzza őket? Miért jöttek zavarni szerencsétlen birodalmunkat...$b$bCarevin mesterbe vetem bizalmamat. Kétségkívül a végére jár a problémának.' WHERE ID=221;
UPDATE quest_offer_reward SET RewardText='$N, hogy őszinte legyek, nem hittem volna, hogy idáig jutsz, de te egyértelműen egy számottevő $c vagy. Sőt, ha hivatalosan is csatlakozni szeretnél Carevin mester küzdelméhez, szívesen írok neked egy ajánlólevelet.' WHERE ID=222;
UPDATE quest_offer_reward SET RewardText='Elnézést a hűvös fogadtatásért, $N, de ahogy biztos látod, rendkívül elfoglalt ember vagyok. Látom, sikerült lenyűgöznöd Calort--és biztosíthatlak, ez nem kis teljesítmény--és megkaptad az ajánlását.$b$bKellemetlen alakok ólálkodnak, $N, és jól jön minden segítség azoktól, akik már bizonyítottak. Démonok, élőholtak és azok ellen harcolunk, akik segítséget nyújtanak nekik. Légy éber, légy óvatos, és ne bízz senkiben, aki nem segíti ügyünket.$b$bDicsőség a Fény alatt.' WHERE ID=223;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N! Hihetetlen bátorságot mutattál a csatatéren. A troggok elleni háborúnkat a hozzád hasonló erőfeszítésekkel nyerjük meg. Jól szolgáltad Magni királyt.$b$bHa úgy érzed, alkalmas vagy erre a fajta kalandozásra, javaslom, beszélj Gravelgaw hegymászóval. A kapitány egy kemény őrjáratra osztotta be, ahol biztosan jól jönne a segítséged. Keresd Gravelgaw-t a torony belsejében.' WHERE ID=224;
UPDATE quest_offer_reward SET RewardText='Morgan Ladimore?$b$bÁ, igen, persze. Hosszú és szomorú történet az övé. Ismertem őt, még mielőtt elment a háborúba, de az volt az utolsó alkalom, hogy láttam. Nemes és jó ember volt, de rossz vége lett.$b$bTessék, kell legyen itt valami, ami jobban elmeséli a történetet, mint az én emlékeim...' WHERE ID=225;
UPDATE quest_offer_reward SET RewardText='Ó, remek. Alaposan megritkítottad azt a falkát, és mivel nem harapdálják a sarkunkat azok a farkasok, most már Morbent Felre összpontosíthatjuk gondolatainkat.$B$BTessék, vigyél magaddal néhányat ezekből a villanócsomagokból. A városban készítik őket, és sokat adományoztak Svennek, hogy segítsék az ügyét.' WHERE ID=226;
UPDATE quest_offer_reward SET RewardText='Morgan Ladimore? Sosem hallottam...$b$bÓ, Mor''Ladimra gondolsz! Gondolom, nem hallottad a történetet?$b$bNos, elmondom a rövid verzióját. Egy kóborló élőholt, aki Mor''Ladimnak nevezi magát, Duskwoodban kóborol. Amennyire tudjuk, ez Morgan Ladimore élőholt teste, akit láthatóan ismersz. Mindenféle bajt okoz nekünk, megtámadja az őrjáratozó Őröket, és embereket öl.$b$b<Végigmér téged.>$b$bÚgy tűnik, elég ügyes vagy, talán te tudnád nyugalomra téríteni.' WHERE ID=227;
UPDATE quest_offer_reward SET RewardText='Megölted? Ez nem kis teljesítmény, $N! Darkshire népe és az Éjjeli Őrség nevében köszönöm.$B$BÁ... van azonban egy apró ügy...' WHERE ID=228;
UPDATE quest_offer_reward SET RewardText='Igen? Az apám...$B$B<Lesüti a szemét.>$B$BBárcsak... tehettem volna valamit érte... Bárcsak beszéltem volna vele, mielőtt ő...' WHERE ID=229;
UPDATE quest_offer_reward SET RewardText='<Sven elolvassa a könyv lapjait, majd becsapja.>$B$BAz az árnyékos alak, akit láttam, szemtanúja volt a családom halálának! Van néhány kérdésem ahhoz az emberhez... bárcsak tudnám, ki ő!' WHERE ID=230;
UPDATE quest_offer_reward SET RewardText='<Kísérteties hang szól a szélben...>$B$BEz...? Sarah? Lehet, hogy még életben van? Kő esik le a szívemről...$B$B$N. Fogd a kardomat, Archeust. Mivel a lelkem nyugalomra tér, többé nincs rá szükségem. Arra kovácsolták, hogy jót tegyen, és bár én méltatlannak bizonyultam a viselésére, talán te tovább viszed rajta keresztül a Fényt.$B$BLys, szerelmem...' WHERE ID=231;
UPDATE quest_offer_reward SET RewardText='Ó, Zingének készletre van szüksége, igaz? Elszomorít, hogy Zinge nem választja, hogy megtiszteljen édes jelenlétével.$B$BNos jó, hadd szerezzek neked egy készletet.' WHERE ID=232;
UPDATE quest_offer_reward SET RewardText='Köszönöm, már jó ideje vártam ezekre a levelekre...$b$bSajnos nem mindegyik levél nekem szól. Ez itt Grelin Whitebeardnek van címezve. Nincs túl messze, ha el szeretnéd vinni neki.' WHERE ID=233;
UPDATE quest_offer_reward SET RewardText='Áá, kiváló. Már jó ideje nem kaptam hírt Ironforge-ból.' WHERE ID=234;
UPDATE quest_offer_reward SET RewardText='Üdvözöllek az új határvidéken, $N. Ashenvale a lehetőségek földje, ahol egy hozzád hasonló ifjú $c korlátlan esélyt talál, hogy bizonyítsa rátermettségét. Nézz körül itt az őrhelyen, és mindenképp látogass el a Zoram-partra is, mert a Hordának ott is van egy másik őrhelye.$B$BJelenléted itt azt mondja nekem, hogy a vadászatról szeretnél többet megtudni. Figyelj jól, és szívesen megosztom veled, amit tudnod kell.' WHERE ID=235;
UPDATE quest_offer_reward SET RewardText='Kiváló! Ez napokra elegendő tüzelőt ad a háború lángjainak.' WHERE ID=236;
UPDATE quest_offer_reward SET RewardText='Jól teljesítetted a küldetésedet, $r. Maga a Király is büszke lenne rád.$b$bAz ígért erősítés azonban sosem érkezett meg. Úgy tűnik, a Szövetség frontja bíborvörös tengerré vált elesett testvéreink vérétől. A veszteségek híre keserű ízt hagy az ember szájában. De nem hagyhatjuk, hogy haláluk hiábavaló legyen. Össze kell fognunk ezekben a komor időkben, és vissza kell hoznunk a dicsőséget a Szövetségnek.$b$bBeszélj Wallbang hegymászóval az áthelyezésért. Most nagyobb szükség van rád, mint valaha.' WHERE ID=237;
UPDATE quest_offer_reward SET RewardText='Jó - örömömre szolgál olyasvalakivel dolgozni, aki büszke arra, hogy nem vesztegeti az időmet.$b$bMiután elvégzek néhány módosítást ezen a készleten, készen fogsz állni a terepre indulásra. Ezt fogod használni, hogy létfontosságú adatokat gyűjts a feladathoz.$b$bCsak egy pillanat, amíg befejezem a módosításokat. Amíg vársz, valószínűleg érdemes lenne elgondolkodnod azon, mit szeretnél magaddal vinni a sivatagba.$b$bIgen, azt mondtam, sivatag.' WHERE ID=238;
UPDATE quest_offer_reward SET RewardText='Dughan marsall küldött, mi? Nos, nem a hadseregtől vagy, de ha Dughan küldött, az elég jó nekem!$b$bA helyzetünk, enyhén szólva, feszült. Remélem, tudsz segíteni nekünk.' WHERE ID=239;
UPDATE quest_offer_reward SET RewardText='Aha! Köszönöm, $N. Ezek pont jókor jöttek!$B$BÉs tessék, hadd fizessek ezekért!' WHERE ID=240;
UPDATE quest_offer_reward SET RewardText='Ó, a 4711-FTZ modellű energiaforrásaink! Általában a vízkutak működtetésére használjuk őket, de A ROHADT NOMÁDOKNAK KÖSZÖNHETŐEN most bőségesen van energiaforrásunk.$b$bPersze, szerezhetek neked egy energiaforrást bármilyen aljas tudományos kísérlethez, amit szerintem próbálsz eltitkolni előlem. Nem lesz ingyenes viszont, $R. Semmi sem ingyenes Gadgetzanben.' WHERE ID=243;
UPDATE quest_offer_reward SET RewardText='Redridge-i gnollok ilyen közel Elwynnhez?? Talán készen állnak, hogy előrenyomuljanak a szülőföldünkre. Hamarosan talán nem csak Lakeshire népe lesz ostrom alatt!$b$bItt a fizetséged, bár baljós hírt hoztál. És rossz időben jön, mert nem vagyunk felkészülve rá.' WHERE ID=244;
UPDATE quest_offer_reward SET RewardText='Á! Visszatértél. És úgy tűnik, nem estél át túl sok viszontagságon. Persze, $N, az Éjjeli Őrség hálás a munkádért, és megígértem a jutalmadat, szóval tessék.' WHERE ID=245;
UPDATE quest_offer_reward SET RewardText='<Feldon helyettes meghallgatja a jelentésedet...>$b$bJelentős méretű gnollcsapat táborozik ott, és amit mondasz, azok kemény ellenfelek. Nem lehetett könnyű megszerezni ezt az információt.$b$bTessék, $N. Hálásak vagyunk a segítségedért.$b$bÉs ha még nem tetted, beszélj Marris marsallal és Solomon bíróval Lakeshire-ben. A helyzetünk egyre kétségbeejtőbb - biztos vagyok benne, hogy szükségük lesz rád.' WHERE ID=246;
UPDATE quest_offer_reward SET RewardText='$N, megölted mindhárom fenevadat, amelyek az Ashenvale-i Vadászatot alkotják. Kellő bizonyítékot hoztál nekem pusztulásukról; erőd és kitartásod kétségtelen. Vadász vére csordogál az ereidben, dicséretet érdemelsz!$B$BKérlek, fogadd el ezt a csecsebecsét gratulációként hatalmas tetteidért, amiket ma Ashenvale-ben tettél a Hordáért. Vigyázzanak rád az őseid!' WHERE ID=247;
UPDATE quest_offer_reward SET RewardText='Megfelelő edénye az Azora Glyph-nek, lehetővé téve Theocritusnak, hogy behatoljon a Stonewatch Keepen belüli elmékbe.' WHERE ID=248;
UPDATE quest_offer_reward SET RewardText='Jól teljesítettél, $N. Morganth boszorkánymester legyőzésével Stormwind megmenekült egy súlyos veszélytől.$B$BAlázatosan felajánlom neked ezt a jutalmat. És békét kívánnék neked, ha ezek békés idők lennének.$B$BDe ehelyett szerencsét kívánok próbáidhoz, és győzelmet az előttünk álló konfliktusokban.' WHERE ID=249;
UPDATE quest_offer_reward SET RewardText='A gyanúsan kinéző hordó furcsa szagú port tartalmaz.' WHERE ID=250;
UPDATE quest_offer_reward SET RewardText='<Sirra elkezdi lefordítani az üzenetet...>' WHERE ID=251;
UPDATE quest_offer_reward SET RewardText='<Ello elolvassa a levelet... és elsápad. Aztán rád néz...>$b$bBár a segítség, amit Abercrombie-nak adtál, jóindulatból fakadhatott, tetteid vesztét okozták a városunknak.$b$b<Ello elmerül gondolataiban...>' WHERE ID=252;
UPDATE quest_offer_reward SET RewardText='Sikerült! A szívében rejlő mágia védelmet nyújt a Balzsamozó gonoszsága ellen, és hatalmas pajzsot ad Darkshire városa fölé.$B$BNagyszerű dolgot tettél népünkért, $N. A neved örökre megmarad krónikáinkban.' WHERE ID=253;
UPDATE quest_offer_reward SET RewardText='Átássz magad a sír fölötti félig laza földön... és egy koporsó maradványaira bukkansz.$B$BA koporsón belül karmos ujjak vibráló kaparászását és rothadt fogak csikorgását érzed...$B$BKinyitod a koporsót, hogy megszerezd a Balzsamozó szívét?' WHERE ID=254;
UPDATE quest_offer_reward SET RewardText='Ó, ez remek hír! Erőfeszítéseidet nagyra értékelem, akárcsak Thelsamar népe. Ami még jobb, ha meg tudjuk oldani az ogre-problémát, átirányíthatjuk figyelmünket azokra a Fényt gyűlölő troggokra.' WHERE ID=255;
UPDATE quest_offer_reward SET RewardText='Fúj! Mi ez a dolog? És miért hoztad ide...$b$bAz áldóját--! Tényleg? Nos, égessen meg a Fény, ez annak az átkozott ogrénak a feje? Ez akkor bizony szép fogás! Tessék, a jutalmad, és köszönet tőlem meg Thelsamar népétől.' WHERE ID=256;
UPDATE quest_offer_reward SET RewardText='Mi? Siker?$B$BHidd el nekem, $Nama, ne hagyd, hogy a fejedbe szálljon. Úgy értem, bármelyik borotválatlan fiú íjjal lelőhette volna ezeket a... apró példányokat. És remélem, nem élvezed túlságosan a keselyűk ölését, igaz? Nem szeretnénk, ha kihalnának.$B$BNos, öhm... Sose mondja senki, hogy a Merész Daryl nem tartja be a szavát.' WHERE ID=257;
UPDATE quest_offer_reward SET RewardText='Kicsit viseltesnek tűnsz. Kétségkívül a vadkanok okoztak némi bajt, mi? Ne aggódj, diszkrét leszek a küzdelmeddel kapcsolatban, el tudom képzelni, milyen nehéz lehet neked pletykálkodó nyelvek vádaskodása nélkül is.$B$BÓ! Sikerült megölnöd a vadkanokat? Én... nos, vagyis... vagyis nem lep meg! Bármelyik gyerek meg tudta volna-- fogadás?$B$BMilyen fogadás?' WHERE ID=258;
UPDATE quest_offer_reward SET RewardText='Bebizonyítottad az eltökéltségedet, és a Skarlát Kereszteslovagok dicsérnek téged.$B$BHa nem riadsz vissza az igaz mészárlástól, talán a te utad is minálunk vezet tovább...' WHERE ID=261;
UPDATE quest_offer_reward SET RewardText='Hmm... valaki nemrég a kezében tartotta ezt a könyvet, valaki, akit bosszúvágy hajt. De a rajta hagyott nyomok, legalábbis az eredeti tulajdonos nyomai, halványak.$b$bAzt viszont meg tudom mondani, hogy a könyv eredeti tulajdonosa nem darkshire-i születésű.' WHERE ID=262;
UPDATE quest_offer_reward SET RewardText='Abban a pillanatban tudtam, ahogy megláttalak, $N, hogy büszkévé teszed majd Ironforge-ot. Jól szolgáltad Magni királyt. Most, hogy bebizonyítottad, milyen hűséges segítője vagy a Királyságnak, talán érdemes lenne beszélned a kapitánnyal, hátha rád bíz egy magasabb beosztást.$B$BTisztelgek előtted, $N.' WHERE ID=263;
UPDATE quest_offer_reward SET RewardText='A hitvány medált a sírra helyezed, és a foglalatban lévő drágakő láthatóan elhomályosul.$b$bAhogy felállsz, hogy elmenj, lenézel a medálra; élettelenül hever a koporsó tetejére faragott dombormű kezein. Gondolataidat egy hűvös, erős szellő szakítja meg, amely átsuhan a Sírkerten. Egy pillanatra minden elcsendesedik körülötted.' WHERE ID=264;
-- quest_offer_reward.RewardText. Batch 6: quest IDs 265-315.

UPDATE quest_offer_reward SET RewardText='Ó, igen. Egy hónapja eladtam ezt a könyvet egy gyanús alaknak. Nem mondta meg a nevét, de ideges, nyugtalan fickó volt, folyton hátranézett.$B$BRemélem, ez segít neked...' WHERE ID=265;
UPDATE quest_offer_reward SET RewardText='Ó igen, emlékszem erre a könyvre. A tulajdonosa néhány napra kivett egy szobát, és éjszakánként a bárban írt.$B$BSietve elhagyta a várost, motyogva valamiről, ami üldözi... valami. Amikor utoljára láttam, nyugat felé tartott ki a városból, új rejtekhelyet keresve.$B$BAz első hely, amit nyugat felé találna, Raven Hill...' WHERE ID=266;
UPDATE quest_offer_reward SET RewardText='Igazán le vagyok nyűgözve, $N. Nagy szolgálatot tettél a törp fajnak azzal, hogy megvédted a földjeinket. Maga Magni Bronzebeard király is büszke lenne rád!' WHERE ID=267;
UPDATE quest_offer_reward SET RewardText='Ez a napló sok mindent megmagyaráz nekem, és a sötét lovasok elleni útra állít! Láttam ezeket a lovasokat Duskwoodban, és láttam, ahogy beszélnek Morbent Fel varázslóval, a Forlorn Rowe-nál.' WHERE ID=268;
UPDATE quest_offer_reward SET RewardText='<Elolvasva a naplót, és meghallgatva szándékodat...>$B$BEgy gonosz szennyeződés vetette meg lábát a már amúgy is ostromlott Duskwoodban. Hálát adok a Fénynek, hogy egy hozzád hasonló hőssel nézhetünk szembe vele.$B$BDe először fel kell készülnöd a közelgő próbatételre... mert Morbent Fel nekromanta rendkívül hatalmas, és sötét varázslatokat vetett magára, hogy megvédje magát a fizikai támadásoktól. Ha le akarod győzni, olyan fegyverre lesz szükséged, amely ellenáll ezeknek a védelmeknek.' WHERE ID=269;
UPDATE quest_offer_reward SET RewardText='A Lightforge vas értékes fém, de úgy hangzik, a küldetésed komoly. Hosszú utat tettél meg, $gtestvér:testvérem;. Szerencsével talán megtalálod, amit keresel!$B$BÉs ha megszerzed a vasat, tudom, ki tudja fegyverré kovácsolni azzal a nekromantával szemben, akiről Duskwoodban beszélsz.' WHERE ID=270;
UPDATE quest_offer_reward SET RewardText='Öhm... ez meg mi? Egy medve feje, úgy néz ki.$B$B<Öntudatlanul végigsimítja az ujjával a sebhelyét.>$B$BNos, ez elég érdekes zsákmány, mondhatom. Csak nem az a medve, régről...$B$B<Elhallgat, majd láthatóan remegni kezd.>$B$BÓ, vidd innen, vidd innen! Vidd ki innen azt a rémséget!' WHERE ID=271;
UPDATE quest_offer_reward SET RewardText='Teljesítetted a Tengerioroszlán Próbáját, $N - gratulálok.$B$BA medál megszerzésének minden feladata megmutatja, hogy mind a fürgeség, mind az állóképesség szükséges ahhoz, hogy összhangban cselekedj a víz alatt kívánt dolgokkal. Egyik sem létezhet a másik nélkül, és egyik sem valósítható meg anélkül, hogy hajlandó lennél magadévá tenni a tengerioroszlán alakját.$B$BJegyezd meg jól ezeket a leckéket, és számíts rájuk, ha megszerezted a vízi alakodat.' WHERE ID=272;
UPDATE quest_offer_reward SET RewardText='Hmpf, egy Dark Iron rajtaütésnél többre lesz szükség, hogy megállítsák a szállításokat!$b$bDe Saean... sosem gyanítottam volna, hogy az egyik szimpatizánsuk. Már majdnem egy éve dolgozunk vele... talán elnéztem a jeleket.$b$bNos, ezen később gondolkodom.' WHERE ID=273;
UPDATE quest_offer_reward SET RewardText='Egy hatástalanító kolloid? Seaforiumhoz? Ó, egek!' WHERE ID=274;
UPDATE quest_offer_reward SET RewardText='Ez a föld megnyugszik erőfeszítéseidnek köszönhetően, és ezért ajándékot adok neked.' WHERE ID=275;
UPDATE quest_offer_reward SET RewardText='A gnollok számának csökkentésével gondját viselted a Wetlands egészségének. Bár a néped iránti bizalmam próbára lett téve a múltban, $R, talán még helyreállhat.' WHERE ID=276;
UPDATE quest_offer_reward SET RewardText='... köszönöm. Összezúzom ezeket a kovaköveket, és a tengerbe vetem őket, hogy sose lehessen többé élő fát felgyújtani velük.' WHERE ID=277;
UPDATE quest_offer_reward SET RewardText='Épp időben, $N!' WHERE ID=278;
UPDATE quest_offer_reward SET RewardText='Ó, szép munka, $N.$b$bFogadd el ezt fizetségül a Kereskedelmi Flottával kötött szerződésed teljesítéséért.' WHERE ID=279;
UPDATE quest_offer_reward SET RewardText='A hordó kissé sistereg, ahogy a hatástalanító keverék leülepedik.' WHERE ID=280;
UPDATE quest_offer_reward SET RewardText='Ezt a ládát karmolásnyomok és vízkár jelei borítják. Kinyitva átázott, rothadt szalmát találsz benne, mintha valami értékeset tároltak volna a ládában. Átkutatod a szalmát...$B$B...és egy karnyi vörös színű üveget találsz.' WHERE ID=281;
UPDATE quest_offer_reward SET RewardText='Hm, nos, ha Whitebeard fontos ügyben küld Dun Moroghba, nem igazán állíthatlak meg, ugye?$b$bLegalább adjak néhány tanácsot és útbaigazítást.' WHERE ID=282;
UPDATE quest_offer_reward SET RewardText='Nagyon köszönöm, $N!! Megmentetted a Stonewrought-gátat! Nélküled a Dark Iron terroristák biztosan elpusztították volna ezt a hatalmas mérföldkövet. Büszkévé tetted a Királyságot és a Szövetséget, bátor $c.$b$bA gát ismét biztonságos... legalábbis egyelőre...' WHERE ID=283;
UPDATE quest_offer_reward SET RewardText='Ez a hordó nagyrészt érintetlen. Kinyitva...$B$B...a sajt csípős szaga csap meg. Kicsit nedves, de még mindig ízletes!' WHERE ID=284;
UPDATE quest_offer_reward SET RewardText='Ez a hordó félig el van temetve a sárban és a fűben...' WHERE ID=285;
UPDATE quest_offer_reward SET RewardText='A Blind Princess kapitánya megkönnyebbülve hallja majd, hogy ez a becses szállítmány előkerült. Jól kiérdemelted ezt a fizetséget a szolgálataidért.$B$BJó látni hozzád hasonló megbízható embereket, különösen ilyen próbára tevő időkben.' WHERE ID=286;
UPDATE quest_offer_reward SET RewardText='Á, $N! Nem hittem, hogy sok gondod lesz a hely megtalálásával, kiváló útmutatást adok, tudod...$b$bHadd fejezzem be a jelentésemet.$b$b<Elővesz egy papírt, és firkál rá egy pillanatra.>$b$bTessék! Nos, haha, ez tényleg mulatságos... nem bánnád, $N, ha megtennél nekem még egy utolsó szívességet?' WHERE ID=287;
UPDATE quest_offer_reward SET RewardText='Á! Ez pont jókor jön, és megoldja a nyelvet. Köszönöm, pajtás!' WHERE ID=288;
UPDATE quest_offer_reward SET RewardText='Köszönetem neked, $N. És átkozott testvéreim hálája is a tiéd.' WHERE ID=289;
UPDATE quest_offer_reward SET RewardText='A kulcs rozsdás, de pontosan illik a zárba.' WHERE ID=290;
UPDATE quest_offer_reward SET RewardText='<Gyorsan átfutja a jelentést.>$b$bA KIRÁLY felhatalmazásával?! Teljesen elment Magni esze! És az az átkozott Whitebeard... Saját kezébe vette a dolgokat, mi? A Szenátus egyáltalán nem fog örülni ennek.$b$bMi, még mindig itt vagy? Menj, mielőtt hívom az őröket!' WHERE ID=291;
UPDATE quest_offer_reward SET RewardText='Egy Paleth-szem? Elképesztő! Hmm... valami baj van ezzel. Az egyik hajóroncsban találtad? Nos, ez megmagyarázza! De... nem tudtam, hogy volt ilyen szemük a Harmadik Flottán...$B$BNem csoda, hogy Fitzsimmons annyira megrémült. Egy átkozott Paleth-szem nem tréfadolog.' WHERE ID=292;
UPDATE quest_offer_reward SET RewardText='Egy Paleth-szem. De ez sok szomorúságot látott... biztos szemtanúja volt egy szörnyű, szörnyű tragédiának.$b$bHadd tisztítsam meg, mert a Szemeket úgy teremtették, hogy fényesen ragyogjanak, és hatalmuk igen veszélyes lehet, ha így beszennyeződnek.' WHERE ID=293;
UPDATE quest_offer_reward SET RewardText='Az ölés piszkos üzlet, de jól végezted a dolgodat, $N. Ha nem lennék köteles a Kutatóval és Merrinnel maradni, ott lennék veled, hogy együtt ontsunk vért.' WHERE ID=294;
UPDATE quest_offer_reward SET RewardText='Remek munkát végeztél azoknak a raptoroknak a kiirtásával, $N!' WHERE ID=295;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Erőfeszítéseidet nem felejtjük el. Sok ártatlan törp halt meg ezen a helyen, egyszerűen csak a munkájukat végezve. A bosszú, amit ezekre a gonosz lényekre mértél, biztos kétszer is meggondoltatja velük, mielőtt még egyszer megtámadnák Magni király alattvalóit.' WHERE ID=296;
UPDATE quest_offer_reward SET RewardText='Megszerezted őket! Szép munka, $N!$B$BÉs nem tűnsz túl megviseltnek, még azok az őrjöngő troggok mellett sem. Rajtad tartom a szemem... van benned potenciál.' WHERE ID=297;
UPDATE quest_offer_reward SET RewardText='Fú! Ironbandnek gondjai vannak a troggokkal. Vajon a robbanóport az ásáshoz akarja, vagy a troggok elleni harchoz...$b$bNos, akárhogy is, jól elköltött por lesz!$b$bDe furcsa, hetekkel ezelőtt küldtem neki bőven robbanóport. Vajon hová lett...' WHERE ID=298;
UPDATE quest_offer_reward SET RewardText='Á, a Goaz-kő elkészült! Szép munka, $N. Valóban szép munka. Most már folytathatom ennek a titán írásnak a kényes fordítását. Már ki tudok venni új szavakat! Hmm... itt az áll: „Ősi Istenek... A Föld Alá Láncolva.” Ez valami epikus dolog kezdete.' WHERE ID=299;
UPDATE quest_offer_reward SET RewardText='Átkozott Ironband! Hetekkel ezelőtt küldtem neki egy rakomány robbanóport, de a jelentésében szó sem esik róla.$b$bSzóval... hová lett a robbanópor?!?' WHERE ID=301;
UPDATE quest_offer_reward SET RewardText='Mi? Stormpike azt akarja, hogy személyesen kísérd el a szállítmányt Ironbandhez?$b$bÉn... gondolom, ez rendben van, csak az a gond, hogy már elküldtem Huldart a hordárokkal, Mirannal és Saeannel. Épp lemaradtál róluk, nem sokkal ezelőtt indultak.' WHERE ID=302;
UPDATE quest_offer_reward SET RewardText='Jól teljesítetted a parancsaidat, $c. Bebizonyítottad, hogy vitéz katona és hűséges szolgája vagy Magni királynak, ezért tisztelgek előtted! A Dark Iron-tábor ellen kifejtett nyomásoddal most esélyünk van rá, hogy végleg kiűzzük őket a földjeinkről... ha csak megjelenne végre az az átkozott tartalék...' WHERE ID=303;
UPDATE quest_offer_reward SET RewardText='Az Aljas Balgaras végre halott. Bár halála nem hozza vissza azt a sok ártatlan törpöt, akik feleslegesen haltak meg a keze által, segít helyreállítani a túlélők lelki nyugalmát. Balgaras halálával a megmaradt Dark Iron söpredéket elég könnyű lesz kezelni. Most ki kell irtanunk őket, mielőtt új vezért küldenek ide.$B$BJól teljesítettél, $c.' WHERE ID=304;
UPDATE quest_offer_reward SET RewardText='Ó, hála az égnek, hogy itt vagy!' WHERE ID=305;
UPDATE quest_offer_reward SET RewardText='Micsoda szörnyű hír! Legalább hárman túlélték. De mikor ér véget a gyilkolás? Vágyom arra a napra, amikor Magni király alattvalói félelem nélkül élhetnek.' WHERE ID=306;
UPDATE quest_offer_reward SET RewardText='Sok koboldot láttál odabent? Alig várom a parancsot, hogy kitakarítsuk őket a bányából. A gondolat, hogy koszos kezeikkel a bányánkban kaparásznak, felkavarja a gyomromat!' WHERE ID=307;
UPDATE quest_offer_reward SET RewardText='Nekem? Igazi hős vagy, $N!' WHERE ID=308;
UPDATE quest_offer_reward SET RewardText='Ó, hála a Fénynek, hogy megvan a por. De aggasztó hírt is hoztál. Elgondolkodtató, hogy a Dark Ironoknak vannak szimpatizánsai, akik ilyen anyagokat tudnak beszerezni gaz terveikhez.$b$bEz valaki más gondja lesz, egy másik alkalommal. Nekem most jó célra kell fordítanom ezt a port.' WHERE ID=309;
UPDATE quest_offer_reward SET RewardText='Gyorsan elhelyezed Marleth Barleybrew Scalder hordóját a Thunderbrew hordók között.' WHERE ID=310;
UPDATE quest_offer_reward SET RewardText='Nem rossz, $N! Nehéz volt átjutni az őreiken?$B$BMindegy - sok köszönet, és ha valaha erős sörre vágysz, ne feledd a Barleybreweket!' WHERE ID=311;
UPDATE quest_offer_reward SET RewardText='Micsoda kedves lélek vagy, $N! Bátorságodnak köszönhetően nem fogok éhezni, amikor beköszönt a hideg évszak hófúvása.' WHERE ID=312;
UPDATE quest_offer_reward SET RewardText='Á igen, ezek a sörények remekül fognak működni! Nagy kitartást mutatsz, $c - fogadni mernék, hogy nagy dolgokat fogunk látni tőled.' WHERE ID=313;
UPDATE quest_offer_reward SET RewardText='Nagyon szép munka! Veron nagyon boldog lesz, amikor meghallja a jó hírt. Vagash megölése nem könnyű feladat. El tudom képzelni, hogy egy nap Magni király embereivel együtt harcolsz majd a Szövetség frontján.' WHERE ID=314;
UPDATE quest_offer_reward SET RewardText='Nagyszerű! Alig várom, hogy felhasználjam ezeket néhány receptemben. Van egy konkrét recept, amiben szerintem remekül fog működni...' WHERE ID=315;
-- quest_offer_reward.RewardText. Batch 7: quest IDs 317-369.

UPDATE quest_offer_reward SET RewardText='Magni szakállára, aztán sokat vadásztál!! Köszönöm, $N.' WHERE ID=317;
UPDATE quest_offer_reward SET RewardText='Bellowfiznek kell az Evershine-omból? Hm... rendben.' WHERE ID=318;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Jó lesz úgy dolgozni a mesterségünkön, hogy nem hallunk annyi morgást és horkantást a falu körül.' WHERE ID=319;
UPDATE quest_offer_reward SET RewardText='Igen, ez pont megteszi. Azt hiszem, most rögtön kinyitok egy üveget, és megkóstolom...' WHERE ID=320;
UPDATE quest_offer_reward SET RewardText='Ez a láda átázott, oldala megrepedt. Sok karcolásnyom éktelenkedik rajta belül és kívül is... mintha murlocok kutatták volna át, és ellopták volna a kincsét.$b$bDe a láda mélyén megbújik egyetlen Lightforge-rúd. Sajnos sokkal többre lesz szükség, hogy elegendő fém álljon rendelkezésre egy fegyver elkészítéséhez.' WHERE ID=321;
UPDATE quest_offer_reward SET RewardText='Elég figyelemre méltó a történeted. És Lightforge-vas! Évek óta nem dolgoztam ilyen fémmel. Megtiszteltetés lesz újra alkotni vele. És vissza kell térned hozzám a nekromanta elleni csatád történetével.$b$bDe elébe szaladunk a dolgoknak. Először a fegyvered Morbent Fel ellen...' WHERE ID=322;
UPDATE quest_offer_reward SET RewardText='Harci tudásod, $N, nem vonható kétségbe. Eltökéltséged talán átsegít minket Morbent Fel végzetéig!' WHERE ID=323;
UPDATE quest_offer_reward SET RewardText='Á, megtaláltad őket! Most kalapáljuk ezt a Lightforge-vasat valami hasznossá, mi?' WHERE ID=324;
UPDATE quest_offer_reward SET RewardText='Á, ez ellenállni fog annak a démon Morbent Felnek! Szép munka!$b$bKészen állsz. Morbent Fel el fog bukni.' WHERE ID=325;
UPDATE quest_offer_reward SET RewardText='Kinyitva a páncélszekrényt, egyértelmű, hogy itt tartja Herod az értékesebb érméit és tárgyait.' WHERE ID=328;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Ez az üzenet az a nyom, amire szükségünk van, hogy leleplezzük az árulót!' WHERE ID=329;
UPDATE quest_offer_reward SET RewardText='Ó, igen, megnézhetem neked. Lássuk csak... a múlt héten...$B$B...nahát, Merle közlegény volt beosztva Thorsennel. Egész múlt héten ugyanazok voltak az őrjárati időpontjaik.' WHERE ID=330;
UPDATE quest_offer_reward SET RewardText='Fájdalmas felfedeznem, hogy Merle árult el minket. Mindig bátor katona volt, és azt hittem, hűséges a szíve. De nagy megkönnyebbülés, hogy leleplezték - egy hozzá hasonló kémmel a soraink között... nem tartanánk ki sokáig Kurzen ezredessel szemben.' WHERE ID=331;
UPDATE quest_offer_reward SET RewardText='Á, szóval láttad Renatót? Nos, tessék, $G uram:asszonyom;. Egy üveg különleges pinot noir-unk. Nem találsz párját egész Azerothban!' WHERE ID=332;
UPDATE quest_offer_reward SET RewardText='Itt az áll, hogy Harlan üzlete virágzik. Ez jó hír, de kíváncsi vagyok, minek annyi páncél az embereknek. Nem hallottam nyílt háborúról... van valami, amit a nemesek nem mondanak el nekünk?$B$BNos, köszönöm, hogy elhoztad a kérést. Itt a fizetséged, és gondoskodom róla, hogy Harlan megkapja az ellátmányát.' WHERE ID=333;
UPDATE quest_offer_reward SET RewardText='Ó, a fenébe! Azt hittem, ha elfelejtem a készletemet, az megszabadít a munkától. Most úgy tűnik, segítenem kell a Larsonoknak a varrásban...$B$BÓ, hát. A móka majd később jön, gondolom.' WHERE ID=334;
UPDATE quest_offer_reward SET RewardText='Igazán kiváló! Ezek valóban remek minták!' WHERE ID=335;
UPDATE quest_offer_reward SET RewardText='Á, köszönöm, hogy elhoztad ezt a szép kinézetű sört, szolga. Tessék, egy rézpénz neked. Most pedig tűnj el a szemem elől, hadd élvezzem az italomat!' WHERE ID=336;
UPDATE quest_offer_reward SET RewardText='Ó, egek! Ez a könyv évekkel ezelőtt, még Stormwind újjáépítése előtt pihent utoljára ezeken a polcokon. Természetesen restaurálni kell majd, elég rossz állapotban van, de megtiszteltetés lenne elhelyezni a ritka könyvek gyűjteményünkben.$B$BKöszönöm, $N. Kérlek, fogadd el ezt fizetségül a könyv visszahozataláért!' WHERE ID=337;
UPDATE quest_offer_reward SET RewardText='Rengeteg bajtól kíméltél meg, $N! Nem tudok eléggé hálás lenni. Már nem tart sokáig, hogy Nesingwary mester könyvét lássuk a könyvtárakban szerte a világon!' WHERE ID=338;
UPDATE quest_offer_reward SET RewardText='Végre! Az I. fejezet kész!' WHERE ID=339;
UPDATE quest_offer_reward SET RewardText='A II. fejezet végre kész! Szép munka!' WHERE ID=340;
UPDATE quest_offer_reward SET RewardText='Fúh! Szép munka, $N. A III. fejezet most már egyben van újra!' WHERE ID=341;
UPDATE quest_offer_reward SET RewardText='Kiváló! Most már készen áll a IV. fejezet!' WHERE ID=342;
UPDATE quest_offer_reward SET RewardText='Kohászat? Á, igen, sok könyvünk van a témában, és örömmel segítünk Kristoff testvérnek a beszédéhez! Most... melyik konkrét könyvre volt szüksége a jó testvérnek?' WHERE ID=343;
UPDATE quest_offer_reward SET RewardText='Sheaf úr azon tűnődik, hol a könyve? Nos, ez kissé kínos. Nálam van a könyv, de még mindig a másolatomat készítem, és még nem állok készen visszaadni az eredetit!' WHERE ID=344;
UPDATE quest_offer_reward SET RewardText='Mit mondtál, mire van szükséged?? Talán nem vetted észre, de épp Lakeshire védelmének megerősítésével és a legutóbbi orktámadások okozta károk helyreállításával vagyunk elfoglalva. Ha Rethban vasércre van szükséged, magadnak kell megszerezned!' WHERE ID=345;
UPDATE quest_offer_reward SET RewardText='Ez az! Köszönöm, $N. Ragyogjon fényesen a Fény testedre és lelkedre egyaránt!' WHERE ID=346;
UPDATE quest_offer_reward SET RewardText='Ó, pompás! Ezzel az érccel el tudom készíteni a festékemet, és be tudom fejezni a Vas feszültségei másolását.$B$BKöszönöm, $N!' WHERE ID=347;
UPDATE quest_offer_reward SET RewardText='...érzem, visszatér az erőm...$b$bHol lehetek? Booty Bay-ben? Egek! Milyen furcsa álmom volt...$b$b...a gyengeség nem múlt el teljesen...' WHERE ID=348;
UPDATE quest_offer_reward SET RewardText='Unbagwa varázsdoktor szereti a gorillaagyarakat! Érted beszélek a szellemekkel. Elhozom a Vad Mokkot.$b$bDe megvéded Unbagwa varázsdoktort a többi gorillafenevadtól, különben nincs Mokk neked!' WHERE ID=349;
UPDATE quest_offer_reward SET RewardText='Viccelsz? Shaw megint a segítségemet akarja? Micsoda pofátlanság...$b$bA Defias Testvériség, azt mondod? Nos, te aztán csodás híreket hozol, nem igaz? Legközelebb azt fogod mondani, hogy Deathwing még életben van, és a várost támadja.$b$bRendben, mondj el mindent az elejétől. És ne hagyj ki semmit, amiről azt gondolod, talán nem fontos. Mindent tudnom kell.' WHERE ID=350;
UPDATE quest_offer_reward SET RewardText='Beteszed a tojást... a vészjelzőt... a csirkébe... az önvezérlő robotba.$B$BZümmögés és zúgás hallatszik a robot belsejéből, ahogy próbál felállni. Miután a robot életre kel, Oglethorpe hangja hallatszik ismét, de most a robot belsejéből:$B$B„Az OOX-17/TN legalább működik, de komoly javításra szorul! Túl nehéz ahhoz, hogy elvidd magaddal... de azt hiszem, van egy ötletem. Vállalod, hogy még egy kicsit vigyázol rá?”' WHERE ID=351;
UPDATE quest_offer_reward SET RewardText='Aha! Szóval Grimand végre befejezte a fejszémet! Alig várom, hogy kipróbáljam néhány troggon és koboldon!$b$bSok köszönet, $N. Hosszú utat kellett megtenni ezért a szállításért. Itt néhány érme az erőfeszítéseidért.' WHERE ID=353;
UPDATE quest_offer_reward SET RewardText='A bosszúnak édes íze van, nem gondolod? Amikor elpusztítottad az Agamandokat, észleltél bennük némi szabad akaratot? Remélem. Remélem, féltek, mielőtt szétzúzták őket a semmibe.$b$bTudom, bolond remény ez. De mégis dédelgetem.' WHERE ID=354;
UPDATE quest_offer_reward SET RewardText='Coleman jól beszél rólad, $N, meséli sikeres kirándulásaidat az Agamand-malmokba.$b$bAz Elhagyatottaknak ismét szükségük van a tehetségedre...' WHERE ID=355;
UPDATE quest_offer_reward SET RewardText='Nagyon jó. Erőfeszítéseid sokat segítenek távol tartani a Csapást. Dicséretet küldök a felettesemnek, Zygand végrehajtónak.' WHERE ID=356;
UPDATE quest_offer_reward SET RewardText='Nagyon jó, $N. Tanulmányozni fogom ezt a könyvet, és megállapítom annak a lichnek a kilétét. Jól szolgáltad Királynődet.$B$B<Bethor kinyitja a könyvet, és feszülten bámulja a ragyogó lapjait...>$B$BLenyűgöző! A könyv, amit visszahoztál, nem másé, mint Gunther Arcanusé!$B$BGunther ügyes nekromanta volt életében; barátok és bajtársak voltunk, a Csapás előtt. És ítélve a könyvéből, halálában még hatalmasabbá vált.$B$BA tudása nagy áldás lenne számunkra.' WHERE ID=357;
UPDATE quest_offer_reward SET RewardText='Szakszerűen elvégezve, $N. A Csapás téved, ha azt hiszi, felhasználhatja azokat a holttesteket ellenünk, és a folyadékot, amit a Rot Hide rabszolgáktól gyűjtöttél, alkimistáink tanulmányozni fogják. Talán olyan titkokat rejt, amit felhasználhatunk ellenük.$b$bAhogy mondtam, szép munka. De küzdelmünk folytatódik, és a konfliktus biztosan több esélyt is ad majd, hogy bizonyítsd értékedet az Elhagyatottaknak.' WHERE ID=358;
UPDATE quest_offer_reward SET RewardText='Sevren bíró jelentést akar? Rendben: a The Bulwark védői a Csapás nagy részét feltartóztatják, de néha átjut néhány közülük.$b$bIdőszakos Csapás-aktivitást észleltünk ettől az állomástól keletre, a Balnir-tanya körül összpontosulva.' WHERE ID=359;
UPDATE quest_offer_reward SET RewardText='Nyugtalanító hallani, hogy a Csapás átjut a The Bulwarkon. A Lichkirály és szolgái szüntelenül támadnak.$B$BDe nem adjuk fel. Nem fog ismét megkaparintani minket!' WHERE ID=360;
UPDATE quest_offer_reward SET RewardText='Ó... szegény Thurmanem! Könyörögtem neki, hogy hagyja el az Agamand-malmokat velem és apámmal, de a családja iránti hűsége túl erős volt! És tudtam! Tudtam, hogy Brand ártani akar neki!! Ó, átkozott legyen ez a Csapás és a Kór!$B$B<Yvette arca ekkor kisimul, és hidegé válik.>$B$BDe a megbánás a gyengéknek való. Elhagyatottként új céljaim vannak, és a szerelem nincs köztük. Köszönöm, hogy kézbesítetted ezt a levelet, mert kíváncsi voltam, mi lett egykori szerelmemmel.$B$BDe az az élet véget ért. Örökre.' WHERE ID=361;
UPDATE quest_offer_reward SET RewardText='Köszönöm. Devlin csontjai szépen fognak pihenni a kandallópárkányomon.$b$bHa hideg szívem képes melegséget találni, az abban van, hogy tudom, az Agamandok elpusztultak. Cserbenhagytak engem és a családomat, amikor eljött a Csapás - most esküszöm, sarkam alá tiprom a maradványaikat!' WHERE ID=362;
UPDATE quest_offer_reward SET RewardText='Még egy a járkáló holtak közül, mi? Biztos komoly sokk volt felébredni a kriptában, ahol csak a hideg és Mordo várt rád...$b$bLátom a zavart az arcodon. Hadd próbáljam meg elmagyarázni neked a... helyzetünket...$b$bÚj vezérünk, Lady Sylvanas szabadított meg minket a Lichkirály uralmától. A Sötét Úrnő vezet minket a gyűlölt Csapás elleni háborúnkban, és az emberiség maradékai ellen, akik minden lépésünket követik.' WHERE ID=363;
UPDATE quest_offer_reward SET RewardText='Sajnálatos, hogy a Csapást nem lehet a soraink közé vonni, nagy számuk hasznos lenne az előttünk álló csatákban.$b$bDe nem fognak csatlakozni hozzánk, így nincs más választásunk, mint elpusztítani őket.' WHERE ID=364;
UPDATE quest_offer_reward SET RewardText='Jól teljesítetted a rád bízott feladatot, ifjú $c. Bebizonyítod, hogy igazi értéket jelentesz a Sötét Úrnő seregének.' WHERE ID=365;
UPDATE quest_offer_reward SET RewardText='A könyvem?!? Szóval te voltál a tolvaj, aki ellopta!$b$bDe... mi ez az új varázslat rajta... Bethor? Ő Lordaeronban van?$b$bHa még létezik, akkor talán ő is megmenekült a Lichkirály karmai közül...' WHERE ID=366;
UPDATE quest_offer_reward SET RewardText='Jól teljesítettél, $N, és köszönöm az erőfeszítéseidet.' WHERE ID=367;
UPDATE quest_offer_reward SET RewardText='A pikkelyek tökéletesek, $N. Pontosan ez kellett ehhez a keverékhez.' WHERE ID=368;
UPDATE quest_offer_reward SET RewardText='Á, ez a méreg tökéletesen megteszi, $N. Minden mást hozzáadtam már a keverékemhez, és lefőztem. Végre készen állok kipróbálni ezt az új halálos szert!' WHERE ID=369;
-- quest_offer_reward.RewardText. Batch 8: quest IDs 370-422.

UPDATE quest_offer_reward SET RewardText='Perrine kapitány halála kétségkívül örömet okoz majd a Sötét Úrnőnek. Jól teljesítetted a feladatodat, $c.' WHERE ID=370;
UPDATE quest_offer_reward SET RewardText='Vachon kapitány halála jelentősen lelassítja majd a Skarlát Kereszteslovagok előrenyomulását Tirisfalban. De más fenyegetések is fennállnak.' WHERE ID=371;
UPDATE quest_offer_reward SET RewardText='Rendkívül jól teljesítettél, $c. Hozzád hasonló könyörtelen harcosokkal, akik az Elhagyatottak nevében hódítanak, fajunk egy lépéssel közelebb kerül ahhoz, hogy egyszer s mindenkorra legyőzzük Arthast. Jó érzésem van veled kapcsolatban, bajtárs.' WHERE ID=372;
UPDATE quest_offer_reward SET RewardText='Edwin VanCleef, azt mondod? Ugyanannyira várnék levelet a halott nagyanyámtól... Szóval megölted? Bocsáss meg, hogy ezt mondom, de kissé meglepődtem. Fiatalabb korában páratlan harcos volt. Lássuk, mit tart annyira fontosnak, hogy megírja nekem, ennyi év után.$b$b<Baros átfutja a levelet.>$b$bEdwin... látom, az évek egy cseppet sem változtattak rajtad, ugyanolyan idealista vagy, mint mindig, és romantikus. Nem érdekli, kinek árt, $N. A bosszú emésztette fel. De hát nem is vagyok biztos benne, hogy hibáztathatom érte.' WHERE ID=373;
UPDATE quest_offer_reward SET RewardText='Varimathras büszke lenne rád. Jól szolgálod a vezetőidet, $c.' WHERE ID=374;
UPDATE quest_offer_reward SET RewardText='Nagyra értékelem az erőfeszítéseidet, $N. Bárcsak Sylvanas egy napon elismerné a bátorságodat...' WHERE ID=375;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Ez a páncél segítségedre lesz.$b$bRemélhetőleg többet ér neked, mint az utolsó embernek, aki viselte...' WHERE ID=376;
UPDATE quest_offer_reward SET RewardText='Szóval Dextren Ward végre megfizetett az emberiség elleni bűneiért? Jó, hogy megszabadultunk attól a söpredéktől, mondom én. Egészségedre, barátom! Nemcsak hogy megadtad a halottak családjainak a megérdemelt lelki nyugalmat, de éles üzenetet is küldtél azoknak a korrupt bürokratáknak a Nemesek Házában. Stormwindnak fel kell nőnie Duskwood népének szükségleteihez, vagy kitörünk a zsarnokságuk alól.' WHERE ID=377;
UPDATE quest_offer_reward SET RewardText='Szóval Kam Deepfury végre megérezte, milyen a Halál másik oldalán állni? Jó. Ez jár a gyáva Dark Iron söpredéknek. Jól teljesítettél, $c. A Thandol Span-i támadás áldozatai csak egyszerű áldozatai voltak egy háborútól és nyugtalanságtól szaggatott világnak. A családjaik megnyugvással tudhatják, hogy Deepfury megkapta a megérdemelt büntetést. Longbraid bátyjának halálát megbosszulták.' WHERE ID=378;
UPDATE quest_offer_reward SET RewardText='Kiváló, tiéd az energiaforrás. Nos, nem teljesen erre a fajta tudományos készletre tervezték, szóval csak korlátozott ideig lesz meg, mielőtt minden összegyűjtött adatod bumm-á válik!$B$BAmikor összegyűjtöttél mindent, amire szükséged van, hozd vissza hozzám, és megfelelően leállítom. Legfeljebb két órád lesz, hogy elvégezd, amit el kell végezned.$B$BHa nem sikerül időben, mindig eladhatok neked egy másik energiaforrást, hogy újra próbálkozz. Jól hallottad - eladhatok!' WHERE ID=379;
UPDATE quest_offer_reward SET RewardText='Hmm, nos, ez egy kezdet. Néhány hétbe vagy hónapba fog telni, hogy teljesen felszámoljuk a fertőzést. Utána le kell mennünk néhány fáklyával, hogy elégessük a hálókat.$b$bJól teljesítetted a kötelességedet, $N, biztos vagyok benne, hogy találok neked más feladatot is.' WHERE ID=380;
UPDATE quest_offer_reward SET RewardText='Bárcsak hallgatnának az észérvekre, mi, $N? Talán leültethetnénk őket egy értelmes megbeszélésre... ha!$b$bA Fénytől elvakult bolondok.' WHERE ID=381;
UPDATE quest_offer_reward SET RewardText='Hmm... lássuk, mit hoztál...$b$b<Átlapozza a visszaszerzett dokumentumokat.>$b$bNéhány hír a velünk szembeni akcióikról... Értéktelen. Felderítő jelentések... Új parancsok, „Folytatni a tábor kiépítését a romos város közelében...” Semmi, amit ne tudtunk volna már... Á, ez meg mi? Egy térkép néhány mezőparancsnokuk és ügynökük elhelyezkedéséről! Ezt tudjuk használni.' WHERE ID=382;
UPDATE quest_offer_reward SET RewardText='Igen, ez nagyon jó. Jól teljesítettél, hogy megszerezted ezt az információt, $N. Hmm... tisztjeik nevei a Tirisfal-tisztásokon...$b$bKépzeld el, milyen csapást mérhetnénk azoknak a véres fanatikusoknak a moráljára, ha egyetlen gyors csapással megölnénk a vezetőiket.' WHERE ID=383;
UPDATE quest_offer_reward SET RewardText='A maláta lefőzve, a vadkanok halottak,$BÉs mielőtt bármit is mondanánk, vagy csinálnánk holnap,$BHarcolnunk kell majd, ki kapja meg elsőnek$BEzeket az ízletes, sörben pácolt vaddisznóbordákat!' WHERE ID=384;
UPDATE quest_offer_reward SET RewardText='Nos, ezek kiváló példányok, amiket összegyűjtöttél, $N. Jó pénzt ér a kiváló minőségű anyag, az biztos.' WHERE ID=385;
UPDATE quest_offer_reward SET RewardText='A Rettegett Targorr végre elnyerte a végzetét. Én örülök, hogy hallom, a fenevad most már tudja, milyen a Halál könyörtelen markának másik oldalán lenni. Jól teljesítettél, $N. Néha a legigazibb igazságszolgáltatás csak a bíróságon kívül, a politika homályos látásmódján túl található meg.' WHERE ID=386;
UPDATE quest_offer_reward SET RewardText='Erőfeszítéseid a Börtönben vitézek voltak, $N. Nyilvánvaló, hogy ez a probléma nagyobb, mint mi ketten együtt. De jól teljesítettél, és ezért hálás vagyok.' WHERE ID=387;
UPDATE quest_offer_reward SET RewardText='Szóval ezek a fejkendők -- a romlottság mocskos jelei -- azok, amiért a Macemnek meg kellett halnia? Micsoda pazarlás. Micsoda tragikus áldozat.$b$bDe sajnos nem térhetek vissza a múltba. Csak tudd, $N, hogy tetteiddel igazságot szolgáltattál a családomnak.' WHERE ID=388;
UPDATE quest_offer_reward SET RewardText='Mi a Fényre akarsz? Nem látod, hogy válsághelyzetünk van itt?$b$bBazil Thredd?! Miért akarnál beszélni azzal a gazemberrel? Honnan tudjam, hogy nem az egyik cimborája vagy, aki lejött, hogy segítsen a véres lázadásában? Ha nem lenne minden átkozott cella nyitva, talán bezárnálak egybe egy időre!' WHERE ID=389;
UPDATE quest_offer_reward SET RewardText='Thredd vezetése nélkül remélhetőleg jobban kezelhetők lesznek a zavargások. Majd meglátjuk.$B$BMeg kell mondjam, fél óra után alig számítottam rá, hogy kijössz, de úgy tűnik, félreismertelek.$B$BAkkor gondolom, nem sikerült sok hasznos információt kiszedned belőle? De tudok egy-két dolgot Thredd tevékenységéről, ami érdekelhet.' WHERE ID=391;
UPDATE quest_offer_reward SET RewardText='Hmm. Maelik? Nem, ez a név nem ismerős, és ez a leírás sem. De bárki lehet! Egy egykori kőműves, a Defias Testvériség egyik tagja... Bár ha annyira jó kapcsolatai vannak, ahogy Thelwater sejteti, talán valaki más felismeri. Hadd gondolkozzam.' WHERE ID=392;
UPDATE quest_offer_reward SET RewardText='Mi? Ez meg mi? Igen, azt hiszem, tudom, ki ez az ember, de a neve nem Maelik. A bérgyilkosok sok nevet és sok álarcot viselnek, és eldobják őket, amint elveszítik hasznukat. Egy másik álnév, amit ez az ember ismerten használ, Marzon; bár még ez sem biztos, hogy az igazi neve.$b$bMindenesetre bérgyilkos, és sokat tudok róla.$b$bMarzon jelenleg Lord Gregor Lescovar szolgálatában áll, aki még Stormwind nemességének romlottságához mérten is gyanús hírű uraság.' WHERE ID=393;
UPDATE quest_offer_reward SET RewardText='Szóval halott? Az igazságszolgáltatásod gyors volt, $N. Imádkozom a Fényhez, hogy sose váljak a zsákmányoddá!$b$b<Nevet, és vállon veregeti.>$b$bNem kritizálni akarlak, $N. Hogy is tehetném, hiszen minden bérgyilkos mestere vagyok? De valójában nagy szolgálatot tettél Stormwind népének, és ezért köszönöm.' WHERE ID=394;
UPDATE quest_offer_reward SET RewardText='Jó látni téged, $N. Hallottam, hogy Lord Gregor Lescovart nemrég holtan találták.$b$bÚgy tűnik, sikeres volt a küldetésed. Hálás vagyok, hogy megmentettél engem, és sok másikat is, VanCleef bosszújától.' WHERE ID=395;
UPDATE quest_offer_reward SET RewardText='Dicséretet érdemelsz a Stormwindnak tett szolgálatodért, $N. Ha VanCleefnek sikerültek volna a mesterkedései, kétségkívül jelentős kárt okozott volna a királyságnak - amit nyilvánvalóan el kell kerülnünk.$B$BFogadd el ezt, $c, elismerésem jeléül.' WHERE ID=396;
UPDATE quest_offer_reward SET RewardText='Mester mondja, adj ajándékot $N-nek. Zggi meg akarja tartani szép ajándékot, de Zggi tudja jobban, minthogy elárulja Mestert.' WHERE ID=397;
UPDATE quest_offer_reward SET RewardText='Maggot Eye aljas tetteit végre megbosszulták. Talán vitéz tetteid világos üzenetet küldenek azoknak, akik ártani akarnak a népünknek. Brill városa nevében köszönöm, $N.' WHERE ID=398;
UPDATE quest_offer_reward SET RewardText='Ó, köszönöm, $N! Gyakorlati hasznom nincs belőle, de az érzelmi értéke... Mondanom sem kell, köszönöm, hogy elhoztad nekem... a saját jólléted rovására is, arról nem is beszélve, mennyi időbe telt egészen Westfallig menni. Hálás vagyok, és fogadd el ezt köszönetem jeléül.' WHERE ID=399;
UPDATE quest_offer_reward SET RewardText='Nálad vannak a szerszámaim? Szép munka, fiam, szép munka! Épp egy órája törtem el az utolsó agyarcsavaromat, és kell egy ilyen, hogy befejezzem Stonegear pilóta ostromgépének javítását. Jól tetted, hogy idecipelted azokat a szerszámokat, $N.$b$bTessék, fogd ezeket az érméket a segítségedért.' WHERE ID=400;
UPDATE quest_offer_reward SET RewardText='Meg is van. Le van fordítva...$B$B<A levegő nehézzé válik, mintha egy vastag, fekete függönyt húznának a föld fölé...>' WHERE ID=401;
UPDATE quest_offer_reward SET RewardText='Ezt a sörös hordót Jarven Thunderbrew őrzi. Amíg ő a pincében van, egyetlen hordót sem lehet megbolygatni.' WHERE ID=403;
UPDATE quest_offer_reward SET RewardText='Szép munka. Sajnálom, hogy nem lehettem ott, hogy lássam, ahogy rothadó péppé zúzod azokat az élőholtakat!' WHERE ID=404;
UPDATE quest_offer_reward SET RewardText='Á, te vagy az az ügynök, akit Sevren bíró küldött. Akkor igen, fontos ügyed van velem.$b$bBízom benne, hogy Sevren megfelelő embert állított a feladatomra... de majd meglátjuk.' WHERE ID=405;
UPDATE quest_offer_reward SET RewardText='A Fényre! Végre ennivaló! Édes, édes tök...' WHERE ID=407;
UPDATE quest_offer_reward SET RewardText='Tetteid súlyos csapást mértek a Csapásra. És győzelmed nem marad észrevétlen - sem az Elhagyatottak, sem ellenségeink szemében.$b$bFolytasd a küzdelmet, ahogy mi is mindannyian tesszük, $N, és egy nap kiűzzük magát a Lichkirályt is Azerothból!' WHERE ID=408;
UPDATE quest_offer_reward SET RewardText='Legyőzted Lillith Nefarát, bizonyítva, hogy a Csapás ellensége vagy. Hihetetlen.$b$bAzt hittem, egyedül vagyok szabad akarattal rendelkező Élőholt, de megmutattad, vannak mások is, akik megtörték a Lichkirály uralmát.' WHERE ID=409;
UPDATE quest_offer_reward SET RewardText='A hívogatás gyertyáját az asztalra helyezed, és meggyújtod...' WHERE ID=410;
UPDATE quest_offer_reward SET RewardText='Sikerült meggyőznöd, hogy csatlakozzon hozzánk! Nagyszerű tettet vittél végbe az Elhagyatottakért, $N. A Sötét Úrnő értesítve lesz.' WHERE ID=411;
UPDATE quest_offer_reward SET RewardText='Ezek a giromechanikus fogaskerekek és stabilizáló fogaskerekek tökéletesen megfelelnek Ozzie tervrajzainak a Rekombobulációs Eszközhöz. Amint hozzáadok egy kis hidrokenőanyagot a belső égésű dugattyúkhoz, beállítom a forgattyú-racsnit, és növelem az elektrogumi gél viszkozitását, a gnóm faj úgy jó lesz, mint új.' WHERE ID=412;
UPDATE quest_offer_reward SET RewardText='<Barleybrew hegymászó megkóstolja a Shimmer Stoutot...>$B$BÓ. Hűha! Ez a cucc tényleg csillogást varázsol a szemedbe. Úgy érzem, látok a sötétben!' WHERE ID=413;
UPDATE quest_offer_reward SET RewardText='Nos, hadd kóstoljam meg...$b$bMagni szakállára! Ettől megpörög a fejed! És a végtagjaidat is könnyűvé teszi.$b$bÚgy érzem, tudok repülni!' WHERE ID=414;
UPDATE quest_offer_reward SET RewardText='$N! Tudod, azt a shimmerweedet, amit hoztál nekem? Nos, felhasználtam néhány receptben, amin dolgoztam, és az egyik nagyszerűen sikerült!$b$bTessék, próbáld ki, és mondd el, mit gondolsz...' WHERE ID=415;
UPDATE quest_offer_reward SET RewardText='Ugh! Amikor azokat a füleket kértem, nem tudtam, hogy ennyire büdösek lesznek!$b$bTessék a jutalmad, $N. Szép munka.' WHERE ID=416;
UPDATE quest_offer_reward SET RewardText='Ez komor hír, Hildelve jó barát volt. És bárcsak ott lehettem volna veled, amikor megtaláltad a fenevadat, Mangeclaw-t!$b$bKöszönöm, $N. Tettedre emlékezni fognak az Ironforge-i Ostromdandár pilótái.' WHERE ID=417;
UPDATE quest_offer_reward SET RewardText='Hidd el, ez sokkal nehezebbnek tűnik, mint amilyennek látszik, de...$b$bÓ, sosem ismertem senkit, aki különösebben érdeklődött volna a kolbászkészítés iránt, de azért megadom a receptet, hátha kell. Tessék, csak arra ügyelj, hogy frissen edd meg!' WHERE ID=418;
UPDATE quest_offer_reward SET RewardText='Itt egy törp holtteste -- széttépve, megfagyva, és a hegyi dögevők által kikoppasztva. Kezében egy könyvet szorongat, amely Mori Hildelve durván odafirkantott jegyzeteit tartalmazza. Testén, még mindig kiváló állapotban, egy Dandártábornoki Mellény van.$b$bEnnek a hátborzongató jelenetnek a helyszínén lelte halálát az ostromgép pilótája.' WHERE ID=419;
UPDATE quest_offer_reward SET RewardText='Ez meg mi? Á, a bátyám jelentése. Hmm...$b$bMondtam neki, hogy fogja vissza magát a Király nevének használatával, de nem hallgatott rám. Nem hiszem, hogy nagy baj lesz belőle, bár biztosan felkavarja a kedélyeket a Szenátusban. Nem mintha nem kellett volna néhány kedélyt felkavarni! Hah!$b$bMindenesetre gondolom, ez azt jelenti, hogy nekem is el kell küldenem a jelentésemet Ironforge-ba, de be kell vallanom, kicsit le vagyok maradva. Átkozottul hideg van.$b$bLesz majd számodra munkám később, ha érdekel.' WHERE ID=420;
UPDATE quest_offer_reward SET RewardText='Jól szolgáltál engem, $c. Egyértelmű számomra, hogy méltó segítőm leszel, amíg felkészülök arra, hogy megszabadítsam a Silverpine-erdőt Arugal átkától.' WHERE ID=421;
UPDATE quest_offer_reward SET RewardText='Pontosan ezt a varázslatot kerestem, $c. Ha az elköteleződésed a Sötét Úrnő ügye iránt megingathatatlan marad, jó jövőd lehet az Elhagyatottak között.' WHERE ID=422;
-- quest_offer_reward.RewardText. Batch 9: quest IDs 423-473.

UPDATE quest_offer_reward SET RewardText='Remélem, elég energiát tudok kinyerni ebből a korlátozott mintából. Talán több bilincset kellett volna hozatnom veled.$b$bMindazonáltal nagy ügyességgel gyűjtötted össze ezeket, $c.' WHERE ID=423;
UPDATE quest_offer_reward SET RewardText='Igazán kiváló. A bánya remek erőforrásokat biztosít majd erőinknek, ahogy terjeszkedünk Silverpine-ban és tovább Azerothba.' WHERE ID=424;
UPDATE quest_offer_reward SET RewardText='Á, köszönöm. Hálás vagyok, $N.$b$bÉs bekerülsz majd a jelentésembe, amit a feletteseimnek küldök.' WHERE ID=425;
UPDATE quest_offer_reward SET RewardText='Erőfeszítéseidet a háborúban érezzük mindannyian, $N. Nem köszönöm meg, hogy megtetted, ami szükséges volt, de Tirisfal Halálőrsége emlékezni fog a nevedre.' WHERE ID=426;
UPDATE quest_offer_reward SET RewardText='Igazán kiváló, $c. Harci tudásod kétségtelen.' WHERE ID=427;
UPDATE quest_offer_reward SET RewardText='Megtaláltál minket! És épp jókor...' WHERE ID=428;
UPDATE quest_offer_reward SET RewardText='<Renferrel átveszi a szíveket>$b$bAggasztó hallani, hogy a Halálleselkedőink kudarcot vallottak a küldetésükben.$b$bReméljük, ritkák az ilyen kudarcok.$b$bMindjárt adom a bájitalt, de itt a receptje - ha a Halálleselkedőknek megint segítségre lesz szükségük, talán te magad is elkészítheted.' WHERE ID=429;
UPDATE quest_offer_reward SET RewardText='<Quinn elveszi a bájitalt, és megissza>$b$bIgen, érzem, hogy hat. Hamarosan utazni tudok majd.$b$bNagy szívességet tettél nekem, $N.' WHERE ID=430;
UPDATE quest_offer_reward SET RewardText='Megragadsz egy gyertyát, és a zsákodba teszed.' WHERE ID=431;
UPDATE quest_offer_reward SET RewardText='Nos, ettől kicsit jobban érzem magam...$b$bDe addig nem leszek boldog, amíg mind meg nem halnak! Mindegyikük!' WHERE ID=432;
UPDATE quest_offer_reward SET RewardText='Ez egy kezdet. Remélhetőleg kihasználhatjuk, és hegymászókat küldünk be a terület biztosítására. Aztán elkezdhetjük helyreállítani az infrastruktúránkat, és visszaküldeni dolgozni a bányászokat.$b$bKöszönöm a segítségedet, $N.' WHERE ID=433;
UPDATE quest_offer_reward SET RewardText='Szóval megvan? Jó. Nagyon köszönöm a diszkréciódat, $N. Több szempontból is bebizonyítottad, hogy méltó vagy. Gondoskodom róla, hogy figyelemmel kísérjem a Szövetségen belüli fejlődésedet.$B$BÜgyelj, hogy tiszta maradjon a neved.' WHERE ID=434;
UPDATE quest_offer_reward SET RewardText='Köszönöm a segítséget, $N. Attól féltem, Erlandot legyűrték Silverpine veszélyei. Segítségeddel látom, hogy nem így történt.' WHERE ID=435;
UPDATE quest_offer_reward SET RewardText='Jern tudni akarja, mi okozza a lassulást, mi?$b$bIronband épp összeállítja legújabb részletes jelentését, de ennyit elárulhatok:$b$bA troggok!!' WHERE ID=436;
UPDATE quest_offer_reward SET RewardText='Hallottam a rot hide-ok elleni sikeres portyádról, $N, és ez az esszencia bizonyítja Nightlash halálát.$b$bA Csapás vesztett teret ma. Az Elhagyatottaknak nyújtott értéked nő.' WHERE ID=437;
UPDATE quest_offer_reward SET RewardText='Ebben a csónakban becsomagolt holttestek halma tornyosul. És kelet felé nézve, a Lordamere-tavon át, egy szemközti móló látszik Fenris-szigeten.$B$BA holttestek sorsa biztosan Fenris-szigeten dől el.' WHERE ID=438;
UPDATE quest_offer_reward SET RewardText='Azt mondod, ezt a gyűrűt egy nemrég megölt nő viselte?$B$BAz egyetlen közeli forrás egy ilyen testhez a Tirisfal-i tömegsírok lennének. A Rot Hide gnolloknak kell elvinniük azokat a holttesteket Fenris-szigetre!' WHERE ID=439;
UPDATE quest_offer_reward SET RewardText='Élt egy Deliah nevű nő Brillben nem is olyan régen. A tömegsírba temették, de ha igaz, amit mondasz, akkor a Rot Hide gnollok biztos ellopták a testét, és elvitték Silverpine-ba.$b$bA Rot Hide-okat, mint minden Csapást, el kell pusztítani. Bízom benne, hogy teszel is lépéseket ez ügyben.' WHERE ID=440;
UPDATE quest_offer_reward SET RewardText='Igen, ez a gyűrű a feleségemé volt. Az ő sorsa mindazok sorsa, akik nem bírják ki ezeket a kemény időket. Semmit sem érzek a halála miatt, sem a történet miatt, amit a teste elrablásáról mesélsz.$b$bAz ilyen érzések rég kihűltek bennem. De egy vágy még mindig ég halott szívemben, $N.$b$bA bosszú vágya.' WHERE ID=441;
UPDATE quest_offer_reward SET RewardText='Thule Ravenclaw halála nem volt kis esemény, $N. Renferrel elmondása szerint az energiákat, amik Thule elpusztításakor szabadultak fel, egészen a Sírkertig érezték.$b$bTetteid visszhangoznak az Elhagyatottak soraiban. Nekünk nyújtott értéked nő.' WHERE ID=442;
UPDATE quest_offer_reward SET RewardText='Nagyon jó. Ez az ichor segít majd megérteni a rot hide-ok természetét, és talán megmutatja a gyengeségüket... ha van egyáltalán.' WHERE ID=443;
UPDATE quest_offer_reward SET RewardText='Ez az anyag hatalmas varázslatokkal van átitatva, néhányukat nagyon, nagyon régóta nem láttam...$b$bEgy pillanat -- egy jóslási varázslatot kell alkalmaznom...' WHERE ID=444;
UPDATE quest_offer_reward SET RewardText='Á, milyen kedves Johaan alkimistától, hogy elküldte a kutatását. Annyi új fejlemény van itt Silverpine-ban, hogy majdnem elfelejtettem a Lordaeronból és a Tirisfal-tisztásokról érkező eredményeket. Ami eszembe juttatja, hamarosan el kell küldenem azokat a mintákat a Nekropoliszba.$b$bDe bocsásd meg a fecsegésemet. Hosszabbítsd meg az itt-tartózkodásodat Silverpine-ban, $N. Jól jönne egy hozzád hasonló, munkabíró $c errefelé.' WHERE ID=445;
UPDATE quest_offer_reward SET RewardText='Ez a tekercs hatalmas mágiával van átitatva. Sosem használtam még ilyen erőket egy bájitalban... erős keverék lesz, és jól szolgál majd, ha megtámadod Thule-t Fenris-szigeti erődjében.' WHERE ID=446;
UPDATE quest_offer_reward SET RewardText='Milyen kedves Renferrel alkimistától, hogy elküldött hozzám, $N. Ezek a minták valóban hasznosak lesznek az ügynek. Azonnal elkezdem tanulmányozni mérgező és fertőzőképes tulajdonságaikat.' WHERE ID=447;
UPDATE quest_offer_reward SET RewardText='Ha igaz, amit Bethor mond, akkor Thule Ravenclaw egy olyan erő, amivel foglalkozni kell, méghozzá hamarosan.$b$bHogy segítsük ezt a feladatot, elvihetsz valamit a fegyverkészletünkből...' WHERE ID=448;
UPDATE quest_offer_reward SET RewardText='Nem számoltam a Csapás Silverpine-erdőben tapasztalt jelenlétének mértékével, sem a Halálleselkedőink felderítő erőfeszítéseik során felmerülő nehézségekkel.$b$bA Halálleselkedőinknek nyújtott segítséged felbecsülhetetlen volt, $N. Dicséretet fogsz kapni.' WHERE ID=449;
UPDATE quest_offer_reward SET RewardText='Berard alkimista naplója! Hát te bizony bátor vagy, $N. Most lássuk, mivel foglalatoskodott Berard, mielőtt megőrült...' WHERE ID=450;
UPDATE quest_offer_reward SET RewardText='Micsoda csapás a Királyi Alkimista Társaságnak Berard elvesztése. De kemény munkádnak és Renferrel alkimista szorgos kutatásának köszönhetően Berard tanulmányai még mindig hasznosak lesznek a Sötét Úrnő ügyének.$b$bValami nagyszerű dolog küszöbén állunk itt, $N. Ha nem lennél ennyire ügyes a harc terén, megpróbálnálak beszervezni a Társaság tagjai közé.' WHERE ID=451;
UPDATE quest_offer_reward SET RewardText='Úgy harcoltál, mint a Sötét Úrnő igazi tanítványa, $N. A tanács halálával talán egyszer s mindenkorra megszerezhetjük az irányítást e város fölött, és kiűzhetjük Arugalt a Shadowfang Keepből. Tisztelgek előtted!' WHERE ID=452;
UPDATE quest_offer_reward SET RewardText='<Jitters felsóhajt...>$B$BIgen, én írtam azt a könyvet. Végre megtaláltál, mi?$B$BNos, ha elolvastad azt a naplót... akkor még csak a felét tudod!' WHERE ID=453;
UPDATE quest_offer_reward SET RewardText='Helló, $c.$b$bTe fogsz elkísérni az ásatás helyszínére? Ezt jó hallani... Saean és cimborái után ki tudja, mi mást tartogatnak még a Dark Ironok?$b$bMindenesetre, hadd végezzek néhány utolsó ellenőrzést. Szólj, ha készen állsz indulni.' WHERE ID=454;
UPDATE quest_offer_reward SET RewardText='A jelentésed tele van rossz hírrel!$b$bLátom, a Dragonmaw-k erőteljesen nyomulnak Algaz felé. Általában a Dragonmaw-k csak a dombok közt bujkálnak. Hogy mi miatt zúdultak be Algazba, egyelőre rejtély...$b$bKöszönöm, $N. És valószínűleg szükségünk lesz a segítségedre ezekkel az orkokkal szemben.' WHERE ID=455;
UPDATE quest_offer_reward SET RewardText='Jól teljesítetted a kötelességedet, $N.' WHERE ID=456;
UPDATE quest_offer_reward SET RewardText='Jól bebizonyítottad a természet iránti elköteleződésedet, $N. Egy hozzád hasonló ifjú $c-nek ígéretes jövője van.' WHERE ID=457;
UPDATE quest_offer_reward SET RewardText='Látom, megtaláltál, ifjú $R. Melithar bölcs druida volt, hogy téged küldött.' WHERE ID=458;
UPDATE quest_offer_reward SET RewardText='Shadowglen teremtményeinek tett szolgálatod jutalmat érdemel, $N.$b$bDe beigazoltad a félelmeimet. Ha a grelleket beszennyezte a Fel-moha, csak elképzelni tudom, mi lett a Gnarlpine furbolgtörzzsel, akik egykor itt éltek.$b$bHa Dolanaarban jársz, ügyes $c, keresd fel a tudós druidát, Athridas Bearmantle-t. Ő is osztja aggodalmunkat az erdő jólléte miatt.' WHERE ID=459;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Attól féltem, a gnollok elpusztították a testemet. Jó tudni, hogy nem így történt.' WHERE ID=460;
UPDATE quest_offer_reward SET RewardText='Meg is van, nyitva van. Hagyj itt engem. Életem legszebb napjait ebben a várban töltöttem, és a gondolat, hogy a falai közt nyugodhatok, megnyugtat.$b$bGondoskodj róla, hogy szorosan bezárd a fülkét - nem akarom, hogy azok a Rot Hide-ok megtaláljanak.$b$bÓ, és fogd ezt. Kiérdemelted.' WHERE ID=461;
UPDATE quest_offer_reward SET RewardText='A gyökerek és páfrányok jót mondanak rólad, kicsi teremtmény. Bár sok nevem van, csak néhányra hallgatok. De te hívhatsz Rethielnek.$B$BÉs figyelned kell... mert ezek a földek gennyes sebekből sírnak, és megbíználak, hogy gyógyítsd meg őket.' WHERE ID=463;
UPDATE quest_offer_reward SET RewardText='Jól harcoltál, $N. A Dragonmaw-k nem ugyanolyan fenyegetést jelentenek, mint amikor sárkányaik voltak, de még mindig kemény ellenfelek.$b$bA Dragonmaw-kat Nek''rosh vezeti, Nekros fia, aki évekkel ezelőtt a Dragonmaw-k egykori vezetője volt. Nekros hatalmas mágiával szelídítette meg a vörös sárkányokat, de amikor a mágia cserbenhagyta... a sárkányok nem örültek.$b$bNekrost megölték, és fia bosszút esküdött az apját megölő sárkányokra.' WHERE ID=464;
UPDATE quest_offer_reward SET RewardText='Némi gyújtóst helyezel a katapultra, majd szikrát csiholsz rá.$B$BLángok törnek ki, és gyorsan terjednek!' WHERE ID=465;
UPDATE quest_offer_reward SET RewardText='Megvan az érc! Szép munka, $N! Rögtön keresek valakit, aki foglalkozik vele. Reméljük, nem robbantja fel magát!' WHERE ID=466;
UPDATE quest_offer_reward SET RewardText='Helló, $N. A feladatom miatt vagy itt, mi? Jó látni egy hozzád hasonló ifjú $R-t, akinek a vére lángol a kaland gondolatára!' WHERE ID=467;
UPDATE quest_offer_reward SET RewardText='Helló, $c! A felderítő küldetés miatt vagy itt? Nagyon jó!$b$bRemélem, jó állapotban van a felszerelésed, mert ez a „felderítő” küldetés valami zűrösebbé alakult...' WHERE ID=468;
UPDATE quest_offer_reward SET RewardText='Hmm, ez Einartól van, ugye? Már majdnem egy hete nem hozza el személyesen a bőröket. Biztos valami nézeteltérése van a feleségével!$b$bTalán elküldöm a feleségem, hogy beszéljen Sidával egyszer...' WHERE ID=469;
UPDATE quest_offer_reward SET RewardText='Ó, köszönöm, $N! Attól féltem, örökre elveszett!$B$B<Gyorsan kiüríti a nyálkával borított táska tartalmát a földre, majd felkapkodja őket.>$B$BHm, nekem már nem sok hasznom van belőle, de moss le róla mindent, és biztos vagyok benne, tudod majd hasznosítani.' WHERE ID=470;
UPDATE quest_offer_reward SET RewardText='Hmm... Nem gondolom, hogy érdekelne a tanoncságom, vagy mégis?$b$bHah! Nem, csak viccelek. Egyrészt túl idős vagy hozzá. Másrészt - úgy tűnik, más ambícióid vannak az életben. Mindazonáltal ezek szép bőrök, amiket beszereztél, és jó hasznukat veszem majd.' WHERE ID=471;
UPDATE quest_offer_reward SET RewardText='Milyen bátor $c küld hírt Menethilből? Á, $N-nek hívnak.$b$bReményt hozol egy reménytelen helyzetbe. Valóban jó hír, hogy az ifjú Harlo túlélte. Menekülés közben súlyos sebet kapott. Alig maradt időnk elküldeni útjára a hadosztály egyetlen túlélő paripájának hátán.$b$bDe most veszélyes helyzettel nézünk szembe. Dun Modr elesett, és már csak árnyéka vagyunk annak a nagyszerű hadosztálynak, amely egykor voltunk.' WHERE ID=472;
UPDATE quest_offer_reward SET RewardText='$N. Valstag tájékoztatott a Dun Algaznál a Dragonmaw orkok ellen elért korábbi sikeredről. Értékes $R vagy.$b$bÉs van egy feladatom számodra.' WHERE ID=473;
-- quest_offer_reward.RewardText. Batch 10: quest IDs 474-525.

UPDATE quest_offer_reward SET RewardText='Vitézül helytálltál, $N. Súlyos csapást mértél a Dragonmaw ork klánra. Talán sosem heverik ki. És a katapultok elpusztításával biztonságosabbá tetted Menethil Harbort.$B$BÉrdemekkel bíró $R vagy, és Ironforge királysága megjutalmazza azokat, akik jól szolgálják.' WHERE ID=474;
UPDATE quest_offer_reward SET RewardText='Hála az erdő szellemeinek, hogy itt vagy! Tudtam, hogy Athridas megérzi a bajt, és segítséget küld.' WHERE ID=475;
UPDATE quest_offer_reward SET RewardText='A csillagokra! Ez valóban elég aggasztó!' WHERE ID=476;
UPDATE quest_offer_reward SET RewardText='<Kifeszíted a láda fedelét, és gondosan becsomagolt tárgyakat találsz. A láda tetején egy köteg térkép hever, korától megsárgulva, amelyek úgy tűnik, Silverpine-erdőt és nyugat-Lordaeron más részeit ábrázolják.$b$bA térképek alatt egy rejtélyesnek tűnő mágikus medál lapul.>' WHERE ID=477;
UPDATE quest_offer_reward SET RewardText='Térképek, és ez a... medál, hm? Érdekes.$b$bNyilvánvaló, hogy a dalarani varázslók valamiért érdeklődnek Ambermill iránt, de a céljuk még mindig rejtve marad előttem.$b$bTalán Dalar tud valamit a felhasználásukról.' WHERE ID=478;
UPDATE quest_offer_reward SET RewardText='Dalar rájött, hogy a szövés a visszaesés ellenére már elég előrehaladott.$b$bEgy nagy hatalmú varázsló irányítja a mágikus energiát. Gyorsan meg kell állítani.' WHERE ID=479;
UPDATE quest_offer_reward SET RewardText='A varázslók mágiája szertefoszlik, a ley-energiák pedig szunnyadásba merülnek. Erőfeszítéseid gyümölcsözőek voltak, $N, és jelentős csapást mértünk ellenségeinkre, valamint Dalaran fennhéjázó varázslóira.$b$bÉbereknek kell maradnunk azonban, hiszen tudjuk, hogy az energiaforrás ilyen közel van hozzánk... Terveket kell szőnünk a jövőre nézve.' WHERE ID=480;
UPDATE quest_offer_reward SET RewardText='Érdekes, úgy tűnik, ez is a Kirin Tor mesterkedése. Ez egy hatalmas ereklye. A Kirin Tor hatalmas varázslói gyakran használták mágikus energiák irányítására.$b$bHogy ennyit szállítanak Ambermillbe, arra utal, hogy valamilyen nagyszabású projekten dolgoznak.$b$bMegnézem, át tudom-e törni a pajzsaikat, hogy megtudjam a szándékukat.' WHERE ID=481;
UPDATE quest_offer_reward SET RewardText='Rossz hírt hozol, $N. Ha Dalarnak igaza van--és nincs okom kételkedni benne--gyorsan kell cselekednünk.$b$bMeg kell beszélnem vele a támadási tervünket. De addig is le kell lassítanunk az előrehaladásukat.' WHERE ID=482;
UPDATE quest_offer_reward SET RewardText='Sikerrel jártál, ifjú $c! Szép munka. És épp időben, tehetném hozzá.' WHERE ID=483;
UPDATE quest_offer_reward SET RewardText='Szép munkát végeztél, $N. Ezeknek a bőröknek a minősége kiváló. Mihamarabb el kell kezdenem a cserzési folyamatot velük. Ó, de mielőtt ehhez hozzáfognék, van más munkám is, amit szerintem el tudnál intézni.' WHERE ID=484;
UPDATE quest_offer_reward SET RewardText='Beteszed a tojást... a vészjelzőt... a csirkébe... az önvezérlő robotba.$b$bZümmögés és zúgás hallatszik a robot belsejéből, ahogy próbál felállni. Miután a robot életre kel, Oglethorpe hangja hallatszik ismét, de most a robot belsejéből:$b$b„Az OOX-09/HL legalább működik, de komoly javításra szorul! Túl nehéz ahhoz, hogy elvidd magaddal... de azt hiszem, van egy ötletem. Vállalod, hogy még egy kicsit vigyázol rá?”' WHERE ID=485;
UPDATE quest_offer_reward SET RewardText='$N, bebizonyítottad, hogy igen méltó és ügyes $c vagy. Egy éjelf, aki ilyen biztosan járja a becsület útját, mint te, kétségkívül nagy dicsőségre lel majd ebben a világban.$b$bAz erdő szellemei óvjanak, bárhová is vigyenek az útjaid.' WHERE ID=486;
UPDATE quest_offer_reward SET RewardText='Jól szolgáltad Dolanaar és Darnassus jó népét, bátor $c. Teldrassil Szentiniel-erőinek tagjaként tisztelgek erőfeszítéseid előtt.' WHERE ID=487;
UPDATE quest_offer_reward SET RewardText='Ha ha! Nos, valóban szép munka.$b$bKi gondolta volna, hogy nekem, Zenn Foulhoofnak, egy $R teljesíti a parancsaimat? Én biztos nem! De hát így megy ez... ez a szeretett világunk tele van meglepetésekkel.$b$bHárom éljen a naivaknak és hiszékenyeknek!' WHERE ID=488;
UPDATE quest_offer_reward SET RewardText='Á, micsoda kedves $R! Tudtam, hogy hasznomra leszel!' WHERE ID=489;
UPDATE quest_offer_reward SET RewardText='...ez meg mi? Thule-nál volt a Fonott Pálcánk? Azt hittem, elveszett, amikor barátságunk megszakadt, és a Lichkirály oldalára állt!$b$bBiztos nem hívta elő az erejét, mert ha igen, megéreztem volna. És jó, hogy nem használta...$b$bEz csodálatos lelet. Hálás vagyok, $N, és jutalmat kapsz.' WHERE ID=491;
UPDATE quest_offer_reward SET RewardText='Á, végre egy ital. Biztos nem Rhapsody Malt, de ezen a ponton bármit elfogadok, hogy megnedvesítsem a torkomat.' WHERE ID=492;
UPDATE quest_offer_reward SET RewardText='Á, igazán kiváló. Renferrel alkimista élvezi a legmélyebb tiszteletemet. Alig várom, hogy tanulmányozhassam a munkáját.' WHERE ID=493;
UPDATE quest_offer_reward SET RewardText='A holló kiáltása nyugatról hív?$b$bKiváló hír! Hillsbrad érett a támadásra. Most már végrehajthatjuk pusztítási tervünket. Varimathras elégedett lesz.' WHERE ID=494;
UPDATE quest_offer_reward SET RewardText='Shalindra küldött? Nos, rendben, hamar rájössz, hogy nem vesztegetem az időt üres fecsegéssel.$B$BMug''Thol egy bosszúság, és gyorsan, alaposan és incidens nélkül elintézzük.' WHERE ID=495;
UPDATE quest_offer_reward SET RewardText='Ezek a példányok tökéletesek. Nos, $N, sikerült egy halvány örömöt csempészned egy újabb nyomorúságos napomba. Nagyra értékelem az erőfeszítéseidet.' WHERE ID=496;
UPDATE quest_offer_reward SET RewardText='Szóval az emberek rabszolgává akarták tenni a harcosainkat? Megmutatjuk nekik!$b$bÚgy tűnik, elvitték Gol''dirt, a vezérünket, egy másik helyre. Meg kell találnunk és ki kell szabadítanunk. De jelenleg fogalmunk sincs, hol lehet...$b$bAmint van egy nyomunk, biztosan szólok neked, $N.' WHERE ID=498;
UPDATE quest_offer_reward SET RewardText='Kvák!' WHERE ID=499;
UPDATE quest_offer_reward SET RewardText='Nagyon jó, $N. Biztos ogrék egész seregén kellett átvágnod magad, hogy megszerezd ezeket a bütyökcsontokat.$B$BEz elég lesz, hogy ne zaklassanak minket. Legalábbis egy ideig.' WHERE ID=500;
UPDATE quest_offer_reward SET RewardText='Kiváló gyűjtés, $N.' WHERE ID=501;
UPDATE quest_offer_reward SET RewardText='Kiöntesz némi elixírt a kezedbe, és Stanley szája elé tartod.' WHERE ID=502;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. A Hadúr parancsára vezettem az expedíciót Durotarból, de ahogy látod, a terveink kissé félresiklottak. Fogva tartottak itt ebben a városban, munkára kényszerítettek, terheket cipeltettek velem, ásattak velem...$b$bDe amit szenvedtem, nem lényeges. Fontos információt kell eljuttatnod annak, aki most vezeti a csoportunkat.' WHERE ID=503;
UPDATE quest_offer_reward SET RewardText='Nagyon jó. Itt a jutalmad.$B$BÉs amikor azokra a Warmongerekre vadásztál, hogy nézett ki Alterac városa? Gondolom, rossz állapotban van. Az ogrék nem híresek a tisztaságukról.$B$BSzerencsére erőfeszítéseid segítenek távol tartani őket Southshore-tól.' WHERE ID=504;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Bár lehet, hogy még mindig ólálkodnak errefelé, reméljük, hogy a tolvajok és útonállók közül, akiket megöltél, néhányan felelősek voltak az utolsó bíró haláláért. De még ha nem is ők voltak, a Syndicate szennyfolt ezen a földön, és folt az emberiségen.$B$BHalálukat örömmel fogadja Southshore.' WHERE ID=505;
UPDATE quest_offer_reward SET RewardText='Micsoda pofátlanság azoktól a fennhéjázó emberektől! Megmutatjuk nekik, hogy az orkok sosem hódolnak be az akaratuknak!$b$bEz lesz mostantól a küldetésünk, amellett, hogy visszaszerezzük a Hadúr által kívánt csecsebecsét. Úgy tűnik, ha véghezvisszük az egyiket, a másikat is véghezvisszük.' WHERE ID=506;
UPDATE quest_offer_reward SET RewardText='Ne, ne, kérlek, ne bánts! Sosem akartam ártani a népednek, ő az akaratom ellenére tartott fogva! Kérlek... kegyelmezz!' WHERE ID=507;
UPDATE quest_offer_reward SET RewardText='Furcsa, hogy a Hadúr ennyi erőfeszítést fektet egy ilyen apró dologba. Nem állítom, hogy megértem őt, de követni fogom, bármit is parancsol. Jól teljesítettél, $N, a Hadúr kétségkívül örömmel hallja majd a sikeredről.' WHERE ID=508;
UPDATE quest_offer_reward SET RewardText='Á, a Mudsnout-virágok szörnyű bűze. Legalább azok a mocskos gnollok jók valamire.' WHERE ID=509;
UPDATE quest_offer_reward SET RewardText='<Maleb elolvassa a dokumentumokat.>$B$BEzek nagyon aggasztóak, $N. A dokumentumokban lévő információk, és a Syndicate múltbeli tettei alapján fel kell tételeznünk, hogy az a torkosbanda háborút indított Southshore ellen.' WHERE ID=510;
UPDATE quest_offer_reward SET RewardText='Ez meg mi? Várj egy pillanatot... hadd nézzem meg közelebbről.$B$B...$B$BHm, sosem láttam még ilyen fajta titkosítást, de be kell vallanom, a tudásom ezen a téren korántsem teljes.' WHERE ID=511;
UPDATE quest_offer_reward SET RewardText='Ha megfosztjuk a Syndicate-et a nemességétől, elveszíti a képességét, hogy határozottan cselekedjen, és nem marad más, mint egy útonálló banda.$B$BJól szolgálod a Szövetséget, $N.' WHERE ID=512;
UPDATE quest_offer_reward SET RewardText='Lydon alkimista küldött? Á, miért nem mondtad rögtön!$b$bBorús kedélye ellenére Lydon alkimista az egyik legelkötelezettebb és legügyesebb tagunk.$b$bA derék fickó Mudsnout-keveréket küld! Most már tudom, mire készül a hillsbrad-i barátunk. És tetszik, ahogy gondolkodik. A Sötét Úrnő igen elégedett lenne az előrehaladásával az új pestis felé.' WHERE ID=513;
UPDATE quest_offer_reward SET RewardText='Á, titkosítás! Ez a specialitásom. Hadd nézzem csak...' WHERE ID=514;
UPDATE quest_offer_reward SET RewardText='Ennek a kísérletnek az izgalma egészen szédültté tesz! Nagyszerű segítségemre voltál, $N. Együtt terjesztjük majd a halált és a betegséget ezen a földön!' WHERE ID=515;
UPDATE quest_offer_reward SET RewardText='Ha felderítőink és ügynökeink továbbra is ilyen értékes információkat szereznek, hamarosan eltávolítjuk a Lichkirály Csapását a földjeinkről.' WHERE ID=516;
UPDATE quest_offer_reward SET RewardText='Végre! Most már készen állunk a cselekvésre!' WHERE ID=517;
UPDATE quest_offer_reward SET RewardText='A hó vörösre virágzik az ogrék vérétől, de nem hagyhatjuk abba az erőfeszítéseinket, amíg a Crushridge szelleme és létszáma szét nem morzsolódik a földbe és a hóba.' WHERE ID=518;
UPDATE quest_offer_reward SET RewardText='...és azt hittem, az ogrék eleve elég büdösek.$b$bAmikor elhozod nekem Mug''Thol fejét, mind a négyet karóra tűzetem Alterac fölé. Méltó emlékmű azoknak, akik szembeszállnak a Sötét Úrnő akaratával.' WHERE ID=519;
UPDATE quest_offer_reward SET RewardText='Jól teljesítetted a kötelességedet, $N. Mug''Thol feje díszíti majd Alterac romjainak legmagasabb csúcsát, a Halálőrség pedig a földbe tiporja a Crushridge maradványait.' WHERE ID=520;
UPDATE quest_offer_reward SET RewardText='Szóval ez az az ereklye, amivel az ogre kibújt a Sötét Úrnő akarata alól...$b$bFurcsa, hogy valami ilyen egyszerű ekkora hatalmat hordozhat. És hogy ilyen ügyetlen kezekbe kerülhetett. Szép munka, $N, elviszem a koronát Lady Sylvanasnak, és gondoskodom róla, hogy halljon a sikeredről.' WHERE ID=521;
UPDATE quest_offer_reward SET RewardText='<Maleb megvizsgálja a szerződést.>$B$BEz megmagyarázza a legutóbbi támadást Southshore ellen. A Syndicate biztos engem üldöz, ahogy az előző bírót is!' WHERE ID=522;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. A fejem kicsit nyugodtabban pihen, tudván, hogy az a gazember elvesztette a sajátját.' WHERE ID=523;
UPDATE quest_offer_reward SET RewardText='A beszennyezett tárgyat a poros szőnyegre helyezed.' WHERE ID=524;
UPDATE quest_offer_reward SET RewardText='<Maleb elolvassa a levelet.>$B$BEz egy levél fordítása, amit egy Syndicate-táborban találtál? Ezt nem egy tolvaj írta, de még csak nem is egy alteraci nemes.$B$BÚgy tűnik, a Syndicate-nek kapcsolatai vannak egy másik hatalommal, és beleborzongok a gondolatba, mi lehet az.' WHERE ID=525;
-- quest_offer_reward.RewardText. Batch 11: quest IDs 526-577.

UPDATE quest_offer_reward SET RewardText='Á, megtaláltad őket! Most kalapáljuk ezt a Lightforge-vasat valami hasznossá, mi?' WHERE ID=526;
UPDATE quest_offer_reward SET RewardText='Pihenj, $c. Látom, visszatértél a csatából. Forrásaim szerint jól teljesítettél a hillsbrad-i fronton.' WHERE ID=527;
UPDATE quest_offer_reward SET RewardText='A halál szorítása egyre erősebb Hillsbrad városa körül. A csata jól halad.' WHERE ID=528;
UPDATE quest_offer_reward SET RewardText='Küldetés teljesítve, $c. És elég ügyesen végrehajtva, tehetném hozzá.' WHERE ID=529;
UPDATE quest_offer_reward SET RewardText='Á, jó. Ezek a kezek ölték meg a feleségemet, Deliah-t. A gyilkosságáért való bosszú volt az egyetlen gondom, és te voltál e bosszú eszköze.$b$bTessék, fogd vissza a gyűrűt, amit korábban hoztál. Deliah már oly régóta halott számomra, a gyűrűje csak egy csecsebecse, amit már nem akarok megtartani. Ehelyett ezeket a kezeket tartom meg emlékeztetőül barátom árulására.' WHERE ID=530;
UPDATE quest_offer_reward SET RewardText='Köszönöm, hogy segítettél a kis tervemben, $N. Hónapok óta viszket a tenyerem, hogy visszavágjak annak a beképzelt, felfuvalkodott fiúnak, és azt mondanám, egész jó munkát végeztünk! Tessék, fogd ezt, kiérdemelted.' WHERE ID=531;
UPDATE quest_offer_reward SET RewardText='A hillsbrad-i dicsőséges tetteid híre gyorsan terjedt. Jól teljesítettél, $c.' WHERE ID=532;
UPDATE quest_offer_reward SET RewardText='Végre tudjuk, hol tartják fogva Gol''dirt. A szóban forgó tábor nincs messze innen, és remélhetőleg nem lesznek annyira felkészülve, mint amikor először elfogtak minket.' WHERE ID=533;
UPDATE quest_offer_reward SET RewardText='Tekintve a közelgő halálomat, azt hiszem, biztonsággal állíthatom, ez a legédesebb ízű dolog, amit valaha ettem... Tessék, fogd ezt, nem lesz rá szükségem, amikor meghalok.$B$BNos, csináld hát!' WHERE ID=535;
UPDATE quest_offer_reward SET RewardText='Remélem, ez elég lesz, hogy meggyőzzem Redpath-et, hogy--ha!--teljesítettem a parancsait, és megszabadítottam Southshore-t a rettegett murlocok szörnyű és iszonyú fenyegetésétől! Mert nincs nagyobb gonoszság, mint a túlnőtt halak pusztítása!' WHERE ID=536;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N. Az Argus Wake nem hangzik olyan csoportnak, amit szeretnénk a Syndicate élén látni.$B$BÉs bár talán elpusztítottad a vezérüket itt, Nagaz csak egy másik szolgája volt. Az Argus Wake talán mélyen behálózza Azeroth kontinensét.$B$BVagy akár az egész világot.' WHERE ID=537;
UPDATE quest_offer_reward SET RewardText='Á igen, emlékszem Miltonra. Egy könyvmoly, kétségkívül. Áldja meg.$B$BÉs igaza van. Alterac romjai még mindig rejtenek olyan tudást, amit elveszíthetünk!$B$BOgrék laknak most Alteracben, és nem sokat törődnek a magasabb tudással.' WHERE ID=538;
UPDATE quest_offer_reward SET RewardText='A Sötét Úrnő elégedett lesz, amikor megtudja, hogy van egy új bányája, amelyből felfegyverezheti katonáit.' WHERE ID=539;
UPDATE quest_offer_reward SET RewardText='Ó, megszerezted őket! Pompás! Azonnal el kell kezdenem tanulmányozni Gri''lek Karját!' WHERE ID=540;
UPDATE quest_offer_reward SET RewardText='Csatatéri tetteid a legmagasabb dicséretet érdemlik.' WHERE ID=541;
UPDATE quest_offer_reward SET RewardText='Egek! Nézd csak ezeket! El sem hiszem, hogy túlélték Alterac pusztulását. És mindazokat az ogréket is!$B$BKöszönöm, $N. Nagyon köszönöm! Segítettél megőrizni az emberi tudást, és hozzájárultál a Stormwindi Királyi Könyvtár nagyszerűségéhez.' WHERE ID=542;
UPDATE quest_offer_reward SET RewardText='Á, ez pompás. Természetesen meg kell majd tisztítani, de tényleg túltettél magadon, $N. Gondoskodom róla, hogy valaki előkészítse a diadémot, és mihamarabb elhelyezze a gyűjteményünkben.' WHERE ID=543;
UPDATE quest_offer_reward SET RewardText='Nagy szolgálatot tettél az Elhagyatottaknak, $N. Ezek az ereklyék nagyon hiányoztak.$b$bÉs jó hallani, hogy Kegant és a többi árulót utolérte az igazságszolgáltatás.' WHERE ID=544;
UPDATE quest_offer_reward SET RewardText='Nagyon jó. Azok a romok most már elég biztonságosak a kutatáshoz, ha valaki óvatos.$B$BKöszönöm, $N.' WHERE ID=545;
UPDATE quest_offer_reward SET RewardText='Értékes koponyák! Milyen gyönyörűek! Tartozom neked, ahogy ígértem, $N!' WHERE ID=546;
UPDATE quest_offer_reward SET RewardText='Megtaláltad!$b$bÁ, mennyivel teljesebbnek érzem magam, hogy drága kardom újra a kezemben van. Nagyon köszönöm!' WHERE ID=547;
UPDATE quest_offer_reward SET RewardText='Kiváló, $c. Ezzel a tempóval hamarosan megszabadulunk a Syndicate kártevőtől ezen a földön.' WHERE ID=549;
UPDATE quest_offer_reward SET RewardText='Szóval te vagy az a hírhedt $c, aki ilyen döntő csapást mért a Szövetség erőire a Hillsbrad-előhegységben? Dicsőséges tetteid híre gyorsan elért az Alvárosba.$b$bSzép jövő vár rád a Sötét Úrnő soraiban, ha továbbra is ilyen vezetői képességet és harci szakértelmet mutatsz.$b$bBár elsődleges fenyegetésünk a Lichkirály északról leereszkedő Csapás-serege, az emberi „probléma” továbbra is akadályozza a harci terveinket. Te azonban megmutattad, hogy az emberek elbukhatnak, és el is fognak.' WHERE ID=550;
UPDATE quest_offer_reward SET RewardText='Még több titkosított jegyzet?$B$BBárcsak lenne tehetségem megfejteni minden furcsa írásfoszlányt, ami Alteracből szivárog le. De attól tartok, hiányzik hozzá a tudásom.' WHERE ID=551;
UPDATE quest_offer_reward SET RewardText='Megtaláltad! Igazán kiváló, $N!' WHERE ID=552;
UPDATE quest_offer_reward SET RewardText='Hatalmas dübörgés árad a földből.' WHERE ID=553;
UPDATE quest_offer_reward SET RewardText='Bölcs döntés. Nem hiszem, hogy rajtam kívül lenne olyan tudós, akinek megvan a tudása ennek a tekercsnek a lefordításához. És ha a tartalma érdekesnek bizonyul, ne félj, üzenek majd érted.' WHERE ID=554;
UPDATE quest_offer_reward SET RewardText='Mindenki nagyon örülni fog: Jessen szakács Nyugtató teknőshúslevese ismét az asztalra kerül!' WHERE ID=555;
UPDATE quest_offer_reward SET RewardText='Ezek pont megfelelnek. Bár úgy tűnik, mágiájuk elhalványult, jobb, ha a Magus kezdeti kísérletei ilyen semleges példányokon folynak.$b$bKöszönöm, $N.' WHERE ID=556;
UPDATE quest_offer_reward SET RewardText='Megtaláltad őket. Remélem, az elementálok, akiktől ezeket a karvédőket levetted, együttműködőek voltak?$b$bHm... úgy tűnik, a halál nemcsak a szívemet állította meg, de a komikus időzítésemet is elvette.$b$bNos, köszönöm, $N. Jól szolgálod a Magust, és ezáltal a Sötét Úrnőt is.' WHERE ID=557;
UPDATE quest_offer_reward SET RewardText='WOW! Megszerezted nekem Lady Jaina aláírását! Nagyon köszönöm! És hűha... személyes üzenetet írt ide - nekem! Tudtam, hogy szuper lesz, és talán egy nap magam is megköszönöm neki... amikor a Szövetség hőse leszek!$B$BTe vagy a legjobb, $N. Köszönöm, hogy ilyen kedves voltál hozzám.' WHERE ID=558;
UPDATE quest_offer_reward SET RewardText='Ó, a Fény szerelmére... csöpögnek a földre.$b$bMagam sem bírom megérinteni ezeket a dolgokat. A halak rendben vannak, de amikor lábakat növesztenek, és elkezdenek járkálni... Hetek óta nem ettem halat, elárulom, és Southshore-ban ez azt jelenti, nem sokat eszel.' WHERE ID=559;
UPDATE quest_offer_reward SET RewardText='Farren küldönce vagy, mi?$b$bHa segítettél Farrennek megszerezni ezeket a fejeket, akkor köszönöm. Southshore-nak kemény munkásokra és erőfeszítésre van szüksége, hogy fenntartsa a védelmét.' WHERE ID=560;
UPDATE quest_offer_reward SET RewardText='A naga, mi? Redpath biztos épp most kapta meg ugyanazt az információt, mint én... Ha! Az én fáradozásomból nem lesz belőle előléptetése. Hadd magyarázzam el.' WHERE ID=561;
UPDATE quest_offer_reward SET RewardText='Miután a naga elpusztult Southshore-ban, biztosra vehetem az áthelyezésemet. Újra láthatom Stormwindot... elszabadulhatok végre erről a Fény-elhagyta kikötőből.' WHERE ID=562;
UPDATE quest_offer_reward SET RewardText='Ez meg mi? Á... szóval a figyelmes tanítványom a southshore-i naga-problémára összpontosított. Köszönöm, hogy elhoztad nekem, mindenképp figyelembe veszem, amikor a jövő hónapban átnézem a személyzeti beosztásokat.' WHERE ID=563;
UPDATE quest_offer_reward SET RewardText='Hát ez remek hír! Az első naptól kezdve rendes háborús hőst kellett volna keresnem, hogy elbánjon azokkal a fenevadakkal. Büszke lenne rád az öreged, $N.' WHERE ID=564;
UPDATE quest_offer_reward SET RewardText='Most eljött az idő, hogy a nagy Bartolo bemutassa a mágiáját! Nincs szükségem varázslóbotra, sem egy $c pálcájára. Mert én, a nagy Bartolo, egyszerű tűvel és cérnával varázsolok!' WHERE ID=565;
UPDATE quest_offer_reward SET RewardText='Hasznos munkát végzel, $N. Vardus báró halálával csökken a Syndicate vezetőinek száma. Ellenállásuk és bosszantásuk rövid életű lesz.' WHERE ID=566;
UPDATE quest_offer_reward SET RewardText='Igazi vérdíj-vadász vagy, $c. Szép munka.' WHERE ID=567;
UPDATE quest_offer_reward SET RewardText='Becsülettel teljesítetted a kötelességedet, $c.' WHERE ID=568;
UPDATE quest_offer_reward SET RewardText='Szép munka. Becsülettel szolgáltad a Hadurat.' WHERE ID=569;
UPDATE quest_offer_reward SET RewardText='Erős a dzsungelismereted, $N. Ezek a példányok tökéletesek lesznek. Megköszönöm a szellemeknek, hogy feláldozták ezeket a remek fenevadakat a Horda ügyéért.' WHERE ID=570;
UPDATE quest_offer_reward SET RewardText='Igazán tökéletes ín, $N. Erőfeszítéseid hamarosan megtérülnek.' WHERE ID=571;
UPDATE quest_offer_reward SET RewardText='Igazán kiváló. Azonnal elkészítem ezeket.' WHERE ID=572;
UPDATE quest_offer_reward SET RewardText='Ezzel a szent forrásvízzel a szertartási nyaklánc készen áll a megbűvölésre.$B$BViseld büszkén, $N, a Hadúr nevében, és a hatalmas Horda védelmében.' WHERE ID=573;
UPDATE quest_offer_reward SET RewardText='$N. Yohwa őrmester bízott a képességeidben, és én bízom benne. A vereség, amit Kurzen erőire mértél, szinte túl jó ahhoz, hogy remélni merjük. Attól féltem, mi, lázadók, egyedül maradtunk, egyedül pedig sosem tudtunk volna szembeszállni az ezredes zsenialitásával.$b$bTalán mégis marad remény a túlélésünkre.' WHERE ID=574;
UPDATE quest_offer_reward SET RewardText='Ezek a bőrök megteszik. A minőségük nem túl fontos, hiszen a csizmák belső rétegét fogják alkotni, de fontos, hogy kényelmesek legyenek.$b$bHa kicsit túl merevek, tigrisvérrel puhítom majd meg őket. A szakma trükkjei, tudod?' WHERE ID=575;
UPDATE quest_offer_reward SET RewardText='Reszkessen a gerincem, és gerincedjen a reszketésem! Megtaláltad a gyönyörű szememet! Lássuk, még mindig passzol-e.$b$b$N, hó! Fenébe is, látok!!' WHERE ID=576;
UPDATE quest_offer_reward SET RewardText='A csizmáim... olyanok, mint a kolbászok, $N. Remekül néznek ki, remekül is ízlenének. Mondom neked, csak a legfinomabb alapanyagokkal és húsokkal vannak töltve, és ha megeszed, imádni fogod.$b$bBiztonságosabb -- és élvezetesebb -- ha egyszerűen megbízol bennem, és nem kérdezed túl alaposan, mi is van valójában bent.' WHERE ID=577;
-- quest_offer_reward.RewardText. Batch 12: quest IDs 578-628.

UPDATE quest_offer_reward SET RewardText='Szóval a történetek igazak voltak! Hihetetlen!$B$BEzonban ki kell találnunk, hogyan győzzük le az Árapály Kövének átkát, ha vissza akarjuk szerezni. Az átok mágikus ügy, szükségünk lesz egy varázslóra, aki segít nekünk.' WHERE ID=578;
UPDATE quest_offer_reward SET RewardText='Érdekel bármelyik ezen címek közül, $N?' WHERE ID=579;
UPDATE quest_offer_reward SET RewardText='Reszkessen a gerincem! Megtaláltad a kapitány grogját!$b$bNagyot tartozom neked, barátom.$b$bÚgy tűnik, vihar közeleg odakint. Talán melegen tartom magam egy ilyen üveggel, amíg elvonul...' WHERE ID=580;
UPDATE quest_offer_reward SET RewardText='Ezek jó agyarak, $N. Bebizonyítod, hogy elég erős vagy a Bloodscalpokra vadászni.$b$bÉs ez jó, mert még nem végeztél velük.' WHERE ID=581;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Megvizsgálom ezeket a fejeket, hogy megbizonyosodjak róla, szegény Yenniku megmenekült a fejvadász fejszéjétől.' WHERE ID=582;
UPDATE quest_offer_reward SET RewardText='Nagyon örülök, hogy megismerhetlek, $N. Egy ideje nem láttam $c-t errefelé.$b$bEgyetlen célból csatlakoztam ehhez az expedícióhoz: hogy egy nagy és megfoghatatlan fenevadra vadásszak. Mivel afféle hős vagy, hajlandó vagyok engedni, hogy részt vegyél a vadászaton, de először bizonyítanod kell.$b$bMegtanítalak a raptorölés fortélyaira. Ajeck a tigrisvadászatra tanít majd. Sir Erlgadin pedig a párducnyomkövetés mestere.$b$bBizonyítsd tehetségedet, és beengedlek a nagy vadászatba.' WHERE ID=583;
UPDATE quest_offer_reward SET RewardText='Gan''zulah és Nezzliok fejét az üstbe helyezed...' WHERE ID=584;
UPDATE quest_offer_reward SET RewardText='Igen. Ezek jól szolgálnak majd. Amikor szellemem felszabadul, három remek szolgával lépek majd be a Nether-be!$b$bBecsületet szerzel $R klánodnak, és megbékítettél engem.' WHERE ID=585;
UPDATE quest_offer_reward SET RewardText='Nem akarom elhinni, de nem tagadhatom, amit tettél. És dühöm enyhül, most hogy Ana''thek legyőzetett.$b$bHatalmad nagy tettekre visz majd, $N. De egy nap... találkozunk a Nether-ben, és ismét összemérjük erőnket.$b$bVárni foglak.' WHERE ID=586;
UPDATE quest_offer_reward SET RewardText='Szép mutatvány, $N! Éppen mielőtt indulnom kellene! Nem tudlak eléggé megköszönni, öreg barátom.' WHERE ID=587;
UPDATE quest_offer_reward SET RewardText='A Kitaszított Zanzil??$b$bHa Yenniku annál a trollnál van fogva tartva, egy aljas és hatalmas varázsdoktornál, akkor félek, csak halvány remény maradt. Halvány. Olyan kicsi, mint a legkisebb rovar.$b$bDe mégis, remény.' WHERE ID=588;
UPDATE quest_offer_reward SET RewardText='Jól teljesítettél, $N. Ezek a szilánkok jól formáltak. Már hallom, ahogy énekelnek nekem.$b$bÉs amíg távol voltál, beszéltem a dzsungel szellemeivel. Tudom, hol nyugszik az Elme Szeme...$b$b...és ki őrzi.' WHERE ID=589;
UPDATE quest_offer_reward SET RewardText='Hihetetlen! Micsoda ügyesség!$B$BAzt hittem, könnyű zsákmány leszel, $N. De jól átvertél.$B$BItt az érme, amit ígértem... nem annyi, amennyit mondtam, de ez azért van, mert eleve hazudtam neked.' WHERE ID=590;
UPDATE quest_offer_reward SET RewardText='Visszaszerezted a szemet! Hatalmad legendás, $N!$b$bÉs hogy megszerezted a Szemet, biztos legyőzted Mai''Zothot, és elküldted a Nether-be. Ezért nem említették korábban a szellemek.$b$bJó, hogy eltűnt a hús és csont világából, de most hogy a szellemek birodalmában van... félek, új uralmat kezd majd.$b$bDe ez egy másik alkalom gondja. Most rituálét kell végeznem, hogy az Elme Szemét szükségleteinkhez igazítsam...' WHERE ID=591;
UPDATE quest_offer_reward SET RewardText='Sikerült! Kiszabadítottad Yennikut Zanzil akarata alól, és teljesítetted a küldetést, amit oly reménytelennek gondoltam.$b$bTörzsünk dalokban fog emlékezni a nevedre, $N, és kőbe véssük történetedet, hogy örökké éljen.' WHERE ID=592;
UPDATE quest_offer_reward SET RewardText='A lélekkövet a homlokára helyezed. Megremeg, ahogy lelke beszippantódik, testét pedig üres, gondolattalan héjként hagyja hátra.' WHERE ID=593;
UPDATE quest_offer_reward SET RewardText='Azért jöttél, hogy kiszabadíts?' WHERE ID=594;
UPDATE quest_offer_reward SET RewardText='A csónakban egy térképet találsz, rajta sietősen odafirkantott szöveggel, néhány érme társaságában.' WHERE ID=595;
UPDATE quest_offer_reward SET RewardText='Á, nagyon jó. Ezeket megfőzöm, kiszívom belőlük az erőt, és tulajdonosaik szellemei meggyengülnek, ahogy a nyakláncaikat péppé olvasztom!$b$bTessék, $N. Ez törleszti a tartozásomat feléd.' WHERE ID=596;
UPDATE quest_offer_reward SET RewardText='Persze, emlékszem rád, $c. Látom, visszatértél a felderítésből...' WHERE ID=597;
UPDATE quest_offer_reward SET RewardText='Nagy az erőd, hogy megszerezted ezeket a nyakláncokat, $N. A Skullsplitterek úgy hullnak el előtted, mint fiatal csemeték, amiket egy baziliszkusz tapos a földbe!$b$bTetteid áldást hoznak ránk.' WHERE ID=598;
UPDATE quest_offer_reward SET RewardText='A Bloodsail kalózok megtámadják Booty Bay-t? Akár le is vethetnék magukat az Overlook-szirtekről. Mindazonáltal, hogy elhoztad ezt az információt, nagy szolgálatot tettél a kardforgató flottámnak. A Blackwater Raiders köszöni.' WHERE ID=599;
UPDATE quest_offer_reward SET RewardText='Remek! Csodálatos! Rengeteget kapok ezekért!!$b$bAz a Venture Company aztán rossz dzsungelt választott a bányászathoz, nem igaz? Mindannyian jobban járnánk, ha elköltöznének innen.$b$bKöszönöm, $N. Jó tettet vittél véghez ma.' WHERE ID=600;
UPDATE quest_offer_reward SET RewardText='Hm, nincs meg a szemem ahhoz, hogy megvizsgáljam ezeket a karvédőket, hasznosak-e, de biztos vagyok benne, hogy legalább az egyikük segít majd. Vidd el őket Dalaranba, és nézesd meg egy mágussal.$B$BElvégre nem hagyhatom el Booty Bay-t csak azért, hogy elcsevegjek azokkal a fárasztó öreg mágusokkal.$B$BNem mintha aggódnék, hogy bárki is megpróbálná könyékkel kitúrni a helyemet, hogy ő legyen az új báró. Senki sem szegül szembe Revilgaz-zal, hogy aztán elmesélhesse.' WHERE ID=601;
UPDATE quest_offer_reward SET RewardText='Az Árapály Köve? Igen érdekes. Talán meglep, hogy évekkel ezelőtt írtam egy kötetet a Gurubashi Birodalom legendáiról. Meglehetősen sokat tudok a Kőről.$B$BLegalább az egyik karvédőn úgy tűnik, van némi mágikus maradvány, amit elemezhetek.$B$BLássuk, mit tudok kideríteni...' WHERE ID=602;
UPDATE quest_offer_reward SET RewardText='A tőröm? Mi vagy te, valami komikus?$B$BMi? Csak azt akarod, hogy elismételjem a történetet, hogy lettem Booty Bay legjobb kés-harcosából a kalózvilág nevetség tárgya!$B$BElvesztettem egy késpárbajt az egyik Bloodsail kalóz ellen--egytől egyig gazemberek!--és elvitte a pengémet zsákmányként.$B$BNem mintha csak sértésekkel és éles nyelvvel boldogulnék kés-harcosként...' WHERE ID=603;
UPDATE quest_offer_reward SET RewardText='Tökéletes, $N. Most, hogy ismerjük a tervüket, csak idő kérdése.$b$bÉs csak elgondolni, hogy azok a bolondok épp a fok mellett vetettek horgonyt...' WHERE ID=604;
UPDATE quest_offer_reward SET RewardText='Aha! Ezek pont megteszik, $N. Igen, egészen jól!$B$BItt a részesedésed, és... öröm volt üzletelni veled.' WHERE ID=605;
UPDATE quest_offer_reward SET RewardText='Áh! Honnan szerezted ezeket? Ne, ne mondd meg. Nem akarom tudni!$B$BKi küldött? A Tengeri Farkas?' WHERE ID=606;
UPDATE quest_offer_reward SET RewardText='Heh heh, szép munka! És amikor megmutattad Shakynek azokat a belsőségeket, mennyire remegett?$B$BHah! Olyan könnyű kiolvasni, amikor kártyázom vele, mindig nyerek!$B$BKöszönöm a segítségedet, $N. Most rajtad a sor, hogy megkapd a fizetséged...' WHERE ID=607;
UPDATE quest_offer_reward SET RewardText='Á, micsoda nagyszerű nap ez a Blackwater Raidersnek! Háromszoros éljen neked, $N!' WHERE ID=608;
UPDATE quest_offer_reward SET RewardText='Remek! Jó árat kapok ezekért, különösen azért, ami Maury lábában van! Nagyon köszönöm, $N!$b$bRemélem, az a három megtanulta a leckét: ne tégy fel olyat, amit nem engedhetsz meg magadnak, hogy elveszíts.$b$bÉs talán már késő nekik, de... óvatosabbnak kellene lenniük, kivel szerencsejátékoznak.' WHERE ID=609;
UPDATE quest_offer_reward SET RewardText='Legyőzted Duncant? Gondolom, nem vagy annyira zöldfülű, mint amilyennek első pillantásra tűntél.$b$bGondolom ez azt is jelenti, hogy nem kéne kihívnom harcra a közeljövőben!' WHERE ID=610;
UPDATE quest_offer_reward SET RewardText='Elképesztő! Az Árapály Köve! Kiemelt helyet kap majd az ősi troll ereklyékből álló gyűjteményemben. Láttad, ahogy szinte úgy tűnik, mintha egy dagály lenne csapdába ejtve a felszínén? Csodálatos!' WHERE ID=611;
UPDATE quest_offer_reward SET RewardText='Megtaláltad! Millió köszönet, $N. Nagy segítségemre voltál!$b$bTessék - kiérdemelted!' WHERE ID=613;
UPDATE quest_offer_reward SET RewardText='Megtaláltad! Ó, micsoda boldog nap! Köszönöm, $N. Hogy visszakaptam a ládámat, kicsit lehűti a bennem égő tüzet.$b$bDe a bosszúm még nem teljes...' WHERE ID=614;
UPDATE quest_offer_reward SET RewardText='Helló, helló, $N. A kapitány mondta, hogy Negolash után eredsz, mi?' WHERE ID=615;
UPDATE quest_offer_reward SET RewardText='Érdekes. Emlékszem, valamikor régen olvastam egy könyvet, ami azt sugallta...$b$bÁ, persze, egy troll legenda volt. Ha igaz, amit Krazek jelent, talán hamarosan hozzáadhatom az Árapály Kövét az ősi ereklyékből és relikviákból álló gyűjteményemhez.' WHERE ID=616;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N. 10 szál akiris-nád végül is nem volt túl nagy kihívás, mi? Nem akarok tiszteletlen lenni a naga-kkal, de hát mindenkinek meg kell élnie valamiből.' WHERE ID=617;
UPDATE quest_offer_reward SET RewardText='Megszerezted a handzsáromat Negolashtól! El sem hiszem a szerencsémet, $N! A veled való találkozás jobbra fordította a sorsomat, ebben biztos lehetsz!$B$BKöszönöm! És ha valaha új hajóm lesz, és kedved lenne tengerre szállni, tiszteletbeli vendégem lennél.' WHERE ID=618;
UPDATE quest_offer_reward SET RewardText='Ételt és italt halmozol fel a tutajon...' WHERE ID=619;
UPDATE quest_offer_reward SET RewardText='Helló. Van dolgod velem?' WHERE ID=620;
UPDATE quest_offer_reward SET RewardText='Á, nagyon jó! Itt a fizetséged.$B$BÉs itt egy kis extra is... a diszkréciódért.' WHERE ID=621;
UPDATE quest_offer_reward SET RewardText='Megjavítva! Ez remek, most már elkezdhetem a vacsorát! Nagyon köszönöm, $N.$B$BRemélem, minden rendben volt veled Booty Bay-ben. Az a hely elég durva tud lenni, és... hallottam pletykákat, hogy a goblinok néha berúgott tengerészeket hurcolnak a rabszolgahajóikra, és elviszik őket isten tudja hova... isten tudja mit tenni velük...' WHERE ID=622;
UPDATE quest_offer_reward SET RewardText='Mi?! Sokkal jobb dolgom van, mint hogy egy hozzád hasonlóval beszéljek, $c. Tedd megérje az időmet, vagy tűnj a szemem elől.$B$BHuh? Bloads küldött, mi? Nos, mid van a számomra?$B$B<Groy kalóz alaposan végignézi a köteget.>$B$BNem rossz, egyáltalán nem rossz. Egy újabb köteg boldoggá teszi az ügyfelemet.$B$BGondolom, a következő kérdésed a pénzről szól, mi, $c? Persze hogy arról!$B$BTessék, fogd ezt az érmét, és egy tanácsot: tűnj el a dokkjaimról.' WHERE ID=623;
UPDATE quest_offer_reward SET RewardText='Az átázott pergamen tartalmazza a következő nyomot...' WHERE ID=624;
UPDATE quest_offer_reward SET RewardText='Egy dohos tekercset találsz.' WHERE ID=625;
UPDATE quest_offer_reward SET RewardText='Kinyitod a ládát, és felfedezed...' WHERE ID=626;
UPDATE quest_offer_reward SET RewardText='Á, pompás! Nagy szívességet tettél nekem.$B$BItt a fizetséged...' WHERE ID=627;
UPDATE quest_offer_reward SET RewardText='Remek! Segítségednek köszönhetően teljesítem ezt a megrendelést, és elküldöm Riddlevox igazgatónak a következő Undermine-i hajóval. Sőt, a menetrend előtt!$b$bKemény munkádért, tessék, készítettem néhány extrát, szóval vigyél egy párat. Drizzlik állja.$b$bÉs ne feledd, nincs olyan finom csizma, mint Drizzlik Excelsior szériája!' WHERE ID=628;
-- quest_offer_reward.RewardText. Batch 13: quest IDs 629-679.

UPDATE quest_offer_reward SET RewardText='Ez jó. Amikor visszatérek Orgrimmarba, szent helyre teszem ezt a szilánkot. Emlékeztetni fog minket Gri''lek erejére és becsületére.$b$bKöszönöm, $N. Tetteid egyre erősebb barátságot jelentenek a Darkspear törzzsel.' WHERE ID=629;
UPDATE quest_offer_reward SET RewardText='$N, megmentettél egy nagy szégyentől. Ha hatalmamban állna, helyet ajánlanék neked a törzsemben. De most csak ezt a jelet adhatom neked a mutatott bátorságodért és nemességedért.' WHERE ID=630;
UPDATE quest_offer_reward SET RewardText='Átkutatod a kicsi, törp holttestet. A sisakba vésve tisztán olvasható: Ebenezer Rustlocke.' WHERE ID=631;
UPDATE quest_offer_reward SET RewardText='Egek, a hír komoly...' WHERE ID=632;
UPDATE quest_offer_reward SET RewardText='A megmaradt híd megmenekült! Nagy szolgálatot tettél Magni királynak és Khaz Modan népének.$B$BMost már csak annyira kell kitartanunk, hogy megérkezzen az erősítés...' WHERE ID=633;
UPDATE quest_offer_reward SET RewardText='Részvétem Longbraidnek és bátor katonáinak. A Thandol Span tragédiájának és Dun Modr elestének híre nehezen nyomja a szívemet.$b$bDe Stromgarde is elesett! Ezért vagyunk itt Refuge Pointe-nál. Az a feladatunk, hogy visszafoglaljuk saját nagyszerű városunkat.$b$bA becsület és a kötelesség megköveteli, hogy ne hagyjuk el a Felföldeket, amíg Stromgarde ismét fel nem lobogtatja a Király hatalmas zászlaját. Üzenetet küldök Longbraidnek, hogy magára maradt...' WHERE ID=634;
UPDATE quest_offer_reward SET RewardText='Ez a kristály lüktet, mintha egy élő erő lenne csapdába ejtve benne.' WHERE ID=635;
UPDATE quest_offer_reward SET RewardText='Azt mondod, láttad a Sullymat a jeges víz alá szorulva? Mondd, hogy nem igaz!$B$BHadd olvassam el, mit írt...' WHERE ID=637;
UPDATE quest_offer_reward SET RewardText='Hogy vagy, $c? A Vol''jin által ránk bízott feladat nehéz lesz, és bármilyen segítséget, amit nyújtasz, nagyra értékelünk, és szükségünk is lesz rá.' WHERE ID=638;
UPDATE quest_offer_reward SET RewardText='Kiváló, haver. Ez jó kezdet a pecsétek összegyűjtéséhez, amikre szükségünk lesz, hogy kivegyük Trol''kalart Trollbane sírjából.' WHERE ID=639;
UPDATE quest_offer_reward SET RewardText='Á, azt akarod, hogy helyreállítsam ezt a pecsétet? Nem lehet túl nehéz... úgy tűnik, minden darab megvan, és a mágikus szerkezetet könnyű lesz újraformálni.$b$bTalán jobb, ha becsukod a szemed.' WHERE ID=640;
UPDATE quest_offer_reward SET RewardText='Félúton vagyunk ahhoz, hogy kivegyük Trol''kalart Trollbane sírjából. Nem tudjuk pontosan, hol van a harmadik pecsét, mert a birtokosai elég sokat mozognak Arathiban, de hiszek benne, hogy meg tudod találni.' WHERE ID=641;
UPDATE quest_offer_reward SET RewardText='Á! Aktiváltad ezeket a szilánkokat. Már most jobban érzem magam!$b$bDe sajnos még mindig messze vagyok a szabadságtól...' WHERE ID=642;
UPDATE quest_offer_reward SET RewardText='A lovassági vezérük elvesztése nagy csapás lesz a Stromgarde védőinek. Ami még jobb, ez azt jelenti, hogy már csak egy pecsétre vagyunk attól, hogy megszerezzük Trol''kalart magunknak.' WHERE ID=643;
UPDATE quest_offer_reward SET RewardText='Micsoda nap ez, $c. Trollbane vére többé nem kísérti a népemet, és a Trol''kalar megszerzéséhez szükséges pecsétek a birtokunkban vannak. Hamarosan, nagyon hamar lecsapunk Zul''Gurub gyűlölt trolljaira.' WHERE ID=644;
UPDATE quest_offer_reward SET RewardText='Ahogy Trollbane sírjának felszínén lévő vonalakat összeilleszted Ignaeus Pecsétjének ragyogó vonalaival, egy fényvillanás elnyeli a pecsétet, és a legendás kard, Trol''kalar kiszabadul a kőkezek szorításából.' WHERE ID=645;
UPDATE quest_offer_reward SET RewardText='Generációkon át Strom és Arathor erői pusztították a trollokat. Most a legnagyobb fegyverük a kezünkben van. Lassú előrehaladásunknak Zul''Gurub gőzölgő erdeiben vége.$b$bNagyszerű volt a segítséged, $N, és a Darkspear trollok hálásak neked.$b$bGondoskodom róla, hogy a kardot eljuttassák Nimboyához Grom''golba.' WHERE ID=646;
UPDATE quest_offer_reward SET RewardText='Á, semmi sem melegít fel jobban egy hűvös napon, mint Foggy MacKreel pálinkája! Én meg azt hittem, az a kis csirkefogó megint elkésik a fizetéssel. Köszönöm, barátom! Nagyon köszönöm!' WHERE ID=647;
UPDATE quest_offer_reward SET RewardText='Ó, TE vagy az OOX-17/TN nagy megmentője! El sem tudom mondani, mennyire hálás vagyok a segítségedért! Az önvezérlő robot sorozatomnak még sok fejlesztésre van szüksége, de a megmentésed rengeteg órányi újjáépítést és sok aranyat spórolt meg nekem!$b$bKérlek, válassz bármelyiket ezekből a tárgyakból, amim van. Remélhetőleg jó hasznát veszed valamelyiknek. Köszönöm még egyszer a nagylelkű segítségedet, a robotjaim és én is tartozunk neked!' WHERE ID=648;
UPDATE quest_offer_reward SET RewardText='Ó igen, a ripple, amit apa akar! El akarja adni egy kocsmának itt, Orgrimmarban, de többet kapunk érte, ha az eredeti csomagolásában van. Ismerek valakit, aki meg tudja csinálni, és a Hinterlandsben van, ahol a ripple is. De ő, hát, egy magas elf.$b$bNos, jó magas elf, mert nem a Szövetség tagja. Nos, nem is annyira jó magas elf, mint inkább részeges magas elf. Szereti, sőt IMÁDJA a piát.' WHERE ID=649;
UPDATE quest_offer_reward SET RewardText='Á, szóval ismered Maltont? Régi ivócimborám. Tudod, találtam valamit, ami túlmutat a mesterséges szerződések és szövetségek határain - az alkoholt. Ha mindannyian oltanánk szomjunkat áldásos tulajdonságaival, mindannyian lelkileg sokkal jobb helyen lennénk.$b$bDe sajnos valami azt súgja, nem az alkohol megváltó erényeit tanulni jöttél ide, ugye.' WHERE ID=650;
UPDATE quest_offer_reward SET RewardText='<Myzrael a kövön keresztül beszél.>$b$bSikerült! Kinyitottad a Kötés Köveit! Érzem, ahogy a bilincsek körülöttem lazulnak, a szabadság pedig egyre közelebb kerül.$b$bNemes $c vagy, $N. A megmentőm!' WHERE ID=651;
UPDATE quest_offer_reward SET RewardText='A pálcát a zárókőbe helyezed. És egy remegést érzel a lábad alatt...' WHERE ID=652;
UPDATE quest_offer_reward SET RewardText='A Hölgy elmondta nekem, hogy jönni fogsz, $c. Szívesen látlak a hajlékomban, hiszen te is, akárcsak én, egy magasabb célt szolgálsz.' WHERE ID=653;
UPDATE quest_offer_reward SET RewardText='Rendben, csak egy másodpercbe telik eltávolítani az energiaforrást. Utána azt csinálsz vele, amit csak akarsz, anélkül, hogy aggódnod kéne a benne lévő adatok elvesztése miatt.' WHERE ID=654;
UPDATE quest_offer_reward SET RewardText='Á, Gor''mulról beszélsz. Igen, amennyire elmondja, úgy tűnik, sosem heverte ki Doomhammer halálát.$B$BGor''mul fogoly volt itt, amikor Thrall és Orgrim harcoltak, hogy felszabadítsák a tábort, de amikor megremegett a föld, és testvéreink megmenekültek, ő hátramaradt. Éveken át bolyongott egyedül és elveszve, útmutatás és remény nélkül, míg vissza nem tértünk, hogy megtelepedjünk itt, Hammerfallban.' WHERE ID=655;
UPDATE quest_offer_reward SET RewardText='Ahogy a hátborzongató bilincseket a Szilánkok köré helyezed, embertelen jajgatás hallatszik messze lentről. A sikolyt üvöltés követi.$b$bMyzrael Szilánkjai már nem keltenek melegséget és biztonságot, mint egykor. Most nyílt fenyegetéssel lüktetnek... mintha az alattuk lévő valami rosszindulattal viseltetne a felszín iránt.' WHERE ID=656;
UPDATE quest_offer_reward SET RewardText='Ha ez békét hoz Phinnek, személyesen pusztítom el az Elhagyatottak mindegyikét. Annyi mindent tett értünk a pestis óta. Sosem hittük, hogy valaha is barátokat vagy családot találunk újra.$B$BAmikor felkészültél, szólj nekem. Rögtön nekiállunk.' WHERE ID=657;
UPDATE quest_offer_reward SET RewardText='Kiváló!$B$BLássuk, miről is van szó...' WHERE ID=658;
UPDATE quest_offer_reward SET RewardText='Próbálj a lehető legcsendesebben maradni, utazó.$B$BAz orkok nem szeretik, ha kikémlelik őket, és ez a farm több, mint amilyennek elsőre tűnik.' WHERE ID=659;
UPDATE quest_offer_reward SET RewardText='Nagy szolgálatot tettél nekünk, $N. Köszönöm.$B$BRemélem, Kin nem okozott túl sok gondot odalent. Nagyon barátságos, de ugyanolyan halálos is tud lenni, ha az ellensége vagy.' WHERE ID=660;
UPDATE quest_offer_reward SET RewardText='Szóval a két bajkeverő végül is jól van? Haha, örülök, hogy ezt hallom. Köszönöm, hogy hírt hoztál a hollétükről és állapotukról--nagyon örülök, hogy még életben vannak; pótolhatatlanok barátként és útitársként.$B$BDe... fontosabb, hogy megfelelően megköszönjem a segítségedet. Tessék. Fogadd ezt a csoportom köszönetével együtt.$B$BHa szerencsénk van, kiderítjük, mire készülnek az Elhagyatottak, és véget vetünk neki.' WHERE ID=661;
UPDATE quest_offer_reward SET RewardText='Tudni, hogy ez az információ biztonságban van, némi megnyugvást hoz a Booty Bay-i parancsnokságnak. Szép munka, $N.' WHERE ID=662;
UPDATE quest_offer_reward SET RewardText='Ahoj, cimbora.$b$bSzörnyű zűrzavar volt. Seahorn elveszi a hajómat, ha megtudja, mi történt.$b$bA Professzor egyik szerkezete azt jelezte, hogy az elveszett kincs ennél az öbölnél van. Behoztam a Harbingert kikötni, és jeleztem a Spirit of Silverpine-nak és a Maiden''s Follynak, hogy kövessék.$b$bAztán megdübörgött a tenger. Az árapály lecsökkent, és a két hajó a zátonynak csapódott.$b$bDe ez nem csak zátony. Van ott lent valami...$b$bSegíts a legénységemnek, és bőségesen megjutalmazlak.' WHERE ID=663;
UPDATE quest_offer_reward SET RewardText='Szép munka odakint, $N.$b$bAz a söpredék megkapta, amit érdemelt. Bár semmi sem hozza vissza a hajómat vagy a legénységemet, azok a naga-k halála némi vigaszt nyújt.' WHERE ID=664;
UPDATE quest_offer_reward SET RewardText='A védőszemüveg most tökéletesen működik! Szép munka, $N.' WHERE ID=665;
UPDATE quest_offer_reward SET RewardText='Igazán kiváló, $N! A kapitány nagyon elégedett lesz! És várd csak meg, mit szól hozzá Seahorn flottamester!' WHERE ID=666;
UPDATE quest_offer_reward SET RewardText='Túléltük a támadást!$b$bNélküled nem sikerült volna, $N.$b$bIndulunk, amint feljön a dagály. Ha nem lennél ilyen ígéretes hős, felajánlanék neked egy helyet a legénységemben. De látom, nagyobb halakra vadászol.$b$bMég ha csak egy vézna $r is vagy...' WHERE ID=667;
UPDATE quest_offer_reward SET RewardText='Szóval a kis gnómok mégis megmutatták, mit érnek? Tudtam, hogy nem hiába tartjuk itt azokat a bokaharapdálókat!' WHERE ID=668;
UPDATE quest_offer_reward SET RewardText='Á, bízzuk csak a jó öreg Shakes O''Breenre! Tudtam, hogy ő a megfelelő kapitány erre a küldetésre!' WHERE ID=669;
UPDATE quest_offer_reward SET RewardText='Köszönöm, hogy megtetted ezt a hosszú és veszélyes utat. A Blackwater Raiders hálája a tiéd.' WHERE ID=670;
UPDATE quest_offer_reward SET RewardText='Időbe telik majd, mire kiderítem a Syndicate valódi szándékait, de a sötét, démoni mágiával való nyilvánvaló kapcsolatuk aggaszt. Szólok, ha többet tudok.' WHERE ID=671;
UPDATE quest_offer_reward SET RewardText='Kiváló. A raptorok szellemei, akiktől ezek a szemek származnak, erőt adnak majd az amulett viselőjének.' WHERE ID=672;
UPDATE quest_offer_reward SET RewardText='Nyugtalan éjszakáim békés szendergéssé válnak majd, ha elpusztítom ezt a gömböt. Köszönöm, $N. Baljós emlékeztető arra a szörnyű hatalomra, amit a démonok gyakoroltak az orkok felett, mielőtt Hellscream megszabadította őket az átkuktól.' WHERE ID=673;
UPDATE quest_offer_reward SET RewardText='Ez meg mi? Csiszolt csont. Mi hasznom van egy csiszolt csontból? Egy csecsebecse visszaadja a Horda dicsőségét?' WHERE ID=674;
UPDATE quest_offer_reward SET RewardText='Látom, nem működött. Mindazonáltal úgy érzem, ha megmutatjuk neki a sámánok erejét, az idővel visszaadja Gor''mulnak egykori büszkeségét. Az amulett ereje nem volt elég nagy ahhoz, hogy megmutassa neki újonnan szerzett hatalmunkat.' WHERE ID=675;
UPDATE quest_offer_reward SET RewardText='Szóval azt hiszed, elég erős vagy, hogy segíts Hammerfallnak? Legyen.$b$bTallow vagy azzal a reménnyel küldött arra az ogré-halomra, hogy megölöd magad, vagy úgy gondolja, elég erős vagy, hogy segíts nekünk. Bárhogy is legyen, most itt vagy, és nekem több katonára van szükségem a folyamatos támadások elleni harcunkhoz.$b$bHa Hammerfallban tervezel maradni, pihenj egy kicsit, és jöjj vissza beszélni velem, amikor készen állsz. Nem lesz hiány harcból.' WHERE ID=676;
UPDATE quest_offer_reward SET RewardText='A háború jelei ott vannak a ruhádon, és izzadság csöpög a homlokodról. Jó, valóban nagyon jó.' WHERE ID=677;
UPDATE quest_offer_reward SET RewardText='Erős vagy, mint egy kodó, és csatavágyad büszkévé teszi a népedet.' WHERE ID=678;
UPDATE quest_offer_reward SET RewardText='Büszkévé teszed a népedet, $N. A fenyegetés jelentősen csökkent, és biztos vagyok benne, hogy virágzásnak indulunk majd itt a Felföldeken.' WHERE ID=679;
-- quest_offer_reward.RewardText. Batch 14: quest IDs 680-730.

UPDATE quest_offer_reward SET RewardText='Nagy szolgálatot tettél nekem, $N. Tudd, hogy a férjem élete és Hammerfall biztonsága egy nappal tovább védve maradt a tetteid által. Kérlek, fogadd ezt bátorságod jutalmául.' WHERE ID=680;
UPDATE quest_offer_reward SET RewardText='Nagyon jó, $N. Azon Syndicate-tagok halálával könnyebben kapunk majd ellátmányt Southshore-ból.$b$bTalán ügyünknek mégis van reménye.' WHERE ID=681;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Értesítjük ezeknek az elesett katonáknak a családjait, hogy csatában haltak meg.$b$bKomor hír lesz, de jobb, mint egy eltűnt szeretett személy bizonytalansága.' WHERE ID=682;
UPDATE quest_offer_reward SET RewardText='Csak egy pillanatba telik átfutnom ezt a levelet...' WHERE ID=683;
UPDATE quest_offer_reward SET RewardText='Legyőzted Marez Cowlt? Szép munka, $N. Valóban szép munka!$b$bMarez fenyegette Stromgarde védőit, és a szóbeszéd szerint közvetítő volt a Syndicate és valamilyen más, sötétebb hatalom között. Örülünk, hogy már nem veti be ellenünk erejét.' WHERE ID=684;
UPDATE quest_offer_reward SET RewardText='Falconcrest és Otto? Csodálatos!$b$bItt a jutalmad, $N. Örömmel fizetem.' WHERE ID=685;
UPDATE quest_offer_reward SET RewardText='Szóval maga Magni Bronzebeard király küldött téged?$B$BEgek! Ennek fontosnak kell lennie!' WHERE ID=686;
UPDATE quest_offer_reward SET RewardText='Helló. Helló, helló helló helló helló HELLÓ!$B$BSajnálom - várj, nem is! Ne légy udvariatlan!$B$BÓ nem... ez őrült beszéd volt.$B$BDe... néha az őrültség az egyetlen vigaszom.' WHERE ID=687;
UPDATE quest_offer_reward SET RewardText='Üdvözöllek, $c. A Hölgy tájékoztatott érkezésedről, és ha vissza akarjuk hozni a felszínre, sok mindent meg kell beszélnünk...' WHERE ID=688;
UPDATE quest_offer_reward SET RewardText='Tökéletes! Jobb, mint amit valaha is elképzeltem volna!$B$BPedig elég élénk a fantáziám, tudod...' WHERE ID=689;
UPDATE quest_offer_reward SET RewardText='Szóval Malin küldött? Nem érdekel, ha Muradin támadt fel a halálból, és sárkányháton hozott ide. El vagyok foglalva! Beszélj Krytennel, ha valamire szükséged van.' WHERE ID=690;
UPDATE quest_offer_reward SET RewardText='Hihetetlen! Már látom, miért kért Malin, hogy csatlakozz hozzánk - valóban nagyon szép munka!$B$BEbben az ütemben Skuerto és én hamarosan visszatérünk Stormwindba.$B$BAzt hiszem, törp társam visszatért a Boulderfist Hall felderítéséből; beszélj vele, ha készen állsz.$B$BÚgy tűnt, mintha kicsit összetűzésbe került volna az ogrékkal. Ne is említsd neki, ha lehet; nagyon érzékeny a felderítői képességeit ért kritikákra.' WHERE ID=691;
UPDATE quest_offer_reward SET RewardText='Á, megtaláltad őket! Szép munka, $N! Ezek lehetnek az egyetlen esélyünk Myzrael gonoszsága ellen!$b$bCsak hadd találjam meg a hulladékracsnimat, és megnézem, vissza tudom-e illeszteni ezeket a töredékeket...' WHERE ID=692;
UPDATE quest_offer_reward SET RewardText='Zseniális, $N. Egy tárgy megvan, még hármat kell szereznünk, a listám alapján. A másik három tárgy mind Stromgarde-ban van.$B$BPihenj egy kicsit, gyűjtsd össze az erődet--a tervem következő szakasza kicsit több időt és erőfeszítést igényel majd. Gyere vissza hozzám, miután ettél egy meleg ételt, és kipihented magad.' WHERE ID=693;
UPDATE quest_offer_reward SET RewardText='Lenyűgözöl, $N. Ismét szép munka.$B$BAdj egy pillanatot, hogy elmondjam a megfelelő varázslatot a drágakő megbűvölésére, és készen leszel.' WHERE ID=694;
UPDATE quest_offer_reward SET RewardText='Jó, jó.$b$bHa nincs több késlekedés, kezdjünk hozzá?' WHERE ID=695;
UPDATE quest_offer_reward SET RewardText='Malin nem kérhetett volna méltóbb személyt, hogy idejöjjön és segítsen nekünk, $N. Remek munkát végeztél!$B$BÖrülni fog majd, milyen elsöprő sikert aratott a küldetésünk.' WHERE ID=696;
UPDATE quest_offer_reward SET RewardText='<Malin főmágus kinyitja a levelet, és tágra nyílik a szeme.>$B$BA Fényre, sikerült. Milyen csodálatos. Trelane nagyon elégedett lesz. Biztos vagyok benne, hogy Kryten és Skuerto ugyanolyan izgatottak, mint én, hogy visszatérhetnek Stormwindba.$B$BKöszönöm, $N. Kérlek, fogadd el ezt, hogy segítsen az utazásaidban.' WHERE ID=697;
UPDATE quest_offer_reward SET RewardText='Á! Csodálatos. Friss hús a mai tűzhöz. Köszönöm, $N.$b$bSegítettél elviselhetőbbé tenni a következő éjszakákat. A tűz fényesen ég, a gyomrunk pedig tele lesz.$b$bKellemes meglepetés, hogy szállítmányt hoztál nekünk; Dar nem a legvonzóbb ork, akit valaha látott az ember, de legalább a modora sokkal kevésbé bűzlik, mint a szaga.' WHERE ID=698;
UPDATE quest_offer_reward SET RewardText='Örülök, hogy élsz és jól vagy, $N.$b$bEzek a karmok pont megfelelnek. Minél több fegyverünk van készenlétben az ellenünk irányuló támadásokhoz, annál jobban járunk.$b$bMihamarabb nekilátok a fegyveredhez. Csak rövid időt vesz igénybe. Egészen ügyes és gyors lettem az elkészítésükben.' WHERE ID=699;
UPDATE quest_offer_reward SET RewardText='A gránit csak apró jelnek tűnik egy nagyszerű törp életéhez képest. De egyetlen törp sem marad örökké ezen a bolygón.$B$BReméljük hát, hogy az emlékmű emlékeztetőül szolgál majd azoknak, akik a jövő nagyszerű Azerothját fogják taposni. Nehogy elfelejtsük, hogy értük adták életüket olyan bátor katonák, mint Sully Balloo.' WHERE ID=700;
UPDATE quest_offer_reward SET RewardText='Igen, ezek tökéletesen megfelelnek. Átviszem az erejüket és a raptorok szellemét ebbe a gömbbe. Ez a gömb megajándékozza majd Gor''mult a raptor tüzes erejével és intelligenciájával.' WHERE ID=701;
UPDATE quest_offer_reward SET RewardText='Legalább valami érdekeset hoztál nekem ezúttal. Furcsa erőt sugároz...' WHERE ID=702;
UPDATE quest_offer_reward SET RewardText='Á, rögtön nekilátok azoknak a szárnyaknak. Már szinte az ízüket is érzem!$b$bÉs itt a recept is, ha magad szeretnéd elkészíteni őket!' WHERE ID=703;
UPDATE quest_offer_reward SET RewardText='Szép munka! Szerencsével és szorgalommal megtaláljuk majd a kapcsolatot a troggok és ezek az ősi ereklyék között.$B$BNagyszerű tettet vittél véghez a Kutatókért, $N. Erőfeszítéseidet nem felejtjük el. Ahogy Agmondot sem.' WHERE ID=704;
UPDATE quest_offer_reward SET RewardText='Ezek remekül fognak működni! Csak porrá kell zúznom őket... aztán összekeverni egy kicsivel ebből, egy kicsivel abból.$b$bVigyázzatok, dögevők! Készüljetek fel a villanásra!' WHERE ID=705;
UPDATE quest_offer_reward SET RewardText='Á igen, ez kiválóan megteszi. Ez lehetővé teszi majd, hogy fegyvereid perzselő hővel csapjanak le!' WHERE ID=706;
UPDATE quest_offer_reward SET RewardText='Szóval Stormpike küldött, igaz? Jó.$B$BVan egy nagy feladatom számodra...' WHERE ID=707;
UPDATE quest_offer_reward SET RewardText='Ó, a szerencse velünk van! Köszönöm! Talán mégis megmenekülünk!' WHERE ID=709;
UPDATE quest_offer_reward SET RewardText='Ezek pont megfelelnek, $N. Köszönöm. Hmm, kicsit több homok, mint vártam. Módosítanom kell a súrlódási együtthatót. Nem, várj; a fagyolajjal még mindig elhanyagolható kell legyen.$B$B<Magában motyogva Lotwil öklét a másik tenyerébe csapja, és úgy bámulja őket, mintha lenyűgözve lenne.>' WHERE ID=710;
UPDATE quest_offer_reward SET RewardText='$N, egyszerűen elképesztő! Azt hittem volna, fél tucat taurenre lesz szükség, hogy mindezt elhozzák nekem.' WHERE ID=711;
UPDATE quest_offer_reward SET RewardText='$N, gondoltál már arra, hogy kutatóasszisztens legyél? Nem? Nem tudom, mit fogok kezdeni a képességeid nélkül itt. Intelligencia, kíváncsiság, erő -- mind egyetlen csomagban.' WHERE ID=712;
UPDATE quest_offer_reward SET RewardText='Elképesztő! Ez lesz a tökéletes hűtőanyag az új karvédőimhez. Ha a varázslatok nem tartanak ki egy évszázadig, akkor odaadom minden vagyonomat Servónak.$B$BA Gyülekezet minden mágusa ámulatba fog esni, ha ezzel végzek, $N. Csak várj, majd meglátod.' WHERE ID=713;
UPDATE quest_offer_reward SET RewardText='HA!$b$b<Lotwil elveszi tőled a girokronatomot.>$b$bTökéletes... szinte kész. Nem, tényleg. MOST tényleg majdnem kész vagyok. Ez a projekt a legfőbb prioritásom... jelenleg. Hadd tegyem a helyére, és magad is láthatod, miben segítettél nekem.$b$bCsak még pár perc... talán... esetleg tovább. Nos, talán sokkal tovább. Majd meglátjuk...' WHERE ID=714;
UPDATE quest_offer_reward SET RewardText='IGEN!$b$bÚgy értem, köszönöm, $N. Ezek hasznosak lesznek a Badlandsen átutazva.' WHERE ID=715;
UPDATE quest_offer_reward SET RewardText='Tessék, $N. Próbáld fel ezeket.' WHERE ID=716;
UPDATE quest_offer_reward SET RewardText='A Kirin Tornak többé nem kell aggódnia Lethlor foglyai miatt. Visszatérek, hogy jelentsem a sikert mesteremnek. Krasus kétségkívül elégedett lesz.' WHERE ID=717;
UPDATE quest_offer_reward SET RewardText='Nagyon köszönöm, $N. Amíg távol voltál, én... öhm... lenyeltem egy szájnyi homokot. Az...$B$BNos, elég ebből, ma este kimegyünk, és szerzünk egy kis ételt. Úgy eszünk majd, mint a királyok!' WHERE ID=718;
UPDATE quest_offer_reward SET RewardText='Te vagy a megmentőm, $c. Örülök, hogy valaki móresre tudta tanítani azokat a Shadowforge-okat. Köszönöm a segítségedet.' WHERE ID=719;
UPDATE quest_offer_reward SET RewardText='Hammertoe él?! Ez elképesztő, $N!' WHERE ID=720;
UPDATE quest_offer_reward SET RewardText='Igen? Bocsáss meg... <köhög> Olyan gyengének érzem magam. Jönnél közelebb, $c?$B$BRyedol küldött? Muradin áldja meg, az a fiú nem is olyan lassú észjárású, mint ahogy egykor gondoltam. <köhög>' WHERE ID=721;
UPDATE quest_offer_reward SET RewardText='Ha! <köhög köhög>$B$BTudtam, hogy megtalálod az amulettemet, $N.$B$B<zihál> Valóban szép munka, $N. <köhög>' WHERE ID=722;
UPDATE quest_offer_reward SET RewardText='Hammertoe amulettje? Azt hiszem, jobb kedvem volt, amikor még halottnak hittem. A bizonyosság csak súlyosbítja a fájdalmat. Ez az amulett volt élete munkája. Nem hagyhatom, hogy hiába haljon meg.' WHERE ID=723;
UPDATE quest_offer_reward SET RewardText='Ó! Nos, ez teljesen más ügy. Valószínűleg még nem érted ennek a súlyosságát, ugye?$B$BMélyen érint Hammertoe halála, de ha elküldött téged az amulettjével, akkor megértette, mi forog kockán.$B$BKésőbb kell majd időt szánnunk a gyászára.$B$BHadd mutassam meg, miért is olyan értékes ez az amulett.' WHERE ID=724;
UPDATE quest_offer_reward SET RewardText='Á, hír Karnik történésztől. Kiváló.$B$BMindig van időm az ő ügyeire.$B$B<Belgrum tanácsadó kinyitja az üzenetet, és olvasni kezdi.>' WHERE ID=725;
UPDATE quest_offer_reward SET RewardText='Olyan sürgősséggel kezeled ezt az ügyet, amit magától a királytól várnék, $N.$B$BRendben, akkor. Tudom, mi fogja legyőzni a Shadowforge-okat.$B$BUldaman-i jelenlétüket lelassíthatjuk, ha lecsapunk a műveleti bázisukra: az Angor-erődre.' WHERE ID=726;
UPDATE quest_offer_reward SET RewardText='Ó. Üdvözlégy, testvér.$B$BÉs dicsértessenek a mélyben lakók.' WHERE ID=727;
UPDATE quest_offer_reward SET RewardText='Légy diszkrét a jeleiddel, $c. Vannak, akik nem hisznek fogadalmunk igazságosságában.$B$BÉs vannak, akik örülnének a bukásunknak, ha tudnának rólunk.$B$BMindig óvatosnak kell lennünk. Éberen. És türelmesen.' WHERE ID=728;
UPDATE quest_offer_reward SET RewardText='Hollee, te vagy az? Segítségre van szükségem, hogy kifaragjam ezt a követ. Add ide a kőkefémet, azt hiszem, látok valamit.$b$bHé, te nem vagy Hollee! Nem láttad esetleg a kőkefémet?$b$bNa mindegy! Megígértem a Ligának, hogy elküldöm a rejtélyes kövületet, amit találtam. Hova lett Hollee?$b$bAnnyi tennivaló van! Most hol van az a rejtélyes kövület... és a kefém... és Hollee...$b$bÉs te ki vagy... na mindegy, amíg itt vagy segíteni.$b$bSzólj, ha készen állsz elkezdeni a keresést.' WHERE ID=729;
UPDATE quest_offer_reward SET RewardText='Nagyon örülök, hogy Greywhisker főrégész elküldött minket...' WHERE ID=730;
-- quest_offer_reward.RewardText. Batch 15: quest IDs 731-782.

UPDATE quest_offer_reward SET RewardText='Hála az égnek, Remtravel kutató biztonságban van! Mondtam, hogy szórakozott. El sem hiszem, hogy ragaszkodott ahhoz, hogy ott maradjon mindazokkal a szörnyű lényekkel, amik ott ólálkodnak.' WHERE ID=731;
UPDATE quest_offer_reward SET RewardText='Jó híreket hozol a Jellel, $N. A Föld Jelét az Angor-erőd Dark Iron törpjei alkották, hogy megkössenek két Deathwing-hadnagyot, az ikreket, Blacklasht és Hematust.' WHERE ID=732;
UPDATE quest_offer_reward SET RewardText='Ez egy kezdet, $N, és meg kell elégednünk vele, amíg hírt nem kapunk Ironforge-ból vagy a Felfedezők Ligájától.$B$BMost csak azt kellene találnom valahol egy kis sót az edzőhordómhoz...' WHERE ID=733;
UPDATE quest_offer_reward SET RewardText='5-ös fogaskerék, mi? Igen, ez nem lesz jó.' WHERE ID=734;
UPDATE quest_offer_reward SET RewardText='Találékony vagy, $c. Ha valóban a te feladatod, hogy elkezdd rendünk új fejezetét, akkor hiszem, hogy jól fogod vezetni.' WHERE ID=735;
UPDATE quest_offer_reward SET RewardText='Le vagyok nyűgözve! Nagy tehetséggel, vagy nagy szerencsével rendelkezel, hogy megszerezted ezeket az ereklyéket. Bárhogy is legyen, hasznunkra vagy.' WHERE ID=736;
UPDATE quest_offer_reward SET RewardText='Megvan! Ó, felcsillan a remény!$B$BErőfeszítéseid talán mégis megmentenek minket, $N. Emlékművet kellene állítani neked! Szentélyt kellene építeni! Bárcsak dicsérnék a nevedet, amíg unokáidnak unokái nem lesznek!$B$BHacsak... ŐK ki nem szabadulnak, és fel nem törnek a felszínre. Ha ez történik, felejtsd el a gyerekeket.$B$BHa ŐK kiszabadulnak, mindannyian féregeledel leszünk.' WHERE ID=737;
UPDATE quest_offer_reward SET RewardText='Ez a csontváz biztos Agmond szerencsétlen maradványa. Teste eltört és összetört, csontjai lecsupaszítva.' WHERE ID=738;
UPDATE quest_offer_reward SET RewardText='Ez kijózanító hír, $N. De Agmond erős karral és félelmetes kalapácscsapással bírt, és a koponyája is a legkeményebbek közül való volt! Bár azok az átkozott troggok ölték meg, biztos vagyok benne, hogy sokat magával rántott közülük.' WHERE ID=739;
UPDATE quest_offer_reward SET RewardText='Egek! Csak Remtravel kutató tud ilyen leletet felfedezni!' WHERE ID=741;
UPDATE quest_offer_reward SET RewardText='Üdvözöllek az új határvidéken, $N. Ashenvale a lehetőségek földje, ahol egy hozzád hasonló ifjú $c korlátlan esélyt talál, hogy bizonyítsa rátermettségét. Nézz körül itt az őrhelyen, és mindenképp látogass el a Zoram-partra is, mert a Hordának ott is van egy másik őrhelye.$B$BJelenléted itt azt mondja nekem, hogy a vadászatról szeretnél többet megtudni. Figyelj jól, és szívesen megosztom veled, amit tudnod kell.' WHERE ID=742;
UPDATE quest_offer_reward SET RewardText='Jól teljesítettél, $N. Úgy tűnik, jól felkészültél a további útra. Legyen mindig hátszeled.' WHERE ID=743;
UPDATE quest_offer_reward SET RewardText='Köszönöm a segítségedet, $N.$b$bAz én szerepem a bátyám szertartásában majdnem teljes. Csak a fejdíszét kell átadnom neki, és tanúskodnom a szertartáson, ez minden, amit a kötelességem megkövetel tőlem.' WHERE ID=744;
UPDATE quest_offer_reward SET RewardText='$N, jó, hogy komolyan vetted a feladatomat. A föld és teremtményei tisztelete fontos. Az élet és a halál kör... szükségszerűség. Egyik sem létezhet a másik nélkül. Szánj időt ennek megfontolására, és sose felejtsd el.' WHERE ID=745;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Ez lecsillapítja Mulgore vadjait. És ha a szellemek is úgy akarják, megtanítja a törpöket, hogy a föld kivájása nem a tudás útja.' WHERE ID=746;
UPDATE quest_offer_reward SET RewardText='Narache taurenjei köszönik, $n. Sok ígéretet mutatsz.' WHERE ID=747;
UPDATE quest_offer_reward SET RewardText='Jól teljesítettél, $N. Fogom ezeket, és erejüket egy megtisztító totembe kötöm.' WHERE ID=748;
UPDATE quest_offer_reward SET RewardText='A láda minden oldalán a Venture Co. Bányászati Osztályának jele látható. A doboz oldalára gondosan nyomtatott jegyzetek szerint a tartalmat az egyik központi üzemükben kell feldolgozni.' WHERE ID=749;
UPDATE quest_offer_reward SET RewardText='Narache $R-jai köszönik ezt az ellátmányt, $N. Vadászati tudásoddal egy nap biztosan tisztelet övez majd Thunder Bluffban.' WHERE ID=750;
UPDATE quest_offer_reward SET RewardText='Valóban úgy tűnik, hogy a Venture Co. megpróbálja ellopni természeti erőforrásainkat. Jó, hogy biztosan tudjuk, és most úgy tűnik, tennünk kell valamit ellene.' WHERE ID=751;
UPDATE quest_offer_reward SET RewardText='Ilyen messzire utaztál csak azért, hogy segíts egy öregasszonynak? Ejnye, ejnye, hát nem vagy te aranyos?' WHERE ID=752;
UPDATE quest_offer_reward SET RewardText='Látom, visszahoztad ezt a korsót a Nagyanya kérésére.$b$bAz a hajlandóságod, hogy segíts másoknak, és gondoskodj a Camp Narache-i taurenekről, arra enged következtetni, hogy egy nap büszkévé teszed a törzsedet Thunder Bluffban.' WHERE ID=753;
UPDATE quest_offer_reward SET RewardText='Tettednek híre pillanatokkal ezelőtt ért el hozzám -- a kút közelében lévő állatok már mohón isznak belőle.$b$bNagyszerű dolgot tettél a földért, $N. És nagyszerű dolgot tettél a tauren népért.' WHERE ID=754;
UPDATE quest_offer_reward SET RewardText='Hawkwind főnök küldött? A Földanya rítusaira lépni nem kis feladat...' WHERE ID=755;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. A tisztaság, amellyel ezek a vadak vadásznak, létfontosságú a következő megtisztító totem elkészítéséhez.$b$bA goblinok sosem fogják megtanulni a különbséget a föld elleni küzdelem és a vele való harmonikus élet között.' WHERE ID=756;
UPDATE quest_offer_reward SET RewardText='Teljesítetted a Földanya rítusainak első próbáját. A törzs büszke lesz.' WHERE ID=757;
UPDATE quest_offer_reward SET RewardText='A Thunderhorn klán ősei szóltak hozzám álomban, dicsérve tetteidet a kútjuk közelében.$b$bHálájuk jeléül ezt akarják adni neked...' WHERE ID=758;
UPDATE quest_offer_reward SET RewardText='Nagyon jó, $N. Érzem a föld áldozatát ebben a felajánlásban, és lelkem szomorúsággal és büszkeséggel telik meg.' WHERE ID=759;
UPDATE quest_offer_reward SET RewardText='Sikerült. Megtisztítottad a kutakat, és meggyógyítottad a földünket. Bloodhoof falva hálás, $N.$b$bSuttogja a szél tetteidet száz évszakon át, és maradjanak Mulgore vizei örökre tiszták.' WHERE ID=760;
UPDATE quest_offer_reward SET RewardText='Tudom, hogy nem volt könnyű feladat összegyűjteni ezeket a tüskéket, $N. Ezzel bebizonyítod, hogy érdemekkel bíró $c vagy. Jó, hogy itt vagy Bloodhoof faluban.' WHERE ID=761;
UPDATE quest_offer_reward SET RewardText='$N, Ironforge és a törp nép iránti elköteleződésed vitathatatlan. Köszönöm a segítségedet ebben az ügyben.$B$BÜzenetet küldök Karnik történésznek, tájékoztatva, hogy sikerrel jártál, és mihamarabb segítséget is küldök a Badlandsbe, hogy segítsen helyreállítani az ásatás helyszínét. Még egyszer köszönöm.$B$BMielőtt mész, van még valami, amit Bronzebeard király nevében kérnék tőled.' WHERE ID=762;
UPDATE quest_offer_reward SET RewardText='Hír jó barátomtól, Hawkwind főnöktől! Á, a faragásaiból látom, különleges fajtából való vagy.' WHERE ID=763;
UPDATE quest_offer_reward SET RewardText='Nem hiszem, hogy sok félreértelmezésre vagy figyelmen kívül hagyásra lenne mód ezzel a jellel, mi? A Venture Co. megtanulja, hogy ne vegye félvállról a taureneket, és ne legyen olyan arrogáns, hogy azt higgye, tiltakozás nélkül hagynánk ellopni a körülöttünk lévő természeti erőforrásokat.' WHERE ID=764;
UPDATE quest_offer_reward SET RewardText='Dühöm kissé alábbhagy annak hírére, hogy a gazember Fizsprocket halott. Átnézem személyes holmiját, hátha van valami további információ arról, mit tervez a Venture Co. a jövőre nézve. Köszönöm az erőfeszítéseidet, $N.' WHERE ID=765;
UPDATE quest_offer_reward SET RewardText='Á, köszönöm, $N. Az általad hozott tárgyakkal el tudom készíteni azt a gyógyszert, amivel megállítom a fertőzés terjedését, és végül teljesen ki is gyógyítom. Az életemmel tartozom neked hálaként.$b$bDe sosem felejtem el azt a visító kiáltást, amikor Mazzranache rám támadt, a színek lángolását, ahogy csőre lecsapott...$b$bLégy óvatos az utazásaid során.' WHERE ID=766;
UPDATE quest_offer_reward SET RewardText='Éreztem, hogy hozzám jössz, $c. Mindig felismerem azt, aki a Földanya rítusait próbálja teljesíteni.' WHERE ID=767;
UPDATE quest_offer_reward SET RewardText='Á, ezek nagyon szép darabok. Remek bőráruk lesznek belőlük.$B$BTessék, $N. Fogd ezt cserébe...' WHERE ID=768;
UPDATE quest_offer_reward SET RewardText='Á, jó. Köszönöm, $N. A szívem büszkeséggel telik meg, amikor ifjakat látok érdeklődni a bőrművesség mestersége iránt.' WHERE ID=769;
UPDATE quest_offer_reward SET RewardText='Alig hiszek az öreg szememnek! Legyőzted a nagy farkast, Ghost Howlt? Új tisztelettel nézek rád, ifjú $c. Rendkívüli tehetségű $c vagy!$b$bHadd ajánljak neked valamit. Az én vadászéveim véget értek, de megtiszteltetés lenne, ha az egyik fegyveremet használnád a vadászataidon.$b$bTaláljon célba, és hozzon dicsőséget neked.$b$bÉs reméljük, Ghost Howl szelleme végre nyugalomra lelt.' WHERE ID=770;
UPDATE quest_offer_reward SET RewardText='Látom, megtanultad gyűjteni a szent földünkről, $N. Csak egy pillanatba telik, amíg megfőzöm a Látnokok vizét.' WHERE ID=771;
UPDATE quest_offer_reward SET RewardText='Ne félj, $N. Sikeresen teljesítetted a Látomás Rítusát.' WHERE ID=772;
UPDATE quest_offer_reward SET RewardText='Nagy szorgalmat mutattál abbéli vágyadban, hogy teljesítsd a Földanya rítusait, $N.$b$bMi, az Ősök Szellemei, a hatalmas taureneket képviseljük, akik bátran adták életüket, hogy megalapítsák és megvédjék nagyszerű városunkat, Thunder Bluffot. Ezennel átadom neked ennek a védelemnek a kötelességét.$b$bTeljesítetted a Bölcsesség Rítusát, ifjú $c. Lépj Thunder Bluffba büszkén.' WHERE ID=773;
UPDATE quest_offer_reward SET RewardText='Üdv, ifjú $c. Látom, megtaláltad az utat a küszöbömhöz.' WHERE ID=775;
UPDATE quest_offer_reward SET RewardText='Szép munka! Az egy remek ölés volt.$b$bKüldök egy gyűjtőcsapatot, hogy behozzák a tetemet, így megszerezhetjük a bőrt és a húst.$b$bNagyszerű tettet vittél véghez a népedért, $N.' WHERE ID=776;
UPDATE quest_offer_reward SET RewardText='Á, tökéletes. Állj hátrébb, amíg felkészülök, hogy még több történelmet írjak!$b$b<Lotwil lázasan tovább dolgozik.>' WHERE ID=777;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Elég komoly megpróbáltatás volt, nem igaz?$b$bNem vagyok biztos benne, mi mehetett félre. Szerencsére a mágiám itt volt, hogy segítsen visszaküldeni a lényt a hazai síkjára.$b$bTalán egy kis elismerés a kemény munkádért...' WHERE ID=778;
UPDATE quest_offer_reward SET RewardText='Ahogy a rúnaköveket a hozzájuk illő mélyedésekbe helyezed, heves dübörgés rázza meg a földet, ahogy a Pecsét megtörik.' WHERE ID=779;
UPDATE quest_offer_reward SET RewardText='Igazán kiváló. Ezekből az alapanyagokból remek pörkölt lesz, és azoknak a vadkanoknak az elvesztése méltó lecke lesz azoknak az aljas Bristlebackeknek.' WHERE ID=780;
UPDATE quest_offer_reward SET RewardText='Ez valóban elég riasztó! De ezzel az információval segítségül hívhatjuk testvéreinket Bloodhoof faluból, hogy meghiúsítsuk a támadást. Sok tauren életét mentetted meg, $N.' WHERE ID=781;
UPDATE quest_offer_reward SET RewardText='Tho''grun halálával, holttestét a sivatagi szelek és dögkeselyűk lecsupaszítva hagyják, az ogrék zűrzavarba esnek. Bár kis győzelem, ez egy sokkal nagyobbhoz vezet.$B$BA Föld Jele most a birtokunkban van, és megnyithatjuk a fekete sárkányok börtönét Lethlorban. Kiszabadítjuk őket a végtelen fogságból, bár a vesztükre!' WHERE ID=782;
-- quest_offer_reward.RewardText. Batch 16: quest IDs 783-847.

UPDATE quest_offer_reward SET RewardText='Á, jó. Egy újabb önkéntes. Mostanában sokan jönnek belőletek.$B$BRemélem, elég lesz.$B$BAz emberi földeket kívülről fenyegetik, és erőink nagy része külföldön van összevonva. Ez pedig teret ad a korrupt és törvénytelen csoportoknak, hogy virágozzanak a határainkon belül.$B$BSok fronton vívunk harcot, $N. Készülj fel egy hosszú hadjáratra.' WHERE ID=783;
UPDATE quest_offer_reward SET RewardText='Bátorságod híre gyorsan terjed, $c. Győzelmed híre a Tiragarde Keepnél visszhangzik majd Orgrimmarban.' WHERE ID=784;
UPDATE quest_offer_reward SET RewardText='A Horda kétségkívül győzedelmeskedne, ha a Kolkar kentaurok támadnának. De azzal, hogy megelőztük ezt a támadást, megkíméltük hatalmas harcosainkat a felesleges vérontástól.$B$BÉs ahogy biztos, hogy homok van a Tanaris-sivatagban, tudjuk, hogy vér fog folyni, mire ezek a próbatevő idők véget érnek.$B$BJól szolgáltad a népedet, $c.' WHERE ID=786;
UPDATE quest_offer_reward SET RewardText='Megint egy Eitrigg-újonc, mi?$B$BSzomorú állapotban vagyunk, ha ez a legjobb, amit a Horda produkálni tud. Nem baj. Mire úgy gondoljuk, készen állsz elhagyni a Völgyet, a Horda büszke harcosa leszel.' WHERE ID=787;
UPDATE quest_offer_reward SET RewardText='Hmmm, nem rossz, $N. De ne szálljon a fejedbe... a pályafutásod során keményebb ellenfelekkel is fogsz harcolni, mint a vadkanok.$b$bMindazonáltal jól bizonyítottál, és a következő próbád egy sokkal veszélyesebb ellenfél ellen lesz, szóval extra védelemre lesz szükséged.' WHERE ID=788;
UPDATE quest_offer_reward SET RewardText='Van egy fontos lecke, amit meg kell tanulnod a skorpiók elleni harcból. A legkisebb vagy a legnagyobb ellenfél is a végzetedet okozhatja. Heves harcban bármi okozhatja a bukásodat.$b$bNincs több, amit tanítanom kellene neked, $N. Jól teljesítettél, és érdeklődéssel figyelem majd a fejlődésedet.' WHERE ID=789;
UPDATE quest_offer_reward SET RewardText='A csapásom nem volt elég, hogy megöljem, de ha az okozott sebesülésre nézek, kis büszkeséget érzek. Ez a kis büszkeség lesz minden, amivel fenntarthatom magam, ha meghalok, és ennek fényében életem rövid teljesítménylistája dühvel tölt el.' WHERE ID=790;
UPDATE quest_offer_reward SET RewardText='Igazán kiváló, $N. Bármelyik jó $c biztos hasznát veszi ennek a zsáknak a csatatéren.$b$bTisztelgek erélyed és a Horda nevében való halálra való hajlandóságod előtt!' WHERE ID=791;
UPDATE quest_offer_reward SET RewardText='Jól teljesítettél, $N.$b$bBár az Aljas Familiárisok csak a Burning Blade sötétebb hatalmainak kedvencei voltak, a velük szembeni sikered nagyobb tetteket jósol előre.' WHERE ID=792;
UPDATE quest_offer_reward SET RewardText='A fekete sárkánycsapat továbbra is szövetséges a lázadó Blackrock orkokkal, és mindkettőt móresre kell tanítani, vagy el kell távolítani. Blacklash és Hematus halálával nyugat felé fordíthatjuk figyelmünket, a Blackrock Spire irányába.' WHERE ID=793;
UPDATE quest_offer_reward SET RewardText='Visszaszerezted! Szép munka!$b$bA Burning Blade-boszorkánycéhben tett erőfeszítéseid kulcsfontosságúak ennek a kultusznak a felszámolásában a Próbák Völgyében. De félek, további terveik vannak a földünkkel.$b$bMég nem láttuk a végét.' WHERE ID=794;
UPDATE quest_offer_reward SET RewardText='Ahogy a rúnaköveket a hozzájuk illő mélyedésekbe helyezed, heves dübörgés rázza meg a földet, ahogy a Pecsét megtörik.' WHERE ID=795;
UPDATE quest_offer_reward SET RewardText='A fenevad leírásából ítélve biztos Sarkothról beszélsz! Nem csoda, hogy Hana''zuát legyűrte. Azonnal segítséget küldünk neki, ne aggódj tovább Hana''zua sorsa miatt.$b$bMindazonáltal meg kell mondjam, igen lenyűgözve vagyok, hogy Sarkoth halálát okoztad. Büszke lehetsz erre a tettre, $N. És hogy egy idegen becsületéért harcoltál, míg más feladatok is elfoglaltak, a saját becsületed is növekszik.' WHERE ID=804;
UPDATE quest_offer_reward SET RewardText='Hm... a jelentésed rossz időben érkezik. A Burning Blade-et itt Sen''jinben nem látni, de gonoszságuk gyökeret vert a parttól nem messze, az Echo-szigeteken.$b$bAz orkok a Darkspear trollok barátai. Becsületes barátok. Segíteni akarunk az orkoknak, de... nekünk is szükségünk van segítségre.' WHERE ID=805;
UPDATE quest_offer_reward SET RewardText='Aha! Elkaptad!$b$bBüszkévé teszed a klánodat, $N. És miattad Durotar megszabadult még egy gonosz ügynöktől.' WHERE ID=806;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Megmentetted Minshinát. Megmentetted a bátyám szellemét a rabszolgaságtól!' WHERE ID=808;
UPDATE quest_offer_reward SET RewardText='Neeru azt akarja, hogy a Démonmag elpusztuljon? Furcsa...$b$bNos, rendben. Ha azt akarja, hogy eltűnjön a mag, elmondom, hogyan távolítsd el.' WHERE ID=809;
UPDATE quest_offer_reward SET RewardText='$N, megmentetted az életemet. Köszönöm.$B$BKérlek, fogadd el ezt; remélem, legalább segít az utazásaid során, ha pénzt nem is hoz. Ahogy mondod, egy darabig nem fogom használni. Kor''ghan még több rituálén hajszol majd keresztül, amíg be nem bizonyítom magam. Több vadkanölés, több skorpiófarok-gyűjtés... <sóhajt>' WHERE ID=812;
UPDATE quest_offer_reward SET RewardText='Itt az ellenszer, $N. Vidd el Rhinaghoz, amilyen hamar csak lehet, és légy óvatos.' WHERE ID=813;
UPDATE quest_offer_reward SET RewardText='Lehet, hogy gyenge vagy, de legalább nem ügyetlen, $N.$b$bTessék, fogd ezt, és tűnj az utamból. Van egy kis főznivalóm.' WHERE ID=815;
UPDATE quest_offer_reward SET RewardText='Ó, a fiam... gyönyörű fiam.$b$bBizonytalanul a fiam sorsáról, gyötörtem magam, mióta elment. Most, hogy tudom, mi történt, talán végre elkezdhetek gyászolni.$b$bKöszönöm, $N. Kérlek, fogadd el ezt. Kronnak akartam adni ajándékul, amikor sikerrel visszatér. Most, hogy tudom, halott, nem bírom nézni.' WHERE ID=816;
UPDATE quest_offer_reward SET RewardText='Elégedett vagyok, $N. Segítségednek köszönhetően a népünk védve lesz, és nem fázik majd, ahogy változnak az évszakok.$b$bKöszönöm.' WHERE ID=817;
UPDATE quest_offer_reward SET RewardText='Szép munka, ifjú... valóban szép munka.' WHERE ID=818;
UPDATE quest_offer_reward SET RewardText='Nahát, azt a...$B$BEz Chen Stormstout egyik hordója volt. Régen Rexxarral utazott. Egy kodó élete óta nem láttam vagy hallottam felőle. Nagyra értékelem, hogy elhoztad nekem, $N.' WHERE ID=819;
UPDATE quest_offer_reward SET RewardText='Haha... sosem hittem volna, hogy még valaha készítek ebből a cuccból.$B$BFelébresztetted bennem a nosztalgia érzését, $N. Kicsit emlékeztet arra, amikor utoljára elájultam a túl sok troggsörtől. Köszönöm. Az emlékek melegítik a gyomrom.' WHERE ID=821;
UPDATE quest_offer_reward SET RewardText='Haha! Tudtam, hogy nem tudsz ellenállni ennek a főzetnek. Gyere vissza bármikor, ha többet szeretnél, $N. Csak hozz nekem még az alapanyagokból, amiket gyűjtettem veled.' WHERE ID=822;
UPDATE quest_offer_reward SET RewardText='Igen? Van valami jelentenivalód? Nos, akkor halljam!' WHERE ID=823;
UPDATE quest_offer_reward SET RewardText='Ez a gömb... rendkívül nyugtalanító. A hatalmasabb elementálok közül sokan ilyen eszközökön keresztül kapják erejüket és energiájukat. Egy ilyet szinte épségben találni egy dolog - ilyen beszennyeződve találni már más.$b$bGondoskodom róla, hogy az Earthen Ring alaposan tanulmányozza ezt a gömböt. Talán véget vethetünk az elemek eme megrontásának. Kérlek - fogadd el ezt méltó cserébe azért, hogy felhívtad az Earthen Ring figyelmét erre a gömbre.' WHERE ID=824;
UPDATE quest_offer_reward SET RewardText='Visszaszerzési küldetésed sikeres volt, $c. Gondoskodom róla, hogy ezek a szerszámok eljussanak Orgrimmarba a következő karavánnal.$b$bSzép munka.' WHERE ID=825;
UPDATE quest_offer_reward SET RewardText='Zalazane eltűnésével törzsünk ismét békében alhat.$b$bKöszönöm, $N. A Darkspear törzs sokkal tartozik neked. Ha valamilyen bajod van, keresd fel az asszisztensemet, Bom''bayt, mögöttem. Az ő voodoo-ja erős...' WHERE ID=826;
UPDATE quest_offer_reward SET RewardText='Jó. Ezekben a nyakörvekben rejtőzik a Burning Blade titka. És fel fogom fedni azt a titkot...' WHERE ID=827;
UPDATE quest_offer_reward SET RewardText='Üdvözöllek, $N. Hír érkezett hozzám érkezésedről, és Durotar-i tetteidről.$b$bNövekvő tudású és hírnevű $c vagy.$b$bMaradj a tiszta úton, és jövőd valóban nagyszerű lesz.' WHERE ID=828;
UPDATE quest_offer_reward SET RewardText='Á, és honnan szerezted ezt? A derék Margoz küldött hozzám Razor Hillből, igaz?$b$bNos, hadd nézzem meg közelebbről...' WHERE ID=829;
UPDATE quest_offer_reward SET RewardText='Ez egyáltalán nem jó előjel. Bölcsen tetted, hogy felhívtad a figyelmemet erre az információra.' WHERE ID=830;
UPDATE quest_offer_reward SET RewardText='Számtalanszor kértem a Hadurat, hogy ne bízzon az emberekben, de itt nem a személyes büszkeség forog kockán.$b$bBecsülettel szolgáltad a Hordát, ifjú $c.$b$bMost bocsáss meg, azonnal tanácsolnom kell Thrallt ezekben az ügyekben...' WHERE ID=831;
UPDATE quest_offer_reward SET RewardText='<Megvizsgálja az Égő Árnyék Szemét>$b$bÉrdekes. A hang, amit hallottál, az én nevemet említette? Ismert vagyok arról, hogy vadászom Hadurunk ellenségeire, de... furcsa, hogy engem emeltek ki. Még furcsább, hogy a Burning Blade kultistáinak, akiktől ezt a medált visszaszerezted, olyan közel áll a nevük az enyémhez.$b$bMeg kell vizsgálnom ezt a medált. Tanulmányoznom kell, és el kell gondolkodnom üzenetének jelentésén.$b$bKöszönöm, hogy felhívtad rá a figyelmemet, $N. Nagy szolgálatot tettél a népednek.' WHERE ID=832;
UPDATE quest_offer_reward SET RewardText='Szép munka. Egyértelmű üzenetet küldtél azoknak az aljas Bristlebackeknek. Kétszer is meggondolják majd, mielőtt ismét beleavatkoznának ebbe a szent helybe.' WHERE ID=833;
UPDATE quest_offer_reward SET RewardText='Hé, ez pont az, amire szükségünk volt! Visszaszerezted az ellátmányunkat. Ez remek. Vissza tudok térni a munkához, amint találok valakit, aki elcipeli nekem ezeket a zsákokat.' WHERE ID=834;
UPDATE quest_offer_reward SET RewardText='Azt hiszem, most már fellélegezhetek, tudván, hogy a hárpiák többé nem zaklatják a szállítmányozó karavánjainkat. És épp jókor is. Hallom, néhány szórakoztató kis játékszert küldenek a következő szállítmánnyal!$B$BEgész ügyes vagy abban, amit csinálsz, $N, kéne keresned a főnökömet Ratchetben. Fogadni mernék, találna neked munkát.$B$BÓ, és ne aggódj, nem felejtenélek el kifizetni a szolgálatodért.' WHERE ID=835;
UPDATE quest_offer_reward SET RewardText='Ó, TE vagy az OOX-09/HL nagy megmentője! El sem tudom mondani, mennyire hálás vagyok a segítségedért! Az önvezérlő robot sorozatomnak még sok fejlesztésre van szüksége, de a megmentésed rengeteg órányi extra újjáépítést és sok aranyat spórolt meg a gyártási költségekben!$b$bKérlek, válassz bármelyiket ezekből a tárgyakból, amim van. Köszönöm még egyszer a nagylelkű segítségedet, $N, a robotjaim és én is tartozunk neked!' WHERE ID=836;
UPDATE quest_offer_reward SET RewardText='Továbbadom a hírt, hogy a quilboarokat kiűzték a búvóhelyeikről, és az építményeiket felégethetjük. A Razormane eltávolítása Durotarból közelebb visz minket ahhoz, hogy teljesen biztosítsuk új szülőföldünk határait.' WHERE ID=837;
UPDATE quest_offer_reward SET RewardText='Igen, $c, a Fővégrehajtó megemlítette, hogy talán te vagy az, akiben megbízhatunk a kulcs ügyében. Legutóbbi tanulmányaim jelentős részét a Scholomance-nak szenteltem, és úgy hiszem, tudom, hogyan szerezhetsz egy olyat, amivel kedved szerint bejuthatsz a bejárati ajtón.$b$bEz a feladat nem lesz könnyű, de az ilyen feladatok ritkán azok. Te biztosan olyan típusnak tűnsz, aki ezt tényként ismeri.' WHERE ID=838;
UPDATE quest_offer_reward SET RewardText='Ó, szóval Takrin küldött? Kiváló felderítő, nem tudom, mit kezdenék nélküle.$b$bAláírom a toborzólevelet, de valójában valakire van szükségünk a Crossroadsnál.' WHERE ID=840;
UPDATE quest_offer_reward SET RewardText='Nos jó, itt egy másik energiaforrás. Erősen ajánlom, hogy ezúttal megfelelően használd, hacsak nem szeretnél újabb tíz víztömlőt elkölteni egy másik energiaforrásra.' WHERE ID=841;
UPDATE quest_offer_reward SET RewardText='Rendben, $N. A Hordával akarod kiérdemelni a helyed? Nos, van itt bőven tennivaló, szóval figyelj jól, és tedd, amit mondanak.$b$b$gLátom azt a pillantást a szemedben, ne hidd, hogy eltűröm a pimaszságot. Maga Thrall jelentette ki, hogy a Horda nőit egyenrangúnak kell tekinteni veletek, férfiakkal. Ha a legkisebb tiszteletlenséget is mutatod irántam, megismered az igazi fájdalmat.:Örülök, hogy megismertelek. Thrall örülni fog, ha megtudja, hogy hozzám hasonló nők is kezdeményezik az előrenyomulást a Barrensben.;' WHERE ID=842;
UPDATE quest_offer_reward SET RewardText='Khazgorm elnyerte, amit érdemelt. Nem érzek bűnbánatot a bolond miatt. Hitetlen volt ezeken a földeken.$B$BLegyen a halála figyelmeztetés mindazoknak, akik meg akarják zavarni életmódunkat.$B$BMost hadd szánjak egy pillanatot a törp naplójának tanulmányozására...' WHERE ID=843;
UPDATE quest_offer_reward SET RewardText='Nagyon jó, $N. A plainstriderek eltűnésével könnyebb lesz épen tartani az ellátási láncainkat. És remélem, tanultál néhány trükköt odakint a Barrensben, mert a következő zsákmányodban egy kicsit több tűz van, mint a plainstriderekben...' WHERE ID=844;
UPDATE quest_offer_reward SET RewardText='Nem rossz, $N. Azok a zhevrák sok erőt tartanak a lábukban. Egy éles rúgásuk még egy taurent is a fenekére ültet!$B$BÚgy tűnik, benned is van erő. Készen állsz egy igazi kihívásra?' WHERE ID=845;
UPDATE quest_offer_reward SET RewardText='Látom, elég szorgalmas vagy, $c.$B$BKétségkívül hamarosan méltó meglepetés vár azokra a törpökre.' WHERE ID=846;
UPDATE quest_offer_reward SET RewardText='Amikor a varázslat elmúlik, beszélek Gor''mullal. Köszönöm a segítségedet, hogy visszahoztad Gor''mult az élők földjére. Nem kétlem, hogy ő is nagyon hálás neked.' WHERE ID=847;
-- quest_offer_reward.RewardText. Batch 17: quest IDs 848-899.

UPDATE quest_offer_reward SET RewardText='Á, igen. Ezek jó példányok. Erősek.$B$BEn vagyok Elhagyatott, és mi tiszteletben tartjuk a szerződéseinket. Itt a jutalmad, $N.' WHERE ID=848;
UPDATE quest_offer_reward SET RewardText='Jól teljesítettél, $N! Bárcsak tisztelet övezne Thunder Bluffban, mint a szent tauren földek védelmezőjét és az elveszett törzs bajnokát.' WHERE ID=849;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N. A kentaurok alantas, barbár teremtmények, de néhányuknak van annyi esze és látásmódja, hogy vezessen. És ők a legveszélyesebbek.$B$BBarak ilyen kentaur volt. Jó, hogy halott.' WHERE ID=850;
UPDATE quest_offer_reward SET RewardText='Nagyon jó. Biztos alaposan felkavartad azokat a kentaurokat -- őreink tevékenységet észleltek lent a Stagnant Oázisnál, ami valószínűleg te voltál.$B$BBüszkének kell lenned a tettedre, $N. Sok bátorság van benned.' WHERE ID=851;
UPDATE quest_offer_reward SET RewardText='Dicséretet érdemelsz, $N. Ezek a kentaurok fegyelmezetlenek, és nem tudják úgy összpontosítani dühüket, mint az orkok, de attól még kegyetlenek. A legyőzésükkel bebizonyítottad vitézségedet.' WHERE ID=852;
UPDATE quest_offer_reward SET RewardText='Á, a Barrensből származó spórák, amiket Helbrim gyűjtött. A segítségedet kérte a kiszállításukhoz? Jó.$B$BÉs az emulzió még mindig erős, tehát nem vesztegetted az időt a szállítással. Szép munka, $c.' WHERE ID=853;
UPDATE quest_offer_reward SET RewardText='Jó látni, hogy több $R szövetségesünk jött segíteni minket egészen Thunder Bluffból. Ismét üdvözöllek.' WHERE ID=854;
UPDATE quest_offer_reward SET RewardText='Szép munka. Biztos vagyok benne, hogy félelmet keltettél a túlélő kentaurokban, $N. Ha van eszük, most lecsillapodnak, és leállnak az előrenyomulásukkal.$B$BDe nem hiszem, hogy így lesz, és ez sajnálatos.$B$BSajnálatos... rájuk nézve.' WHERE ID=855;
UPDATE quest_offer_reward SET RewardText='Végre, a hatalom ismét az enyém! Az enyém, mondom!' WHERE ID=857;
UPDATE quest_offer_reward SET RewardText='Igen, ez a megfelelő kulcsnak tűnik. Hadd bizonyosodjak meg róla, hogy tudom, hogyan működik ez a dolog...$B$BHmm... forgásszabályzó... ez szabályozza a sebességet és a stabilitást... finom karmozgás-vezérlés. Nézd csak ezt! El sem hiszem, hogy a Venture Company ennyivel jobbat tudott tervezni, mint a miénk. Vissza kell vinnem ezt Ratchetbe!' WHERE ID=858;
UPDATE quest_offer_reward SET RewardText='Vadászni akarsz a Barrensben?$b$bA szemed lelkes, és fiatal. Még nem húzta össze a szemhéjadat, hogy zsákmányt kövess ennek a földnek a száraz síkságain.$b$bDe ne aggódj. Megedzzük a testedet és az elmédet. És megtanítjuk, hogy a vadászat több, mint zsákmányod megtalálása és megölése.$b$bKészülj fel. Az utazásod elkezdődik. Most.' WHERE ID=860;
UPDATE quest_offer_reward SET RewardText='Skorn Whitecloud bölcs tauren. Évek óta vadászik, és bár teste öreg, szelleme hevesen ég. Megtiszteltetés, hogy velünk van.$B$B\n Ha Skorn küldött hozzám, akkor neked is meg kell legyen a vadász lelke. És hogy összegyűjtötted ezeket a karmokat, mutatja fejlődő tudásodat.$B$BTalán készen állsz, hogy az útra lépj.' WHERE ID=861;
UPDATE quest_offer_reward SET RewardText='Általában nem szeretem megenni ezeket a rágcsálókat, amikor ilyen... ilyen... érettek. Szeretem hagyni őket néhány hétig rothadni, hogy igazán kihozzam belőlük az ízt. De te olyan éhesnek tűnsz.$B$BHadd készítsek neked egy kis Dig Rat pörköltet. Á, tessék is.$B$BItt van!' WHERE ID=862;
UPDATE quest_offer_reward SET RewardText='Remélhetőleg kinyerhetünk valami értékeset a roncsolt aprítógép-prototípusból... fogy az időm! Azonnal kiküldök egy mentőcsapatot Wizzlecrank helyszínére.$B$BÓ, hadd adjak neked is valamit a fáradozásodért.' WHERE ID=863;
UPDATE quest_offer_reward SET RewardText='Azonnal elemzem ezt az adatot. Talán Keever őrülete végül az én zsenialitásomnak bizonyul.$B$BAmi téged illet... hasznos vagy nekem, és jól megjutalmazom azokat, akik hasznosak maradnak. Fogd ezt a tárgyat, ezt az érmét, és ami a legfontosabb, a köszönetemet is velük együtt.$B$BNézz vissza hozzám időnként - fogadok, a projekten való közös munkánknak még nincs vége.' WHERE ID=864;
UPDATE quest_offer_reward SET RewardText='Remek, megszerezted őket! Most csak porrá kell zúznom őket, és összekevernem egy kis borral, és...' WHERE ID=865;
UPDATE quest_offer_reward SET RewardText='Igen igen, ezek nagyon szépek! Ezekből a gyökerekből példányokat növesztek, és tanulmányozom őket. Remélem, új tulajdonságokat találok bennük. Rejtett, értékes tulajdonságokat...!$B$BÉs ne aggódj -- ha megtalálom, te leszel az első, aki tudja. Mert szükségem lesz valakire, aki többet gyűjt!' WHERE ID=866;
UPDATE quest_offer_reward SET RewardText='Ó, ezek szépek. Igazán szépek... Szép munka, $N. Alig várom, hogy lássam a jövőben a további munkádat.' WHERE ID=867;
UPDATE quest_offer_reward SET RewardText='Elégedett vagyok veled, $N. A tojások és a szerszám. Szép munka.$B$BÉs a jutalmadért...' WHERE ID=868;
UPDATE quest_offer_reward SET RewardText='Megszabadultál a raptoroktól!$B$BKöszönöm, $N. Értékes $c vagy.' WHERE ID=869;
UPDATE quest_offer_reward SET RewardText='Egy repedést találtál a földben, amiből gázok bugyognak elő? Furcsa. Ez talán válasz lehet a kérdéseinkre, de még nem lehetünk biztosak benne.$B$BDe ez egy nyom. És hálás vagyok, hogy megtaláltad.' WHERE ID=870;
UPDATE quest_offer_reward SET RewardText='Jól teljesítettél, $N. Azok a pimasz quilboarok végre megtanulják, hogy a Horda hatalmát nem lehet figyelmen kívül hagyni.' WHERE ID=871;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N. Kreenig halálával határozottan csökkennek majd a karavánjaink elleni támadások.$B$BA néped büszke lehet, hogy közéjük tartozol.' WHERE ID=872;
UPDATE quest_offer_reward SET RewardText='Most már eggyé váltál Isha Awakkal, $N. Szelleme veled van. A szemedben ólálkodik...$B$BSzemek, amelyek egy napon megtanulnak majd látni.' WHERE ID=873;
UPDATE quest_offer_reward SET RewardText='A bátyám küldött, igaz? Akkor biztos bebizonyítottad magad neki. Ha kiérdemelted Jorn tiszteletét, akkor az enyémet is kiérdemelted.$B$BKészen állsz, hogy továbblépj a vadász útján?' WHERE ID=874;
UPDATE quest_offer_reward SET RewardText='Kiváló munka, barátom. Azt hiszem, messzire jutsz majd a Hordán belül.' WHERE ID=875;
UPDATE quest_offer_reward SET RewardText='HA! Szép munka, $N! Nagyon szép munka... Nem voltam biztos benne, hogy megfelelsz a feladatnak, de bebizonyítottad, hogy igazi kegyetlen harcos vagy. Még egyszer köszönöm, hogy segítettél megfékezni a hárpiajárványt. Itt a jutalmad, használd bölcsen.' WHERE ID=876;
UPDATE quest_offer_reward SET RewardText='A felfedezéseid elképesztőek! A magok, amiket adtam neked, szárazak és halottak voltak. Bármi is nyugszik ezek alatt az oázisok alatt, a semmiből tud életet teremteni!$B$BTöbbet kell tanulmányoznunk ezt...' WHERE ID=877;
UPDATE quest_offer_reward SET RewardText='Igen, igen... örömmel telve, mert végre <fintorog> a Bristleback ismeri törzsem fájdalmát, $R. Így kéne éreznem, de <fintorog> nem ez a helyzet.$B$BTe segíted a népedet, és ők tisztelnek téged. Mangletooth segíti a népét, és ők mit tesznek? Hátat fordítanak neki. Elfelejtik, és hagyják, hogy rohadjon a ketrecben!$B$BÉn segítem őket még rácsok mögé zárva is, és senkit sem küldenek, hogy megmentsenek engem!' WHERE ID=878;
UPDATE quest_offer_reward SET RewardText='Akkor hát megvan. Jobb, ha így ér véget, mondja Mangletooth. <fintorog> Meg kellett volna <fintorog> bizonyosodniuk, hogy halott vagyok, amikor hátat fordítottak nekem, ahelyett hogy <fintorog> itt hagynak ebben az elátkozott ketrecben.$B$BMár csak egyetlen feladat maradt, amit be kell fejezned, $R.' WHERE ID=879;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Egy terület vadjainak tanulmányozása sokat elárulhat magáról a területről. Lássuk, milyen történetet mesélnek ezek a páncélok.$B$BKérlek, fogadd hálámat segítségedért... és talán hasznodra válnak ezek az érmék. Úgy találom, nincs rájuk szükségem.' WHERE ID=880;
UPDATE quest_offer_reward SET RewardText='Legyőzted Echeyakee-t, és bár vadászatai véget értek... szelleme veled van. Megmutatja neked a finomságban rejlő erőt, és az irgalomban rejlő becsületet.$B$BAz utad még hosszú, $c. Reméljük, jól lépdelsz majd rajta.' WHERE ID=881;
UPDATE quest_offer_reward SET RewardText='Ez az agyar csak egy jelkép, de amit képvisel, az mélyreható.$B$BIshamuhale ereje benned van, $N. Bárcsak mértékkel használnád. Ez a te terhed.$B$BEz a te becsületed.' WHERE ID=882;
UPDATE quest_offer_reward SET RewardText='Lakota''manit a nyelvünkön Földrázónak hívjuk, és léptei olyanok, mint az összegyűlt mennydörgés. Most veled van, és bátorsága összefonódik a tiéddel. Együtt nincs olyan konfliktus, amivel ne néznél szembe.$B$BJárj büszkén, $N. Járj büszkén, Földrázó.' WHERE ID=883;
UPDATE quest_offer_reward SET RewardText='A mennydörgőgyíkot, Owatankát a taurenek Kékvillámnak hívják, mert benne olyan gyorsaság lakozik, amely megcáfolja a méretét. Azt mondják, régen villám csapott Kékvillámba, és az ég dühéből táplálkozva a nagy fenevad ereje határtalan.$B$BÁramoljon rajtad keresztül az ereje, $N. Mert most már lépést tartasz Owatankával.' WHERE ID=884;
UPDATE quest_offer_reward SET RewardText='A mennydörgőhéja ritka fenevad a Barrensben, és halála nagy szerencsét vagy nagy végzetet jelezhet előre.$B$BDe Washte Pawne, akit Taurahe nyelven Szellemharapónak hívnak, egyiket sem hozhatja... vagy mindkettőt.$B$BA fájdalom, amit Szellemharapó vadászatakor éreztél, azt a szúrást jelenti, amit mindenki érez, aki nagy áron ér el nagy nyereséget. A szúrás, amit éreztél, a megbánás fájdalma.$B$BDe látom, legyőzted ezt. Megtanultad, hogy a megbánás bölcsességgé válik, és hogy a fájdalmon keresztül erőt nyerünk.$B$BSokat tanultál, $N.' WHERE ID=885;
UPDATE quest_offer_reward SET RewardText='Thunder Bluff-i testvéreim bölcsen tették, hogy elküldtek téged, ifjú $c. Mert a Barrens rejtélyét egyedül nem tudom megfejteni.$B$BSegítségeddel remélhetőleg választ találunk kérdéseinkre.' WHERE ID=886;
UPDATE quest_offer_reward SET RewardText='Jól csináltad, kölyök. Még egy kicsit ilyen munka, és eggyel kevesebb dolgom lesz, amivel aggódnom kell. Remélhetőleg meggyőzöm őket, hogy máshova helyezzék át a működésüket.$B$BAddig is, van itt egy apró ügy: vissza kell szereznem az árut, amit elloptak tőlem!' WHERE ID=887;
UPDATE quest_offer_reward SET RewardText='Megkönnyebbülés, hogy visszakaptam mindezt a cuccot, szóval köszönöm a segítségedet, $N. Tudod, tudnék használni egy hozzád hasonló $R-t, hogy segítsen az itteni működésemben. Ha valaha munkát keresnél, ne feledd, milyen jól fizet Gazlowe a szolgálatért!' WHERE ID=888;
UPDATE quest_offer_reward SET RewardText='Jó. Menj Agamaggan szellemével, mint vezetőddel, $R. Térj vissza hozzám, ha többet szeretnél Agamaggan mágiájából.' WHERE ID=889;
UPDATE quest_offer_reward SET RewardText='Á, Gazlowe küldött, igaz? Egy pillanat, hadd nézzem meg itt, és ellenőrizzem a saját nyilvántartásomat, hogy nem küldtem-e Gazlowe szállítmányát rossz helyre.$B$BFogadni mernék, a Drizzlek-féle csizmákat várja...' WHERE ID=890;
UPDATE quest_offer_reward SET RewardText='Sajnos az igaz Szövetség ágyúi elnémultak. Jutalmat kapsz a segítségedért, $N.$B$BMost pedig lássunk hozzá a komor feladathoz, hogy behozzuk a halottak testét...' WHERE ID=891;
UPDATE quest_offer_reward SET RewardText='Nincs szerencse, mi? Gondolom, akkor a Freebooterök voltak... Dizzywig rendes fickó, biztos nem csapna be így engem. Elvégre a fizetési listámon van.$B$BÚgy tűnik, van néhány árum, amit vissza kell szereznem, $N. Mit szólsz hozzá?' WHERE ID=892;
UPDATE quest_offer_reward SET RewardText='Kiváló, valóban kiváló példányok.$B$BA quilboarok jóval előrébb tartanak, mint vártam.$B$BTessék, $c, fogd ezt, és tűnj az utamból. Jobb, ha közelebbről megvizsgálom ezeket a fegyvereket. Talán alábecsültük az ellenségünket, és ilyen hibát nem engedhetünk meg magunknak.' WHERE ID=893;
UPDATE quest_offer_reward SET RewardText='Különféle gombok, karok és villogó fények vannak kissé rendszertelenül elrendezve a vezérlőpult felületén. Egy kis műszer jelzi, hogy a berendezés jelenleg optimális szinten működik, és hogy az egyestől a hármas számú vezérlőszelepek jelenleg nyitva vannak. A vezérlőpanel jobb alsó oldalán egy kis kulcslyuk található.' WHERE ID=894;
UPDATE quest_offer_reward SET RewardText='Ááá! Ilyen ügy. Tudod, egyszer láttam a Heedlesst a nyílt tengeren. Félelmetes hajó, vagy csónak volt... azok a tengerészek olyan finnyásak!$B$BMindenesetre nézni, ahogy siklik a vízen, igazán látványos volt. Örülök, hogy hírhedt kapitánya többé nem zaklatja a hajóimat.' WHERE ID=895;
UPDATE quest_offer_reward SET RewardText='Nézd meg ennek a méretét, $N! Meggazdagszunk! Lássuk csak, az Undermine-ba érkező drágakövek árai alapján ki tudom számolni a te részedet--ötven százalék, ne aggódj!$B$BMost lássuk... azt hiszem, ez pont megfelelő lesz. Öröm volt üzletelni veled, $N.' WHERE ID=896;
UPDATE quest_offer_reward SET RewardText='Nem tudok semmit mondani ennek a fenevadnak a természetéről, mert szelleme elmenekült. De ahogy sejtetted, nem a Barrensbe való. Attól félek, komor jövőt jelezhet előre a népünk számára...$B$BDe egyelőre készülj fel, és reméljük, az idő megfejti ennek a lénynek a rejtélyét.' WHERE ID=897;
UPDATE quest_offer_reward SET RewardText='És csak gondolni, azt hittük, Firebough már rég halott!$B$BHőstetteid megérdemelt helyet szereztek neked a Thalo''dan Kalózok között, $N.' WHERE ID=898;
UPDATE quest_offer_reward SET RewardText='$c, komolyan veszed a feladatomat, és ezért köszönöm.$B$BBár a bosszúvágyam megmaradt, legalább elmosolyodhatok, látva, hogy a quilboarok is megérezték a fájdalmat.' WHERE ID=899;
-- quest_offer_reward.RewardText. Batch 18: quest IDs 900-952.

UPDATE quest_offer_reward SET RewardText='A három vezérlőszelepet jelző fények elhalványulnak, ahogy lezárják őket. A zöld fények lassan sárgává fakulnak, és a berendezést vezérlő kapcsoló most már mozgatható, mivel a szelepek zárva vannak, ki lehet kapcsolni.' WHERE ID=900;
UPDATE quest_offer_reward SET RewardText='A kulcsot a zárban elfordítva a vezérlőpult kinyílik. A pult tetején egy piros fény kialszik, és minden áram kiürül a terminálból.' WHERE ID=901;
UPDATE quest_offer_reward SET RewardText='Ez... öhm... érdekes... igen. Elküldöm a Tinkers'' Union undermine-i központjába. Biztos vagyok benne, hogy alapos boncolás és kutatás után értelmet tudnak adni neki.$B$BDe talán előbb magam is vetek rá egy pillantást...' WHERE ID=902;
UPDATE quest_offer_reward SET RewardText='Á, látom, szorgoskodtál, a füvekben lapulva vadászva a prowlerekre. Gondolod hát, hogy eljött az idő, hogy szembenézz a bajnokukkal?' WHERE ID=903;
UPDATE quest_offer_reward SET RewardText='Szóval jártál a fészkeknél, és elhelyezted bennük zsákmányod tollait. Ehhez kellett némi bátorság, kétségkívül.$B$B\n Érzed magad kicsit keményebbnek, $N? Mert keményebbnek is tűnsz, mint amikor először idejöttél. Gondolom, a Barrens elvégzi a dolgát.' WHERE ID=905;
UPDATE quest_offer_reward SET RewardText='Megtaláltad a Razormane vezérét, és saját kezűleg megölted, $N? Elképesztő.$B$BSzavak nélkül maradtam, de ez nem jelenti azt, hogy hála nélkül maradnék. A Crossroads népe jól teszi, ha tiszteli az erődet.$B$BBe kell vallanom, azt hittem, ezeknek az ellátási vonalaink elleni rajtaütéseknek a vezetője egy másik quilboar. Még egyszer köszönöm, $N.' WHERE ID=906;
UPDATE quest_offer_reward SET RewardText='Jó látni, hogy győzelmed bizonyítékával térsz vissza. És jó tudni, hogy ép csontokkal tetted ezt.' WHERE ID=907;
UPDATE quest_offer_reward SET RewardText='Pontosan erre volt szükségem! Egy mélységmag hihetetlen információforrás, amiből sok jót meríthetünk. Bármit is forral a Twilight''s Hammer odabent - és hidd el, ha azt mondom, nem jót -, most bajtársaimmal együtt feltárjuk.$b$bJól teljesítettél ma; az Earthen Ring melegen tekint rád a segítségedért. A Hordának mint egésznek is segítettél, és ezért büszke lehetsz.' WHERE ID=908;
UPDATE quest_offer_reward SET RewardText='Ez... ez igazi lelet, $N.$b$bAzt mondod, Aquanis bárótól szerezted, Blackfathomban? Aquanis bárót régóta beszennyeződött elementál hatalomnak tartják; ez a gömb bizonyítja majd, mi pontosan rontotta meg. Bár nem lenne meglepő, ha a Twilight''s Hammer állna mögötte, kutatásaink azt is megmutatják majd, hogyan tették.$b$bJól tetted, hogy elhoztad nekem. Kérlek - fogadd ezt, az Earthen Ring legmelegebb üdvözletével együtt.' WHERE ID=909;
UPDATE quest_offer_reward SET RewardText='Hű, az óceán HATALMAS! Rengeteg sirály és minden más is volt - pont olyan zajos és nyüzsgő, mint ahogy elképzeltem. Kalózok is vannak a közelben - de menő!$B$BKöszönöm, hogy elvittél Ratchetbe, $N. Ez annyira szuper volt!' WHERE ID=910;
UPDATE quest_offer_reward SET RewardText='Hű, Ashenvale-ben történnek az igazi kalandok! Harcoltál már valaha Ashenvale-ben, $N? Amikor felnövök, és hős leszek, el akarok jönni Ashenvale-be, és harcolni a dicsőséges Hordáért!$B$BKöszönöm, hogy elvittél a határvidékre, $N. Te vagy a legjobb!' WHERE ID=911;
UPDATE quest_offer_reward SET RewardText='Neked, akárcsak a mennydörgőhéjának, büszkének kell lenned. Legyőzted minden ellenfelet, akit eléd állítottunk, mégpedig erővel, bátorsággal és becsülettel.$B$BDe az utad, $N, folytatódik. Valójában rájössz majd, hogy az igazi vadászok örökké küzdenek, örökké ugyanazzal a büszkeséggel járják útjukat, amit nekem mutattál.$B$BMost pedig ideje továbblépni.' WHERE ID=913;
UPDATE quest_offer_reward SET RewardText='Sikerült, $N. Megölted az Agyar Druidáinak vezéreit. Álmaim most mentesek gonosz arcuktól, és segítettél megmenteni a Barrenst egy elátkozott jövőtől.$b$bKöszönöm, $N. Köszönöm magamnak, Thunder Bluff druidáinak, és a földnek is.' WHERE ID=914;
UPDATE quest_offer_reward SET RewardText='Mmmmmmmmm! Imádom az eperfagylaltjukat! Ha egy dolgot tud Tigule és Foror, az a fagylaltkészítés!$B$BNagyon köszönöm, $N - ez a valaha volt legjobb csemege!' WHERE ID=915;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Amikor visszatérek Darnassusba, összehasonlítom az ezekben a zacskókban lévő mérget más pókok mérgével. Az a meggyőződésem, hogy tulajdonságai kapcsolatban állnak majd új világfánk közelmúltbeli növekedésével.' WHERE ID=916;
UPDATE quest_offer_reward SET RewardText='Á, nagyon jó. Elszállíttatom ezt a tojást és a mérget Darnassusba, majd visszatérek oda, amikor itt befejeztem a tanulmányaimat. Sokat várok ezektől a mintáktól, $N. Nagy segítségemre voltál.' WHERE ID=917;
UPDATE quest_offer_reward SET RewardText='Megszerezted őket. Ez jó!$b$bElültetem ezeket a magvakat egy speciális talajba, amit előkészítettem. Úgy hiszem, a magvakból sokkal szelídebb timberlingek nőnek majd ki. Talán később megnézheted az eredményt!' WHERE ID=918;
UPDATE quest_offer_reward SET RewardText='Ez tényleg sok! Attól tartok, veszélyes ütemben terjednek. Remélem, meg tudom fejteni, mi rontja meg őket.$b$bKöszönöm a segítségedet, $N. A föld tisztább hely erőfeszítéseidnek köszönhetően.' WHERE ID=919;
UPDATE quest_offer_reward SET RewardText='Á, $N. Reméltem, gyorsan válaszolsz a hívásomra. Van egy fontos feladatom, amit szeretném, ha elvégeznél.' WHERE ID=920;
UPDATE quest_offer_reward SET RewardText='Szóval hallottad a Hyjal-hegyi csata következményeinek első részét. Sokkal többet kell még elmesélni, és a feladat, amit itt elkezdtél, folytatódik utad hátralévő részén, Teldrassilon keresztül egészen Darnassusig.' WHERE ID=921;
UPDATE quest_offer_reward SET RewardText='Á, egy timberling-mag? Szerettem volna kipróbálni, hogy növesztek egyet, hogy segítsem Denalan tanulmányait.$b$bDe attól tartok, felfedeztem, hogy sok timberlingben megrontás nőtt, és az ilyen lényekből származó magvak hordozzák szüleik szennyeződését. Ez meghaladja a képességeimet, hogy helyrehozzam.$b$bDenalan nagyon ügyes a növekvő dolgokban. Talán ő találhat gyógymódot a jövőbeli timberlingeknek. Talán ő az egyetlen reményük.' WHERE ID=922;
UPDATE quest_offer_reward SET RewardText='Szép munka! Ezek a daganatok a timberlingek betegségének tünetei. Olyan méreggel vannak tele, amit ki kell tisztítanunk új földünkről.$b$bMegsemmisítem ezeket a daganatokat. Köszönöm, $N.' WHERE ID=923;
UPDATE quest_offer_reward SET RewardText='Feladatod teljesítve. Elpusztítottad a Démonmagot, ahogy Neeru kérte. De ez még nem a vég...$b$bA Démonmag elpusztítása hatalmi hullámokat küldött szét az éteren keresztül, megdöbbentő erejű hullámokat. Éreztem őket, és biztos vagyok benne, más lények is. Mások, akik azon tűnődnek majd, miért tört el a játékszerük...$b$bDe a jövőbeli bajoktól függetlenül, van valamim a számodra. Neeru küldte fizetségül. És megkért, hogy köszönjem meg.' WHERE ID=924;
UPDATE quest_offer_reward SET RewardText='WOW! Megszerezted nekem Cairne patanyomát! Nagyon köszönöm! És hűha... személyes üzenetet írt ide - nekem! Tudtam, hogy szuper lesz, csak tudtam! Talán egy nap magam is megköszönöm neki... amikor a Horda hőse leszek!$B$BTe vagy a legjobb, $N. Köszönöm, hogy ilyen kedves voltál hozzám.' WHERE ID=925;
UPDATE quest_offer_reward SET RewardText='Ezek a kövek mágikus energiával vannak átitatva, de szándékosan hibásak. Nagyon instabilak, és amint elveszik őket az asztalról, gyorsan felemésztik önmagukat.' WHERE ID=926;
UPDATE quest_offer_reward SET RewardText='...Ez meg mi? Egy timberling szíve?? Aljas mohával van borítva!$b$bKöszönöm, hogy elhoztad nekem, $N. Megvizsgálom a szívet, és ha szerencsém van, kiderítem, milyen természetű a rajta lévő moha.' WHERE ID=927;
UPDATE quest_offer_reward SET RewardText='Á, értem. Tenaron küldött. Nos akkor, úgy tűnik, sok mindent kell megbeszélnünk, sok tennivalónk van, és kevés időnk hozzá.$B$BAzt hiszem, jobb, ha nekilátunk.' WHERE ID=928;
UPDATE quest_offer_reward SET RewardText='A Hyjal-hegyi csata után iránytalanok voltunk. Nordrassil füstölgött a felszabadított tűztől, halhatatlanságunk pedig--lényünk maga a lényege!--elveszett.$B$BEbben a próbatevő időben szabadult ki börtönéből az Áruló, és tűnt el Shan''do Stormrage. Sötét idő volt mindenki számára.' WHERE ID=929;
UPDATE quest_offer_reward SET RewardText='Teldrassilon találtad ezt? Érdekes... ez a gyümölcs egzotikus. Talán a magvait messziről hozták ide. Talán egészen Azerothból! És van valami ebben a gyümölcsben... úgy tűnik, nagyon furcsán reagált Teldrassil talajával.$b$bKöszönöm, $N. Most, ha megbocsátasz, tovább kell tanulmányoznom ezt...' WHERE ID=930;
UPDATE quest_offer_reward SET RewardText='Honnan szerezted ezt? Nem láttam ilyen növényt, mióta a Bánat mocsarába látogattam... évtizedekkel ezelőtt! Elképesztő, hogy egy példány eljutott Teldrassilra. És ekkorára nőtt!$b$bKöszönöm, $N. Bocsásd meg szófukarságomat, de van egy teszt, amit szeretnék elvégezni ezen a leveleken...' WHERE ID=931;
UPDATE quest_offer_reward SET RewardText='Melenas úr nyugalomra térésével végre továbbléphetek más ügyekre. Köszönöm, $N.' WHERE ID=932;
UPDATE quest_offer_reward SET RewardText='Shan''do Stormrage sosem tért vissza, a druidák pedig felbomlottak, és mindmáig nem tudjuk, mi lett vele. Malfurion eltűnésével Fandral Staghelm fődruida vette át a druidák vezetését, meggyőzve a Darkshore-i Ősök Körét, hogy eljött az idő, hogy népünk újjáépüljön, és visszanyerje halhatatlanságát.$B$BA Kör jóváhagyásával Staghelm és a leghatalmasabb druidák felnövesztették Teldrassilt, az új Világfát.' WHERE ID=933;
UPDATE quest_offer_reward SET RewardText='Az Orákulum Fa jelenlétében lenni... szinte megtapasztalni, ahogy a bölcsesség alakot ölt. Hadd folytassam a történetet...$B$BTeldrassil felnövesztése után a Fő $c a sárkányokhoz fordult áldásukért, ahogy a sárkányok egykor Nordrassilra is helyezték azt. De Nozdormu, az Idő Ura megtagadta áldását, dorgálva a $c-t arroganciájáért. Nozdormuval egyetértve Alexstrasza is elutasította Staghelmet, és áldása nélkül Teldrassil növekedése hibássá és kiszámíthatatlanná vált...' WHERE ID=934;
UPDATE quest_offer_reward SET RewardText='Á igen, a víz, amit kértem. Tenaron és Corithras aztán tényleg ráértek a kézbesítéssel... talán nem a legmegbízhatóbb hírnököket választották... hmm.$B$BMindazonáltal végre visszatérhetek a munkámhoz. Teldrassil problémáinak súlya az én vállamra nehezedik. Egy iga, amitől szeretnék hamarosan megszabadulni.$B$BFogd ezt, talán hasznát veszed.' WHERE ID=935;
UPDATE quest_offer_reward SET RewardText='Üdvözöllek, $c; örülök, hogy érdekel, hogy segíts kutatásunkban. Sok a tennivaló, és rossz szolgálatot tennék neked, ha azt mondanám, hogy ez a munka nem veszélyes. Remélhetőleg ez nem riaszt el... de úgy nézel ki, mint aki már volt hasonló veszélyben.' WHERE ID=936;
UPDATE quest_offer_reward SET RewardText='Lenyűgöz, amit itt ilyen rövid idő alatt véghezvittél, $N. Bárcsak kérhetnélek, hogy maradj itt segíteni a feladataimban... de szívemben tudom, hogy nagyobb feladatok várnak rád.$b$bÉszrevettem, hogy az Orákulum Fa most vetett le egy darabot a kérgéből. Kétségkívül van egy feladata, amit szeretne teljesíteni. Beszélj vele.' WHERE ID=937;
UPDATE quest_offer_reward SET RewardText='Ó, köszönöm, $N! Attól féltem, sosem látom többé Mistet, csak a halálát ismerve a szívemben, sosem egyesülve újra hűséges társammal. Többel tartozom neked, mint tudnád, és örök hálám a tiéd.' WHERE ID=938;
UPDATE quest_offer_reward SET RewardText='Érzem az ősiek szenvedését, $N...$B$BAlig bírom elviselni, hogy ezeket a tárgyakat tartom...' WHERE ID=939;
UPDATE quest_offer_reward SET RewardText='Azon tűnődtem, miért nem kommunikált velem az Orákulum Fa ilyen sokáig... Úgy tűnik, néhány probléma enyhül, míg mások nagyobb aggodalmakká nőnek.$b$bAttól félek, a Teldrassilon végzett munkám sosem fejeződik be, halhatatlanságunk pedig sosem áll helyre.$b$bMindazonáltal jól teljesítetted az Orákulum Fa feladatát, és jutalmat érdemelsz szorgalmadért.' WHERE ID=940;
UPDATE quest_offer_reward SET RewardText='A szívet az ültetőbe helyezed, és az gyorsan beássa magát!$b$bNéhány másodperc múlva megtisztultan kúszik ki. Enyhén lüktet... arra hívogatva, hogy vedd el.' WHERE ID=941;
UPDATE quest_offer_reward SET RewardText='Egek! Azt mondod, ez Kalimdor távoli földjéről származik?$B$BElképesztő! Egyszerűen elképesztő!' WHERE ID=942;
UPDATE quest_offer_reward SET RewardText='Igazán kiváló, $N!$B$BMost pedig lássuk, tudom-e a követ használni a kövületek erejének megfejtésére.' WHERE ID=943;
UPDATE quest_offer_reward SET RewardText='A Twilight''s Hammer a Mester Alabárdjánál van?$b$bSajnálatos.$b$bAz öreg úr, akit az alabárd átdöfött, régen halott, de ez nem jelenti, hogy hatalmának szilánkjai nem maradtak fenn.$b$bA Twilight''s Hammer biztos ezt a hatalmat keresi.' WHERE ID=944;
UPDATE quest_offer_reward SET RewardText='A húgom hol volt?? Therylune nem bánja, ha bepiszkolja magát, de mégis! Az hosszú út kóborolni, és a Mester Alabárdja nem egészséges hely...$B$BNos, köszönöm, $N. Nagyon kedves volt tőled, hogy tudattad velem, hogy jól van.' WHERE ID=945;
UPDATE quest_offer_reward SET RewardText='Sok köszönet, $N. Ezek a gombák remek példányok!$b$bÉs amikor a Cliffspring-vízesésnél jártál, találtál valamit, ami megerősíti az Ősök figyelmeztetéseit?$b$bAz Ősök bölcsek, de reméltem, hogy ezúttal tévednek.' WHERE ID=947;
UPDATE quest_offer_reward SET RewardText='$N. Itt vagy.$b$bJó.$b$bVannak ügyeink... amiket meg kell beszélnünk. Te és én.' WHERE ID=948;
UPDATE quest_offer_reward SET RewardText='Ez a könyv kézzel nyomtatva egy ősi nyelven, és egy mesterművész illusztrálta.' WHERE ID=949;
UPDATE quest_offer_reward SET RewardText='Kaotikus, ősi mágia lengi körül ezt a firkált pergament. Az öregek munkáját érzem benne.$b$bReméljük, felfedi a Twilight''s Hammer darkshore-i szándékát...' WHERE ID=950;
UPDATE quest_offer_reward SET RewardText='Köszönöm. Ezek az ereklyék abból az időből valók, amikor Mathystra ragyogott. Az elfek egykor nagyszerű bástyája elhalványult, de mágiájának szilánkjai megmaradtak. Reméljük, mi tudjuk feltárni annak a helynek a titkait ellenségeink előtt...$b$bLégy éber, $N.' WHERE ID=951;
UPDATE quest_offer_reward SET RewardText='Á. Köszönöm, $N. Bár furcsa. A Fődruida mindig olyan sietősnek tűnik. Az erdő tudja, hogy minden a kijelölt időben történik meg. Shan''do Stormrage ezt megértette.' WHERE ID=952;
-- quest_offer_reward.RewardText. Batch 19: quest IDs 953-1009.

UPDATE quest_offer_reward SET RewardText='Kevés feljegyzésünk maradt az Ősök Háborúja körüli időkből, különösen az Örökkévalóság Kútjának pusztulása közeléből. Tekintve a felfordulást és a kataklizmikus eseményeket, amik akkoriban zajlottak, ez nem meglepő.$B$BKöszönöm, $N. A segítségeddel a munkám itt befejeződött, és teljes jelentést tudok küldeni a Körnek.' WHERE ID=953;
UPDATE quest_offer_reward SET RewardText='Áh... Vajon minek köszönhetem azt a rendkívüli megtiszteltetést, hogy egy ilyen $r társaságában lehetek? Sokat elárul jelenlegi társaimról -- nem akarva megsérteni vendéglátóimat, a nemes grelleket és satyrokat --, hogy a jelenléted javulásnak számít.$b$bDe kérlek, ne hagyd, hogy modortalan nyelvem elűzzön innen. Bizony sok éve, évtizede már, hogy udvarias társaságban lehettem.' WHERE ID=954;
UPDATE quest_offer_reward SET RewardText='Valóban... Bashal''Aran grelljei nem birtokolják, amit keresek... ám mostanában kapcsolatba kerültek vele. Mostanában... a te időszámításod szerint, nem az enyém. Számomra a „mostanában” a múlt fátylába nyúlik vissza, szinte egy másik Korszakba...' WHERE ID=955;
UPDATE quest_offer_reward SET RewardText='Nehezen hiszem el, hogy amit most a kezemben tartok, az volt az, ami oly sokáig fogva tartott engem. Ne vesztegessük az időt, $N. Ha a pecsét megsemmisül, ismét szabadon járhatom a föld erdeit.' WHERE ID=956;
UPDATE quest_offer_reward SET RewardText='Szabad vagyok, $N! Saját szememmel láthatom a világunkban végbement változásokat... Eddig csak töredékeket ismertem belőlük. Ha belegondolok, hogy amikor utoljára szabadon jártam, a Kút még állt, és a Highborne Azsharánál, szeretett királynőnknél tartott udvart.$B$BÉrzem, hogy fogvatartóm, egykori mesterem, Athrikus még mindig él... A reménytelenség érzése máris bosszúvágynak adja át a helyét.' WHERE ID=957;
UPDATE quest_offer_reward SET RewardText='Bár bizonyára csak a képzeletem szüleménye, mégis szinte érzem rajtuk az undorító Highborne-mágia szennyét. Elpusztíttatom ezeket, hogy a bennük szunnyadó gonosz soha többé ne szabaduljon el.' WHERE ID=958;
UPDATE quest_offer_reward SET RewardText='Kiváló! Pont amikor már azt hittem, elveszítem az állásomat! Gondoskodom róla, hogy Gazlowe azonnal megkapja ezt az ajándékot.$B$BKöszönöm, $N. Szép munka, mondhatom!' WHERE ID=959;
UPDATE quest_offer_reward SET RewardText='A Twilight''s Hammer kultistáinak felbukkanása nyugtalanító. Elmélkednem kell szándékaikon...$B$BHa több információd lesz, egy jóstálon keresztül szólj hozzám. Ha szükséged van egy jósló fiolára egy tál elkészítéséhez, akkor... itt van még egy.' WHERE ID=961;
UPDATE quest_offer_reward SET RewardText='Á, pompás példányok. Jó munkát végeztél, $N.' WHERE ID=962;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Talán jobb lett volna... ha magam teszem meg. De még ennyi évezred után sem tudtam volna kezet emelni szerelmemre.$b$bKérlek, hadd maradjak egyedül a gyászommal...' WHERE ID=963;
UPDATE quest_offer_reward SET RewardText='Ez működni fog, $N! Most rajtam a sor -- megfelelő edzettséggel látom el őket, hogy kibírják a heves kovácsolási folyamatot, amin végül átesnek majd.$b$bA következő lépés egy megfelelő öntőforma beszerzése a kulcshoz. Ismerek egy goblin kovácsot Tanarisban, aki a múltban hasonlóan hátborzongató tárgyakhoz készített öntőformákat. Annak dolgozik, akinek a goblinok általában szoktak -- a legtöbbet fizetőnek.' WHERE ID=964;
UPDATE quest_offer_reward SET RewardText='Elissa küldött? Akkor jó híreket hozol. Nyugtalanító hírem van számára, de nem volt módom eljuttatni hozzá.' WHERE ID=965;
UPDATE quest_offer_reward SET RewardText='Köszönöm szépen, $N. Ez talán fényt derít a warlockok gyülekezésére...$b$bHmm... a Sötét Fonat Kultusza... Sosem hallottam még erről a csoportról. Történetük ismerete nélkül szinte lehetetlen megmondani, mik lehetnek a terveik.$b$bNincs több idő a késlekedésre. A figyelmeztetést azonnal el kell juttatni Delgrenhez.' WHERE ID=966;
UPDATE quest_offer_reward SET RewardText='Ha nem veszed zokon, hogy megjegyzem, kissé jól felszereltnek tűnsz egy futárhoz képest, nemde? Gondolom, Balthule biztos akart lenni benne, hogy levele a kezembe kerül. Lássuk, mit ír...$B$BEz nyugtalanító hír. Amikor élőholtakat vagy démoni erőket találnak, segítek az Őrszemeknek elpusztítani őket.$B$BElőször nem szoktam hozzá az éjszakai tündék szokásaihoz, de idővel nagy tisztelettel kezdtem tekinteni rájuk mint szövetségesekre.' WHERE ID=967;
UPDATE quest_offer_reward SET RewardText='Á, egy példány „Az alant lakozó erők”-ből. Érdekes szöveg, ez. És néhányan hasznosnak találhatják...$B$BDe ez a példány szomorú állapotban van. És nézd csak! Szinte minden oldal margóján jegyzetek vannak!$B$BHm... ismerem ezt a példányt. Tavaly adtam el Bolgarnak. Te... a barátja vagy? Igen, gondoltam. Ugyanaz a tűz van a szemedben!$B$BNos, ha Bolgar barátja vagy, akkor definíció szerint az enyém is. És mi gondoskodunk a magunkfajtáról, ugye?' WHERE ID=968;
UPDATE quest_offer_reward SET RewardText='Áh, igen... Mingyá'' megcsinálom neked azt a talizmánt. Csak várjál!' WHERE ID=969;
UPDATE quest_offer_reward SET RewardText='Hmm, valami sötét mágia van ezen a lélekkövön. Lássuk, mi van bezárva belé, jó?' WHERE ID=970;
UPDATE quest_offer_reward SET RewardText='Megtaláltad a kéziratot! Micsoda örömteli nap ez! Másolatokat készítünk és terjesztünk, és Lorgalis ősi tudása végre ismertté válik testvéreim számára!$B$BSzolgálatod számunkra többet ér, mint gondolnád, $N. De remélem, ez az ajándék megmutatja a hálát, amit szövetségeseinknek nyújtunk.' WHERE ID=971;
UPDATE quest_offer_reward SET RewardText='Vidd magaddal a vízi saptát, és keresd meg a beszennyezett vizű tavat Silverpine-ban, $N. Nagy hittel vagyok képességeid iránt.' WHERE ID=972;
UPDATE quest_offer_reward SET RewardText='Nagyszerű dolgot tettél ma, $N. Igazán büszke lehetsz magadra, amiért szembeszálltál egy ilyen hatalmú warlockkal.$b$bMost pedig lássuk, mit tudhatunk meg Ilkrud írásaiból.' WHERE ID=973;
UPDATE quest_offer_reward SET RewardText='Igen, egyértelműen látom az összefüggést a vulkán hőmérséklete és a hőforrások között. Kétszer is ellenőriznem kell majd az egyenleteimet a pontosság kedvéért, de úgy tűnik, a távolság és a hőátadás sebessége... Hmm...' WHERE ID=974;
UPDATE quest_offer_reward SET RewardText='Itt is van, $N. Ne feledd, magaddal kell vinned. Mit szólnál, ha visszamennél Winterspringbe, és megnéznéd, mit találsz ott?' WHERE ID=975;
UPDATE quest_offer_reward SET RewardText='Jó munkát végeztél ma, $c. Az Auberdine megsegítésére küldött készletek azonnal hasznosak lesznek az erdőt fertőző sötét fenyegetések elhárításában.$B$BFogadd ezeket szívből jövő köszönetem jeleként.' WHERE ID=976;
UPDATE quest_offer_reward SET RewardText='Alig várom, hogy megmutassam a barátaimnak! Most pedig várj egy pillanatot, amíg felerősítem ezeket...$b$bTökéletes!' WHERE ID=977;
UPDATE quest_offer_reward SET RewardText='Most már össze tudom hasonlítani a tollakat... Lássuk csak...' WHERE ID=978;
UPDATE quest_offer_reward SET RewardText='Szia! Erelas küldött? Remek, épp készülődtem felmenni a barlangokhoz, és nem bánnám a társaságot.' WHERE ID=979;
UPDATE quest_offer_reward SET RewardText='Szia, $N. Igen, amit Krakle mondott neked, igaz...' WHERE ID=980;
UPDATE quest_offer_reward SET RewardText='Tudtam, hogy megbirkózol a feladattal, $N.$B$BNagy tetteket érzek előtted, és hogy sok igazságtalanságot helyre fogsz hozni, ami földjeinket sújtja. Vidd magaddal áldásomat, $N, valamint ezt az ajándékot.' WHERE ID=981;
UPDATE quest_offer_reward SET RewardText='Nagy szolgálatot tettél nekünk itt, Auberdine-ban, fiam. Gondoskodunk róla, hogy a holmijaikkal megfelelően bánjunk.$b$bAmi téged illet, kérlek, fogadd ezt el. Ez a legkevesebb, amit tehetek valakiért, akinek volt bátorsága helyrehozni a dolgokat.' WHERE ID=982;
UPDATE quest_offer_reward SET RewardText='Ahogy a Crawler lábakat a gépbe helyezed, fogaskerekek csikorgását hallod. A Buzzboxból jövő dörömbölő hangokból ítélve úgy tűnik, a Crawler lábak a helyükre kerülnek. Hamarosan a gép zümmögni kezd, és egy apró hangot hallasz belülről kiáltani.$b$b„Halló? Öhm... Halló! Megjavítottad! Amúgy Wizbang vagyok! Nagyon köszönöm... Hé, nem lenne kedved megjavítani még egyet?”' WHERE ID=983;
UPDATE quest_offer_reward SET RewardText='Ez valóban szörnyű hír, $N.$B$BMivel a furbolgok ilyen közel vannak Auberdine-hoz, fel kell készülnünk az elkerülhetetlenre.$B$BKöszönöm, $N.' WHERE ID=984;
UPDATE quest_offer_reward SET RewardText='Mosd le a vért a ruháidról, $N, és ne gyászold, amit tenned kellett. Inkább adj hálát. Csökkentetted a fenyegetést népünk számára itt Auberdine-ban, még ha Darkshore-t továbbra is veszélyezteti is a fel moha hatása.' WHERE ID=985;
UPDATE quest_offer_reward SET RewardText='Ezek tökéletesen megfelelnek, $N. Azonnal nekilátok a köpeny elkészítésének.$B$BAdj néhány pillanatot, aztán gyere vissza hozzám.$B$BÓ, még valami: miután a bűbájt a köpenyre használtad, korlátozott lesz a másokkal való érintkezésed. Ha teheted, ne tégy mást, csak beszélj velük. Bármi ennél több szétoszlathatja az illúziót.' WHERE ID=986;
UPDATE quest_offer_reward SET RewardText='Á, egy $c Darkshore-ból. Selarin jól tette, hogy ilyen gyorsan ideküldött téged, $N. Bárcsak ne ilyen súlyos nyomás alatt kellett volna idejönnöd. Talán a segítségeddel javíthatunk a helyzeten.$B$BÉn a látogatásomat azzal kezdeném, hogy beszélek Astranaar többi polgárával. Néhányuknak biztosan jól jönne a segítséged.' WHERE ID=990;
UPDATE quest_offer_reward SET RewardText='Teronis holtteste összetörve fekszik a sziget tetején. Valamilyen ismeretlen okból a murlocok nem nyúltak hozzá.$B$BA holttestén lévő mély vágások egyértelműen a murlocok fegyvereitől és karmaitól származnak.' WHERE ID=991;
UPDATE quest_offer_reward SET RewardText='Ez meg mi? Valamiféle rosszindulatú, kúszó-mászó szörnyeteg támadott rád? Ó, ez bizony nem sok jót ígér a Gadgetzan Vízi Társaságnak, valóban nem...$B$BGondolom, szólnom kellett volna a jelentésekről, amik valami őrült bogárszerű lényekről szóltak, amik mintha felszívnák az összes vizet a sivatagban. Először azt hittem, csak duma az egész. Amúgy is elég bajunk van a nomádokkal; azt hittem, csak megint valami trükkjük. Nos, most már legalább tudjuk!' WHERE ID=992;
UPDATE quest_offer_reward SET RewardText='Csodálatos! Terenthis talált valakit, aki segít nekem.$b$bÉs nézd csak, egy holdvadász köpeny... <köhög> Ó... az fáj. Köszönöm, $N.$b$bA furbolgok megsebesítettek, mielőtt sikerült kikerülnöm őket. Adj egy pillanatot, és rendbe jövök, hogy tovább beszélgessünk.' WHERE ID=993;
UPDATE quest_offer_reward SET RewardText='$N! Örülök, hogy sikeresen visszatértél. A Volcornak nyújtott segítséged hitet adott nekem, hogy legyőzhetjük az itt Darkshore-ban és azon túl ránk váró kihívásokat.' WHERE ID=994;
UPDATE quest_offer_reward SET RewardText='$N! Örülök, hogy sikeresen visszatértél. A Volcornak nyújtott segítséged hitet adott nekem, hogy legyőzhetjük az itt Darkshore-ban és azon túl ránk váró kihívásokat.' WHERE ID=995;
UPDATE quest_offer_reward SET RewardText='Két Cenarion növénykenőcsöt kensz fel a szélvirágra. Az azonnal elkezdi levetni beszennyezett formáját, és élénk, egészséges növényként bomlik ki.' WHERE ID=996;
UPDATE quest_offer_reward SET RewardText='Á, itt van! Már jó ideje vártam erre a ritka földre. Remélem, még friss...$b$bKöszönöm, hogy elhoztad nekem, $N. Olyan $R vagy, aki nagylelkűen bánik az idejével.' WHERE ID=997;
UPDATE quest_offer_reward SET RewardText='Két Cenarion növénykenőcsöt kensz fel a szélvirágra. Az azonnal elkezdi levetni beszennyezett formáját, és élénk, egészséges növényként bomlik ki.' WHERE ID=998;
UPDATE quest_offer_reward SET RewardText='Üdvözlégy, $c.$b$bÖrömmel látom, hogy hozzád hasonlók érdeklődnek a természet jóléte iránt; hatalmas tetteid híre megelőz téged, és szívesen látunk itt. Az, hogy előttem állsz, bizalmat kelt bennem, hogy a Cenarion Circle megkapja a szükséges segítséget.$b$bA Moonglade-i Cenarion Circle-lel való kapcsolatunk túllép fajon és politikai megosztottságon. Tartsd ezt észben, miközben a Cenarion Circle nevében dolgozol, és jól fogsz boldogulni.' WHERE ID=1000;
UPDATE quest_offer_reward SET RewardText='A Buzzbox életre kel, miután behelyezed a Thresher szemeket. Egy pillanatnyi recsegés után egy ismerős, apró hangot hallasz kiáltani.$B$B„A csúszó-mászó bor a legjobb...” *csuklás*$B$B„Mi? Ó, már meg is javítottad? Hűha, gyorsh vagy. Sho, van kedved megjavítani még egyet?”$B$BÚgy tűnik, folyadékot töltenek egy pohárba, majd hangos kortyolást hallasz.' WHERE ID=1001;
UPDATE quest_offer_reward SET RewardText='A Buzzbox hirtelen életre kel, és belülről tisztán kivehető a fogak porrá őrlésének hangja.$b$b„Sho, shikerült! Ez remek hír... Sho... Miért nem mész tovább? Ó! Hacsak nem akarsz még egy munkát!”' WHERE ID=1002;
UPDATE quest_offer_reward SET RewardText='Sho, behoztad a fejbőröket? Ez sho remek... Mi? Nos, igen, gondolom, rájöttél, hogy anyagok nélkül is tudok beszélni veled a gépen keresztül. De igazat mondtam, amikor azt mondtam, el vannak romolva!$b$bLátod, a Buzzboxok kommunikációs eszközök mellett finom szeszt is főznek és desztillálnak. Shajnálom a megtévesztést, de az éjszakai tündék nem nézik jó szemmel az italkereskedésemet a városaikban. Tettem valami különlegeset ebbe a dobozba, hogy megmutassam hálámat a fáradozásodért. Élvezd!' WHERE ID=1003;
UPDATE quest_offer_reward SET RewardText='Üdvözlégy, $c.$b$bÖrömmel látom, hogy hozzád hasonlók érdeklődnek a természet jóléte iránt; hatalmas tetteid híre megelőz téged, és szívesen látunk itt. Az, hogy előttem állsz, bizalmat kelt bennem, hogy a Cenarion Circle megkapja a szükséges segítséget.$b$bA Moonglade-i Cenarion Circle-lel való kapcsolatunk túllép fajon és politikai megosztottságon. Tartsd ezt észben, miközben a Cenarion Circle nevében dolgozol, és jól fogsz boldogulni.' WHERE ID=1004;
UPDATE quest_offer_reward SET RewardText='Megtaláltad! Köszönöm, $N!$B$BZoram ősi városa sok titkot rejt, és ez a szobrocska sokuk kulcsa lehet.' WHERE ID=1007;
UPDATE quest_offer_reward SET RewardText='Nagyon szép munka, $N. A Zoram Strand-en a naga ellen véghezvitt tetteid dicséretre méltóak.$B$BTudom, hogy nem volt könnyű feladat, hiszen a naga ereje és ravaszsága jól ismert az éjszakai tündék körében. Tudjuk ezt, mert közös történelmünk van velük.$B$BOlyan történelem, amit nem szeretnék megismételni.' WHERE ID=1008;
UPDATE quest_offer_reward SET RewardText='Megtaláltad a gyűrűt! Köszönöm, $N. Kérlek, fogadd el ezt fizetségként, és tudd, hogy mai tetteid örökre emlékezetemben maradnak.' WHERE ID=1009;
-- quest_offer_reward.RewardText. Batch 20: quest IDs 1010-1059.

UPDATE quest_offer_reward SET RewardText='Á, megvan a haj! Most összekeverem a gyógyszert a gyermeknek, és imádkozom, hogy a keverékem működjön.$B$BÉs... Forsaken-ek vannak Bathran''s Hauntnál? Nagyon nyugtalanító hír ez. Bizony, nagyon nyugtalanító...' WHERE ID=1010;
UPDATE quest_offer_reward SET RewardText='Nagyon jó, $N. Most... ha megvizsgáljuk ennek az üvegnek a tartalmát, a Forsaken céljai napvilágra kerülnek!' WHERE ID=1011;
UPDATE quest_offer_reward SET RewardText='Éreztem, ahogy a Dor''danil Barrows gyötrelme enyhül, és tudtam, hogy teljesítetted a feladatod.$B$BKomor munka volt ez, $N, hiszen a szellemek, akiket elpusztítottál, csupán a Forsaken gonoszságának áldozatai voltak. De reméljük, elpusztításukkal a többi megőrült szellem is békére lel.' WHERE ID=1012;
UPDATE quest_offer_reward SET RewardText='Nagyon jó. Ez a könyv szépen kiegészíti Ur munkásságáról szóló gyűjteményemet. Tudása nagy volt, de lelkiismerete visszatartotta az igazi hatalomtól. Így amikor eljött a Scourge, és erejét próbára tették, kudarcot vallott.$B$BMi, a Forsaken tagjai, nem engedhetünk meg magunknak ilyen gyengeséget, ha túl akarunk élni...' WHERE ID=1013;
UPDATE quest_offer_reward SET RewardText='Silverpine Forest végre megszabadult annak a nyomorult Arugalnak a szorításától. Nagy szolgálatot tettél a Dark Ladynek, $N. Kitartásod jutalmat érdemel.' WHERE ID=1014;
UPDATE quest_offer_reward SET RewardText='Mi alapján gondolod, hogy szeretném, ha egy hozzád hasonló zaklatna, $c? Várj csak -- hadd hagyjam abba a napi fontos teendőimet, hogy segítsek megtalálni valami vacakot valahol. Természetesen Darnassus jóléte -- sőt, egész Teldrassilé -- másodlagos legyen egy csecsebecse megszerzéséhez a gyűjteményedhez.$B$BA moonglade-i bolondok az idejét pazarolják a segélykérésükkel, és most ezt is el kell viselnem?' WHERE ID=1015;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N, ez megadja nekünk azt az információt, amire szükségünk van a tettes felfedezéséhez. Mit szólnál hozzá, ha kiiktatnád azt a mágust, aki beszennyezett elementálokkal tölti meg tavainkat? Ashenvale és a környék megrontása önmagában is felkavarja a gyomrom -- az, hogy egy varázsló szándékosan tovább pusztítja, végtelenül undorít. Megfizettetjük vele.' WHERE ID=1016;
UPDATE quest_offer_reward SET RewardText='Most már örökre eltűnhet az undorító mosoly az arcáról. Nagyon jó munkát végeztél, $N. Vedd el ezt, Elune Fényét, idd meg, ha minden elveszettnek tűnik, és közel a halál. Megmentheted az életed, ha az Istennő is úgy akarja.' WHERE ID=1017;
UPDATE quest_offer_reward SET RewardText='Üdvözlégy, $c.$b$bÖrömmel látom, hogy hozzád hasonlók érdeklődnek a természet jóléte iránt; hatalmas tetteid híre megelőz téged, és szívesen látunk itt. Az, hogy előttem állsz, bizalmat kelt bennem, hogy a Cenarion Circle megkapja a szükséges segítséget.$b$bA Moonglade-i Cenarion Circle-lel való kapcsolatunk túllép fajon és politikai megosztottságon. Tartsd ezt észben, miközben a Cenarion Circle nevében dolgozol, és jól fogsz boldogulni.' WHERE ID=1018;
UPDATE quest_offer_reward SET RewardText='Mi alapján gondolod, hogy szeretném, ha egy hozzád hasonló zaklatna, $c? Várj csak -- hadd hagyjam abba a napi fontos teendőimet, hogy segítsek megtalálni valami vacakot valahol. Természetesen Darnassus jóléte -- sőt, egész Teldrassilé -- másodlagos legyen egy csecsebecse megszerzéséhez a gyűjteményedhez.$b$bA moonglade-i bolondok az idejét pazarolják a segélykérésükkel, és most ezt is el kell viselnem?' WHERE ID=1019;
UPDATE quest_offer_reward SET RewardText='Ez Orendiltől van?$B$BNagy a tudása a füvekben és a gyógyításban. Ez a gyógyszer reményt ad nekem, amikor korábban alig volt bennem...' WHERE ID=1020;
UPDATE quest_offer_reward SET RewardText='Az oldalán tátongó seb alapján ítélve Anilia a halál szélén áll.' WHERE ID=1021;
UPDATE quest_offer_reward SET RewardText='A Mel''Thandris Kódexe furcsa módokon működik. Az események, amiket rögzít, az események, amiket megmutat... senki sem érti igazán, miért teszi, amit tesz.$B$BMindazonáltal egyértelmű, hogy amit Starsong papnő kapott -- ezt az Elune Kaszáját -- további vizsgálat illeti.' WHERE ID=1022;
UPDATE quest_offer_reward SET RewardText='Ez szörnyű, $N. Teronis meghalt?!$B$BEljön még a gyász ideje, de most az erőfeszítéseinkre kell koncentrálnunk. Küldök néhány Őrszemet, hogy mielőbb visszahozzák Teronis holttestét.$B$BNálad van Teronis naplója és a drágakő, amit keresett. Szerinted képes lennél befejezni a feladatát? Sokkal nyugodtabban aludnék, ha tudnám, hogy halála nem volt hiábavaló.' WHERE ID=1023;
UPDATE quest_offer_reward SET RewardText='Ó, Raene küldött téged? Akkor bizony komoly lehet a helyzet. Miben segíthetek?' WHERE ID=1024;
UPDATE quest_offer_reward SET RewardText='Jó munkát végeztél, $N. Köszönöm.' WHERE ID=1025;
UPDATE quest_offer_reward SET RewardText='Örülök, hogy látom, visszatértél, $N.' WHERE ID=1026;
UPDATE quest_offer_reward SET RewardText='Megtaláltad az utolsó darabot? Csodálatos neked... és Raene-nek is.$B$BGondolom, meg kell néznünk, hogyan javítsuk meg, nem igaz?' WHERE ID=1027;
UPDATE quest_offer_reward SET RewardText='Miután a fény elhalványul, láthatod az újra elvarázsolt pálcát a szentély medencéjében.' WHERE ID=1028;
UPDATE quest_offer_reward SET RewardText='Újra elkészítetted a pálcát, amit Teronis keresett? Ezt csodálatos hallani.$B$BTeronis büszke lenne, ha látná, hogy küldetése tragikus halála után is folytatódik.' WHERE ID=1029;
UPDATE quest_offer_reward SET RewardText='Igen, igen... a fajtámbéli vagy, de még mindig teljes. Még mindig tiszta.$B$BNem tudom, hogyan kerülted el azokat a szörnyűségeket, amiket az éjszakai tündék hoztak népünkre, de örülök, hogy tudom, már nem vagyok egyedül.$B$BMegrontás folyik most már fajtánk ereiben, ifjú, olyan megrontás, amit a gőgös éjszakai tündék zúdítottak ránk. Ők azok, akik ezt tették népünkkel... Őket hibáztatom azért, hogy kitaszítottak a törzsemből.$B$BÉjjelente még mindig látom a tábortüzeket égni a sötétben.' WHERE ID=1030;
UPDATE quest_offer_reward SET RewardText='Anilia meghalt? Nem... ez nem lehet! Csak tegnap futkároztunk és játszottunk együtt az erdőben.$B$BGondolom, azoknak a napoknak vége...' WHERE ID=1031;
UPDATE quest_offer_reward SET RewardText='Köszönöm, kedves $R. Húgom szelleme örül erőfeszítéseidnek.' WHERE ID=1032;
UPDATE quest_offer_reward SET RewardText='Ó, megtaláltad! Beleteszem a könnyet egy raguba, és imádkozom, hogy meggyógyítja őt.$B$BKöszönöm! Köszönöm, $N!' WHERE ID=1033;
UPDATE quest_offer_reward SET RewardText='Összegyűjtötted a port! Borogatást készítek belőle -- ennek le kell vinnie Relara lázát.$B$BKöszönöm még egyszer, $N. A segítséged nélkül a gyermekem biztosan elpusztult volna.' WHERE ID=1034;
UPDATE quest_offer_reward SET RewardText='Ó, $N, megmentetted a lányomat! Tudom, hogy a holdkő ereje visszaadja majd a lányom erejét!$B$BSoha nem tudom teljesen viszonozni a segítséget, amit nyújtottál, de... kérlek, fogadd el ezt. Relarán kívül ez a legkedvesebb tulajdonom.' WHERE ID=1035;
UPDATE quest_offer_reward SET RewardText='Állj meg, te csirkefogó! Hallom, olyan fajta vagy, aki nem riad vissza egy kis aljasságtól. Nos, ha nem vagy Booty Bay barátja, akkor talán különleges helyed lehet a Bloodsail Buccaneers között.$B$BArrrr...' WHERE ID=1036;
UPDATE quest_offer_reward SET RewardText='Velinde Starsong? Az, hogy a papnő eltűnt egy ideje, szinte biztosan közismert tény. Ami a távozását övező események további részleteit illeti... jó okra lenne szükségem ahhoz, hogy ilyen információt kiadjak.' WHERE ID=1037;
UPDATE quest_offer_reward SET RewardText='Úgy tűnik, Velinde eltűnése nyugtalanítóbb, mint eredetileg gondoltam. Mégis, nem tudom elhinni, hogy rossz vég jutott neki. Talán hasznos lenne felvennünk vele a kapcsolatot.$B$B$N, mivel érdeklődést mutattál ez ügyben, szeretném igénybe venni a segítséged.' WHERE ID=1038;
UPDATE quest_offer_reward SET RewardText='$R, mi? Be kell vallanom, ritkán látunk itt hozzád hasonlót. Valakit keresel, mi? Adj egy pillanatot, biztos vagyok benne, hogy fel van jegyezve valamelyik könyvemben.$B$BSokan járnak errefelé, szóval adj egy percet.' WHERE ID=1039;
UPDATE quest_offer_reward SET RewardText='Igen? Nos, nem úgy nézel ki, mint akinek szállítandó árui lennének, szóval vagy munkát keresel a karavánomnál -- és most nincs felvehető munka --, vagy valószínűleg rossz goblinnal beszélsz.$B$BSzóval melyik?' WHERE ID=1040;
UPDATE quest_offer_reward SET RewardText='Az utóbbi évek furcsa eseményei miatt igyekszem minél alaposabb feljegyzéseket vezetni az idegenekről. Sosem tudni, mikor jöhet jól... bár amikor jól jön, az általában nem kellemes ügy. Nem mintha bármit is sugallnék erről a Velinde-ről, akit keresel.' WHERE ID=1041;
UPDATE quest_offer_reward SET RewardText='Sötét idők ezek. Minden hajladozó ágról rossz hírek suttognak, és minden kő alatt gonoszság lapul.$B$BÉs ilyen időkben egy ismeretlen idegen lép be az otthonomba, és worgenekről érdeklődik... Nem kérek bocsánatot a gyanakvásomért, csak válaszokat.$B$BÉs válaszokat kapok.' WHERE ID=1042;
UPDATE quest_offer_reward SET RewardText='Érdekes történetet meséltél, $N. Bár a Carevin család befolyása nem elég nagy ahhoz, hogy megtaláljuk e bajok gyökerét, és egyszer s mindenkorra végezzünk velük, megteszünk mindent, hogy kordában tartsuk a worgenek számát Duskwoodban.$B$BMár utasítottam Calort, hogy ezt tegye a legfőbb prioritásává.' WHERE ID=1043;
UPDATE quest_offer_reward SET RewardText='Szóval ez Velinde sorsa? A főpapnő csalódott lesz, ha ezt meghallja, jó barátnők voltak az eltűnése előtt. Mégis, az Elune Kaszáját bizonyára istennőnk adományozta neki áldásként, és nyugtalanító számomra, hogy kikerült szolgáinak kezéből.$B$BEz azonban egy másik alkalomra tartozó ügy. Nem kis hálával tartozom neked azért, amit elértél.' WHERE ID=1044;
UPDATE quest_offer_reward SET RewardText='Jó munkát végeztél, barátom.$B$BAz erdő még mindig beszennyezett, de legalább tudjuk, hogy tettünk egy kis részt azért, hogy visszanyerje régi dicsőségét. Ha szívesen visszatérnél hozzám, örülnék a magamfajta társaságának.$B$BLégy jól. Talán törzseink egy kevésbé erőszakos időben újra találkoznak.' WHERE ID=1045;
UPDATE quest_offer_reward SET RewardText='Szóval ez a koponyája Ashenvale legveszettebb furbolg-fenyegetésének?$B$BTöbb mint elégedett vagyok a képességeiddel, $N. Az Őrszemek nem tudnak eléggé hálásak lenni. Remélem, a jövőben is számíthatunk rád népünk megsegítésében.$B$BEzt a koponyát és Dartol pálcáját tiszteletet parancsoló helyre teszem, hogy mások is láthassák.$B$BTeronis büszke lenne. Köszönöm még egyszer.' WHERE ID=1046;
UPDATE quest_offer_reward SET RewardText='Mi alapján gondolod, hogy szeretném, ha egy hozzád hasonló zaklatna, $c? Várj csak -- hadd hagyjam abba a napi fontos teendőimet, hogy segítsek megtalálni valami vacakot valahol. Természetesen Darnassus jóléte -- sőt, egész Teldrassilé -- másodlagos legyen egy csecsebecse megszerzéséhez a gyűjteményedhez.$b$bA moonglade-i bolondok az idejét pazarolják a segélykérésükkel, és most ezt is el kell viselnem?' WHERE ID=1047;
UPDATE quest_offer_reward SET RewardText='Jól szolgáltad a Dark Ladyt, $c. Nem volt kis feladat, amit kértem tőled.$b$bA Forsaken iránti hűséged feljegyzésre került. És harci kitartásod emlékezetes marad.' WHERE ID=1048;
UPDATE quest_offer_reward SET RewardText='Az Elesettek Kódexe! Már kezdtem azon tűnődni, hogy egyáltalán létezik-e ez a könyv!$b$bJól szolgáltad Thunder Bluff taurenjeit, $N. Elkötelezettséged nem lesz elfeledve.' WHERE ID=1049;
UPDATE quest_offer_reward SET RewardText='Megmentetted a szent szöveget!$b$bUtazásod hosszú volt, és a könyv megszerzése kétségtelenül nem volt könnyű feladat. De Ironforge törpjei profitálnak majd sikeredből.$b$bKöszönöm, $N, az Explorers'' League nevében.' WHERE ID=1050;
UPDATE quest_offer_reward SET RewardText='Vorrel olyan zaklatott életet élt. És micsoda jó barát volt...$b$bÁtkozott mocskos emberek!$b$bVorrel eltávozott, sosem élvezheti már többé az élőholtlétet. Legalább vigaszt találok a bosszúban, amit a nevében álltál. Ezért köszönetet mondok neked.$b$bMost hagyj gyászolni...' WHERE ID=1051;
UPDATE quest_offer_reward SET RewardText='Anton testvér még mindig terjeszti a Scarlet Crusade tanait? Egek...' WHERE ID=1052;
UPDATE quest_offer_reward SET RewardText='Bár a Fény tanítványai sosem örülnek életek elvesztésének, el kell fogadnunk, hogy néha ilyen áldozatokra szükség van a Királyság és a bolygó nagyobb java érdekében.$B$BA kolostorban végzett tetteiddel sok ártatlan életet mentettél meg, $N. Tisztelgek kitartásod előtt.' WHERE ID=1053;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N.$B$BÁllandó fenyegetésnek vagyunk kitéve a furbolgok részéről. Remélhetőleg ez egy ideig távol tartja őket.' WHERE ID=1054;
UPDATE quest_offer_reward SET RewardText='Sikerült, $N! Szép munka!' WHERE ID=1055;
UPDATE quest_offer_reward SET RewardText='Végre megérkeztél. Látom, Faldreas hallgatott az erdő szellemeire...' WHERE ID=1056;
UPDATE quest_offer_reward SET RewardText='Most, hogy a Bloodfuryk ekkora veszteséget szenvedtek, talán elkezdődhet a föld helyreállításának igazi munkája...' WHERE ID=1057;
UPDATE quest_offer_reward SET RewardText='Ó, mennyire boldogok lesznek ezek a kis erdei nimfák! Ezzel a különleges főzettel egészen otthon fogják érezni magukat!' WHERE ID=1058;
UPDATE quest_offer_reward SET RewardText='Albagorm Őrző bölcsen tette, hogy ilyen sürgősen elküldött téged.$B$BLássuk, tudunk-e segítséget hívni a nagy erdőből, hogy még időben eljuthassunk a Charred Vale-be.' WHERE ID=1059;
-- quest_offer_reward.RewardText. Batch 21: quest IDs 1060-1110.

UPDATE quest_offer_reward SET RewardText='Áh, egy levél Darsoktól. Évek óta nem hallottam felőle.$b$bSzóval az utolsó Bloodfeather is meghalt, mi? Ez jó hír, emlékszem, amikor a barátom, Rokhan azzal az őrült mok''nathallal ment el, hogy megölje az idősebb nővérét. Áh, bárcsak megint fiatal lennék, mint te.' WHERE ID=1060;
UPDATE quest_offer_reward SET RewardText='Á, egy $c. Nagyon jó. Szükségünk lesz a képességeidre, hogy elbánjunk ezekkel a fosztogatókkal!' WHERE ID=1061;
UPDATE quest_offer_reward SET RewardText='Bátran tetted, $N.$b$bVégső soron talán a tauren vének bölcsességére lesz szükségünk, hogy megnyugtassuk Stonetalon szellemeit, de...$b$bA Venture Company embereinek megtizedelése jó első lépés ellenük.' WHERE ID=1062;
UPDATE quest_offer_reward SET RewardText='Üdvözöllek. Tanácsért jöttél?' WHERE ID=1063;
UPDATE quest_offer_reward SET RewardText='Magatha üzenetet küldött érkezésedről, $N. Bár a szívem már nem dobog, még mindig szomorúságot érzek Stonetalon szellemei miatt.$b$bA Forsaken készen áll megadni minden segítséget, amit csak tudunk.' WHERE ID=1064;
UPDATE quest_offer_reward SET RewardText='Egy üzenet Zamahtól? Nagy szüksége lehet rám, ha ilyen messziről küldött hírt. Lássuk, mit ír...$b$bÁ, pompás! Pontosan tudom, mit kell tennem!' WHERE ID=1065;
UPDATE quest_offer_reward SET RewardText='Nagyon jó! Remélem, a Syndicate nem okozott sok gondot?$B$BAhogy említettem, ártatlanok vérét nem könnyű megszerezni. Szerencsénk van, hogy a Syndicate árnymágusai elvégezték helyettünk a nehéz munkát.$B$BMost pedig várj egy pillanatot, amíg elkészítem a keverékem...' WHERE ID=1066;
UPDATE quest_offer_reward SET RewardText='Egy méreg Lydon patikáriustól? Nagyon jó. Ha ismerem Lydont, ez a méreg egészen hatásos lesz a Venture Company ellen...' WHERE ID=1067;
UPDATE quest_offer_reward SET RewardText='Az XT:4 és XT:9 gépek elpusztítása megnyugtatta Stonetalon számos szellemét, $N. Elvesztésükkel reméljük, hogy a Venture Company elhagyja majd ezeket a hegyeket.$b$bMert ha nem, attól tartok, az itt elszenvedett szörnyűségek eltörpülnek majd ahhoz képest, ami még jöhet.' WHERE ID=1068;
UPDATE quest_offer_reward SET RewardText='Megszerezted őket! Köszönöm!$B$BElküldöm ezeket Dizzywignek, hogy Booty Bay-be szállítsák. Máris érzem a haszon ízét!$B$BItt a részed, $N. Nem tudtam volna megkötni ezt az üzletet nélküled.' WHERE ID=1069;
UPDATE quest_offer_reward SET RewardText='Á, Ashenvale-ből jöttél, Thenysil kérésére -- mennyire hiányzik ő, a hazám és a barátaim. Biztosan jól megy neki az Őrszemeknél, ha kalandozókat tud átirányítani más feladatokra. Büszke vagyok rá.$B$BÖröm megismerni téged, $N.' WHERE ID=1070;
UPDATE quest_offer_reward SET RewardText='Nagyon köszönöm a segítséged, $N. Épp időben érkeztél vissza.$B$BAzt hiszem, megvan a tökéletes tervem. Robbanóanyagok. Nos, nem ez maga a terv, de ez a terv része.$B$BLátod, nagy erejű robbanóanyagokat használok -- ne aggódj, nem olyan veszélyesek, mint mindenki hiszi --, hogy egy kicsit megijesszem velük a goblinokat. Elég jól tudom terelni őket néhány jól irányzott robbantással a hegyek peremén, de már napok óta kevés az utánpótlásom.' WHERE ID=1071;
UPDATE quest_offer_reward SET RewardText='Ááá. Gaxim küldött, mi? Honnan tudjam, hogy nem hazudsz nekem?! Hm? Hm?' WHERE ID=1072;
UPDATE quest_offer_reward SET RewardText='Ez pont megfelel.$B$BHa nem tudnám jobban, idegen, azt mondanám, értesz valamit az alkímiához. Jó, jó... a világ nem csak kardokról és varázslatokról szól, tudod?' WHERE ID=1073;
UPDATE quest_offer_reward SET RewardText='A feladatodat kifogástalanul teljesítetted, $N.$B$BAz NG-5 az egyértelmű összetevője annak a receptnek, amivel begyújthatók a dinamitos szekerek.$B$BMi? Igen, dinamit... szekérszámra. Ez a tökéletes elterelés, mondom neked... csak várd ki, és meglátod.' WHERE ID=1074;
UPDATE quest_offer_reward SET RewardText='Nos, ez a varázslat, amire szükséged van; olyan, ami lehetővé teszi, hogy távolról robbants... hmmm.' WHERE ID=1075;
UPDATE quest_offer_reward SET RewardText='Adj néhány pillanatot, és kész lesz a tekercsed.' WHERE ID=1076;
UPDATE quest_offer_reward SET RewardText='Ez tökéletes, $N! Szép munka.$B$BEz a varázslat az NG-5-tel keverve a tökéletes távoli robbanószert alkotja majd.$B$BEzzel tökéletes elterelést hozhatunk létre neked, hogy belopózhass, és ellophasd a Venture Co. leveleit és mérnöki terveit.$B$BEz biztosan lassítani fogja az erdőirtásukat.' WHERE ID=1077;
UPDATE quest_offer_reward SET RewardText='Ez tökéletes, $N. Nagyon köszönöm.$B$BTalán egy napon a jövőben én is segíthetek majd neked, ahogy te segítettél nekem.' WHERE ID=1078;
UPDATE quest_offer_reward SET RewardText='Igazán elképesztő! Ez hatalmas csapás a Venture Co.-nak.$B$BKépesek leszünk megtalálni a gyengeségeket a gépeikben, és beépíteni a terveiket a saját alkotásainkba. Ez bizony csodálatos nap.' WHERE ID=1079;
UPDATE quest_offer_reward SET RewardText='Hihetetlen, $N! Kaela és az Őrszemek nagyon boldogok lesznek. A te ügyességeddel és az én alkotásaimmal megállíthatatlanok vagyunk.' WHERE ID=1080;
UPDATE quest_offer_reward SET RewardText='Üdvözöllek, $N. Valóban hallottam már a nevedet, és bár még tele vagy fiatalsággal, örömmel látom azt az utat, amit magadnak választottál.$B$BNagy megtiszteltetés lenne számomra, ha elfogadnád ezt hálám jeleként.' WHERE ID=1081;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Szolgálatot tettél az Őrszemeknek.$B$BÖrülök, hogy Kaela... és még Gaxim is jól van.$B$BKiérdemelted a hálánkat.' WHERE ID=1082;
UPDATE quest_offer_reward SET RewardText='Ellenségünk maradványai... erőd jól szolgál minket, $N. Köszönöm.' WHERE ID=1083;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N.$B$BEz bőven elegendő lesz Gaximnak ahhoz, hogy kiderítse, hogyan romlottak meg a fák szellemei. Azonnal átadom neki.' WHERE ID=1084;
UPDATE quest_offer_reward SET RewardText='Áruló... áruló és veszélyes, ez a föld.$B$BDe azért vagyok itt, hogy megmutassam az éjszakai tündéknek, hogy egy kis jó öreg mérnöki tudással és egy csipetnyi mágiával biztonságosabb hely lehet.$B$BLátod, ha teljesen lemondanak a mágiáról, azzal nem segítenek az éjszakai tündéknek -- szükségük van rá. A világnak szüksége van rá. És mérnöki tudással meg alkímiával megfejelve nem hibázhatsz. A lehetőségek végtelenek.' WHERE ID=1085;
UPDATE quest_offer_reward SET RewardText='Megtaláltad a kikötőt? Szép munka, $N! Biztos vagyok benne, hogy a goblinok jól meglepődtek a szállítmányodtól! Reméljük, a méreg eljut a főhadiszállásukra.$B$BJól szolgáltad a néped, és azt tanácsolom, ne érezz bűntudatot amiért megmérgezted a Venture Companyt. Sokkal rosszabbat érdemelnének.$B$BÉs ha van egy szemernyi bölcsesség, amit a Forsaken taníthat szövetségeseinek, az ez:$B$BNe riadj vissza a sötét ösvényektől... ha azok az ösvények győzelemhez vezetnek.' WHERE ID=1086;
UPDATE quest_offer_reward SET RewardText='Már érzem is... igen... az erő olyan édes... a rohanó áradat. A kaldorei bolondok, hogy elutasítják e világ ajándékait, hogy visszautasítják a mágia áramlását, ahogy énekelve folyik ereidben.$b$bMilyen sápadt gúny az élet lángoló ölelése nélkül!' WHERE ID=1087;
UPDATE quest_offer_reward SET RewardText='Ismertem Ordanust egykor, régen. Megvolt benne fajtája gőgje, még a Highborne fölé is helyezte magát.$b$bMost már nem tartja olyan magasan a fejét, ugye, $N?$b$bMegígértem a jutalmadat, és meg is kapod. Figyelj rám.' WHERE ID=1088;
UPDATE quest_offer_reward SET RewardText='Ahogy a három kulcsot a hozzájuk illő nyílásokba csúsztatod, az izzó fény közepén számos tárgy jelenik meg.' WHERE ID=1089;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Egy pillanatra elég kockázatosnak tűnt a helyzet, és valószínűleg túl sok figyelmet vontunk magunkra.$b$bA lényeg viszont az, hogy megvan az ércminta, és mielőbb el kell juttatnunk Zizhez.' WHERE ID=1090;
UPDATE quest_offer_reward SET RewardText='Ez bizony érdekes.$B$BTe és Gaxim nagyon jól teljesítettetek, $N. Köszönöm.' WHERE ID=1091;
UPDATE quest_offer_reward SET RewardText='Ááá, tudtam, hogy jól tettem, hogy azt mondtam Pizniknek, maradjon hátra. Biztos vagyok benne, hogy az Undermine-i mérnökök nagyon érdekesnek találják majd ezt...$b$bTermészetesen megtartok magamnak egy kis darabot, de amiről nem tudnak, az nem árt nekik, ugye?' WHERE ID=1092;
UPDATE quest_offer_reward SET RewardText='Hé, ez az, aminek gondolom? Remek!$b$bMost pedig lássuk. Ugh... hogy kellene megértenem ezt a cuccot... nem tudom kiismerni, hogyan gondolkodnak a gnómok. Elárulom, meglep, hogy egyáltalán fel tudták találni a kereket, nemhogy azokat a repülőgépeket, amiket annyira szeretnek.' WHERE ID=1093;
UPDATE quest_offer_reward SET RewardText='Fizziks, mi? Nem mondhatnám, hogy bízom benne, de ez az információ elég jónak tűnik. Mit meg nem adnék, ha végre megszabadulhatnék a Venture Companytől.$b$bBár tényleg jó gépeket találnak ki... nem tagadhatom, hogy hasznunkra váltak néhány fejlesztésük.' WHERE ID=1094;
UPDATE quest_offer_reward SET RewardText='Kiiktatni Gerenzót? Nos, ez ellen semmi kifogásom.$b$bA gnómok már önmagukban is elég rosszak, de amit Gerenzóról megtudtam, csak rontja a helyzetet. Úgy tűnik, ő volt a Gnomeregan egyik vezető mérnöke, ahol titkos projektjükön dolgozott -- sosem sikerült elég jól beépülnünk Dun Morogh-ba, hogy kiderítsük a részleteket. Kudarcba fulladt. Jelentéseink szerint bármi is volt az, szó szerint a képükbe robbant.' WHERE ID=1095;
UPDATE quest_offer_reward SET RewardText='Nézd csak azt a micsodát... csak egy gnóm találhatott ki ilyesmit. Nem értem, miért vágnál le egy kart, hogy ezzel helyettesítsd, amikor simán megtarthatnád mindkét karod, és hozzátehetnél egy harmadikat is!$b$bGnómok, mondhatom...$b$bLegalább Gerenzo harcképtelen. Remélhetőleg ez elég bizonyíték lesz, és Sputtervalve beoszt engem az egyik Tinkers'' Union műhelybe Gadgetzanban, vagy talán még Undermine-ban is.' WHERE ID=1096;
UPDATE quest_offer_reward SET RewardText='Azért jöttél, hogy segíts a szállítmányommal? Nagyon jó!' WHERE ID=1097;
UPDATE quest_offer_reward SET RewardText='Vincent teste törötten és mozdulatlanul fekszik.$b$bBár Deathstalker Adamant elküldi jelentését Hadrecnek... bármilyen további részletet is szerzett Vincent, azoknak vele kell maradniuk.$b$bDe a kezében egy kis csecsebecsét szorongat...' WHERE ID=1098;
UPDATE quest_offer_reward SET RewardText='Azt mondod, egy halott törpénél találtad ezt a naplót? Adj egy pillanatot, hadd nézzem át az oldalakat...' WHERE ID=1100;
UPDATE quest_offer_reward SET RewardText='A banyát végleg nyugalomra helyezted. Ez fantasztikus hír, $N.$B$BEzekben a veszélyes időkben felüdítő látni valakit, aki olyan bátor, mint te.$B$BMivel Razorflank szolgáival elbántunk, folytathatjuk kutatásainkat a területen. Talán most több tudást szerezhetünk arról, pontosan mi rontotta meg Agamaggan nyughelyét.$B$BAzonban attól tartok, e kérdés válasza szintén árulásban rejlik...' WHERE ID=1101;
UPDATE quest_offer_reward SET RewardText='Látom, a Razorfen Kraul aljas törzse most már ismeri népem fájdalmát. Jól van ez így, azoknak az utálatos fenevadaknak.$b$bValakit elűzni egy szent földről olyan bűn, ami a legszigorúbb bosszút érdemli.$b$bKöszönöm, $N, hogy segítettél a bajomban.' WHERE ID=1102;
UPDATE quest_offer_reward SET RewardText='Ááá, akkó'' kész is vagy...$B$BBeteszem a holmimat a serpenyőbe, oszt beszélhetsz a szellemmel is.$B$BÉs ne is aggódj a szellemvilágba való látás miatt a saptával... az öreg Tiev ismer pár trükköt, hogy hogy'' működik a sapta mágiája.$B$BGyere má'', menjünk le velem a szentélyhez, oszt beszéljünk a szellemekkel együtt, tesó.' WHERE ID=1103;
UPDATE quest_offer_reward SET RewardText='Rendben! Ez a méreg remekül fog működni! Köszönöm, $N!$b$bMost már csak be kell forralnom, hozzáadni a skipper-otomert, egy nega-katalizátort, és... A francba! Hol vannak a jegyzeteim?!' WHERE ID=1104;
UPDATE quest_offer_reward SET RewardText='Megszerezted őket! Köszönöm, $N!$B$BHűha, ezek a páncélok keményebbek, mint gondoltam! Ha ezekkel dolgozom, valószínűleg egy egész doboznyi szerszámra lesz szükségem!' WHERE ID=1105;
UPDATE quest_offer_reward SET RewardText='Fizzle küldött? Nos, ez megváltoztatja a dolgokat! Természetesen segítek. Fizzle és a testvére azon kevesek közé tartoznak, akik nem akarják a halálomat!$b$bSzóval Fizzle dugattyúkat akar csinálni, mi? Olyan erős dugattyúkat, amik kibírják bármilyen igénybevételt, amit tervez, és ha ismerem Fizzle-t, akkor ez az új kocsija egy kerekeken guruló vulkán!' WHERE ID=1106;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N! Miután ezeket összeőrlöm, és összeolvasztom néhány másik hozzávalóval, kész lesz a kompozit anyag. És utána a kocsi biztonságos lesz a saját sebességétől.$b$bBiztonságos, amíg nem ütközik semmivel...' WHERE ID=1107;
UPDATE quest_offer_reward SET RewardText='Á, igen, ezek tökéletesen megfelelnek. Most tegyük őket egy kis hőbe, és lássuk, hogyan bírják...' WHERE ID=1108;
UPDATE quest_offer_reward SET RewardText='Pompás! Pontosan erre a kezdésre volt szükségünk, $N.' WHERE ID=1109;
UPDATE quest_offer_reward SET RewardText='Hűha, nézd csak azt a rakást! Van néhány jó holmi abban a kacathalomban. Biztos vagyok benne, hogy jó pénzért el tudom sózni.$b$bÉs... az ott egy fül, amit két fémlemez közé szorulva látok?? Aú! Heh, biztos nem szeretnék annak a pilótának a helyében lenni!$b$bKöszönöm, $N. Itt a fizetséged. És itt egy jó tanács, ingyen...$b$bHa elég alaposan megnézed, mindig találsz hasznot mások tragédiájában.' WHERE ID=1110;
-- quest_offer_reward.RewardText. Batch 22: quest IDs 1111-1170.

UPDATE quest_offer_reward SET RewardText='Ó igen. Alkatrészek Kravelnek. Örülök, hogy itt vagy. Ezek a dolgok napok óta itt hevernek, és féltem, hogy berozsdásodnak!' WHERE ID=1111;
UPDATE quest_offer_reward SET RewardText='Remek, megszerezted őket! Most el kell juttatnunk a gnómokhoz. De előbb...$b$bVegyünk ki egy apró tárgyat...' WHERE ID=1112;
UPDATE quest_offer_reward SET RewardText='Micsoda bőséges vérfürdőt hoztál nekem, $N! Kiváló munkát végeztél!' WHERE ID=1113;
UPDATE quest_offer_reward SET RewardText='Hát itt vannak! A hidrokulcsaim és ismétlőcsavarjaim! Ezek pont megfelelnek. Köszönöm!' WHERE ID=1114;
UPDATE quest_offer_reward SET RewardText='Nazz Steamboilról akarsz tudni? Ő az a versenypilóta ott kint a Shimmering Flatsen, nem igaz?$b$bIgen, talán kideríthetek róla valamit... de nem lesz könnyű. Sem gyors.$b$bSem olcsó.' WHERE ID=1115;
UPDATE quest_offer_reward SET RewardText='Nocsak, nézd csak. Megtaláltad az álomport!$b$bÉs hogy tetszett a mocsár, $N? Nem könnyű ott meleg ételhez jutni, ugye?' WHERE ID=1116;
UPDATE quest_offer_reward SET RewardText='No nézd csak! Ez érdekes... nagyon érdekes. Heh, talán meg kellene hajolnom a goblin pilóta előtt, ha legközelebb találkozunk.$b$bEz sokat ér, $N. Biztos vagyok benne, hogy Nazz egy kisebb vagyont fizetne, hogy a titka... titok maradjon.' WHERE ID=1117;
UPDATE quest_offer_reward SET RewardText='Értem. Kravelnek nagy terve van. Sötét elme lakozik benne -- ez tetszik bennem.$b$bSzóval valami elmezavaró szerre lesz szükséged, mi? Valami erősre...$b$bVajon fel lehetne-e használni azt a keveréket, amivel Zanzil eteti a zombijait...' WHERE ID=1118;
UPDATE quest_offer_reward SET RewardText='Csodálatos! Fizzlebub kihúzta magát! Ezt megjegyzem, ha legközelebb találkozunk.$b$bÉs köszönöm, $N. Remek munkát végzel, és mindketten sok pénzt kereshetünk ezen...' WHERE ID=1119;
UPDATE quest_offer_reward SET RewardText='Barna sör? Milyen figyelmes! Köszönöm!$b$bNem kellene innunk a közelgő verseny miatt, de... talán a fiúknak jólesne egy kicsi. Amúgy sem lehet olyan erős, nem igaz?' WHERE ID=1120;
UPDATE quest_offer_reward SET RewardText='Mit is látok itt? Piát, mi?$B$BNos, nem bánom, ha iszunk egy kicsit...' WHERE ID=1121;
UPDATE quest_offer_reward SET RewardText='Itt az áll, hogy a Bolond Söre sikeres volt. Ez jó hír!$b$bHa valaha még kellene belőle, szólj, és gyűjtetek veled még Zanzil Keverékéből.' WHERE ID=1122;
UPDATE quest_offer_reward SET RewardText='Rabine Saturna vagyok, és Remulos Őrző, valamint e szent tisztás minden lakója nevében üdvözöllek.$B$BÉrtékelem az érdeklődésedet és lelkesedésedet, hogy segíts a Cenarion Circle-nek. A taurenek hihetetlen fogékonyságot mutattak Cenarius tanításai iránt, és rajtuk keresztül a Horda is szívesen látott vendég e tisztás biztonságában. Azeroth megőrzése közös célunk.$B$BItt barátok között vagy, $N.' WHERE ID=1123;
UPDATE quest_offer_reward SET RewardText='Rabine küldött, igaz? Nos, tekintsd magad üdvözöltnek itt... amennyire ez az elhagyatott, pusztaságba veszett föld egyáltalán üdvözölni tud valakit.$b$bNem éltem még akkor, amikor az itteni nagy megpróbáltatások zajlottak, de a sivatag egyes részei nyugtalanító képei lehetnének annak az elfeledett múltnak. A segítségeddel a Cenarion Circle talán véget vethet egy fenyegetésnek, aminek generációkkal ezelőtt kellett volna elpusztulnia.' WHERE ID=1124;
UPDATE quest_offer_reward SET RewardText='Azt gondoltam, talán a falu romjai közelében lévő hatalmas, örvénylő kaptár szerepet játszott a pusztulásában. Úgy tűnik, a munkád igazolta ezt; a kaptár közelsége veszélyt jelent bármilyen jövőbeli munkára, amit itt végezhetünk.$b$bKöszönöm a jóságodat, amiért megszabadítottad az elesettek lelkeit; tudom, hogy ez sosem könnyű munka. Amikor készen állsz, szeretnék még egyszer segítséget kérni tőled...' WHERE ID=1125;
UPDATE quest_offer_reward SET RewardText='Mi a... mi ez?$b$bOlyan alakja van, mint egy... doboznak, talán? Valami kemény anyaggal van bevonva. Várj csak, itt van egy kitett rész... egy könyv van eme mocsok alatt?$b$bAzt hiszem, egészen nagy leletre bukkantál, $N... nos, legalábbis remélem. Talán egy napló vagy feljegyzés az ősi időkből, ebben a burokban megőrizve.$b$bAzt hiszem, tudok egy módot arra, hogy kiderítsük, mi ez.' WHERE ID=1126;
UPDATE quest_offer_reward SET RewardText='Á, nagyon jó! Itt a fizetséged.$B$BÉs itt egy kis extra is... a diszkréciódért.' WHERE ID=1127;
UPDATE quest_offer_reward SET RewardText='Szóval, $N, eljöttél. Most pedig, felkészültél rá, hogy távoli földeken át utazz?$B$BHa igen, ifjú $c, akkor hallgass tovább...' WHERE ID=1130;
UPDATE quest_offer_reward SET RewardText='Azzal, hogy legyőzted Steelsnapet, megtisztítottad a Thousand Needlest egy szörnyű szennyeződéstől.$b$bÉs ez, $N, a mai leckéd.' WHERE ID=1131;
UPDATE quest_offer_reward SET RewardText='Szép napot! Flint úr küldött Menethil Harborból? Nos, Flint úr kiváló emberismerő. Ha ő küldött, akkor nincs kétség, hogy ide tartozol, Kalimdorba!' WHERE ID=1132;
UPDATE quest_offer_reward SET RewardText='Azért jöttél, hogy szolgálataidat felajánld a Szövetségnek, $N? Örömmel fogadjuk a segítséget, mert bár szépsége megmaradt... Ashenvale Forest már nem az a békés hely, ami egykor volt.' WHERE ID=1133;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Elszomorít, hogy olyan lények lemészárlását kell elrendelnem, akik talán nem is akarva segítik ellenségeinket, mégis kötelességem ezt tenni.$B$BSzíved talán sírhat a levágott büszkeszárnyúak miatt, barátom, de talán meg is dagad örömtől, tudva, hogy szövetségeseid biztonságban vannak a büszkeszárnyúak mérgétől.' WHERE ID=1134;
UPDATE quest_offer_reward SET RewardText='Á, ezek közül a legtöbb szinte szétpattan a méregtől, $N. Ilyeneket általában csak fiatal viverrákból vagy termékeny nőstényekből lehet gyűjteni. Alaposan lemészárolhattad őket ott fent, Highperchen!' WHERE ID=1135;
UPDATE quest_offer_reward SET RewardText='Erőre és ravaszságra egyaránt szükség volt Frostmaw felkutatásához és legyőzéséhez, $N. Neked mindkettő megvan.$b$bUtad elvezetett a Thousand Needles völgyeibe és Alterac magas hegyeibe. Egy napon majd a Földanya minden földjén át fog vezetni, hiszen ez a vadász útja.' WHERE ID=1136;
UPDATE quest_offer_reward SET RewardText='$N, visszatértél! Megtaláltad Marteket? Beszéltél vele? Mit mondott? Tud segíteni??$b$bMondd el, mondd el, mondd el!!' WHERE ID=1137;
UPDATE quest_offer_reward SET RewardText='Hűha, pont ezekre a szép rákdarabokra volt szükségem. Köszönöm, $N! Ezt egy ideje horgászás közben találtam, de nem tudom hasznát venni. Talán te tudsz vele kezdeni valamit. Semmiképp sem lesz belőle jó rákétel.$B$BElmondtam már mindent a rákokról, ugye?' WHERE ID=1138;
UPDATE quest_offer_reward SET RewardText='<Belgrum tanácsos hitetlenkedve rázza a fejét, ahogy átadod neki a kőtöredéket.>$B$B$N, ez elképesztő. Mielőbb elviszem ezt a király mágusaihoz. Tanulmányozni akarják majd, hogy kiderítsék, igazak-e a legendák. De ez egy másik alkalomra tartozó beszélgetés: többet segítettél népünknek, mint valaha is vártam volna -- köszönöm.' WHERE ID=1139;
UPDATE quest_offer_reward SET RewardText='Talán túl sokáig hagytuk, hogy a satyrok megmaradjanak az erdőben. Beszélek erről Elissával, amikor legközelebb Auberdine-ba utazom.$B$BMindazonáltal a lélekkövek elpusztításával Athrikus ereje jelentősen csökken. Ki kell használnunk ezt a lehetőséget, hogy végezzünk vele és kultuszával.' WHERE ID=1140;
UPDATE quest_offer_reward SET RewardText='Azok ám a szép sügérek, $N! Köszönöm, hogy segítettél!$B$BLegalább olyan jó horgász vagy, mint az unokatestvérem, Graun Blump. Neki is van szakálla, és kicsit fura szaga is van, de ez semmit sem gátolja a horgászatban. Úgy vélem, megvan benned, ami kell egy Blump Family horgászbot használatához.' WHERE ID=1141;
UPDATE quest_offer_reward SET RewardText='Nem!$B$BEz nem igazságos. Ó, kegyetlen és elviselhetetlen világ!$B$BMost viselnem kell ezt a gyász terhét, és nem hagyhatom, hogy Heralath munkája vele együtt haljon.$B$BBátor voltál, hogy elutaztál egy ilyen veszélyes helyről, $N. De kérlek, most hagyj magamra.$B$BMagányomban fogok gyászolni.' WHERE ID=1142;
UPDATE quest_offer_reward SET RewardText='Athrikus halálával remélem, hogy a démoni erőket visszaszorítjuk ezen a területen. Nem kétlem, hogy újraszerveződnek és visszatérnek, de akkor még jobban felkészülünk a fenyegetésükre.' WHERE ID=1143;
UPDATE quest_offer_reward SET RewardText='Köszönöm még egyszer, barátom! Mondtam, hogy megéri majd.' WHERE ID=1144;
UPDATE quest_offer_reward SET RewardText='Á, egy üzenet Korrantól. Már jó ideje hűséges szolgám. Épp azon tűnődtem, hogyan haladnak a feladatai a Crossroadsban.' WHERE ID=1145;
UPDATE quest_offer_reward SET RewardText='Ne törődj a hegyek falairól visszaverődő dörgő visszhangokkal. A goblinok és gnómok kint versenyeznek egymással a Flatsen olyan förtelmes szerkezetekkel, amiket ők tudománynak neveznek. Nagyobb fenyegetések is vannak itt, a Thousand Needlesben, az egyikük megölte a harci csapatom több mint felét.$B$BDe itt maradunk, amíg hírt nem kapunk Belgromtól Orgrimmarból. Addig tartjuk a pozíciónkat, és éberek maradunk.' WHERE ID=1146;
UPDATE quest_offer_reward SET RewardText='Ha! Az a nedv, amivel be vagy kenve, tényleg csinosabbá tesz téged, $N! Bár egyben elég bűzössé is tesz. Ne állj túl közel a kodókhoz; vagy pánikba kergeted őket, vagy párzási vágyat gerjesztesz bennük.$B$BAzt hiszem, a társaim is egyetértenének, hogy már önmagában a szagod is bizonyítja, hogy kivetted a részed a rovarlények elleni harcból. Köszönöm, $N.' WHERE ID=1147;
UPDATE quest_offer_reward SET RewardText='Ááá, nemrég láttad Moktart? Mindig vigyáz rám. Sajnálom hallani, hogy a harci csapatja felügyeletével tölti az idejét csata helyett, de biztos vagyok benne, hogy nagy örömét leli az Explorers'' League tagjainak megölésében.$b$bOkosan tetted, hogy elhoztad nekem ezeket a mintákat, $N. A Field of Giantsban talált tojásokkal együtt ezek jó kezdést adnak ahhoz, hogy kiderítsem, mik ezek a rovarok, és mit akarnak.' WHERE ID=1148;
UPDATE quest_offer_reward SET RewardText='Csak akkor kezdjük megérteni, mennyire erős a lelkünk, amikor váratlan megpróbáltatással nézünk szembe. Bátran ugrottál a bizonytalanba, még ha nem is volt garancia a túlélésedre. Elméd nyitott, és lelked felkészült arra, ami jönni fog.$b$bHa hajlandó vagy rá, akkor készen áll a következő próbád.' WHERE ID=1149;
UPDATE quest_offer_reward SET RewardText='Grenka hatalmas volt, még trollmércével mérve is. Büszkének kell lenned a mai teljesítményedre.$b$bA hit próbáján lelki erőt mutattál, most pedig kitartást mutattál a csatában, amikor szembeszálltál a Roguefeather hárpiákkal, de eljött az idő egy új próbára.' WHERE ID=1150;
UPDATE quest_offer_reward SET RewardText='Az Erő Próbája véget ért. Erőt és bátorságot mutattál, és most felkészültél az utolsó próbára, mielőtt ezek a szertartások befejeződnek.' WHERE ID=1151;
UPDATE quest_offer_reward SET RewardText='A napok és éjszakák egyre hidegebbek szerte a világban, ahogy a goblinok kifosztják a földet, és az éjszakai tündék az ifjabb fajokra mutogatnak. Nem csak a Forsaken és az orkok hibáztathatók a Kalimdor és Lordaeron szerte tapasztalható nehézségekért. Számos értelmes faj hozzájárult a világ fájdalmához. Dorn ezt tudja, és azért küldött hozzám, mert megmutattad a szükséges tulajdonságokat ahhoz, hogy te is felismerd ezt.$b$bMost Braug előtt állsz.' WHERE ID=1152;
UPDATE quest_offer_reward SET RewardText='Jó minta, $N. Bizony, jó minta.$B$BAzok az utazók már nem henceghetnek nekem az általuk talált érccel, most hogy sikerrel jártál.$B$BAzonnal munkához látok vele. Ha elég erősnek bizonyul, egy belőle készített fegyvert küldök vissza a hadvezérnek, hogy megmutassam neki sikerünket.$B$BNem felejtem el a segítséged, $c.' WHERE ID=1153;
UPDATE quest_offer_reward SET RewardText='Ez az a könyv, amit megneveztem. Van remény, hogy helyesen válaszolsz majd a kérdésemre... hacsak nem felejtetted el tanulmányozni a tartalmát.$b$bAmikor felkészültél, szólj hozzám ismét, és felteszek neked egy kérdést.' WHERE ID=1154;
UPDATE quest_offer_reward SET RewardText='Braug küldött? Lehetetlen.$b$b<Parqual tetőtől talpig végigmér téged.>$b$bSzembeszálltál Dor''Danillal, ugrottál a bizonytalanba, harcoltál és legyőztél egy hatalmas elementált? Pfú! Valószínűleg csak szélhámos vagy; valami kalandozó, aki fültanúja volt egy kocsmai beszélgetésnek. És most azt hiszed, megvan benned, ami kell a próbám teljesítéséhez. Legyen hát... $c.' WHERE ID=1159;
UPDATE quest_offer_reward SET RewardText='Ez az a könyv, amit keresni küldtelek.$b$b<Parqual lassan végigsimítja kezét a könyv tetején, miközben lenéz rá.>$b$bSzóval most egy kérdést szeretnél, hogy bebizonyítsd, elméd olyan hatalmas, mint tested és lelked. Ha elég sokáig tanulmányoztad a könyvet, felteszem a kérdésemet, és végezhetsz ezekkel a próbákkal!' WHERE ID=1160;
UPDATE quest_offer_reward SET RewardText='A bosszú alakjaként állsz előttem, és hálával hajolok meg előtted.$B$BAzzal a tehénnel a halálával, és tudva, hogy magjuk többé nem terjed szét Azeroth arcán, energiámat valami jövedelmezőbb dologba fektethetem. Remélem, kifosztottad a farmjukat, miután végeztél velük.' WHERE ID=1164;
UPDATE quest_offer_reward SET RewardText='Te jó $r. Nekem hiányzik sok minden. Most kedvellek téged.' WHERE ID=1166;
UPDATE quest_offer_reward SET RewardText='Á, jó újra látni téged, $N! A legfurcsább dolgok történnek errefelé, örülök, hogy felbukkantál!$B$BNagyon furcsa volt, $N. Minden normálisnak tűnt -- nos, amennyire itt normálisak lehetnek a dolgok --, aztán hirtelen vakító fényvillanás áradt a torony felső szobájából. Aztán jöttek a sikolyok. A kiáltások hasították a levegőt, és időnként villámok csaptak a földbe. Mi folyik itt?' WHERE ID=1167;
UPDATE quest_offer_reward SET RewardText='Te ölsz sok fekete sárkány hadseregéből. Te bátor $r.$b$bTharg boldog lesz.' WHERE ID=1168;
UPDATE quest_offer_reward SET RewardText='Kétségtelenül veszélyes vállalkozás volt összegyűjteni ezeket a szíveket és nyelveket. Belemerülök a mágia mélységeibe, hogy felderítsem annak a fekete fenyegetésnek az eredetét, amely egykori otthonunkra szállt.' WHERE ID=1169;
UPDATE quest_offer_reward SET RewardText='Miért mesélsz nekem sárkányokról? Nekem nem tetszik a sárkány. Nekem itt tetszik. Itt nincsenek sárkányok.' WHERE ID=1170;
-- quest_offer_reward.RewardText. Batch 23: quest IDs 1171-1247.

UPDATE quest_offer_reward SET RewardText='Az a lusta gyáva!$b$bMok''Morokk erőt mutatott, amikor Rexxar volt a vezetőnk. De Rexxar távozása után Mok''Morokk hamar a hatalom csábításának áldozatává vált. Vezetés helyett követelőzött. Nem szolgálja a népét, hanem elvárja, hogy mi szolgáljuk őt.$b$bTenni kell valamit.' WHERE ID=1171;
UPDATE quest_offer_reward SET RewardText='Pompás! Eltart majd egy ideig, mire Onyxia újra tojásokat tud létrehozni.$b$bNépem nevében köszönöm neked, $N.$b$bEddig sok mindent kértem tőled. Talán megtehetnéd a Stonemaul Klánnak ezt az utolsó szolgálatot.$b$bMok''Morokk nem alkalmas arra, hogy vezessen minket. Tharg kiváló vezető lenne, de sérülései és kora hátráltatják. Űzd el Mok''Morokkot innen erővel. Csak akkor nevezhetünk ki új vezetőt, hogy visszatérjünk jogos otthonunkba, délre.' WHERE ID=1172;
UPDATE quest_offer_reward SET RewardText='Az a gyáva, kövér tömeg, Mok''Morokk úgy menekült el, mint egy megrémült gyerek. Nagy szolgálatot tettél, $N.$B$BMost népem új vezetőt nevezhet ki, olyat, aki segít visszaszerezni régi otthonunkat egyszer s mindenkorra.' WHERE ID=1173;
UPDATE quest_offer_reward SET RewardText='Remélem, egyetlen baziliszkuszt sem öltél meg magukon a síneken! Sokáig tart, mire a tetemek elbomlanak a napon, és nem szeretnék lapáttal takarítani utánuk.' WHERE ID=1175;
UPDATE quest_offer_reward SET RewardText='Remek! Máris munkára foghatom a legénységet. Köszönöm, $N!' WHERE ID=1176;
UPDATE quest_offer_reward SET RewardText='Nekem tetszik halfej!$B$BÉn most nem eszlek meg téged.' WHERE ID=1177;
UPDATE quest_offer_reward SET RewardText='Pozzik küldött, mi? Tudod, Pozzik az egyik legelismertebb szerelő volt Undermine-ban, mielőtt visszavonult, hogy a versenyautókkal foglalkozzon.$b$bAz első dolog, amit a csapathoz csatlakozva tett, hogy kifejlesztette a kétmotoros versenyautó-modellt. Lehet, hogy az üzlet megsínyli, hogy már nem dolgozik a Tinkers'' Unionnal, de kit érdekel, igaz? Semmi sem fogható a versenyekhez!' WHERE ID=1178;
UPDATE quest_offer_reward SET RewardText='Á! Longbeard küldött egy rakomány sisakkal! Hurrá!$B$BMost talán rá tudunk beszélni egy pilótát, hogy vezesse a kocsinkat...' WHERE ID=1179;
UPDATE quest_offer_reward SET RewardText='Szállítmányok Ratchetbe? Hadd nézzem meg a naplókat...$b$bNem, a legutóbbi feljegyzett szállítmány, ami Ratchetbe ment, Drizzlik csizmái voltak. Nem sok más volt, csak építőanyagok és szerszámok. Semmiképp sem versenyalkatrészek.' WHERE ID=1180;
UPDATE quest_offer_reward SET RewardText='Ó, persze, hogyne, tudom, miről beszélsz. Nem, viszont nem tudok segíteni. Néhány emberemnek ki kellett volna derítenie az üzemanyag-szabályozó tervrajzait, de üres kézzel tértek vissza.' WHERE ID=1181;
UPDATE quest_offer_reward SET RewardText='Most pedig hadd készítsek másolatot ezekről a tervrajzokról a saját jegyzeteimhez, te pedig egyenesen elviheted őket Pozziknak. Nem szeretném, ha azt hinné, hogy az egyik támogatója cserben hagyja.' WHERE ID=1182;
UPDATE quest_offer_reward SET RewardText='Reméltem, hogy már össze lesz szerelve, de ez egyedülálló lehetőséget ad arra, hogy a tervet a semmiből javítsam. Köszönöm, $N. Hamarosan tudok majd fejlettebb terveket vázolni, megépíteni a szerkezetet, és beszerelni.' WHERE ID=1183;
UPDATE quest_offer_reward SET RewardText='Értékelem az erőfeszítéseidet, $c. A hadvezér örömmel hallja majd, milyen kitartóan végezted a feladataidat.$B$BÓ, természetesen megemlítem neki a nevedet. Gyakran beszél velem, és nagyra értékeli a véleményemet.$B$BMenj most, sok dolgom van. És ha hamarosan beszélsz Korrannal, és van híre ezekről a lényekről, gyere vissza hozzám -- úgy vélem, komolyan veendő fenyegetést jelentenek.' WHERE ID=1184;
UPDATE quest_offer_reward SET RewardText='Hé, megint te vagy az! Nos, úgy értem, te - vagyis te, aki $N vagy! Igen - te!$B$BHé, hadd kezdjem újra!$B$BAz a tárgy, amit Silithusban találtál - valójában egy könyv volt. Egy napló, egy nagyon ősi nyelvjárásban írva, amit ma Darnassiannak hívunk. Eltart majd egy ideig, de alaposan átnézem majd. Gondoltam, tudnod kell, hogy amit találtál, rendkívül értékes a Circle számára.$B$BA den mother teljesen izgatott miatta!' WHERE ID=1185;
UPDATE quest_offer_reward SET RewardText='Te vagy az a $R, aki Pozziknak segít, igaz? Egyszer én is olyan voltam, mint te, a bokszban futkostam, és bármiben segítettem, amit a szerelők hagytak.$b$bMost pedig nézz rám! A goblin versenycsapat rendkívüli pilótája!' WHERE ID=1186;
UPDATE quest_offer_reward SET RewardText='Csak nézd meg ezt a szépséget! Tizenöt font tiszta seaforium erő! Amint ezt a versenyautóm oldalára erősítem, olyan gyorsan száguldok majd körbe a pályán, hogy kétszer is megelőzöm a gnómokat!' WHERE ID=1187;
UPDATE quest_offer_reward SET RewardText='Csak Razzeric nézne rá erre, és mondaná azt, hogy valahogy biztonsági zárat tettem rá. Ez a rakéta majdnem teljesen seaforium robbanóanyagból áll. Már módosítottam is, hogy nagyobb hatóanyagot adjon le használatkor, de Razzeric sosem elégedett, hacsak nem viszi túlzásba!' WHERE ID=1188;
UPDATE quest_offer_reward SET RewardText='Na, ez már inkább az! Bárcsak láthatnám a gnómok arcát, amikor meglátják, ahogy elsütöm ezt a kis szépséget.$b$bKár, hogy túl elfoglalt leszek egy új pályacsúcs megdöntésével!' WHERE ID=1189;
UPDATE quest_offer_reward SET RewardText='Sietős, kapkodó kézírással firkált tekercs, jegyzetekkel és tervekkel valamilyen nyersanyag finomításához.' WHERE ID=1190;
UPDATE quest_offer_reward SET RewardText='Induljunk!' WHERE ID=1191;
UPDATE quest_offer_reward SET RewardText='Kiváló! Máris munkára fogom a legénységet azokon az alkatrészeken, amikre a következő versenyhez szükségünk lesz.' WHERE ID=1192;
UPDATE quest_offer_reward SET RewardText='A thoriumszerkezet könnyedén a helyére csúszik, csatornát létrehozva a fagyolaj beöntéséhez. Amint az olaj utolsó cseppjei is beleürülnek, a csapda a helyére pattan.$B$BJaj annak a gyanútlan ogrénak, aki épp arra kószál!' WHERE ID=1193;
UPDATE quest_offer_reward SET RewardText='Indurium? Érdekes... Ha valóban annyira ellenáll a hőnek, ahogy mondod, az megmagyarázná a gnómok teljesítménynövekedését az utóbbi időben.$B$BEz a minta, amit hoztál, felbecsülhetetlen lesz. Tudok majd rajta néhány tesztet végezni, de többre lesz szükségem ahhoz, hogy ez tényleg hasznunkra váljon.' WHERE ID=1194;
UPDATE quest_offer_reward SET RewardText='Nagyon jó. Ez tökéletesen teljesíti Rau kérését. El tudnád vinni neki? Talán élvezni fogod, ha egy kis időt töltesz kint a Needlesben.' WHERE ID=1195;
UPDATE quest_offer_reward SET RewardText='Hm, igen, ez a fiola víz tökéletesen megfelel a céljainknak. A driádok és a kentaurok közös eredete miatt a holdkutak vize lehetővé teszi majd, hogy áttörjük a kentaur ereklyét körülvevő örökláng védelmét.' WHERE ID=1196;
UPDATE quest_offer_reward SET RewardText='Furcsa energiát érzek a Pata felől áradni... Nem kétlem, hogy meglepő új információkat fedezünk fel a kentaurokról a tanulmányozása során.$B$BKöszönöm, $N. Most pedig hozzá kell látnom, hogy megfejtsem a rejtélyeket, amiket hoztál nekem.' WHERE ID=1197;
UPDATE quest_offer_reward SET RewardText='Dawnwatcher Shaedlass jól tette, hogy elküldött téged. Valóban gonosz cselszövés zajlik ezen a megrontott helyen.' WHERE ID=1198;
UPDATE quest_offer_reward SET RewardText='Kétségtelenül bátor és nemes vér folyik ereidben, $N. Az Argent Dawn dicséretben részesít a gonosz elleni erőfeszítéseidért.' WHERE ID=1199;
UPDATE quest_offer_reward SET RewardText='Kelris egészen sokáig elkerült minket.$B$BÚgy tűnik, valahányszor a gonosz megmutatta jelenlétét ezen a vidéken, Kelrisnek szerepe volt benne. Egy ideig halottnak vagy eltűntnek hittük.$B$BDe ez most már tökéletesen érthető. Uralmának véget vetve sok ártatlan ember életét mentetted meg.$B$BA Fényre! Valakit feláldozni egy Ősi Isten szolgájának személyes haszonszerzésért minden szónál gyalázatosabb!$B$BNagy tettet vittél véghez, $N. Tisztelgek előtted az Argent Dawn nevében.' WHERE ID=1200;
UPDATE quest_offer_reward SET RewardText='Jó munka. A beépített ügynökeik ügyesek, de nem elég jók ahhoz, hogy elkerüljék a Horda éber tekintetét!' WHERE ID=1201;
UPDATE quest_offer_reward SET RewardText='Elismerésem, $N. Ez nem volt könnyű küldetés. De a megszerzett dokumentumokat feletteseink nagyra értékelik.' WHERE ID=1202;
UPDATE quest_offer_reward SET RewardText='Ez egy jó penge. Jól lendül. Egy jó lendülő penge. Köszönöm. Köszönöm, köszönöm, köszönöm!!! Most ki akarom próbálni...$B$BKésőbb. Majd később kipróbálom. De ahogy mondtam... köszönöm.' WHERE ID=1203;
UPDATE quest_offer_reward SET RewardText='Ezek pont megfelelnek! Köszönöm, $N!$B$BMost különböző főzési technikákat próbálok ki ezeken a nyelveken, hogy megtaláljam a legjobb módot az ízük kihozatalára.$B$BVégül olyan ételem lesz, amit méltó felszolgálni a Blue Recluse-ban, Stormwindben!' WHERE ID=1204;
UPDATE quest_offer_reward SET RewardText='Nagyon jó, $N.$b$bBiztos vagyok benne, hogy a vadászat nem volt könnyű, de jó tudni, hogy a fenevad szenvedése végre véget ért.' WHERE ID=1205;
UPDATE quest_offer_reward SET RewardText='Megszerezted a szemeket! Megszerezted a szemeket! Ízletes, ízletes pókszemek!$B$BNéhány szem... ha rájuk bámulsz, ők is visszabámulnak. Azokat edd meg utoljára. Társaságot tartanak neked... kint a mocsárban.$B$BSzia, kis pókszem. Szia! Olyan íze van, mint a csirkének. Nyálkás, sós csirke!$B$BMmmh.' WHERE ID=1206;
UPDATE quest_offer_reward SET RewardText='Á, ez az a fűszer! Most pedig itt egy jó kis mocsári ragu.' WHERE ID=1218;
UPDATE quest_offer_reward SET RewardText='Hm... nem tudok túl jól olvasni orkul, de ez jelentésnek tűnik... amit egy ork kém írt!' WHERE ID=1219;
UPDATE quest_offer_reward SET RewardText='Egy jelentés egy ork kémtől! Hogy találtad ezt meg? Nem számít -- lássuk, mi áll benne...' WHERE ID=1220;
UPDATE quest_offer_reward SET RewardText='Remek, megszerezted őket! Jó pénzért el tudom adni ezeket a kapcsolataimnak!$B$BKöszönöm a szállítást, $N! Remek partner vagy.' WHERE ID=1221;
UPDATE quest_offer_reward SET RewardText='Mr. Ignatz éppen most volt itt a mocsárbab levelekkel, és elmondta, hogy komoly bajból segítettél ki neki.$B$BKöszönöm, $N. Megkérem a nagybátyámat, hogy hívjon meg egy lakomára, amikor legközelebb ellátogatsz a Blue Recluse-ba, Stormwindbe.' WHERE ID=1222;
UPDATE quest_offer_reward SET RewardText='Jó munka, $N. Ügynökünk, Marg Nighteye, Theramore-on kívül állomásozott. Az volt a feladata, hogy kémkedjen a város után.$b$bEz a legutóbbi jelentése, és lehet, hogy ez lesz az utolsó is -- a beszámolód alapján attól tartok, Marg a mocsárban lelte halálát...' WHERE ID=1238;
UPDATE quest_offer_reward SET RewardText='Ez Marg Nighteye feje! Ahogy féltem, halott.$b$bNézd csak a sebet a nyakán! Vajon egy fegyver okozta ezt a szaggatott vágást, vagy valami fenevad ölte meg ügynökünket?$b$bEz egy rejtély, amit meg kell fejtenünk, $N. Ki kell derítenünk, hogy Marg halálát a Szövetség keze okozta-e!' WHERE ID=1239;
UPDATE quest_offer_reward SET RewardText='Á, most már látom. Ennek az orknak a szelleme e világhoz van kötve, dühtől forrva egy be nem fejezett feladat miatt.$b$bNos, váltsunk pár szót ezzel a dühös orkkal...' WHERE ID=1240;
UPDATE quest_offer_reward SET RewardText='Hmm... <Jorgen összehúzott szemmel néz fel rád.>$b$bRendben. Segítek neked, de nem azért, mert akarom, hanem mert kötelességem.$b$bÉs tisztázzunk valamit: te máris sokkal többet tudsz, mint kellene. Tartsuk meg ezt kettőnk közt titokban, és ne fecsegj semmilyen kocsmában arról, amit megtudsz. Érted?' WHERE ID=1241;
UPDATE quest_offer_reward SET RewardText='Elnézést, egy levél nekem? Nos, hogy a csudába... nem gyakran kapok olyan szállítmányt, ami nem láda vagy hordó, amikor csak dolgozom. Lássuk, miről van szó.$B$B<Elling rád néz, miközben felbontja a levelet.>$B$BKicsit feszültnek tűnsz, jól vagy, $N?' WHERE ID=1242;
UPDATE quest_offer_reward SET RewardText='Ó, Trias küldött, mi? Ez egy kicsit más.$B$BNyugodtan harcolj meg bármilyen szörnyűséggel, ami a sötétségből előjön. Biztos vagyok benne, hogy elég könnyen elbánsz vele, ha olyan típus vagy, aki hozzá hasonlókkal barátkozik.$B$BSzóval, mire van szüksége tőlem a barátomnak egy ilyen komor napon?' WHERE ID=1243;
UPDATE quest_offer_reward SET RewardText='Épségben visszatértél. Ennél többet nem is kívánhatnál, igaz?$B$BMost pedig lássuk, mi van itt. Ez elég hivatalosnak tűnik a Defias dokumentumok között, amiket eddig láttam. De lehet, hogy csak egy csali, hogy eltereljen arról, amit valójában keresel.' WHERE ID=1244;
UPDATE quest_offer_reward SET RewardText='Igen... ez érdekes olvasmány. Jorgen és DeLavey okosan tette, hogy bevontak ebbe engem.$B$BÚgy tűnik, a Defias keményen próbálkozik befejezni ezt a tervüket. Hmm... ez meg mi? Fist? Ismerős név.' WHERE ID=1245;
UPDATE quest_offer_reward SET RewardText='Mi?!$B$BBejössz az én sikátoromba, és kérdéseket teszel fel a személyes ügyeimről? Olyan ügyekről, amikhez nyilvánvalóan semmi közöd.' WHERE ID=1246;
UPDATE quest_offer_reward SET RewardText='Jó látni, hogy még életben vagy, $N. Szóval, jól sikerült a dolog Dashellel, mi?$B$BTovább olvastam a tervükről, és bár nem szerepel benne annak a diplomatának a neve, akire vadásztak, arról igen szó esik, hogy egy B tervet hajtottak végre, miután az első próbálkozásuk, hogy elfogják, kudarcba fulladt.$B$BEz a Slim, akit Dashel említett, nincs más néven feltüntetve itt, de ha azt mondod, Menethilben van, az már egy kezdet.' WHERE ID=1247;
-- quest_offer_reward.RewardText. Batch 24: quest IDs 1248-1369.

UPDATE quest_offer_reward SET RewardText='Üdvözöllek, üdvözöllek, üdvözöllek, $N. Örülök, hogy csatlakozol hozzánk. Talán egy sört ma? Vagy egy kis birkahúst?$B$BMondd meg, mire vágysz, és gondoskodom róla, hogy elégedett légy. Mikhail vagyok, és örömmel szolgállak ki.$B$BHm? Mi az? Trias? Halkabban, barátom. Ez nem olyasmi, amit az egész kocsmának hallania kell.' WHERE ID=1248;
UPDATE quest_offer_reward SET RewardText='Elkaptad, mi? Szép munka. Meglep, hogy ő volt Slim.$B$BŐszintén szólva sosem gondoltam volna, hogy hiányozni fog néhány alattomosabb földalatti tevékenység izgalma. Gondolom, a régi szokások nehezen halnak. Ne mondd el Ellingnek -- valószínűleg megpróbálna rávenni, hogy térjek vissza Stormwindbe, ha meghallaná, hogy hiányzik nekem az akció.$B$BÖrülök, hogy legalább egy kicsit szolgálatodra lehettem, amíg Menethilben voltál. Ha bármi másra szükséged van, csak szólj.' WHERE ID=1249;
UPDATE quest_offer_reward SET RewardText='A KIRÁLY?! Vagyis... a király? A valódi király? Csak viccelsz? Nem is említetted, hogy a király elrablóit keresed. Azt sem hallottam, hogy eltűnt volna -- ez megmagyarázná, miért koronázták meg a fiát.$B$BAzonnal üzenek Ellingnek. Tudni akarja majd, hogy a nyomon vagy.$B$BSosem gondoltam volna, hogy Jahn eladja Stormwindet valami nyomorult pénzért. Még egy csirkefogónak is kell legyen becsülete bizonyos dolgokban.$B$BMost az a kulcs, hogy megtaláljuk ezt a Hendelt. És azt hiszem, ebben tudok segíteni.' WHERE ID=1250;
UPDATE quest_offer_reward SET RewardText='Elismerem, hogy az embereknek furcsa dekorációs ízlésük van, de vajon egy egyszerű vaspajzzsal díszítenék a kandallójukat? Talán azok tették oda ezt a pajzsot, akik felgyújtották a fogadót.$b$bEgy figyelmeztetés? Egy fenyegetés?' WHERE ID=1251;
UPDATE quest_offer_reward SET RewardText='Sosem jó hír, amikor egy őrjelvényt hoznak elém.$b$bNéha egy elesett férfi vagy nő az, és nekem kell a hírt a gyászoló családhoz vinnem. Máskor sosem tudjuk meg, mi történt velük. És néha még ennél is rosszabb a helyzet.' WHERE ID=1252;
UPDATE quest_offer_reward SET RewardText='Hm, nem vagyok szakértője a fegyverek és páncélok készítésének. Használatuknak igen, de készítésüknek nem.$b$bEz a pajzs teljesen hétköznapinak tűnik, leszámítva a fogadót elnyelő tűz okozta károkat.' WHERE ID=1253;
UPDATE quest_offer_reward SET RewardText='Ezek csodálatos példányok, $N! A páncélok tökéletes állapotban vannak, a hús pedig rózsaszín és omlós. Biztos vagyok benne, hogy szakácsvér folyik az ereidben!' WHERE ID=1258;
UPDATE quest_offer_reward SET RewardText='Üdv, $N. Információt szeretnél a Theramore-i őrség egy konkrét tagjáról? Reethe volt az?$b$bAdj egy pillanatot, hadd találjam meg a megfelelő könyvet.' WHERE ID=1259;
UPDATE quest_offer_reward SET RewardText='Ó, a nagybátyám küldött, igaz?$b$bNos, recepteket kutattam, és van néhány nyomom, de segítségre van szükségem.$b$bOlyasvalaki segítségére, aki hajlandó vizes lábbal is dolgozni.' WHERE ID=1260;
UPDATE quest_offer_reward SET RewardText='Ezt a medált egy stormwindi katona viselte??$B$BKöszönöm, $N. Feltártad Marg halálának titkát. De ez a medál egy új rejtély, amit meg kell fejteni, és amely súlyos hatással lehet a Szövetségre és a Hordára is.' WHERE ID=1261;
UPDATE quest_offer_reward SET RewardText='Ezt a medált nagy ügyességgel és precizitással készítették, $N. Egyetlen ork sem áhítozna ilyen ékszerre...$B$BDe sok ember igen.$B$BMegvizsgáltatom ezt a medált. Remélhetőleg idővel feltárulnak előttünk a rejtélyei.' WHERE ID=1262;
UPDATE quest_offer_reward SET RewardText='Örülök, hogy megismerhetlek, $N. Samaul parancsnok vagyok. Én vezetem Miss Proudmoore erőit itt, Theramore-ban.$B$BBár elég elfoglalt vagyok, ha bármi kérdésed van, nyugodtan tedd fel. Lehet, hogy röviden kell válaszolnom, de semmi okom udvariatlannak lenni, ha segítségre van szükséged.$B$BHa a városon kívülre tervezel utazni, azt tanácsolom, légy óvatos. Ogrék, orkok és murlocok mellett a mocsár déli része tele van fekete sárkányokkal.' WHERE ID=1264;
UPDATE quest_offer_reward SET RewardText='A férfi, akit keresel, a Hendel néven ismert, nincs itt. Más források olyan információt juttattak el Lady Proudmoore-hoz, amit szerintem már ismersz. Megkért, hogy találjalak meg, és segítsek a vállalkozásodban. Ha megengeded, elmondom, hol találod meg Hendel közlegényt, hogy igazságot szolgáltathassunk.' WHERE ID=1265;
UPDATE quest_offer_reward SET RewardText='Üdv, polgár. Veszélyes hely ez a kóborlásra. Nem maradnék itt sokáig, ha kedves az életed.$B$BHa röviden fogalmazod meg a kérdéseidet, megnézem, tudok-e segíteni. Csak tartsd nyitva a szemed azokra a mocskos ogrékra. A pletyka szerint van egy Horda-bázis valahol a mocsarakban. A beépített ügynökök mindent megtesznek, hogy megtalálják, de a folyamat lassan halad, és kevés eredményt értünk el.' WHERE ID=1266;
UPDATE quest_offer_reward SET RewardText='Hadd legyek én az első, aki köszönetet mond mindazért, amit tettél, $N. Hihetetlen áldás voltál a népemnek és Stormwind népének. Sajnálom, hogy nem jobb körülmények között ismerhettelek meg.$b$bMegértem azt is, hogy nem köszönhetem meg nyíltan az erőfeszítéseidet, de biztosítalak, hogy nagyra értékelem.$b$bHa a jövőben ellátogatsz Theramore-ba, keress meg, és igyekszem majd tájékoztatni a helyzetről.$b$bKöszönöm még egyszer, $N.' WHERE ID=1267;
UPDATE quest_offer_reward SET RewardText='Patanyomok... Gondolom, lehettek a quilboarok is. Vagy talán a kentaurok. A jelenlétük a Barrensben nem elhanyagolható, és nem tartanám elképzelhetetlennek, hogy ilyen tettet kövessenek el.$b$bMondtam már? Nem csak arról volt szó, hogy a fogadót felégették... A tulajdonos asszonyát és kölykét is megölték. Csúnya ügy, az.$b$bMindazonáltal elküldöm Kagorot, hogy kiderítse, hova vezetnek a nyomok.' WHERE ID=1268;
UPDATE quest_offer_reward SET RewardText='Ismerem ezt az embert, Paval Reethét. Szánalmas, még a fajtájához képest is. Elhagyta bajtársait, és most az erdőben bujkál.$b$bElküldtem Ogront, hogy felkutassa. Néhányan gyanítják, hogy lopott a készleteinkből. Azt hiszem, láttam Ogront délkelet felé indulni.' WHERE ID=1269;
UPDATE quest_offer_reward SET RewardText='Stinky itt volt a füvekkel, amiket kértem tőle, és elmondta, hogy kisegítetted egy szorult helyzetből. Szép munka! Stinky barátja az én barátom is!$B$BMegkért, hogy adjam ezt neked, ha valaha látlak, mielőtt visszaindult délre, a mocsár felé.' WHERE ID=1270;
UPDATE quest_offer_reward SET RewardText='Az unokaöcsém elmondta, hogy segítettél neki a Dustwallow-i kutatásában, és hogy kihúztad a társát egy szoros helyzetből. Nos, mi Sternek összetartunk, és nem hagyjuk figyelmen kívül a barátainkat!$B$BSzóval mosd meg a kezed, $N, mert épp egy tiszteletedre rendezett ünnepséget készülünk tartani!' WHERE ID=1271;
UPDATE quest_offer_reward SET RewardText='Hm. Jó, hogy Reethe többé nem ólálkodik a mocsárban, de kár, hogy az emberek olyan törékenyek, hogy egy kis nyílvesszősebből sem tudott felépülni.$b$bÚgy tűnik, ez a nyom sehova sem vezetett, és máshol kell keresnünk.' WHERE ID=1273;
UPDATE quest_offer_reward SET RewardText='Üdv, $N. DeLavey püspök vagyok.$B$BKétségtelenül, ha az itteni váras ügyeimről kérdezel, akkor az ifjú Thomasnak sikerült rávennie téged, hogy segíts királyságunknak. Mindig is ügyesen teljesítette a kéréseimet.$B$BAttól tartok, nincs időm sokat részletezni, úgyhogy hadd legyek egyenes... és kérlek, próbáld meg titokban tartani.' WHERE ID=1274;
UPDATE quest_offer_reward SET RewardText='Messziről jöttél, és kétségtelenül nagy veszélyekkel néztél szembe.$B$BTetteid önzetlenek voltak. Egész Azeroth javát szolgálja, hogy segítesz a kutatásomban. Köszönöm, $N, mindazt, amit tettél.$B$BMost pedig, ha megbocsátasz, sok dolgom van még...' WHERE ID=1275;
UPDATE quest_offer_reward SET RewardText='Igen, teljesen igazad van. Ezt a pajzsot én készítettem.$b$bAttól tartok, ennél többet nem tudok mondani, $N. Annyiféle pajzsot és páncélkészletet kovácsolok, hogy nem tudom mindet nyomon követni.' WHERE ID=1276;
UPDATE quest_offer_reward SET RewardText='James Hyal az igazi neve. Fogadót nyitott a Barrens szélén. Egy szép helyet akart teremteni, ahol az utazók megpihenhetnek...$B$BLehet, hogy túl nagyra tervezett, de a fogadó egy ideig jól ment. Aztán elvesztettük az uralmat az utak felett a mocsárban, és az ogrék átvették a hatalmat.$B$BJames túl makacs volt ahhoz, hogy feladja álmát a falaink közti biztonságért, és a Shady Rest Inn porig égett. Nyomozunk, de nem sok szerencsével. Ha segíteni akarsz, nézd meg, mit találsz a romok között.' WHERE ID=1282;
UPDATE quest_offer_reward SET RewardText='Patanyomok, mi? Igaz, hogy rendkívüli mennyiségű kentaur-tevékenység zajlik a Dustwallow Marsh közeli földeken. Rövid Barrens-i kirándulásaink során a táboraikat és birtokaikat láttuk szétszórva a területen.$b$bElküldöm Falgran Hastilt, az egyik nyomkövetőnket, hogy kiderítse, hova vezetnek a nyomok.' WHERE ID=1284;
UPDATE quest_offer_reward SET RewardText='Eltűnt? Ez Tesoran finomkodó módja annak, hogy azt mondja: áruló.$b$bKétségtelenül egyike azoknak a bolondoknak, akik olyan vakon hűségesek Daelin admirálishoz, hogy árulóvá váltak. Nem ízléses irónia ez? A dezertőrök minket vádolnak a Szövetség elárulásával.' WHERE ID=1285;
UPDATE quest_offer_reward SET RewardText='Vimes küldött? Nem tudta maga elvégezni a piszkos munkát, mi...' WHERE ID=1286;
UPDATE quest_offer_reward SET RewardText='Elküldöm Caldwell hadnagyot, hogy elbánjon a Lost Point-i dezertőrökkel. Emellett utasítom, hogy találja meg Reethét is. A mocsár nem olyan nagy és úttalan, hogy ne tudná megtalálni.' WHERE ID=1287;
UPDATE quest_offer_reward SET RewardText='James? Ó, ő jó ideje elment már.$B$BGondolom, a hazafiság új lendületet kapott benne. Nem is nehéz megérteni, miért. Az összes lordaeroni őrültséggel sokan csatlakoztak Jaina Proudmoore-hoz, amikor átkelt a tengeren.' WHERE ID=1301;
UPDATE quest_offer_reward SET RewardText='James Hyal, James Hyal... Miért olyan ismerős ez a név?$b$bHát persze! A Shady Rest Inn incidens. Ha bármilyen információd van arról, mi történt ott, javaslom, beszélj Vimes kapitánnyal. Ő vezeti a nyomozást.' WHERE ID=1302;
UPDATE quest_offer_reward SET RewardText='Hm... érdekes vasdarab, amit itt hoztál. Egészen biztosan nem a tenger ezen oldalán ismert kovácsok egyike készítette, és biztosan nem az én munkám.' WHERE ID=1319;
UPDATE quest_offer_reward SET RewardText='Nem sok információ ez, amivel dolgozni lehet, de észben kell tartanunk. Remélhetőleg a rejtély többi darabja is a helyére kerül, és világosabb képet fest arról, mi történt.' WHERE ID=1320;
UPDATE quest_offer_reward SET RewardText='Ez jó pajzs. Nagyon erős, nehéz, jó. De Do''gol nem kell neki. Én pajzsot csinálok, nem veszek, $N.$b$bEzt tudnod kellene.' WHERE ID=1321;
UPDATE quest_offer_reward SET RewardText='Nem szeretem az olyan nagy pókokat, amiken nem tudok ráülni, hogy szétnyomjam őket.$b$bKöszönöm, hogy megszerezted őket, $N. Most feltépem, és a pajzsra öntöm őket...' WHERE ID=1322;
UPDATE quest_offer_reward SET RewardText='Mosarn? Ismerősen hangzik... Nem tudom pontosan hova tenni. Talán majd eszembe jut később.$b$bValószínűleg nem fontos. Egy pajzs bárhonnan jöhet, és nem jelenthet semmit...' WHERE ID=1323;
UPDATE quest_offer_reward SET RewardText='Biztosíthatlak, mindannyian nagyon fel vagyunk háborodva a jelenlegi események miatt, de engedd meg, hogy visszavigyük Theramore-ba kihallgatásra, és meglátjuk, mit tehetünk a Király megtalálásáért.$B$BBiztos vagyok benne, hogy Lady Proudmoore szeretné megköszönni a segítségedet. Beszélj vele, ha van egy szabad perced.' WHERE ID=1324;
UPDATE quest_offer_reward SET RewardText='Á, egy kérés az egyik Stormpike-tól. Büszke klán, kiváló törpékkel teli. Gazdagokkal is.$B$BKöszönöm, $N. Nap végére nekilátok Mountaineer Stormpike pajzsának.' WHERE ID=1338;
UPDATE quest_offer_reward SET RewardText='Így igaz. Van egy feladatom, amit nem tudok elvégezni, amíg őrködöm. Sőt, ez messze elvisz majd Loch Modantól.$B$BItt a tökéletes lehetőséged a kalandra!' WHERE ID=1339;
UPDATE quest_offer_reward SET RewardText='Á, nagyon jó. Ha az első jelentések igazak, akkor ezeknek a szíveknek a mérgezettsége további előrelépéshez vezethet a mérgekkel kapcsolatos tudásunkban.$b$bEz egy örömteli szállítmány, $N. Kiérdemelted a jutalmadat.' WHERE ID=1358;
UPDATE quest_offer_reward SET RewardText='Á, igen, a szívminták, amikről Renferrel beszélt. Alig várom, hogy kísérletezzek velük... a Royal Apothecary Societyt mindig érdeklik az újonnan felfedezett méregformák.' WHERE ID=1359;
UPDATE quest_offer_reward SET RewardText='Á, ismét teljesnek érzem magam -- köszönöm szépen.$B$BNéhány törpe a fém csillogását becsüli, mások a drágakövek fényét... de egy Stoutarm becses söröskorsó nélkül a kezében aligha nevezhető Stoutarmnak!' WHERE ID=1360;
UPDATE quest_offer_reward SET RewardText='Igen, toborzok. Ez a küldetés Desolace-ba vezet, az ottani kentaurok ellen. Röviden fogalmazok, hogy gyorsan elkezdhesd.' WHERE ID=1361;
UPDATE quest_offer_reward SET RewardText='Regthar parancsára jöttél? Akkor azért vagy itt, hogy elbánj a kentaurokkal. Jó.$B$BRemélem, kipihented magad. Nem tudom, hogyan végződik majd a kentaurok elleni hadjáratunk, de tudom, hogy hosszú küzdelem lesz.$B$BÜlj le, és hallgass.' WHERE ID=1362;
UPDATE quest_offer_reward SET RewardText='Nem az én hibám volt. Tényleg nem.' WHERE ID=1363;
UPDATE quest_offer_reward SET RewardText='Á, pompás!$B$BEgy ideje már féltem, hogy Mazen mester, az Academy of Arcane Arts and Sciences vezetője, figyelmen kívül hagyta a kérésemet Khadgar Esszék a Dimenzionális Konvergenciáról című művére.$B$BBiztos elárasztották kérésekkel, tekintve a sok furcsa eseményt, ami zajlik mostanában.$B$BMost pedig, ha megbocsátasz, azonnal el kell kezdenem a kutatásomat. Végre bepillantást nyerhetek egy olyan nagyszerű elme meglátásaiba, mint Khadgar, ez végtelenül izgat.' WHERE ID=1364;
UPDATE quest_offer_reward SET RewardText='Szép munka. Ez a gyors csapás a Kolkar ellen hatékony erődemonstráció, és a kentaurok legjobban az erőt értik.$B$BA Kolkar vezető halála nem csak azt a klánt zavarja meg, hanem a többieket is megállásra készteti.' WHERE ID=1365;
UPDATE quest_offer_reward SET RewardText='Mostanra a kentauroknak ismerniük kell a neved. Biztos vagyok benne, hogy ismerik, tisztelik és félik is. És ahogy téged ismernek, úgy ismerik azt a zászlót is, ami alatt lovagolsz.$B$BA Horda zászlaját.' WHERE ID=1366;
UPDATE quest_offer_reward SET RewardText='A Gelkis sír, ha meghallja a neved, $N. Félnek tőled, és gyűlölnek. Úgy gyűlölnek, ahogy a Magramot gyűlölik!$b$bTalán te is olyan erős vagy, mint a Magram. Meglátjuk...' WHERE ID=1367;
UPDATE quest_offer_reward SET RewardText='A föld szól hozzám. Azt mondja, sok Magramot megöltél. Ez jó.$B$BHa a Gelkis barátja vagy, akkor figyelj. Több feladatom is van számodra.' WHERE ID=1368;
UPDATE quest_offer_reward SET RewardText='Megszerezted a könnyeket! Most a Gelkis megtudja, hogy Theradras nem segít nekik. Nem sír majd, amikor eltiporjuk őket! A Magram fog uralkodni!$B$BOkosan tetted, hogy segítettél nekünk, $N. Mi vagyunk a legerősebbek.' WHERE ID=1369;
-- quest_offer_reward.RewardText. Batch 25: quest IDs 1370-1445.

UPDATE quest_offer_reward SET RewardText='Jó. Hallom, ahogy a Magram hasak hangosan korognak a falujukból, messze innen!$B$BOdaadom ezt a húst a Gelkisnek. És napokig harcolunk majd pihenés nélkül.$B$BAmit tettél, az jó a Gelkisnek, $N.' WHERE ID=1370;
UPDATE quest_offer_reward SET RewardText='Igen, ez volt az enyém! Újra mozgásba hozom. Ez megnevettet!' WHERE ID=1371;
UPDATE quest_offer_reward SET RewardText='Zraedus épp arról mesélt nekem, mielőtt megérkeztél, hogy van egy kíváncsi kis Beépült Ügynökünk.$b$bValóban komoly probléma. Az utolsó, amire szükségünk van, egy pletykás alak, aki a Beggar''s Haunt körül szaglászik.$b$bBiztos vagyok benne, hogy Stonard orkjai nagyon kíváncsiak lennének rá, mit mesél a barátunk. Mivel ők a szövetségeseink, ahem, segítenünk kell nekik, hogy minden információt kiszedjenek az emberből.$b$bDolgozz velem, $N, és eljuttatunk egy igazságszérumot Stonardba.$b$bA Hordáért!$b$b...jól mondtam?' WHERE ID=1372;
UPDATE quest_offer_reward SET RewardText='Igen, ez az a szilánk, amiről a föld suttogott. Erős mágiát érzek benne! Ezt a mágiát a Gelkis ellenségei ellen fogom használni.$B$BMég egy feladatot teljesítettél számunkra, $N. Talán hamarosan barátunknak nevezünk majd.' WHERE ID=1373;
UPDATE quest_offer_reward SET RewardText='Khan Jehn erős volt, de ostoba. Azt hitte, saját ereje hatalmas. Nem látta, hogy a föld mágiája erősebb. A Magram kentaurok most vezetőjük nélkül elbuknak, és a Gelkis egy napon uralkodni fog!' WHERE ID=1374;
UPDATE quest_offer_reward SET RewardText='Khan Shaka halott! A fejét egy karóra tűzöm, és magamnál tartom, hogy Shaka láthassa a Magram erejét!' WHERE ID=1375;
UPDATE quest_offer_reward SET RewardText='Halott! Khan Hratha halott! És most a Maraudine el fog bukni! Amikor a Gelkis uralja majd ezt a földet, $N, emlékezni fogunk rád. És a föld szellemei örökké énekelni fogják a neved.' WHERE ID=1380;
UPDATE quest_offer_reward SET RewardText='Khan Hratha halott! Most a Magram a legerősebb a kentaurok közül! Eltiporjuk a többieket, és uralni fogjuk Desolace-t!$B$BEmlékezni fogunk rád, $N, és megkíméljük a patáinktól, amikor mindenki mást eltiprunk.' WHERE ID=1381;
UPDATE quest_offer_reward SET RewardText='A neved suttognak a Gelkis között. Sok Magram vér tapad a kezedhez. Ez jó.$B$BTalán az is jó, ha beszélünk. Beszéljünk arról, mit tehetsz a Gelkisért, és mit tehetünk mi érted.' WHERE ID=1382;
UPDATE quest_offer_reward SET RewardText='Pompás, $N! És pont időben. Zraedus szerint a Beépült Ügynök felépült sebeiből, és készen áll arra, hogy az orkok kikérdezzék.$B$BAdj egy pillanatot, hadd készítsem el a mér-- vagyis az igazságszérumot.' WHERE ID=1383;
UPDATE quest_offer_reward SET RewardText='Jó dolgot teszel a Gelkisért. A Kolkar gyenge, és meg fog halni. Mágiájuk szánalmas, és nem menti meg őket. Ezt megmutattad nekik, és a félelmük még gyengébbé teszi őket!$B$BÉs a mi földjeinken a gyengék hamar meghalnak.' WHERE ID=1384;
UPDATE quest_offer_reward SET RewardText='Sok Gelkis esik el kezed által. Ez tetszik nekem. Talán még több olyat tehetsz, ami tetszik nekem. Talán te és a Magram barátok lehettek.' WHERE ID=1385;
UPDATE quest_offer_reward SET RewardText='A Kolkar most már fél tőled! Remélem, nevettél, amikor megölted őket. Jobb, ha nevetsz, amikor ölsz, hogy az ellenség lássa, mennyire gyenge.' WHERE ID=1386;
UPDATE quest_offer_reward SET RewardText='Á, a fülek. Szép munka.$B$BSzolgálatod a Szövetségnek megkérdőjelezhetetlen, $N. A vér, amit Desolace-ban ontottál, kétségtelenül számtalan életet fog megmenteni.' WHERE ID=1387;
UPDATE quest_offer_reward SET RewardText='Tudtam, hogy az öreg Faustin kitalál valami jót! Kétségtelenül óriási segítség voltál.$B$BMost pedig térjünk a lényegre, jó?' WHERE ID=1388;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Adósaid vagyunk.' WHERE ID=1389;
UPDATE quest_offer_reward SET RewardText='Köszönöm az elvégzett munkát!' WHERE ID=1390;
UPDATE quest_offer_reward SET RewardText='Egy ital nekem? Milyen kedves. Napok óta nem hagyták, hogy igyak. Hadd igyam meg, aztán elmondom, mit tudtam meg...' WHERE ID=1391;
UPDATE quest_offer_reward SET RewardText='Megszerezted a rettegett Noboru fegyverét? Akkor tehát halott?$B$BEz örömteli nap a Harborage számára. Noboru és bandája rettegésben tartott minket, a mocsarakban kóborolva megöltek minden draeneit, aki keresztezte az útjukat. Közvetlen fenyegetést jelentett a túlélésünkre, és nem volt erőnk szembeszállni vele.$B$BSzerencsénk van, hogy benned barátra leltünk, $N.' WHERE ID=1392;
UPDATE quest_offer_reward SET RewardText='Ennek az erszényes ládának a kulcslyuka fekete gyantával van tele. Lehetetlen kinyitni.$b$bDe Galen mesélt neked egy rejtett zárszerkezetről a láda alján...$b$b...Egy gyors keresés után megtalálod a zárszerkezetet. Elfordítod, és a láda kinyílik...' WHERE ID=1393;
UPDATE quest_offer_reward SET RewardText='Á, $N. Régen jártál utoljára az otthonomban. Úgy tűnik, sok hold telt el azóta, hogy megtetted az első ugrást, ami az utadra állított.$b$bÉs most erősebben térsz vissza hozzám, mint egykor voltál... megvilágosodottabban. Ez örömmel tölt el. És méltányosan meg kell jutalmazni azért, hogy végigvitted a próbáimat.' WHERE ID=1394;
UPDATE quest_offer_reward SET RewardText='Á, az erőkövek! A mágusok örülni fognak ezeknek!$B$BNagyon köszönöm, $N. Tudom, hogy az utad Darkshire-ból nem volt könnyű.' WHERE ID=1395;
UPDATE quest_offer_reward SET RewardText='Az állatok hangjai most halkabbak, távolabbiak. Köszönöm, $N. Most reméljük, hogy nem térnek vissza!' WHERE ID=1396;
UPDATE quest_offer_reward SET RewardText='Ez a fa könnyű, de erős. Köszönöm, $N. Tökéletesen megfelel majd.' WHERE ID=1398;
UPDATE quest_offer_reward SET RewardText='Helgrum jelentést akar, mi? Alig három napja küldtem egy futárt Stonardba. Kudarcot vallott a küldetésében? Ha Stonardban nincs meg a jelentésem, akkor úgy tűnik, kudarcot vallott.$b$bReméljük, a következő futár, akit küldök, ügyesebb vagy szerencsésebb lesz.' WHERE ID=1418;
UPDATE quest_offer_reward SET RewardText='Ez ám a szép állkapocsgyűjtemény, $N. Most azok a prérifarkasok nem fogják szétdúlni a készleteinket maradékokért.$B$BSzép munka. A Badlands prérifarkasai nem könnyű préda. A tetted megmutatja, hogy talán túlélheted itt.' WHERE ID=1419;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Neeka jelentéséből látom, hogy a Szövetségnek is megvannak a maga problémái. És talán rájövünk, hogy néhány ellenségünk közös.' WHERE ID=1420;
UPDATE quest_offer_reward SET RewardText='Á, megtaláltad őket! Ezekkel a Nethergarde-i varázslók folytathatják munkájukat. Nem tudom, mit csinálnak pontosan, de kapcsolatban áll a Blasted Lands-i Sötét Portállal, és létfontosságú a Szövetség biztonsága szempontjából.' WHERE ID=1421;
UPDATE quest_offer_reward SET RewardText='Legyél csendben egy pillanatra, $c. Még a tenger tompa moraján keresztül is hallani azokat az undorító, gurgulázó hangokat a halembertől.' WHERE ID=1422;
UPDATE quest_offer_reward SET RewardText='Á, köszönöm, $N! Annyi készlet vész el Darkshire-tól idáig. Jó látni, hogy néhányat visszaszereztünk.' WHERE ID=1423;
UPDATE quest_offer_reward SET RewardText='Az Atal''ai ereklyék összegyűjtésében tanúsított szorgalmad dicséretre méltó, $c.' WHERE ID=1424;
UPDATE quest_offer_reward SET RewardText='Mi? Egy csomag Biggs karavánjából? Azt hittük, elveszett, ő is, meg a csomag is.$B$BKöszönöm, $N. Szerencsével ezek a készletek a nagyon szükséges alapanyagot, az Azoran Kristályokat hozzák. A készletünk fogytán van...' WHERE ID=1425;
UPDATE quest_offer_reward SET RewardText='A tenger hatalmasnak és könyörtelennek tűnik, de bemocskoltad saját ivadékainak vérével. A halemberek ismerik a fájdalmat. Ostobaságuk arra kényszeríti majd őket, hogy megerősítsék soraikat az általad okozott pusztítás után, és ez jó.$B$BHadd homályosítsák el gurgulázó sikolyaik a tenger moraját mélyen az éjszakába nyúlóan. Mosolyogni fogok, valahányszor elhallgattatnak egyet közülük.$B$BTérj vissza hozzám, ha még több halembert szeretnél megölni. Szívesen jutalmazlak meg ismét.' WHERE ID=1426;
UPDATE quest_offer_reward SET RewardText='Á, $N, visszatértél. Jó. Befejeztem újabb fegyverek elkészítését a murlocok elleni harcunkhoz. Amiért friss fűrészfog húst hoztál nekünk, és amiért kis mosolyt csaltál Katar arcára, felajánlok neked egyet közülük.' WHERE ID=1427;
UPDATE quest_offer_reward SET RewardText='Szép munka, $c. Több vérüket kérem. Pusztuljon minden halember.' WHERE ID=1428;
UPDATE quest_offer_reward SET RewardText='Elhozod nekem az Atal''ai idéző ereklyéit?$b$bLátom, Jammal''an, a Próféta a Vér Kamrájának tanítványait vezeti kiválasztott sorsuk felé. Vajon Hakkar visszatért a Templomba? Beteljesült a sorsuk?' WHERE ID=1429;
UPDATE quest_offer_reward SET RewardText='Á, ez tökéletes lesz. Alig várom, hogy megkóstoljam ezeket, miután tökéletesen elkészítik nyílt tűzön. Vigyél belőle egy mintát az utazásaidra. Valóban finom.' WHERE ID=1430;
UPDATE quest_offer_reward SET RewardText='Putanni, nemes $c. Keldran vagyok, a mágia... és más misztikus művészetek tanítványa.$b$bAz ügy, amiről Craven küldött, hogy beszélj velem, egy kicsit több finomságot igényel, mint amire eddig szükséged volt, de ez nem jelenti azt, hogy nem segíthetsz ügyünknek.$b$bKérlek, helyezkedj kényelembe, és elmondom, miért van szüksége a Hadvezérnek a segítségemre... és a tiédre is.$b$bA külsőnél kezdődik, $N. Hogyan látja magát a Horda. Hogyan látnak minket a szövetségeseink. És ami a legfontosabb, hogyan látnak minket az ellenségeink.' WHERE ID=1431;
UPDATE quest_offer_reward SET RewardText='Üdvözöllek, $c. Híreket hozol Orgrimmarból; ez jó.$b$bA démoni fertőzés még a kentaurtrágya szagánál is jobban elárasztja ezt a területet. A lóemberek a sajátjuknak vallják ezt a földet, de nyilvánvalóan olyan hatások is jelen vannak, amiket nem tudnak kontroll alatt tartani, és összezúzzák majd őket, ha nem fékezik meg.$b$bNem tetszik nekem, hogy közvetve segítjük a kentaurokat, de ez a Horda javát szolgálja, így teljesítem kötelességemet a Hadvezér felé, még ha ez azt is jelenti, hogy segítenem kell a Hordán belüli warlockoknak.' WHERE ID=1432;
UPDATE quest_offer_reward SET RewardText='Á, igen. A Hadvezérhez hű segítséget mindig szívesen fogadjuk.$b$bMaurin vagyok. Keldran és a fiatal Hadvezér, Thrall kérésére vagyok itt. Az a vágyam, hogy segítsem az ifjú vezetőt az uralmát fenyegető gonoszságok ellen.$b$bGyere, gyere közelebb, $c. Elmagyarázom a tervemet arra, hogyan távolítsuk el azt a gennyedző kelést, ami a Burning Blade.' WHERE ID=1433;
UPDATE quest_offer_reward SET RewardText='Jó munkát végeztél, $c. Becsületet és elkötelezettséget mutattál.$B$BAmikor a Desolace-i hadjáratunk véget ér, a Hadvezér tudni fogja, hogy segítettél nekünk itteni tetteinkben, és hogy segítettél megvalósítani az akaratát.$B$BKöszönöm.' WHERE ID=1434;
UPDATE quest_offer_reward SET RewardText='Á, sikeresen visszatértél. Ez jó. Add ide a drágaköveket, biztonságos helyre teszem őket...$B$BA feladataim számodra teljesültek, $c. Beszélj Takatával, ha kipihented magad. Talán van számodra más feladata, vagy talán szüksége van rá, hogy visszatérj Orgrimmarba, és tájékoztasd Keldrant a Desolace-i haladásunkról.' WHERE ID=1435;
UPDATE quest_offer_reward SET RewardText='Több mint sikeresen tértél vissza Desolace-ból, $N. Köszönöm.$B$BKöszönöm az erőfeszítéseidet, az időt, és a megértést a kérésem iránt. Thrall megérti és vágyik a békére a Horda és a Szövetség között, és azzal, hogy biztosítjuk, hogy a megjelenésünk elfogadható legyen, nem provokálunk ki további szükségtelen erőszakot.' WHERE ID=1436;
UPDATE quest_offer_reward SET RewardText='Ahogy átkutatod a szekér roncsait, egyértelművé válik, hogy varázslatokkal és fegyverekkel is megtámadták. A harc egyoldalúnak és gyorsnak tűnt; sehol egy csepp vér, sehol egy holttest maradványa.$B$BAki megtámadta a szekeret, hatékony és gyors volt.' WHERE ID=1437;
UPDATE quest_offer_reward SET RewardText='Hála Elune-nak, végre jött valaki, aki segít. Kérlek, $c, szükségem van a segítségedre. A testvéremet, Tyranist, és engem elfogott és idehozott a Burning Blade. Azt hiszem, engem akarnak feláldozni a démoni uraiknak!$B$BTudtam, hogy Desolace-ba jönni hiba volt, de Tyranis mostanában áhítozni kezdett minden arkánus tudásra -- még népünk kívánsága ellenére is. Úgy döntött, megteszi ezt az utat, még azután is, hogy hallott a föld démoni fertőzöttségéről.$B$BA legrosszabbtól tartok miatta.' WHERE ID=1438;
UPDATE quest_offer_reward SET RewardText='Ez szörnyű! De gondolom, szükséges volt. Ha nem a te kezed által történik, biztosan a népemé által történt volna. Gondolom, köszönetet kellene mondanom -- bocsáss meg, ha nem tűnik őszintének. Nem akarok megsérteni.$B$BAnnak tudatában, mi lett testvérem sorsa, úgy tűnik, eljött a menekülésem ideje. Ha még mindig hajlandó vagy rá, elfogadom a segítségedet, hogy elmeneküljek erről a rettenetes helyről.$B$BAmikor készen állsz, elindulhatunk a biztonság felé.' WHERE ID=1439;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Dalinda épségben visszaért ide, Nijel''s Pointra, és sokkal jobb állapotban, mint amit kérhettem volna. Az, hogy saját erejéből ért ide, jó jel volt. Remélem, jól vagy?$B$BFáj tudnom, hogy sem Tyranis, sem Dalinda nem tért vissza, de Tyranis döntéseinek szégyenét neki kell elviselnie. Ezzel majd akkor kell szembenéznie, amikor visszatér Darnassusba.' WHERE ID=1440;
UPDATE quest_offer_reward SET RewardText='Ez valóban az a drágakő, amit Stilwell akar, de mielőtt engedhetném, hogy elvidd neki, meg kell tisztítani a megrontástól -- a naga boszorkák valóban erővel töltik meg a drágaköveket, de saját, gonosz fajtájú erővel.$B$BTudasd Stilwell-lel, hogy az ereje sértetlen, és jól fog működni bármilyen szertartásban, amiben részt vetetne vele.$B$BRemélem, tudod, mit csinálsz, $c, ez nem egyszerű tárgy, amit birtokolsz.' WHERE ID=1442;
UPDATE quest_offer_reward SET RewardText='Jó ideje nem beszéltünk, $c. Remélem, sikeres volt az utad.$b$bMilyen tudást szereztél a Hinterlandsben élő száműzött Atal''aitól?' WHERE ID=1444;
UPDATE quest_offer_reward SET RewardText='Bátor $c, bebizonyítottad, hogy a Horda nagyszerű bajnoka vagy.$b$bMost pedig azonnal el kell intézni Hakkar ereklyéinek ezt a gyűjteményét!' WHERE ID=1445;
-- quest_offer_reward.RewardText. Batch 26: quest IDs 1446-1503.

UPDATE quest_offer_reward SET RewardText='Jammal''an vakmerő bizalma a hamis látomásokban örök végzetbe vezette népemet.$b$bKöszönöm, $c, hogy megbosszultad száműzetésemet. Gyászolom népemet. Nincs otthon, ahova visszatérhetnék.' WHERE ID=1446;
UPDATE quest_offer_reward SET RewardText='Szóval okkal jöttél hozzám. Mire van szükséged?' WHERE ID=1447;
UPDATE quest_offer_reward SET RewardText='Atal''Hakkar Temploma a Könnyek Tava alá süllyedt? És körülvette a zöld sárkányraj?$B$BLenyűgöző felfedezés, $c. De nyilvánvalóan valami szörnyen elromlott.' WHERE ID=1448;
UPDATE quest_offer_reward SET RewardText='Mit akarsz, fiacskám? Nem látod, hogy itt problémáim vannak, amikkel foglalkoznom kell? Kinek van ideje egy fecsegő $R-rel itt állva locsogni?$B$BTrollok másznak elő mindenhonnan! Siess.' WHERE ID=1449;
UPDATE quest_offer_reward SET RewardText='Á, igen. Persze, emlékszem, hogy elküldtem az egyik griffidomárom, hogy segítsen Brohann Caskbellynek.$B$BMindig is lágy szívem volt az Explorers'' League iránt. Az apám segített abban a kezdeti ásatócsapatban, amely felfedezte Uldamant, ha már itt tartunk.$B$BAzt küldtem, akit akkoriban a legjobb griffidomáromnak gondoltam, Brohann-nal. Egy fickó volt, Rhapsody Shindigger néven.$B$BÉs micsoda griffidomár volt! Nos, amíg...' WHERE ID=1450;
UPDATE quest_offer_reward SET RewardText='Csuklás!$B$BEgyenest rád nézek, de folyton föl-le ugrálsz. Szédülök tőle. Hohó!$B$BCsuklás!$B$BHűha! Ezt érezted? Rázkódik a föld, barátom. Innom kell valamit.$B$BCsuklás!' WHERE ID=1451;
UPDATE quest_offer_reward SET RewardText='Látom, semmi bajod nem volt megszerezni, amire szükségem van! Biztos elég kemény menet volt odaát a messzi Kalimdorban.$B$BEgy pillanat, és kivonom, amire szükségem van ezekből a zúzákból és májakból. Csuklás!$B$BAztán lepárolhatok egy vad kis italt, és végre elmondhatom, amit tudni akarsz.$B$BCsuklás!$B$BCsak arra gondolok, milyen volt az az öreg mocsár, máris borsódzik a hátam.$B$BCsuklás!$B$BHadd kotyvasszak gyorsan egy italt.' WHERE ID=1452;
UPDATE quest_offer_reward SET RewardText='Örülök látni, hogy a Reclaimersnek nincs hiánya munkából, sem segíteni akaró kalandozókból.$B$BKreldig vagyok, $N. Okosan tetted, hogy segítettél a Reclaimersnek. Manapság mindenkinek kell valami: elveszett egy családi örökség, egy mágikus tárgy, egy szeretett személy. Sosem lehet tudni. De amíg a Reclaimers itt van, nincs ok, hogy a megfelelő árért bárki ne találja meg, amit elveszített.' WHERE ID=1453;
UPDATE quest_offer_reward SET RewardText='Észreveszed, hogy a ládán nincs semmilyen vízkár.$B$BA második dolog, amit észreveszel, hogy a tetejét erővel feltörték, és bármilyen mágikus csapdát is állítottak a védelmére, az már rég aktiválódott -- ez egyértelmű a szélein lévő égésnyomokból.' WHERE ID=1454;
UPDATE quest_offer_reward SET RewardText='Isten hozott vissza, Nijel''s Pointon, $N. Szóval, mondd el, mit találtál.$B$BMi?! Semmit? Egy üres ládáért attól tartok, nem fizetnek nekünk.$B$BMesélj bővebben ezekről a nyomokról, amiket láttál... ezekről a vágásokról.' WHERE ID=1455;
UPDATE quest_offer_reward SET RewardText='Ez remek, $N! Megtaláltad Karnitol holmiját!$B$BAzok az átkozott naga, mindig bajt okoznak. Azt hiszem, inkább töltenék egy egész életet a Hordával háborúzva, mint hogy a fajtájuk ellen kelljen küzdenem. Nagy szolgálatot tettél a Reclaimersnek.' WHERE ID=1456;
UPDATE quest_offer_reward SET RewardText='Á, a Karnitol ügy Desolace-ban. Kiváló!$B$BSzóval a láda tönkrement, de a tárgyak mind itt vannak, mi? Nos, majd ő eldönti. Az egyik jó dolog ebben az üzletben, amit itt viszek, hogy ha nincsenek megelégedve, mondhatom nekik, hogy tűnjenek el! Ránk hagyatkoznak, hogy megtaláljuk a holmijukat... nem arra, hogy szép és jó állapotban legyen, amikor visszakapják.$B$BSzép munka, $N. Nézzük, hogy fizessünk neked.' WHERE ID=1457;
UPDATE quest_offer_reward SET RewardText='Jó, jó, $N. Nem vagyok biztos benne, hogy ezek jó minőségűek-e, de ha Leftwitch egy bizonyos típust akart, akkor meg kellett volna adnia, mielőtt kiküldte a Reclaimerst ide.$B$BMit szólnál, ha folytatnánk a listáján lévő következő tétellel?' WHERE ID=1458;
UPDATE quest_offer_reward SET RewardText='A segítséged igazi áldás, $N. Legalább a felére csökkented az itt, Desolace-ban töltött időmet. A segítségeddel hamarosan visszatérek Ironforge-ba, hogy melegítsem a lábam.$B$BAmikor ezzel a listával végzünk, és otthon leszek, keress meg, biztosan meghívlak egy sörre.$B$BDe addig gyűjtsük össze a többi alapanyagot.' WHERE ID=1459;
UPDATE quest_offer_reward SET RewardText='Vidd magaddal, és ne feledd, ez szent.' WHERE ID=1462;
UPDATE quest_offer_reward SET RewardText='Jóhiszeműen adok neked egyet. Már egyszer bebizonyítottad magad, de szerintem óvatosabbnak kéne lenned a jövőben.' WHERE ID=1463;
UPDATE quest_offer_reward SET RewardText='Égjen tűz a szívedben, $N.$B$BAz elemek várnak rád.' WHERE ID=1464;
UPDATE quest_offer_reward SET RewardText='Felháborító! Ez az egész fiaskó!$B$BMindkettőjüket figyelmeztették, mennyire veszélyes lenne idejönni. Most mindketten eltűntek... vagy még rosszabb.$B$BAzt mondtad, nyomokat láttál egy közeli erőd felé vezetni? Ez lehet a legjobb esélyünk.$B$BA helyiek szerint az az erőd tele van a Burning Blade tagjaival -- orkokkal, akik démoni ügyeknek szentelték magukat. Talán nem képviselik a Horda hiedelmeinek többségét, de gonoszak, és azon nyomban megölnek, ha kémkedésen kapnak.' WHERE ID=1465;
UPDATE quest_offer_reward SET RewardText='Őszintén? Nem gondoltam volna. Elképesztő vagy, $N. Démonokkal szállsz szembe egy mágus kísérleteiért, és még egy darabban is térsz vissza. Remek munka!$B$BSzemélyesen fogok mesélni rólad Roettennek, amikor visszatérek Ironforge-ba.' WHERE ID=1466;
UPDATE quest_offer_reward SET RewardText='Á, a csomag Leftwitchnek, Desolace-ból. Kiváló. Értékelem a munkát és a pontosságodat, $c. Örülök, hogy fedélzeten voltál, legalábbis ehhez a kis munkához.$B$BItt a fizetséged. Tudd meg, hogy a Reclaimers Inc. mindig jól fizet egy kemény heti munkáért.' WHERE ID=1467;
UPDATE quest_offer_reward SET RewardText='Öhm... szia. Randis vagyok, és gondolom, te vigyázol rám? Kalandozó vagy, mint anyukám és apukám voltak. Örülök, hogy megismerhetlek.$B$BRemélem, sokat fogunk szórakozni együtt. Van néhány dolog, amit szeretnék csinálni, és a gondozónő azt mondta, olyan leszel nekem ezen a héten, mint egy nagy $gtestvér:testvér;. Ez nagyon tetszene, igen, $guram:hölgyem;.' WHERE ID=1468;
UPDATE quest_offer_reward SET RewardText='Rhapsody Shindigger! Így igaz... hogy is felejthettem volna el egy ilyen nevet?$B$BSzóval végig tudott a templom elsüllyedéséről? Nos, ez biztosan megspórolt volna neked egy kis gyaloglást.$B$BDe ez az Atal''ai ereklye! Hát ez aztán a lelet!' WHERE ID=1469;
UPDATE quest_offer_reward SET RewardText='Bár még próbálatlan és fiatal vagy a tanulásban, bebizonyítottad, hogy elegendő képességgel rendelkezel egy imp megidézésének és megkötésének elsajátításához. Ne hagyd magad megtéveszteni az imp méretétől. Bár nincs fizikai ereje, olyan hatalmakkal és ravaszsággal bír, amik jól szolgálnak majd.$b$bFigyelj rám alaposan, $N, mert nem ismétlem meg ezt a leckét, és az elsajátítását rád bízom.' WHERE ID=1470;
UPDATE quest_offer_reward SET RewardText='Jó munkát végeztél, $N. Most átadom neked a varázslatot, amivel megidézhető a voidwalker.$B$BAz erő, amit rád szabadított, most a te parancsod alatt áll. Használd bölcsen.' WHERE ID=1471;
UPDATE quest_offer_reward SET RewardText='Carendin küldött? Akkor Sithel vagy.$b$bNe gondold, hogy jelentéktelen vagyok, mert elveszett a látásom. Olyan dolgokat látok most, amik mögöttem hevernek, olyan tisztasággal, amit korábban sosem ismertem. Amit egykor átoknak hittem, most áldás.' WHERE ID=1472;
UPDATE quest_offer_reward SET RewardText='Á, ez kiváló. Perrine valószínűleg mit sem tudott a tőlünk ellopott dohos könyv igazi erejéről.$B$BEz nem fog többé kicsúszni a kezünkből. Figyeld meg, $N, a varázslat felépítését, azt a módot, ahogyan az erődet csatornáznod kell.' WHERE ID=1473;
UPDATE quest_offer_reward SET RewardText='Ismét jó munkát végeztél, $N. Jó ideje nem láttam olyan fiatal $c-t, akiben ennyi potenciál lenne, mint benned. Biztosíthatlak, hogy továbbra is figyelemmel kísérem a fejlődésedet, és felkészítelek, segítelek a jövőbeli próbáid során.$B$BMost pedig hadd mutassam meg neked az idéző varázslatot az újonnan leigázott succubusodhoz.' WHERE ID=1474;
UPDATE quest_offer_reward SET RewardText='Az Atal''ai Táblák! Köszönöm, $N!$B$BAmint ezeket eljuttatom az Explorers'' League-nek, a nevünk együtt kerül be a történelembe. Segítettél egy öreg törpének teljesíteni élete utolsó kötelezettségét. Ezért örökre hálás vagyok.' WHERE ID=1475;
UPDATE quest_offer_reward SET RewardText='Egy jóravaló ember szíve nagyjából ugyanolyannak tűnik, mint bármelyiké, ha így nézed, nem gondolod?$B$BTalán... más... nézőpontunk van erről a témáról. Ezek viszont pont megfelelnek. Nem kétlem, hogy egy succubust vonzana a tisztaságuk.' WHERE ID=1476;
UPDATE quest_offer_reward SET RewardText='Andromath küldött? Nagyon jó. Van egy fontos feladatom számodra...' WHERE ID=1477;
UPDATE quest_offer_reward SET RewardText='Jó, látom, Ageronnak sikerült megtalálnia téged, $N. Ne vesztegessük az időt csevegéssel és udvariaskodással, koncentráljunk a kiképzésedre. Még sok mindent kell megtanulnod.' WHERE ID=1478;
UPDATE quest_offer_reward SET RewardText='Hűha, még annál is menőbb volt, mint amit elképzeltem - az Örökkévalók Ága! Nem gondoltam, hogy ilyen nagy lesz, de az volt! Láttad a tetején lévő madarat is?! Vajon hogy sikerült így kialakítaniuk az ágakat!$B$BKöszönöm, hogy elvittél Darnassusba, $N. Szuper vagy!' WHERE ID=1479;
UPDATE quest_offer_reward SET RewardText='Hmm, ezek a rúnák valóban egy nyelvet alkotnak, $N, egy ősi nyelvet. Távolról hasonlítanak az Eredun nyelvre, de a különbségek drasztikusak. Ha nem tévedek, ez valamiféle szerződés... Itt, igen, ez a jel a démon aláírása: Lord Azrethoc.' WHERE ID=1480;
UPDATE quest_offer_reward SET RewardText='Az árnyvadászok nem tudtak végezni veled, $c. Lenyűgöző... nagyon lenyűgöző.$B$BEz a fejbőr pont megfelel a varázslatomhoz. Amíg távol voltál, sikerült összegyűjtenem néhány más alapanyagot is, amire a varázslathoz szükség van.$B$BMajdnem készen állok. Csak egy fókuszpont kell a varázslathoz -- valami, ami kivetíti a démonúr képét és hollétét.' WHERE ID=1481;
UPDATE quest_offer_reward SET RewardText='Egy értékes jósló kristály... hibátlan... gyönyörű. Valóban.$B$BAzonnal kezdünk. Ennek a démonúrnak a megtalálása legyen az elsődleges célunk, elpusztítása pedig teljes figyelmünket igényli.$B$BLépj hátrébb, $c, és lássuk, mi ez a démon, és hol találhatjuk meg.' WHERE ID=1482;
UPDATE quest_offer_reward SET RewardText='Azt hittem, a Venture Company főnökei rabszolgahajcsárok, de aztán megismertem Sputtervalve-ot, a legkegyetlenebbet mindközül!$b$bHa! Bár gondolom, jobb, mint munka nélkül lenni... Vagy még rosszabb, azzal a Gerenzóval dolgozni. Ha segíteni jöttél, van itt valami dolgom számodra.' WHERE ID=1483;
UPDATE quest_offer_reward SET RewardText='Tanúja voltam annak, ami épp Maurin és a démonúr között történt. Az a lény, még jelenésként is, erősebbnek tűnik warlock társamnál. Vajon képes lesz legyőzni a szörnyeteget? A Hadvezért jobban szolgálná, ha magam mennék, de az itteni felelősségeimmel szégyent hoznék a klánomra, ha hátat fordítanék a kötelességeimnek, hogy saját becsületemért harcoljak e gonosz ellen.' WHERE ID=1484;
UPDATE quest_offer_reward SET RewardText='$c-ként folytatott kiképzésed során megtanulod majd megidézni sokféle lényt. Némelyik talán nem tűnik annak, de mind hasznos eszköz.$B$BNe hagyd magad megtéveszteni az imp kis mérete által. Ahogy kétségtelenül észrevetted, még mindig félelmetes ellenfél.' WHERE ID=1485;
UPDATE quest_offer_reward SET RewardText='Erőfeszítéseid nem maradnak észrevétlenül, amiért összegyűjtötted ezeket a bőröket, $N.$b$bKöszönöm az elkötelezettségedet.' WHERE ID=1486;
UPDATE quest_offer_reward SET RewardText='Naralex tanítványaként dicsérem a bátorságodat, $N.$b$bA segítséged a barlangok megtisztításában az első lépés hosszú küzdelmünkben, hogy visszaállítsuk a Barrenst.$b$bKöszönöm, és virágozz.' WHERE ID=1487;
UPDATE quest_offer_reward SET RewardText='Hatalmas győzelem ez mindannyiunk számára, $N. Örvendjünk sikerednek. Most már bízom benne, hogy a jövőnk itt nem olyan sötét, mint egykor gondoltam.$B$BA démonokat elpusztítjuk, a Burning Blade kudarcot vall törekvéseiben, és egy napon talán ismét lesz egy hely, amit biztonságosan otthonnak nevezhetünk.' WHERE ID=1488;
UPDATE quest_offer_reward SET RewardText='Üdvözöllek, $N. Szívesen látunk itt, és azt javaslom, gyűjtsd össze minden erődet. Mert a feladat, amit most elétek állítunk... súlyos.' WHERE ID=1489;
UPDATE quest_offer_reward SET RewardText='Igen, ez igaz. Tudok a Wailing Caverns druidáiról. Láttam eltorzult, pikkelyes arcukat. Ismerem bűneiket, és ismerem terveiket.$b$bMeg kell állítanod őket, $N.' WHERE ID=1490;
UPDATE quest_offer_reward SET RewardText='Remek, megszerezted! Alig várom, hogy kipróbáljam. Ez vagyont fog hozni nekem, csak tudom!$B$BKöszönöm, $N. Fogd ezt, és amint gazdag leszek, küldök még, ígérem!' WHERE ID=1491;
UPDATE quest_offer_reward SET RewardText='Elég kicsi láda. Igen, biztos találok neki helyet a hajón. A következő dagállyal indul, remélem, ez elég hamar lesz? Kiváló. Csak beírom a naplómba.$B$BMinden el van intézve! Szép napot, $c.' WHERE ID=1492;
UPDATE quest_offer_reward SET RewardText='Á. Látom, legyőzted a mennydörgőgyíkokat, ami bizonyítja, hogy kemény vagy. Most megmutatom, hogyan egyesülhet a kemény bőr és a ravasz mozdulatok áthatolhatatlan védőfallá.$b$bTanuld meg jól a leckét, $N. És készülj fel a jövőbeli tanításokra.' WHERE ID=1498;
UPDATE quest_offer_reward SET RewardText='Jó munkát végeztél, $N.$b$bBár az aljas familiárisok csupán a Burning Blade sötétebb erőinek kedvencei voltak, a sikered ellenük nagyobb tetteket jósol a jövőre nézve.' WHERE ID=1499;
UPDATE quest_offer_reward SET RewardText='Jó. Remélem, más veszteségeket is okoztál a Burning Blade-nek, amíg ezt visszaszerezted.$B$BNagy bosszúságot okoztak a Hadvezérnek, és nagy szégyenfoltot jelentenek a warlockok egészére nézve.' WHERE ID=1501;
UPDATE quest_offer_reward SET RewardText='A szemeim régen kiszáradtak már a kohó lángjába bámulástól, de néhány dolgot még mindig látok. Látom, hogy akarsz valamit.$b$bÉs ha idetaláltál, akkor sejtem, mire vágysz.' WHERE ID=1502;
UPDATE quest_offer_reward SET RewardText='Megtaláltad őket! És minden rúd itt van, ami nem lep meg. Nem hittem, hogy a Razormane-ek tudnák, mit kezdjenek egy ilyen finom acéllal.$b$bKöszönöm, $N. Itt a jutalmad. Szolgáljon jól.' WHERE ID=1503;
-- quest_offer_reward.RewardText. Batch 27: quest IDs 1504-1644.

UPDATE quest_offer_reward SET RewardText='Jó munkát végeztél, $N. Megmutatom, hogyan idézz meg egy voidwalkert, hasonlót ahhoz, amit épp most győztél le.$B$BTudnod kell, hogy nagy elvárásaink vannak veled szemben, és eddig meg is feleltél nekik.$B$BNe hagyd azonban, hogy fejedbe szálljon, mert az előtted álló feladatok ehhez képest olyan egyszerűnek fognak tűnni, mint reggel felébredni.' WHERE ID=1504;
UPDATE quest_offer_reward SET RewardText='Üdv, fiatal. Tanításért jöttél, igaz?' WHERE ID=1505;
UPDATE quest_offer_reward SET RewardText='Jó. Attól féltem, Ophek nem ér el hozzád.$B$BItt az ideje, hogy továbbfejlesszem warlock kiképzésedet. Bármilyen jelenlegi ügyednek várnia kell.$B$BBízom benne, hogy ezzel nem lesz gond?' WHERE ID=1506;
UPDATE quest_offer_reward SET RewardText='Hm... $N. Még új vagy az utadon, de érzem benned a nagyság lehetőségét.$B$BAjándékokkal születtél, $N. Ügyelj rá, hogy ne vesszenek kárba.' WHERE ID=1507;
UPDATE quest_offer_reward SET RewardText='Hírrel jöttél Dogranról? Napokkal ezelőtt kellett volna visszatérnie, és semmit sem hallottam felőle...' WHERE ID=1508;
UPDATE quest_offer_reward SET RewardText='Zankaja? Ő Dogran párja, igaz?$B$BIgen, hallottam felőle, de ez nem olyan hír, amit hagynunk kéne visszajutni hozzá...$B$BNem, nem halott. De megsérült, és a quilboarok foglya.' WHERE ID=1509;
UPDATE quest_offer_reward SET RewardText='Még egy $R, mi? Remélem, nem a másikért jöttél. Ő nem élte túl. Azok a goblinok alaposan elintézték.$B$BAzt mondta, gyógyitalra van szüksége, de nem sokra másra.' WHERE ID=1510;
UPDATE quest_offer_reward SET RewardText='Nos, épp itt az ideje! Dogran haldoklik odakint, erre várva.$B$BAzonnal el kell juttatnunk hozzá, de a legtöbb itt állomásozó közlegény élelemgyűjtő küldetésen van.' WHERE ID=1511;
UPDATE quest_offer_reward SET RewardText='Ha azt mondod, ez elegendő lesz, akkor bízom benned, $N. Engedd meg, hogy megtisztítsam... Makulátlanul és csillogva talán még csábítóbb lesz egy succubus számára.' WHERE ID=1512;
UPDATE quest_offer_reward SET RewardText='Siker! Ne is várj kevesebbet a legjobb tanítványomtól.$B$BBebizonyítottad az értéked, és örömmel megmutatom, hogyan idézd meg leigázott succubusodat. Menj most, sok mindent kell még tanulnod, és amikor legközelebb látlak, elvárom, hogy valódi uralmat találj succubusod felett.$B$BHagyd Dogran és Zankaja szomorúságát ránk, akik idősebbek vagyunk nálad, de emlékezz rá, és tartsd magadnál védelemként a sötét hatalom csábításai ellen, amit ma tanultál meg megidézni.' WHERE ID=1513;
UPDATE quest_offer_reward SET RewardText='Két Cenarion növénykenőcsöt kensz fel a szélvirágra. Az azonnal elkezdi levetni beszennyezett formáját, és élénk, egészséges növényként bomlik ki.' WHERE ID=1514;
UPDATE quest_offer_reward SET RewardText='Undorító ízű főzet...$B$BÉrzem most az erőt magamban, elég ahhoz, hogy sántikálva elmenjek... De a lábam, azt életem hátralévő részére elveszítettem. A karomat is.' WHERE ID=1515;
UPDATE quest_offer_reward SET RewardText='Kiváló. Sikered mutatja, hogy felkészültél.$B$BAz elemek közül a föld minden dolog alapját jelenti. Ez az erőd, az állóképességed, a türelmed. A föld megvéd téged, de csak ha megfelelő tisztelettel bánsz vele. Mint a többi elem, a föld is lehet szeszélyes. A föld az élet alapja, és törvényeit megfigyelve nagyobb bölcsességre teszel szert. Sose feledd a titkokat, amiket a föld megoszt veled.$B$BMost készítek neked egy saptát, és elfogadásával rátalálsz utadra.' WHERE ID=1516;
UPDATE quest_offer_reward SET RewardText='Á... $N... a föld örül, hogy itt vagy.$B$BTestben és lélekben összekötve haladsz majd tovább, tudva, hogy a hegyek az erőd; a síkságok a türelmed; és maga a világ a lényeged.$B$BAlázatosan állni a föld előtt minden, amit ehhez a szertartáshoz teljesítened kell. De a többi elem nem ilyen passzív. Lehetnek kaotikusak és gyakran erőszakosak, de ilyen az elemek természete. Egymással szembenálló kettős természeteket kell alaposan megismerned.' WHERE ID=1517;
UPDATE quest_offer_reward SET RewardText='Kiváló!$B$BA totem, amit készítek neked, több, mint a $c közötti státuszod jelképe -- ennél nagyobb képességekkel bír. A totem egyik felhasználása, hogy fókuszpontként szolgáljon varázslatokhoz. Ezek a varázslatok a földhöz kötődnek, és ahogy egyre nagyobb bölcsességre teszel szert, a föld egyre több képessége válik elérhetővé számodra.$B$BA kiképzők tudni fogják, amikor készen állsz nagyobb tudásra.$B$BDe most vedd el ezt a földtotemet, és egy tekercset, ami megtanítja első képességedet.' WHERE ID=1518;
UPDATE quest_offer_reward SET RewardText='Jó, $N. Visszatérted ide azt jelzi, hogy valóban felkészültél a következő lépésre.$B$BAz elemek közül a föld minden dolog alapját jelenti. Ez az erőd, az állóképességed, a türelmed. A Földanya megvéd téged, de csak ha megfelelő tisztelettel bánsz vele. Ő az élet alapja, és törvényeit megfigyelve nagyobb bölcsességre teszel szert. Sose feledd a titkokat, amiket megoszt veled.$B$BMost elkészítem a saptádat, és elfogadásával új út nyílik meg előtted.' WHERE ID=1519;
UPDATE quest_offer_reward SET RewardText='Á... $N... a föld örül, hogy itt vagy.$B$BTestben és lélekben összekötve haladsz majd tovább, tudva, hogy a hegyek az erőd; a síkságok a türelmed; és maga a világ a lényeged.$B$BAlázatosan állni a föld előtt minden, amit ehhez a szertartáshoz teljesítened kell. De a többi elem nem ilyen passzív. Lehetnek kaotikusak és gyakran erőszakosak, de ilyen az elemek természete. Egymással szembenálló kettős természeteket kell alaposan megismerned.' WHERE ID=1520;
UPDATE quest_offer_reward SET RewardText='Pompás.$B$BA totem, amit készítek neked, több, mint jelkép -- ennél nagyobb képességekkel bír. A totem egyik felhasználása, hogy fókuszpontként szolgáljon varázslatokhoz. Ezek a varázslatok a földhöz kötődnek, és ahogy egyre nagyobb bölcsességre teszel szert, a föld egyre több képessége válik elérhetővé számodra. A Kalimdor-szerte megtalálható kiképzők tudni fogják, amikor készen állsz nagyobb tudásra, és tudatni fogják veled, amikor meglátogatod őket.$B$BDe most vedd el ezt a földtotemet, és egy tekercset, ami megtanítja első képességedet.' WHERE ID=1521;
UPDATE quest_offer_reward SET RewardText='Hmmm, Searn küldött hozzám, igaz?$B$BNos, Searnben mindig meg lehetett bízni, tehát ez azt jelenti, készen állsz a következő sapta megismerésére -- a tűz saptájára.$B$BMár látom is a szemedben, az égést, a vágyat. Megízlelted a hatalmat, és most készen állsz többre. Türelem, $N. Emlékezz, mit tanított neked a föld. A hatalom és pusztítás könnyen jön, de tudnod kell, mikor kell megállítanod a kezed.' WHERE ID=1522;
UPDATE quest_offer_reward SET RewardText='Hmmm, Narm küldött hozzám, igaz?$B$BNos, Narmban mindig meg lehetett bízni, tehát ez azt jelenti, készen állsz a következő sapta megismerésére -- a tűz saptájára.$B$BMár látom is a szemedben, az égést, a vágyat. Megízlelted a hatalmat, és most készen állsz többre. Türelem, $N. Emlékezz, mit tanított neked a föld. A hatalom és pusztítás könnyen jön, de tudnod kell, mikor kell megállítanod a kezed.' WHERE ID=1523;
UPDATE quest_offer_reward SET RewardText='Á, hibáztam, $N. Elnézést. Nem tudtam, hogy birtokolod a Fáklyát. Örömmel ismerlek meg.$B$BSok kalandozó talál ide elveszett kincset vagy misztikus lényeket keresve, csak hogy elutasítsák őket egy látszólag üres szentélytől. De mi ismerjük az igazságot, nem igaz, $N?$B$BEz a szentély nagyobb titkot rejt a Horda hétköznapi tagjai elől. Számunkra szent hely.' WHERE ID=1524;
UPDATE quest_offer_reward SET RewardText='Ezek pont megfelelnek, $N.$B$BA tűz több, mint káosz és pusztítás -- jól teszed, ha ezt megjegyzed. Az élettel és a teremtéssel is kapcsolatos. Minden dolog így kapcsolódik össze. Az erők szemben állnak egymással, ugyanakkor egyik sem létezhet a másik nélkül. Mindkettő kioltja a másikat, de értelmet is ad egymásnak. Sose feledd ezt.$B$BKülönböző mágiafajták együttes használata nem csak igazi ügyességet, hanem nagy bölcsességet is mutat.' WHERE ID=1525;
UPDATE quest_offer_reward SET RewardText='Fehéren izzó láng gyúl a tálban, ahogy beleteszed a parazsat. Érzed, ahogy a sapta mágikus hatásai átjárják a tested, a tűz pedig ritmikusan táncol előtted.$B$BA fáklya tetejét a medencébe helyezed, és az azonnal lángra kap.' WHERE ID=1526;
UPDATE quest_offer_reward SET RewardText='A lelked fényesebben ég, mint bármelyik fáklya, amit valaha láttam, $N, és ezért büszke lehetsz.$B$BHa folytatod ezen az úton, az elemek a te parancsod alá kerülnek, és testvéreink hozzád fordulnak majd útmutatásért és bölcsességért. Hadd legyek az első, aki gratulál neked, és átadja legújabb totemedet.' WHERE ID=1527;
UPDATE quest_offer_reward SET RewardText='A szél gyorsan közeleg feléd a horizontról; a föld szilárdan áll lábad alatt; és lelkedet már felmelegítette a tűz -- azt mondanám, itt az ideje, hogy megismerd a víz tisztaságát.$B$BUtad idáig vezetett, és lelked erőt ad, hogy még tovább menj. De az első lépést neked kell megtenned.' WHERE ID=1528;
UPDATE quest_offer_reward SET RewardText='A szél gyorsan közeleg feléd a horizontról; a föld szilárdan áll lábad alatt; és lelkedet már felmelegítette a tűz -- azt mondanám, itt az ideje, hogy megismerd a víz tisztaságát.$B$BUtad idáig vezetett, és lelked erőt ad, hogy még tovább menj. De az első lépést neked kell megtenned.' WHERE ID=1529;
UPDATE quest_offer_reward SET RewardText='Igen?$B$BMmm. Van egy olyan érzésem, tudom, mit fogsz kérdezni: mi vehetne rá valakit, hogy itt éljen, a Barrens legmélyén, mindenfelől quilboar fenyegetéssel, védelem nélkül? Nos, mindannyiunknak megvan az oka, ami igazolja, miért cselekszünk úgy, ahogy. Az igazi kérdés, mi hoz egy alantas $R-t a Barrens legmélyebb zugába, hogy beszéljen egy nővel, aki nyilvánvalóan nem törődik a saját jólétével?$B$BFogadni mernék, mindketten tudjuk a választ erre.' WHERE ID=1530;
UPDATE quest_offer_reward SET RewardText='Egyelőre. Megadom neked, amire szükséged van, hogy varázslataidat fókuszáld, és megidézd a levegő szellemeit. Vedd el ezt a totemet, és amikor készen állsz, edzhetünk együtt még.' WHERE ID=1531;
UPDATE quest_offer_reward SET RewardText='Egyelőre. Megadom neked, amire szükséged van, hogy varázslataidat fókuszáld, és megidézd a levegő szellemeit. Vedd el ezt a totemet, és amikor készen állsz, edzhetünk együtt még.' WHERE ID=1532;
UPDATE quest_offer_reward SET RewardText='Csodálatos, $N. Mind a három minta összegyűjtve elkészíthetem neked a legtisztább víz fioláját, amit bármely élőlény találhat. Ezt fogjuk használni beavatási szertartásod következő lépéseiben.$B$BÖrömmel számítalak a fajtánk közé, $N. Büszkévé teszed az összes $c-t, és izgatottan várom, hogy halljak jövőbeli tetteidről.' WHERE ID=1534;
UPDATE quest_offer_reward SET RewardText='Gondoltam, vérontás következhet, ha megpróbálsz vizet venni a tóból. Kár, hogy a quilboarok nem értik meg, hogy minden élőlény összeköttetésben áll; hogy a mohóságuk csak fenntartja saját népük fájdalmát és szenvedését. Mennyit érhetnének el, ha félretennék nézeteltéréseiket, és klánjaik egyesülnének.$B$BIsmét csak kár, de valószínűleg áldás a Barrens többi faja számára.' WHERE ID=1535;
UPDATE quest_offer_reward SET RewardText='Ez jó, $N. Elkötelezett vagy a feladat iránt, és megvan benned a képesség, hogy megkeresd, amire szükség van.$B$BMég egy minta, és minden megvan, amire szükségem van a saptádhoz szükséges alapanyag elkészítéséhez. Islen is elégedett lesz.' WHERE ID=1536;
UPDATE quest_offer_reward SET RewardText='HŰHA - a gát SOKKAL nagyobb volt, mint gondoltam! Alig hallottam a saját hangomat a zubogó víz zajától! Hé, szerinted valaha kifogyhat a vízből? Ember, mi történne, ha az a gát egyszer eltörne! HŰHA, az félelmetes lenne!$B$BKöszönöm, hogy elvittél megnézni a gátat. Ez nagyon kedves volt tőled. Mondtam, hogy nem hajolok ki túlságosan!' WHERE ID=1558;
UPDATE quest_offer_reward SET RewardText='Szóval mérnök vagy, mi? Nos, azért a segítségért, hogy megszerezted nekem azokat a gyöngyöket, itt a vakítóbomba receptje.$b$bSok szerencsét, és próbáld meg nem megvakítani magad!' WHERE ID=1559;
UPDATE quest_offer_reward SET RewardText='Szóval nem talált vissza egyedül? Gondolhattam volna.$B$BNos, gondolom, kiérdemeltél valamit a fáradozásodért...' WHERE ID=1560;
UPDATE quest_offer_reward SET RewardText='Á, elnézést! Nem tudtam, hogy azért jöttél, hogy segíts újra ellátni a csapatainkat. Amit készítettél, nagy segítség lesz!$B$BItt vannak néhány páncél tervei. Remélem, hasznosnak találod őket.' WHERE ID=1578;
UPDATE quest_offer_reward SET RewardText='Nem hiszem el, hogy megtaláltad őket! Biztos te vagy a legszerencsésebb $R Kalimdorban!' WHERE ID=1579;
UPDATE quest_offer_reward SET RewardText='Nem hiszem el! Megtaláltad őket! Te vagy a legjobb horgász, akit valaha láttam!$b$bKöszönöm, $N. És tessék, vedd el ezeket. Bár olyan jó vagy, hogy valószínűleg nincs is rájuk szükséged, segíteni fognak a horgászatban.' WHERE ID=1580;
UPDATE quest_offer_reward SET RewardText='Ezek szépen ki vannak keverve. Nagy gondot fordítasz a mesterségedre, $N, és ez fontos egy alkimistának.$b$bItt vannak a füveid, frissen gyűjtve. Használd őket jól.' WHERE ID=1581;
UPDATE quest_offer_reward SET RewardText='Igen, ezek jó darabok. Ügyes kezed van, és van szemed a részletekhez. Jövőd bőrművesként ígéretes.$B$BTessék, $N. Hadd mutassam meg a Moonglow Mellény mintáját.' WHERE ID=1582;
UPDATE quest_offer_reward SET RewardText='Kiváló... Sosem tudtam hozzáférni ehhez a szöveghez, a könyvtár egy védett szárnyában őrizték, ahol gyanúsnak tűnt volna, ha ott ácsorgok.$B$BNos, jó munkát végeztél, hogy megszerezted ezt, és meg vagyok győződve róla, hogy valószínűleg elbírsz a saját impeddel, szóval nincs okom, hogy ne mutassam meg neked, hogyan idézz meg egyet.' WHERE ID=1598;
UPDATE quest_offer_reward SET RewardText='Nagyon jó, nagyon jó! Jó munkát végeztél, $N. Talán mégis megérdemelt az irántad mutatott érdeklődés.$B$BEz majd a többiek dolga lesz eldönteni -- feltéve, hogy az imped nem kerekedik feléd, és nem töri derékba a karrieredet csírájában. Egyelőre elégedett vagyok, hogy valószínűleg túléled az első pár hónapodat $c-ként.$B$BEgy szót az impről, $N. Ahogy egy $R tudja, ne hagyd, hogy a mérete megtévesszen, a mágiája nagyon veszélyes lehet.' WHERE ID=1599;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Ez rendkívül sokat segít nekem. Mivel a Blackrock orkok Stonewatch Keepből támadnak, a Redridge gnollok pedig az északi domboldalakon ólálkodnak, folyamatosan páncélokat javítok és új fegyvereket készítek csapatainknak.$B$BA hozott készletek egy pillanatnyi nyugalmat adnak nekem. Lesz elég időm, hogy tanítsak neked valamit...' WHERE ID=1618;
UPDATE quest_offer_reward SET RewardText='Ohó! Igyál velem, $N. Kívülről keménynek tűnsz, de lássuk, bírja-e a gyomrod a Pig and Whistle legerősebb sörét, néhány korsóval!!$B$BVagy... leckéért jöttél?' WHERE ID=1638;
UPDATE quest_offer_reward SET RewardText='Üdv, elegáns $gfiú:lány;! Mit keres egy ilyen finnyás jószág a Pig and Whistle-ban? Vigyázz, még beletörhet a körmöd...' WHERE ID=1639;
UPDATE quest_offer_reward SET RewardText='Sokkal keményebb vagy, mint amilyennek látszol!' WHERE ID=1640;
UPDATE quest_offer_reward SET RewardText='Itt, Stormwindben az én feladatom, hogy a lovagokat a nagyobb erény útjára tereljem, ahogy a Fénynek szentelik magukat, és megvédik Azerotht a Scourge-tól és más fenyegetésektől.$B$BEljött az idő, hogy megtedd első lépésed az igaz erény felé. Ha elfogadod, adok neked egy Isteniség Könyvét. Tanulmányozva megtudsz valamit a Fényről, és arról, mit várnak el tőled. Ha megérted, és képes vagy rá, akkor sikerülni fog nagyobb képességekre szert tenned.' WHERE ID=1641;
UPDATE quest_offer_reward SET RewardText='Üdv újra, $N. Hogy haladnak az Isteniség Kódexének tanulmányai?$B$BAkkor fel kell készülnöd, hogy próbára tegyenek. Mindig van tennivaló szerte a városban és földjeinken; könyörületesség és megértés cselekedetei; emberek, akiknek segítségre van szükségük; lények, akiket le kell győzni.$B$BAzzal, hogy bebizonyítod, van türelmed segíteni másoknak, különösen a kevésbé szerencséseknek, bizonyítod, hogy a Fény szolgája vagy, józan ésszel.' WHERE ID=1642;
UPDATE quest_offer_reward SET RewardText='Ó, üdv, drágám. Hogy haladnak a kalandjaid? Ó, örülök, hogy jól megy a sorod.$B$BÓ, én? Köszönöm, hogy kérdezed -- jól vagyok, mindent egybevetve.$B$BA kereskedők számának növekedése kicsit visszafogta, mennyi bőrtől és vászontól hajlandóak megválni az emberek manapság, így nehezebb ruhát készíteni az árvaház gyerekeinek, de majd megoldjuk. „Mi” alatt a férjemet és magamat értem. Ő fent van Ironforge-ban, és próbál segítséget kérni az ottani polgároktól.' WHERE ID=1643;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N, nagyon köszönöm!$B$BA gyerekek nagyon örülni fognak, és rengeteg időt spóroltál meg nekem. Most a gyerekek egyéb szükségleteire tudok koncentrálni, és remélhetőleg Johnom hamarabb hazatérhet, mint gondoltuk.$B$BKöszönöm még egyszer, $N. Tudtam, hogy számíthatok mások jótékonyságára. A Fény legyen veled.' WHERE ID=1644;
-- quest_offer_reward.RewardText. Batch 28: quest IDs 1645-1713.

UPDATE quest_offer_reward SET RewardText='Itt, Ironforge-ban az én feladatom, hogy a lovagokat a nagyobb erény útjára tereljem, ahogy a Fénynek szentelik magukat, és megvédik Azerotht a Scourge-tól és más fenyegetésektől.$B$BEljött az idő, hogy megtedd első lépésed az igaz erény felé. Ha elfogadod, adok neked egy Isteniség Könyvét. Tanulmányozva megtudsz valamit a Fényről, és arról, mit várnak el tőled. Ha megérted, és képes vagy rá, akkor sikerülni fog nagyobb képességekre szert tenned.' WHERE ID=1645;
UPDATE quest_offer_reward SET RewardText='Üdv újra, $N. Remélem, időt szántál a könyv elolvasására?$B$BAkkor fel kell készülnöd, hogy próbára tegyenek. Mindig van tennivaló szerte a városban és földjeinken; könyörületesség és megértés cselekedetei; emberek, akiknek segítségre van szükségük; lények, akiket le kell győzni.$B$BAzzal, hogy bebizonyítod, van türelmed segíteni másoknak, különösen a kevésbé szerencséseknek, bizonyítod, hogy a Fény szolgája vagy, józan ésszel.' WHERE ID=1646;
UPDATE quest_offer_reward SET RewardText='STORMWIND ÁRVAH... ó, elnézést, nem akartam önre kiabálni, uram.$B$BJohn Turner vagyok. Hogy s mint?$B$BJó, jó, örülök hallani, hogy jól alakulnak a dolgai. Már egy hosszú munkanapon vagyok túl, és rettenetesen hiányzik a feleségem, de ez az ára annak, ha éhes szájakat kell etetni és mezítelen hátakat felöltöztetni.' WHERE ID=1647;
UPDATE quest_offer_reward SET RewardText='Ez annyira csodálatos tőled, $N. Köszönöm még egyszer.$B$BNemes ember vagy, hogy ezt megtetted értem. Nem csoda, hogy a Fény követését választottad. Bárcsak lenne mód, hogy viszonozzam mindazt, amit tettél... mi az? Ez volt a legkevesebb, amit tehettél? Látod? Erről beszélek, $N, nemes a végsőkig.$B$BLégy óvatos, és a Fény óvjon utazásaidon.' WHERE ID=1648;
UPDATE quest_offer_reward SET RewardText='Á, egy vitézségi próbáért folyamodsz hozzám. Pompás.$B$BSok kihívást rejtő feladat van szerte a városban és a környező földeken, és jól jönne egy hozzád hasonló képességű ember.$B$BEzt a próbát nem szabad félvállról venni, $N. Ez, akárcsak sok minden az utunk során, az életünkbe kerülhet. Az Egyház mindig meg akarja erősíteni sorait, de megérti azokat az áldozatokat, amik szükségesek ahhoz, hogy a szolgáló lovagok méltóak legyenek.$B$BFelkészültél?' WHERE ID=1649;
UPDATE quest_offer_reward SET RewardText='Üdv, $N. Gondolom, abból a páncélból és fegyverből ítélve, vagy azért jöttél, hogy elvedd a földemet, vagy az Egyház végre küldött valakit, hogy megvédjen, amíg Jordanem távol van.$B$BNos, hadd mutatkozzam be: Daphne Stilwell vagyok. Örvendek.$B$BNem érkeztél túl későn... csak fél tucat söpredéket öltem meg tegnap napfelkelte óta. Kicsit lassan kerülnek elő ott fenn a kanyar mögül, de valószínűleg megláttak téged jönni, ami azt jelenti, bármelyik pillanatban itt lehetnek.' WHERE ID=1650;
UPDATE quest_offer_reward SET RewardText='Sikerült, $N! Köszönöm a segítséged. Igazán elképesztő voltál odakint. Sosem gondoltam volna, hogy egy $c ennyi ellenséggel bír el egyszerre.$B$BValóban bátorságot mutattál a túlerővel szemben.' WHERE ID=1651;
UPDATE quest_offer_reward SET RewardText='Szóval újra találkozunk, $N, és látom, jó kedved van.$B$BA Stilwell otthon még egy napig biztonságban lesz, és a történetedből látom, nem volt hiány veszélyből. Szép munka.$B$BDaphne és Jordan sokat segített az Egyháznak, és az, hogy megvédted a tulajdonukat -- és az életüket --, a legkevesebb volt, amit tehettünk értük.$B$BVitézségedért jutalmat kapsz.' WHERE ID=1652;
UPDATE quest_offer_reward SET RewardText='Szép napot, $N. A Fény veled van, remélem?$b$bMi az? Duthorian küldött?! A feleségem, hogy van? Tudtam, hogy baj lesz, ha elmegyek. Kérlek, mondd, hogy ő... ó, hála az égnek. Nagyon örülök, hogy biztonságban van. A Defias már jóval ezek a támadások előtt is fenyegetést jelentett, de most már a Király tanácsadói sem tagadhatják.$b$bMit mondott még Duthorian?$b$bTe vagy az, akit a feleségem védelmére küldtek? Akkor még egyszer köszönöm, $N. Jobb vitézségi próbát el sem tudnék képzelni ennél.' WHERE ID=1653;
UPDATE quest_offer_reward SET RewardText='Ez csodálatos! Megszerezted az összes tárgyat.$B$BNem lesz gondom egy nagyszerű fegyvert kovácsolni ezekkel. Már egy ideje megvoltak hozzá a terveim. Csak sosem volt alkalmam összegyűjteni az anyagokat. Köszönöm, $N.$B$BJó érzés, hogy megint apám kalapácsa van nálam... és egy Kor drágakő. Sosem gondoltam volna, hogy magam is látok ilyet.' WHERE ID=1654;
UPDATE quest_offer_reward SET RewardText='Ja, ja, ez az. Ha! Ha tudtam volna, hogy tényleg odamész, hogy megküzdj néhány ogréval, adtam volna neked egy egész listát, nem csak ezt az egy dolgot. De nem az én üzletemért vagy itt, igaz?$B$BEgy alku az alku; Jordan egy ötvözetszállítmányt akart tőlem, azt is kapja.$B$BÜdvözöld őket a nevemben, és légy óvatos, $c.' WHERE ID=1655;
UPDATE quest_offer_reward SET RewardText='Á, a szőrmék, amiket vártam. Köszönöm.$B$BEzek hamarabb érkeztek, mint vártam. Jó takarókat készítünk belőlük bárkinek, aki itt szeretne maradni.$B$BÉrezd magad otthon, maradj, ameddig csak akarsz. A fogadóm mindig nyitva áll, és minden népünk tagját szívesen látjuk itt. És ne becsüld alá egy jó éjszakai pihenést, nagy különbséget tehet, amíg úton vagy.' WHERE ID=1656;
UPDATE quest_offer_reward SET RewardText='Á, szép munka! Remélem, a Szövetség megfullad az undorító ajándéktól, amit adtunk nekik, ahogy minket is a Scourge rabigája fojtogatott!$B$BHűek maradtál a Hallow''s End eszméihez, $N, és ezért tisztelgek előtted. Extra bónuszként hadd osszak meg veled néhány Hallow''s End csemegét, amim van. Azt hiszem, egészen élvezetes időtöltésnek fogod találni!' WHERE ID=1657;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N. A Wickerman Fesztivál mindaddig gond lesz, amíg az utálatos Forsaken kísértheti Lordaeron maradványait. Ez NEM méltó tisztelgés az egykor büszke királyság előtt, elhiheted...$B$BItt egy kis pénz bármilyen javításhoz, amire szükséged lehet, és az ünnep szellemében néhány csemegét is mellékeltem, amiket talán szeretsz. Boldog Hallow''s Endet -- tartsuk ezt a lehető legbiztonságosabban itt, Southshore-ban.' WHERE ID=1658;
UPDATE quest_offer_reward SET RewardText='Gratulálok, és a Fény óvjon.' WHERE ID=1661;
UPDATE quest_offer_reward SET RewardText='Hát itt van! Bizony nem akart megválni tőle, de meggyőző voltál. Szép munka.$B$BMost pedig jöjjön a leckéd...' WHERE ID=1665;
UPDATE quest_offer_reward SET RewardText='Ki az ott?$B$BBurlguard, te vagy az?$B$BLépj egy kicsit közelebb. A szemem már nem a régi.$B$BAhogy úgy közeledtél, azt hittem, egy gnoll vagy!' WHERE ID=1666;
UPDATE quest_offer_reward SET RewardText='Remek, megtaláltad! Attól féltem, örökre elveszett, hogy a Defias felhasználja egy stormwindi tisztviselő megszemélyesítésére. Nos, ez most már nem történik meg, hála neked.$B$BItt van néhány fegyver, amiket akkor használtam, amikor Marshal voltam. Kiváló állapotban tartottam őket -- válassz kedvedre!' WHERE ID=1667;
UPDATE quest_offer_reward SET RewardText='Vejrek bizony egy csúnya fickó volt, mi? Szép munka, $N! Megvan benned, ami kell, most pedig kezdjük a leckédet...$b$bTalán nem tudod, de egy erős védekezés nagyon fontos egy $c számára. Ez tartja talpon olyan ellenfelekkel szemben, akik másokat ledöntenének, és pont erre van szüksége a szövetségeseidnek.' WHERE ID=1678;
UPDATE quest_offer_reward SET RewardText='Á, $N. Hallottam, ahogy Dun Morogh harcosai a nevedet emlegetik. Remélem, nem az összes időd a sörfőzdékben töltötted!' WHERE ID=1679;
UPDATE quest_offer_reward SET RewardText='Muren küldött, igaz? Igen, tudok neked egy szép fegyvert készíteni... de mielőtt megtenném, van egy szívességem, amit kérnék tőled.$b$bNe aggódj. Kellően veszélyes, és akár a halálodat is jelentheti; pontosan az a fajta munka, amit egy $c akar.' WHERE ID=1680;
UPDATE quest_offer_reward SET RewardText='Megtaláltad! Szép munka!$b$bRemélem, sok Dark Iron törpét öltél meg kutatás közben. Attól tartok, Ironband telepe nem lesz az utolsó hely, ahol velük találkozunk.$b$bDe köszönöm az ércet, $N. Alig várom, hogy megmunkáljam, és felfedezzem a tulajdonságait.' WHERE ID=1681;
UPDATE quest_offer_reward SET RewardText='Itt van néhány fegyver, frissen az üllőről, az újonnan hozott árnyékérccel készítve!$B$BKérlek, $N, válassz kedvedre!' WHERE ID=1682;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N. Jó tudni, hogy Vorlus legyőzve, holdkutunk pedig megtisztítva, és jó látni fiatal harcosokat, akik lelkesen tartják szeretett Teldrassilunkat megrontástól mentesen.$B$BMost pedig kezdjük el a kiképzésedet...' WHERE ID=1683;
UPDATE quest_offer_reward SET RewardText='Üdvözöllek, $N. A neved hangosan cseng Darnassusban, hiszen ígéretesnek mutatkozol. De hamarosan meglátjuk, van-e elég akaraterőd, hogy kövesd a $c útját.' WHERE ID=1684;
UPDATE quest_offer_reward SET RewardText='Épp ideje volt, hogy felbukkanj. Bár talán valakit ügyesebbet kellett volna küldenem Remennél, hogy megtaláljon.$B$BNem számít.$B$BTúl sokáig voltál kiképzés nélkül, és egy kiképzés nélküli warlock nem valószínű, hogy sokáig tartja a fejét a vállán.' WHERE ID=1685;
UPDATE quest_offer_reward SET RewardText='Bátran tetted, $N.$B$BMegadtad Elura Árnyékának a megérdemelt békét, és az összegyűjtött elunitból finom fegyvert készítünk neked.' WHERE ID=1686;
UPDATE quest_offer_reward SET RewardText='HŰHA, ez egy valódi szellem volt! Ez annyira szuper volt - alig várom, hogy elmeséljem mindenkinek otthon, az árvaházban. Grayson kapitány... még kalóznak is nézett ki! Ha felnövök, én is szellemkalóz akarok lenni!$B$BKöszönöm, hogy elvittél Westfallba, $N. Tudom, hogy vannak ijesztő dolgok odakint Westfall vadonjában, és remélem, nem voltam túl nagy teher. Szuper vagy!' WHERE ID=1687;
UPDATE quest_offer_reward SET RewardText='Surena tehetséges volt, de nem eléggé ahhoz, hogy egyedül elsajátítsa a $c mágiáját. Kár a tehetség pazarlásáért, de néha szükséges.$B$BRemélem, a beléd fektetett befektetésem más eredményt hoz.' WHERE ID=1688;
UPDATE quest_offer_reward SET RewardText='Jobban teljesítettél, mint vártam, $N, de pontosan úgy, ahogy reméltem. Most megtanulhatod irányítani leigázott voidwalkeredet, egy szövetségest, aki hasznosnak bizonyul majd a rád váró próbákban.$B$BJelenleg nincs több tanítanivalóm számodra, de messze nem végeztem veled, $N.' WHERE ID=1689;
UPDATE quest_offer_reward SET RewardText='Ezt nevezem hatékonyságnak! Sikerült annyira megritkítanod a nomádok számát, hogy elkezdhetünk gondolkodni azon, hogyan szerezhetjük vissza azokat a vizeskutakat.$B$BA Gadgetzan Vízi Társaság köszöni a segítségedet, de messze nem vagyunk kész azokkal az undorító nomádokkal.  Figyelj jól -- itt van, mire van szükségünk legközelebb...' WHERE ID=1690;
UPDATE quest_offer_reward SET RewardText='Elsőrangú munka, $N... elsőrangú! Annyira megritkítottad a nomádok létszámát, hogy immár mi is támadásba lendülhetünk ellenük!$b$bHa még nem tetted, beszélj Luglunket csapkezelővel itt; jutalmat ad bármelyik Wastewander vizestömlőért, amivel esetleg találkoztál, amíg igazságot szolgáltattál a nomádoknak!' WHERE ID=1691;
UPDATE quest_offer_reward SET RewardText='Á, elunit érc. Kiváló fém ez, amivel dolgozni lehet, hiszen maga Elune istennő áldotta meg. Megtiszteltetés lenne fegyvereket kovácsolni belőle.$B$BKérlek, várj, amíg dolgozom...' WHERE ID=1692;
UPDATE quest_offer_reward SET RewardText='$N, ezeket a fegyvereket az elunitból kovácsoltam, amit hoztál nekem. Kérlek, vedd el, amelyik leginkább megfelel neked.$B$BÉs köszönöm neked. Az elunittal dolgozni megtiszteltetés és öröm egyben.' WHERE ID=1693;
UPDATE quest_offer_reward SET RewardText='Hah! Szóval hallottál a kihívásomról, mi?$B$BNos, ülj le, és hallgass. Igyál egy italt, és élvezd... mert lehet, hogy ez az utolsó.' WHERE ID=1698;
UPDATE quest_offer_reward SET RewardText='Sikerült! Szép munka! Háromszoros éljen $N-nek!' WHERE ID=1699;
UPDATE quest_offer_reward SET RewardText='Furen írta ezt? Hogy merészelte! Hiszen mindent én tanítottam neki, amit tud! Az a gondolat, hogy ő taníthatna nekem valamit, felháborító! Felháborító!$B$BHm... de van valami a jegyzeteiben, amit kipróbálnék...' WHERE ID=1700;
UPDATE quest_offer_reward SET RewardText='Mindent megszereztél? Elképesztő! Attól féltem, azok a kiméra egészen biztosan felfalnak!$B$BNos, kezdjünk hozzá a páncélhoz...' WHERE ID=1701;
UPDATE quest_offer_reward SET RewardText='Á, Barleybrew Scalder. Remek cucc! Szóval jártál Yorusnál, mi?$B$BSzerezhetek neked egy pajzsot, bizony, uram! Ennél jobbat nem találsz, és ez nem hazugság!' WHERE ID=1702;
UPDATE quest_offer_reward SET RewardText='Ezek érdekesek, valóban nagyon érdekesek. Törpe kollégám, Furen, egészen nagyszerű felfedezést tett!$B$BKöszönöm, $N. Megtiszteltetés lesz az ő új technikáit a saját munkáimra alkalmazni.' WHERE ID=1703;
UPDATE quest_offer_reward SET RewardText='Egek! Ezek a jegyzetek elképesztőek! És ami még jobb... hihetetlenek, bámulatosak, és egészen remegővé teszik a térdemet!$B$BFuren áttörést ért el! Valódi áttörést! Alig várom, hogy kipróbáljam az új technikáját!' WHERE ID=1704;
UPDATE quest_offer_reward SET RewardText='Szép munka! Most pedig, ha megbocsátasz, nekem is van egy kis dolgom...' WHERE ID=1705;
UPDATE quest_offer_reward SET RewardText='Alig hiszem el! Furen technikája sikeres volt, és ennek a páncélnak hatalmas terhelést kell kibírnia.$b$bTessék, $N. És köszönöm. Nem hittem volna el Furen felfedezését, ha nem gyűjtöd össze az anyagokat, amikre szükségem volt, hogy magam is kipróbáljam.' WHERE ID=1706;
UPDATE quest_offer_reward SET RewardText='Kiváló -- minél több vizestömlőt sikerül visszaszereznünk, annál messzebb kerülünk a katasztrófától!  Csak hozd tovább, és minden öt vizestömlőért, amit hozol, biztosan megjutalmazlak.' WHERE ID=1707;
UPDATE quest_offer_reward SET RewardText='Ez az! Szép munka! Most hadd olvasszam meg és kalapáljam ki, hogy alkalmazhassam Furen technikáját a sajátommal, és lássuk, mi történik!$B$BEgek, egek! Csak tudom, hogy a páncél nagyon-nagyon-nagyon erős lesz!' WHERE ID=1708;
UPDATE quest_offer_reward SET RewardText='Itt a páncélod, $N. Furen módszere zseniálisan működött! Tökéletesen! Csodálatosan, tényleg!$B$BEzen a páncélon átgázolhatna egy ostromgép, és rögtön visszapattanna eredeti formájába!' WHERE ID=1709;
UPDATE quest_offer_reward SET RewardText='Á, köszönöm. Ezek pompásan fognak beválni!$B$BAzonnal nekilátok a páncél elkészítésének...' WHERE ID=1710;
UPDATE quest_offer_reward SET RewardText='Elkészültem a páncéloddal, és nagyon elégedett vagyok. Furen új technikái tökéletesen összeillettek a sajátommal, és biztos vagyok benne, hogy ez a páncél igen ellenállónak bizonyul majd.$B$BKöszönöm, $N. És szolgáljon jól a jövőbeli csatákban.' WHERE ID=1711;
UPDATE quest_offer_reward SET RewardText='Összegyűjtötted a varázslatomhoz szükséges tárgyakat, és megmutattad erődet és ravaszságodat. De küldetésünk következő szakasza még veszélyesebb.$b$bReméljük, erőd nem inog meg.' WHERE ID=1712;
UPDATE quest_offer_reward SET RewardText='Sikerült! Legyőzted Cycloniant, és megszerezted a Forgószél Szívét!' WHERE ID=1713;
-- quest_offer_reward.RewardText. Batch 29: quest IDs 1714-1841.

UPDATE quest_offer_reward SET RewardText='A talizmánok lassan lesüllyednek az üst mélyére...$B$BEgy nagy buborék emelkedik a folyadék felszínére, majd szétpattan...$B$B...És egy örvénylő, olvadt kőzetdarab tárul fel.' WHERE ID=1714;
UPDATE quest_offer_reward SET RewardText='Blackwrench küldött, igaz? Az átkozott warlockoknak Ironforge-ban rendezniük kell a dolgaikat. Csak korlátozott a hely és a tanárok száma Stormwindben. A megnövekedett forgalommal biztosan felkeltjük valaki figyelmét, előbb-utóbb.' WHERE ID=1715;
UPDATE quest_offer_reward SET RewardText='Nehéz volt az átkelésed, $N? Hosszú utat tettél meg, hogy beszélj velem. De ne félj, tudom, miért küldött Gakin, és bölcsen tette, mert segíthetek a kutatásodban.' WHERE ID=1716;
UPDATE quest_offer_reward SET RewardText='Épp ideje volt, hogy felbukkanj. Bár talán valakit ügyesebbet kellett volna küldenem Remennél, hogy megtaláljon.$B$BNem számít.$B$BTúl sokáig voltál kiképzés nélkül, és egy kiképzés nélküli warlock nem valószínű, hogy sokáig tartja a fejét a vállán.' WHERE ID=1717;
UPDATE quest_offer_reward SET RewardText='Üdv, $N. Jó látni, hogy sikerült eljutnod Fray Islandre. Remélem, ínyedre lesz...' WHERE ID=1718;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N. Sikeresen teljesítetted a Csetepatét!$B$BMéltó harcos vagy, és megtiszteltetés, hogy taníthatlak...' WHERE ID=1719;
UPDATE quest_offer_reward SET RewardText='Igen, ez pont megfelel, csak hadd dolgozzam vele egy pillanatig...$B$BTakar valóban leleményes fickó, nem igaz? Bárcsak rá tudnám beszélni, hogy térjen vissza a civilizációba.' WHERE ID=1738;
UPDATE quest_offer_reward SET RewardText='Szép munka, szép munka, $N. Látom, jól döntöttünk, amikor a kiképzésed mellett döntöttünk. A teljesítményed egyáltalán nem okoz csalódást.$B$BSemmi kétségem afelől, hogy megmutassam neked, hogyan irányítsd újonnan megkötött succubusodat. Figyelj alaposan.' WHERE ID=1739;
UPDATE quest_offer_reward SET RewardText='Igen... Az orb nem tört szét nagyon, és szinte minden darabja itt van. Egyszerű dolog lesz újra összeállítani, hogy Soran''ruk ismét egésszé váljon.$B$BAz életemet a Burning Legion orbjainak és azok újraalkotásának tanulmányozására szenteltem. Szívességet tettél nekem azzal, hogy összegyűjtötted ezeket a darabokat tanulmányozásra, és visszaadom neked -- teljesen újjáépítve -- olyan formában, amilyet választasz.' WHERE ID=1740;
UPDATE quest_offer_reward SET RewardText='A Kabál Kódexe? Hmm... ismerősen hangzik. Bár még sosem láttam itt -- és hidd el, minden könyvre emlékszem, amit olvastam.$B$BHmm... Á, igen!$B$BLáttam már hivatkozást rá könyvtári katalogizáló könyvekben.' WHERE ID=1758;
UPDATE quest_offer_reward SET RewardText='Szóval ilyen gyorsan visszatértél, mi? És áruld el, mit értél el, amíg távol voltál innen?$B$BSikerült egy nemes ügynek segítened? Talán megtanultad a jótékonyság értékét, vagy még többet Azeroth polgárai iránti kötelezettségeidről. Mondd el, kinek segítettél, és hogyan... Lenyűgöző, $N, ezek biztosan a Fényt követő ember tettei.$B$BAz ilyen áldozatvállalás mindig jutalmat kap idővel.' WHERE ID=1778;
UPDATE quest_offer_reward SET RewardText='*köhög*$B$BSzép napot, $c. Ne törődj a sebeimmel, a jó pap majd ellátja az öreg Muiredont idővel. Egyelőre nincs szükségem az Élet Jelképének erejére, amit ott hoztál.$B$BSzóval a feleségem küldött hozzám, hogy beszéljek veled, mi? Rendben. Szánok rá időt -- elmondom pontosan, mi történt Muiredonnal és legjobb barátjával, Narmmal, egy $c-vel, akárcsak te.' WHERE ID=1779;
UPDATE quest_offer_reward SET RewardText='Ilyen gyorsan visszatértél, $N. És mit értél el, amíg távol voltál a Katedrálistól?$B$BSegítettél egy nemes ügyet? Talán megtanultad a jótékonyság értékét, vagy még többet Azeroth polgárai iránti kötelezettségeidről. Mondd el, kinek segítettél, és hogyan... Nos, lenyűgözött, $N, ezek biztosan a Fényt követő és mások érdekeit önmaga fölé helyező ember tettei.$B$BAz ilyen áldozatvállalás mindig jutalmat kap idővel.' WHERE ID=1780;
UPDATE quest_offer_reward SET RewardText='*köhög*$B$BÖrülök, hogy megismerhetlek, $R. Ne törődj a sebeimmel, a jó pap majd ellátja az öreg Gazint ezúttal. Nem lesz szükségem az Élet Jelképének erejére, amit ott hoztál... legalábbis még nem.$B$BSzóval Duthorian küldött, hogy beszélj velem, mi? Rendben. Elmondom pontosan, mi történt velem és barátommal, Henzével. És egy kis szerencsével, és némi ügyességgel a részedről, talán még segíthetsz mindannyiunknak.' WHERE ID=1781;
UPDATE quest_offer_reward SET RewardText='Itt a páncélod, $N. Ez kiállja a legerősebb támadásokat is, vagy nem Furen Longbeard a nevem!$B$BÉs köszönettel tartozom neked. Sokat tanultam, miközben az anyagokkal dolgoztam,$Bamiket hoztál nekem. Azt hiszem, egy napon lesz még egy áttörésem!$B$BElküldöm, amit megtanultam, a Szövetség többi$Bkovácsának.$B$BElmondom nekik, hogy nagy segítségemre voltál, és talán ők is szeretnék majd viszonozni.' WHERE ID=1782;
UPDATE quest_offer_reward SET RewardText='Sosem tudlak eléggé megköszönni, $gtestvér:testvér;.$B$BCsak feltételezhetem, hogy Tiza és Muiredon küldött ide, hogy segíts nekem, ha nálad van az Élet Jelképe.$B$BIgaz, elestem a Dark Ironoktól, miközben az egyik iratot próbáltam megszerezni: elég sokáig ki tudtam tartani ahhoz, hogy Muiredon elmenekülhessen, de a Fény már szinte teljesen magába ölelt, amikor megjöttél. Az, hogy elég erős voltál a Jelkép használatához, nagy dolgokat jelent számodra, de erről majd később beszélünk.' WHERE ID=1783;
UPDATE quest_offer_reward SET RewardText='Haha! Sikerült! Megmentetted Narmot, és megtaláltad a bizonyítékot, amit a feleségem elvihet a tanácshoz. Igazi áldása vagy a Fénynek, ha valaha is láttam ilyet... a feleségemet leszámítva persze.$B$BKöszönöm még egyszer, $N.' WHERE ID=1784;
UPDATE quest_offer_reward SET RewardText='Nagy szolgálatot tettél ma egész Ironforge-nak, $N. Büszke vagyok, hogy közénk számíthatlak, és ha úgy érzed, készen állsz, szeretnélek megáldani ezzel a tekerccsel. Az Élet Jelképe csak akkor működött volna, ha egy olyan $c használja, aki készen áll a Fény egyik legnagyobb áldására -- az erőre, hogy visszaadja a holtaknak az életet.$B$BMegtanítom neked a képességet, hogy feltámaszd társaidat. Használd bölcsen, $N, és köszönöm, a magam, a férjem és Ironforge nevében.' WHERE ID=1785;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $Gtestvér:testvér;.$B$BLátva, hogy az Élet Jelképét forgatod, feltételezhetem, hogy Duthorian vagy Gazin küldött?$B$BElestem a Defias varázslóitól, miközben Gazinnal próbáltuk megszerezni a terveiket: elég sokáig ki tudtam tartani ahhoz, hogy Gazin elmenekülhessen, de végül a mágiájuk legyűrt.$B$BDe sikerült visszahoznod: a Jelkép használatának képessége nem mindenkinek adatik meg, $N. Jó jel számodra, hogy a saját hiteddel tudtad megtölteni erővel.' WHERE ID=1786;
UPDATE quest_offer_reward SET RewardText='Csodálatos! Sikerült, és megmentetted Henzét. A Fény bizonyosan veled van, $N!' WHERE ID=1787;
UPDATE quest_offer_reward SET RewardText='Jó munkát végeztél ma, $N. Büszkének kell lenned arra, amit elértél.$B$BMég inkább büszke lehetsz a képességeidre. Nem mindenki tudja használni az Élet Jelképének erejét. Ha a Fényhez fordulsz, hogy visszahozd a holtakat, az azt jelenti, felkészültél a $c egyik legnagyobb megtiszteltetésére: a feltámasztás hatalmára.$B$BKépes leszel visszahozni elesett társaidat, ahogy Henzével is tetted.$B$BLégy jól, $N. A Fény rád ragyog, és teljes szívvel fogadd be.' WHERE ID=1788;
UPDATE quest_offer_reward SET RewardText='Siess, $N, több élet is a mérleg nyelvén van, ha kudarcot vallasz.$B$BHa valamiért nem sikerülne segítened Muiredonnak és Narmnak, gyere vissza hozzám, és adok egy másik Élet Jelképét az utadra.$B$BNe tévesszed a segítségemet egyszerű jótékonyságnak, be kell bizonyítanod, hogy méltó vagy, mint bármelyik másik $c, és a folytonos kudarc később rád vetülhet.' WHERE ID=1789;
UPDATE quest_offer_reward SET RewardText='Siess, $N, több élet is a mérleg nyelvén van, ha kudarcot vallasz.$B$BHa valamiért nem sikerülne segítened Gazinnak és Henzének, gyere vissza hozzám, és adok egy másik Élet Jelképét az utadra.$B$BNe tévesszed a segítségemet egyszerű jótékonyságnak, be kell bizonyítanod, hogy méltó vagy, mint bármelyik másik $c, és a folytonos kudarc később rád vetülhet.' WHERE ID=1790;
UPDATE quest_offer_reward SET RewardText='Messziről jöttél, ifjú $c. Tüzet látok a szemedben. Nagy erejű fegyvert keresel, igaz?$B$BSegíthetek a küldetésedben. És te is segíthetsz az enyémben.' WHERE ID=1791;
UPDATE quest_offer_reward SET RewardText='Nálam van a forgószél szíve, és készen állok, hogy beleépítsem a választott edénybe.$B$BVálaszd ki a fegyveredet, $N, és tudd, hogy ereje Cyclonian ereje.' WHERE ID=1792;
UPDATE quest_offer_reward SET RewardText='Bebizonyosodott, hogy a Fény veled van, $N, de ahogy az idők egyre veszélyesebbé válnak, egyre fontosabbá válik tudni, milyen erő rejlik a hús alatt. Amikor démonok, sárkányok, vagy bármilyen más gonosz lép földjeidre, az állóképességedet próbára teszik. Elég erős leszel?$B$BA bátorság, a helyzettől függetlenül, ugyanannyira része a lovagságnak, mint a Fény, a páncélod és a fegyvered. A gyengék védelme és a hit el nem vesztése két további lecke, amit el kell sajátítanod, amíg a Fény Katedrálisában tanulsz.' WHERE ID=1793;
UPDATE quest_offer_reward SET RewardText='Bebizonyosodott, hogy a Fény veled van, $N, de ahogy az idők egyre veszélyesebbé válnak, egyre fontosabbá válik tudni, milyen erő rejlik a hús alatt. Amikor démonok, sárkányok, vagy bármilyen más gonosz lép földjeidre, az állóképességedet próbára teszik. Elég erős leszel?$B$BA bátorság, a helyzettől függetlenül, ugyanannyira része a lovagságnak, mint a Fény, a páncélod és a fegyvered. A gyengék védelme és a hit el nem vesztése két további lecke, amit el kell sajátítanod, amíg a Fény Katedrálisában tanulsz.' WHERE ID=1794;
UPDATE quest_offer_reward SET RewardText='Meg kell mondanom, lenyűgöztél, $N. Amikor szembeszálltam a saját felhunteremmel, alig menekültem meg élve. Érzem, hogy megvan benned a lehetőség, hogy e kor egyik leghatalmasabb warlockja légy.' WHERE ID=1795;
UPDATE quest_offer_reward SET RewardText='Ez pont megfelel, $N.$B$BMinden mágikus tárgynak magas minőségű alapból kell kiindulnia. Minél több erőfeszítést és ügyességet fektetnek egy tárgyba, annál nagyobb mágiát tud tárolni. A ritka és drágább alapanyagok jobban megtartják a mágiát. Nem fogod megbánni, hogy a köntösökből azt készítjük, amit később kapsz majd.' WHERE ID=1796;
UPDATE quest_offer_reward SET RewardText='$N? Á, persze. Legújabb csodagyerekünk. Attól tartok, a valóság nem tud lépést tartani a legendával.$B$BNem baj, azért jöttél, hogy tanulj, nem azért, hogy meghallgasd, ahogy magamban viccelődöm.' WHERE ID=1798;
UPDATE quest_offer_reward SET RewardText='Ó, szóval Menara küldött. Rendben... gondolom, egyelőre maradhatsz vendégemként. De biztosan sürgős ügyben jársz -- talán elveszett hatalmat keresel? Talán tévedek. Talán a romlás mégsem áll olyan messze tőled.' WHERE ID=1799;
UPDATE quest_offer_reward SET RewardText='Az a trónterem ijesztő volt, $N! Bár üres volt, mégis úgy éreztem, mintha nagy gonoszság történt volna ott. Mérgesnek éreztem magam... de szomorúnak is. Megértem, miért mesélik el nekünk a gondozónők ezeket a történeteket; sosem árulnám el így a népemet!$B$BKöszönöm, hogy elvittél a trónterembe, $N. Sokat tanultam.' WHERE ID=1800;
UPDATE quest_offer_reward SET RewardText='Térképkészítés! Képek, a valóság becslései. Nincs szükségem ilyesmire.$b$bKönyvekben, elbeszélésben, leírásban! Ott rejlik az igazság. Elcserélném az összes térképet ebben a boltban egyetlen könyvért a nekromancia felemelkedéséről, vagy a Dark Lady diadalának történetéért.' WHERE ID=1801;
UPDATE quest_offer_reward SET RewardText='Fantasztikus! Most csatlakozhatok azok kevés soraihoz, akik betekintést nyertek a tartalmába.$B$BAlig várom, hogy alaposabban átnézzem ezt a szöveget. Ez egy nagyszerű nap, $N! Ha megengeded, hogy egy pillantást vessek rá, mielőtt elmész. Biztos vagyok benne, hogy Strahad szívesen küld nekem egy másolatot.' WHERE ID=1802;
UPDATE quest_offer_reward SET RewardText='Nocsak, nocsak! Mit is látunk itt?$B$BEz lenyűgöző, $N. Nem hittem volna, hogy lehetséges, de itt van a saját kezemben, a Kabál Kódexének teljes kiadása.$B$BEngedd meg, hogy egy pillanatra átlapozzam az oldalait, mielőtt újra útnak indulsz.' WHERE ID=1803;
UPDATE quest_offer_reward SET RewardText='Szép munka! A Kabál Kódexe és három makulátlan -- na jó, kissé megkarcolt -- csatornázó pálca.$B$BEz érdekes lesz. Már egy ideje nem próbált egy fiatal $c saját felhuntert szerezni.' WHERE ID=1804;
UPDATE quest_offer_reward SET RewardText='Szép munka! A Kabál Kódexe és három makulátlan -- na jó, kissé megkarcolt -- csatornázó pálca.$B$BEz érdekes lesz. Már egy ideje nem próbált egy fiatal $c saját felhuntert szerezni.' WHERE ID=1805;
UPDATE quest_offer_reward SET RewardText='Íme, $N. Egy fegyver, méltó egy hozzád hasonló, a Fény bajnokához. A barátom, egy nagyszerű törpe lovag után neveztem el. A neve Verigan volt... Bosch Verigan.$B$BKérlek, fogadd el a magam és a feleségem nevében. Nagy adóssággal tartozunk neked, és a világ biztonságosabb hely lesz, ha egy hozzád hasonló képességű valaki járja a földeket.' WHERE ID=1806;
UPDATE quest_offer_reward SET RewardText='Küldetésért jöttél? Jó. Van egy fontos, ami próbára teszi a harci képességedet... és eltökéltségedet a Forsaken védelmében.' WHERE ID=1818;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N. Ulag nem volt a Scourge jelentéktelen ügynöke. Megmutattad a Deathguardoknak, és így a Dark Ladynek is, hogy ügyes és eltökélt $c vagy, méltó a további tanításra.' WHERE ID=1819;
UPDATE quest_offer_reward SET RewardText='Igen, ez igaz. Szükségem van harci képességeidre. Az eszközeim csekélyek, de a feladatom mind engem, mind a Forsaken ügyét szolgálja. Tedd meg, és a jutalmad kétszeres lesz.' WHERE ID=1820;
UPDATE quest_offer_reward SET RewardText='Á! Megszerezted őket! Most az utolsó nyoma is eltűnt a becsületnek és emlékezetnek az átkozott Agamand földekről. A család valóban nincs többé!' WHERE ID=1821;
UPDATE quest_offer_reward SET RewardText='Megtartok három fegyvert, amiket visszahoztál, fájdalmam és veszteségem emlékeként. De kérlek, $N, válaszd ki a kedvenc örökségedet, és tartsd meg magadnak.$B$BSzolgáljon jobban téged, mint egykori, átkozott tulajdonosait szolgálta.' WHERE ID=1822;
UPDATE quest_offer_reward SET RewardText='A próbámért jöttél, $N?' WHERE ID=1823;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N! A Field of Giants-i próba teljesítésével egy lépéssel közelebb kerülsz a $c útjához.' WHERE ID=1824;
UPDATE quest_offer_reward SET RewardText='Igen, eljöttél. Ez jó, mert sok mindent kell megbeszélnünk, te és én.' WHERE ID=1825;
UPDATE quest_offer_reward SET RewardText='Elhoztad mindazt, amit kértem. Most pedig én is megteszem a magamét...' WHERE ID=1838;
UPDATE quest_offer_reward SET RewardText='Üdvözöllek, $N. Az öreg Thun''grim üzent érkezésedről, de ha csendben marad, akkor sem lepett volna meg a jelenléted itt.$B$BA szellemek figyelik előrehaladásodat, ifjú $c, és azt mondják nekem, hogy sok ellenfél esett el előtted.' WHERE ID=1839;
UPDATE quest_offer_reward SET RewardText='Üdvözöllek, $c. Orm vagyok, és Thun''grim szerint sisakot szeretnél készíttetni?' WHERE ID=1840;
UPDATE quest_offer_reward SET RewardText='Lábpáncélért jöttél? Remek!$b$bÖhm... én készítem a páncélt neked, vagy te készíted nekem?$b$bEz vicc volt. Vicces volt? Nem tudom megmondani... a humorérzékemet ugyanakkor vesztettem el, amikor a szaglásomat. Ami nagyjából akkor volt, amikor abbahagytam a légzést.' WHERE ID=1841;
UPDATE quest_offer_reward SET RewardText='Ah, megvannak! Most, ahogy a szatírok kiszívták Ashenvale erejét, én is kiszívom az ezekben a patákban rejlő erőt, és felhasználom a munkámhoz...' WHERE ID=1842;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Ezek a kesztyűk a legjobb munkám. Fogadd el őket. Viselésükkel megtiszteled engem és őseimet.' WHERE ID=1843;
UPDATE quest_offer_reward SET RewardText='Teljesítetted a feladatod, $N, és megmutattad az értékedet és eltökéltségedet. A sisak a tiéd lesz...' WHERE ID=1844;
UPDATE quest_offer_reward SET RewardText='Neked adom ezt a sisakot.$B$BNagy tettek vezettek hozzám, $N, és ha az Anyaföld is úgy akarja... még nagyobb tettek várnak rád.' WHERE ID=1845;
UPDATE quest_offer_reward SET RewardText='Szép munka! Ezek mind erősnek tűnnek. Azt hiszem, remekül megteszik majd. Hogy fogadták az orkok, hogy elvitted a sípcsontjaikat, $N? Sokat panaszkodtak?$B$BEz megint egy vicc volt. Nem nevetsz.$B$BMostanában nem vagyok túl vicces, ugye...' WHERE ID=1846;
UPDATE quest_offer_reward SET RewardText='Itt vannak a lábvértjeid, $N. Szólj, ha jól állnak, vagy ha módosítás kell rajtuk. A célom, hogy elégedett légy! Legalábbis régen az volt.$B$BMostanában nem sokat törődöm a mesterségemmel. De ez még mindig jobb, mint a Csapás agyatlan szolgájának lenni!$B$BAzt hiszem.' WHERE ID=1847;
UPDATE quest_offer_reward SET RewardText='Biztos vagyok benne, hogy sok nehézséget és vért áldoztál a feladatomért, $N. Íme a fáradozásod gyümölcse.$B$BViseld egészséggel, és bár egy nap visszatérj ide, hogy elmeséld, milyen jó szolgálatot tett neked.' WHERE ID=1848;
UPDATE quest_offer_reward SET RewardText='Hmmm, ez érdekes. Ezzel bőven bebizonyítottad az értékedet, $N. Igazán lenyűgöztél. Tekintsd magad a Shattered Hand legújabb tagjának. És fogadd el ezt, azt hiszem, nagy segítségedre lesz a jövőben.' WHERE ID=1858;
UPDATE quest_offer_reward SET RewardText='Nagyon jó, örülök, hogy Kaplak elért téged.$b$bVan miről beszélnünk, nem utolsósorban a Hand-del kapcsolatos jövődről.' WHERE ID=1859;
UPDATE quest_offer_reward SET RewardText='Téged küldtek, hogy segíts a feladatomban, $N? Jó. Örömmel látom, hogy fiatal mágusok is szívesen segítenek az ügyünknek...$b$bMilyen ügyről van szó, kérdezed? Idővel, ifjú. Meg fogod tudni... idővel.' WHERE ID=1860;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Megvizsgálom ezt a vizet mágikus tulajdonságok után kutatva. Reméljük, nem találunk ilyet, különben kiderülhet, hogy akik túl sokáig isznak a Mirror Lake-ből, azokra káros hatással van.$B$BItt van, $N. Fogadd el ezt a gömböt vagy botot szolgálatod jeleként. Szolgáljon jól téged.' WHERE ID=1861;
UPDATE quest_offer_reward SET RewardText='Kitűnő - minél több vizestömlőt sikerül visszaszereznünk, annál messzebb kerülünk a katasztrófától! Csak hozd őket továbbra is, és minden öt vizestömlőért, amit hozol, jutalmat kapsz tőlem.' WHERE ID=1878;
UPDATE quest_offer_reward SET RewardText='Ó, látom, van benned tehetség, bizony van! De ahhoz, hogy jó $c legyél, több kell puszta tehetségnél. És ha nem vagy jó $c, akkor rossz $c vagy. A rossz mágusok pedig részei a problémának, bizony azok!$b$bJaj, elébe vágok a dolgoknak. Kezdjük az elejéről!' WHERE ID=1879;
UPDATE quest_offer_reward SET RewardText='Ó, csodálatos nap! Amikor megépítettem a gizmonitort, nem is gondoltam, mennyire függővé válok tőle. Most újra elkezdhetem a tanulmányaimat!$b$bKöszönöm, $N! És tessék - ezek voltak az első szerszámaim $c koromból. Kicsit megkopottak, de jól bevált eszközök. Válassz - biztos vagyok benne, hogy bármelyiket hasznosnak találod majd.' WHERE ID=1880;
UPDATE quest_offer_reward SET RewardText='Üdvözöllek, $N. Bölcsen tetted, hogy válaszoltál a hívásomra, és még bölcsebben teszel, ha megfogadod, amit most mondok...' WHERE ID=1881;
UPDATE quest_offer_reward SET RewardText='Ah, ez egy remek példány. Elküldöm a patikáriusainknak, hogy tanulmányozzák, és megállapítsák a Plagueland fertőzöttségének mértékét.$B$BSzép munka, $N. Szolgálataidért felajánlom neked ezt a választást: egy gömböt vagy egy botot. Bármelyiket is választod, hasznosnak találod majd.' WHERE ID=1882;
UPDATE quest_offer_reward SET RewardText='Üdv, $N. Dicséret illet, amiért válaszoltál segélykérésemre. Reméljük, megfelelsz a feladatnak...' WHERE ID=1883;
UPDATE quest_offer_reward SET RewardText='Érzem, hogy Zalazane ju-ju halmai megsemmisültek, és idővel, ha szerencsénk van, Durotar mágikus áramlása visszatér a normál kerékvágásba.$b$bNagy tettet vittél véghez a néped javára, $N. És bebizonyítottad az értékedet nekünk, a Horda mágusainak.' WHERE ID=1884;
UPDATE quest_offer_reward SET RewardText='Hm. Kétségtelenül azonnal idesiettél, amint meghallottad a hívásomat, ugye? Természetesen. Nem is várnék kevesebbet egy leendő Deathstalkertől.' WHERE ID=1885;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N. Túljutottál a próba első részén. Reméljük, Andron nem szerzett tudomást a tevékenységedről, és sikerül meggyőznünk arról, hogy valóban te vagy az a hírnök, akit vár.' WHERE ID=1886;
UPDATE quest_offer_reward SET RewardText='Ah, igen, vártalak már. Nem kétlem, hogy közös ismerőseink elégedettek az eddig szolgáltatott információimmal.$B$BGondolom, felesleges is megkérdeznem, kétlem, hogy ilyen tudással terhelnének téged. Miért is bíznának ennyire egy hírnökben, hm?' WHERE ID=1898;
UPDATE quest_offer_reward SET RewardText='Nos, ez bizony több információ, mint amennyit Androntól vártam. Adj egy percet, hogy átnézzem, mielőtt a következő feladatodra küldenélek.' WHERE ID=1899;
UPDATE quest_offer_reward SET RewardText='Találsz egy förtelmes vízgolyót, és úgy döntesz, hozzám hozod? Ki vagyok én, az Earthen Ring vagy mi?$b$bBár, ez ad egy ötletet... talán tényleg az Earthen Ringre van szükséged ehhez. Úgy értem, ha ez véglegesen megoldja a tó helyzetét, akkor teljes mértékben támogatom.$b$bTudod, kicsoda az Earthen Ring, $N?' WHERE ID=1918;
UPDATE quest_offer_reward SET RewardText='$N, van egy küldetésem számodra, itt a $c negyedben. Figyelj jól, mert nincs vesztegetni való idő.' WHERE ID=1919;
UPDATE quest_offer_reward SET RewardText='Nagyon szép munka! Tanulmányozni fogom ezeket a lényeket, és szorgalommal és szerencsével kiderítem, hogyan jutottak be a világunkba.$B$BEgyre nagyobb értéket képviselsz a mágusok társasága számára, $N.' WHERE ID=1920;
UPDATE quest_offer_reward SET RewardText='Igen, ezek remek vászondarabok. Szép köntöst tudok belőlük készíteni. És ha beleszövöm a rift drágaköveket, egy $c-hoz méltó ruhadarabunk lesz!' WHERE ID=1921;
UPDATE quest_offer_reward SET RewardText='Attól féltem, hogy Morganth máshova rejtette a könyvet, vagy módot talált a kinyitására és tartalmának elolvasására.$B$BJó látni, hogy nem így történt, és hogy az „Ur értekezése az árnyékmágiáról” című műre helyezett pecsétjeink még mindig tartanak.' WHERE ID=1938;
UPDATE quest_offer_reward SET RewardText='Üdvözöllek, $N. Örülök, hogy látlak, és remélem, van időd meghallgatni egy öregember szavait...' WHERE ID=1939;
UPDATE quest_offer_reward SET RewardText='Szép példányok ezek. Azonnal munkához látok!' WHERE ID=1940;
UPDATE quest_offer_reward SET RewardText='Itt a köntösöd. Ez az egyik legjobb munkám eddig! Viseld büszkén, és ha kérdezik... mondd, hogy a Larson Clothiers-nál szerezted!' WHERE ID=1941;
UPDATE quest_offer_reward SET RewardText='Elkészült a ruhadarabod! És az a selyem, amit gyűjtöttél, olyan szép volt... nem baj, ha kicsit rövidebbre vettem, hogy maradjon belőle magamnak is, ugye?$B$BCsak viccelek. Tökéletesen fog állni rajtad, és tökéletes lesz kalandokhoz és díszebédekhez egyaránt. Élvezd!' WHERE ID=1942;
UPDATE quest_offer_reward SET RewardText='Jó, hogy eljöttél. A feladatom nem könnyű, de létfontosságú a mágusok társasága számára. Ha segítesz nekem, biztos vagyok benne, hogy megéri majd.' WHERE ID=1943;
UPDATE quest_offer_reward SET RewardText='Ah, nagyon jó. Remélem, a Xavian szatírjai nem okoztak nagy gondot?$B$BKöszönöm, $N. Azonnal tanulmányozni fogom ezt a Xavian-vízmintát.' WHERE ID=1944;
UPDATE quest_offer_reward SET RewardText='Ah, ebből a hajból szép köntöst lehet szőni, $N. Kár, hogy a nevető nővéreknek meg kellett halniuk, hogy megváljanak tőle, bár kétlem, hogy önként odaadták volna.$B$BKár érte, de csak egy kicsit.' WHERE ID=1945;
UPDATE quest_offer_reward SET RewardText='Itt a nether-csipkéd, $N. Kényelmes és tartós egyaránt, és magában hordozza a nevető nővérek hajának mágiáját.$B$BÉlvezd, és ha megfelelőnek találod, kérlek, említsd meg Deinónak. Ő egy olyan $c, akinek a jóindulatát szeretném megtartani...' WHERE ID=1946;
UPDATE quest_offer_reward SET RewardText='Csendet! Kényes pillanatban vagyok, nem szabad zavarni!$B$BEgy pillanat...' WHERE ID=1947;
UPDATE quest_offer_reward SET RewardText='Aha! Megszerezted a jádét, és elkészítetted a tüskebokrot! Szép munka!$B$BAz füst, amit a füledből látok szállni? Talán túl közel voltál, amikor a villám lesújtott a totemrudakra, de ne aggódj. A villámcsapás szerencsét hoz!' WHERE ID=1948;
UPDATE quest_offer_reward SET RewardText='Mi? Beszélj hangosabban! Ezek a vén fülek már nem olyan élesek, mint régen.$B$BNos, remélem, egy friss korsó sörrel jöttél, vagy forró tippekkel a következő versenyről! Ha nem, akkor jobb, ha továbbmész... mert van egy átváltoztató pálcám, amin a te neved áll!' WHERE ID=1949;
UPDATE quest_offer_reward SET RewardText='Ah, most már emlékszem...$B$BElfelejtettem azt a kis átkot, amit Johnsonra helyeztem. Nem emlékszem, miért tettem, de biztos vagyok benne, hogy megérdemelte, a kis hálátlan!' WHERE ID=1950;
UPDATE quest_offer_reward SET RewardText='Ez az! Pontosan erre van szükségem, hogy felkészüljek a szertartásra, amivel elkészítem a pálcádat! Remélem, nem volt túl nagy gond megtalálni...' WHERE ID=1951;
UPDATE quest_offer_reward SET RewardText='Itt vannak a pálcák, amiket készítettem. Válassz közülük!' WHERE ID=1952;
UPDATE quest_offer_reward SET RewardText='Ah, igen. Egy gömbért vagy botért jöttél, $N? Rendben. Segítek elkészíteni.$B$BDe figyelmeztetlek - a folyamat veszélyes, és akár a halálodat is jelentheti.$B$BVagy az enyémet. Biztosan valakinek a halálát...$B$BDe reméljük, hogy másvalakiét, nem igaz?' WHERE ID=1953;
UPDATE quest_offer_reward SET RewardText='Ó, ez egy szép darab! Nem, nem úgy értem, hogy „szép”, mint egy hideg ital egy forró napon.$B$BValójában, ha jobban belegondolok, egyáltalán nem szép. Nem az ital. A gömb!$B$BFigyelj, $N! Koncentrálnod kell, ha valaha be akarjuk fejezni a feladatunkat!' WHERE ID=1954;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N! Olyan leckét adtál annak a démonnak, amit nem felejt el egyhamar.$B$BKétszer is meggondolja, mielőtt visszadugja csúf fejét ebbe a világba, keresve azt az ostoba halandót, aki legyőzte. Valószínűleg legközelebb barátokkal jön. Nagy, pikkelyes barátokkal, akik semmi mást nem akarnának, mint apró $R darabokra tépni téged.$B$BCsak nem ijesztettelek meg, $N?' WHERE ID=1955;
UPDATE quest_offer_reward SET RewardText='Sikerült? Szép munka!$B$BBeszélgettem néhány kollégámmal, és amikor szóba került a neved, azt mondták: „Tudod, az a $N tényleg jól teljesít nyomás alatt!”$B$BDe amikor elmondtam nekik, hogy elküldtelek Uldamanba az obszidián őrszem ellen, azt mondták, megőrültem! Azt mondták: „Tabetha, te megőrültél! $N esélye sincs legyőzni azt az őrszemet!”$B$BÉn meg azt mondtam: „Majd meglátjuk”, mire ők: „Igen, majd meglátjuk...”$B$BNos, alaposan megmutattuk nekik, nem igaz!' WHERE ID=1956;
UPDATE quest_offer_reward SET RewardText='Sikerült! Egy pillanatig sem kételkedtem benned! Nos, talán egy-két pillanatig... de alapvetően nem sok kétségem volt.$B$BŐszintén.' WHERE ID=1957;
UPDATE quest_offer_reward SET RewardText='Büszkének kell lenned magadra, $N. Sok mágus elbukott már azokkal a lényekkel szemben, akikkel szembenéztél.$B$BA Celestial Orb elkészült. Vagy ha szeretnéd, felszerelhetem egy bot tetejére. Rajtad múlik. Én a gömböt választanám, de ki vagyok én, hogy ítélkezzek?' WHERE ID=1958;
UPDATE quest_offer_reward SET RewardText='Igaz. Mágikus zavart észleltünk a városunkban. Még nem vagyunk biztosak az eredetében, sem abban, hogy ártó vagy ártalmatlan-e. Először több információt kell gyűjtenünk...$B$BÉs ez, $N, elvezet minket a te feladatodhoz.' WHERE ID=1959;
UPDATE quest_offer_reward SET RewardText='Nagyon jó, $N. Az ezekben a tárolóládákban lévő lényeket a legkiválóbb elméink fogják tanulmányozni, és megállapítjuk, mi okozza jelenlétüket az Undercityben.$B$BHa megjelenésüket a mágia természetes áramlásának egy szakadása okozza, meg kell állapítanunk, hogy a szakadás véletlen volt-e. Ha nem volt véletlen, hanem valamilyen mágikus erő támadása, akkor fel kell készülnünk a jövőbeli, súlyosabb zavarokra.' WHERE ID=1960;
UPDATE quest_offer_reward SET RewardText='Ez nagyon jó minőségű anyag, és bár nekem nincs meg a tehetségem, hogy felmérjem ezeknek a mana drágaköveknek a minőségét, hamarosan kiderül, hogy megvan-e bennük a szükséges erő a spellfire köntösök elkészítéséhez...' WHERE ID=1961;
UPDATE quest_offer_reward SET RewardText='Itt vannak a köntöseid, $N. Viseld egészséggel.' WHERE ID=1962;
UPDATE quest_offer_reward SET RewardText='Hm, bár örülök, hogy Tazan már nincs köztünk, egy zárt tarisznya semmit sem ér. Szükségünk van a benne őrzött információra.$b$bEz méltó második próba lesz annak, aki csatlakozni kíván a Shattered Hand-hez.' WHERE ID=1963;
UPDATE quest_offer_reward SET RewardText='Hmm, ez érdekes. A Deathstalkerek csodálatra méltóan végezték a feladatukat, hogy ezt kiderítsék.$B$BAmennyire értem, téged is dicséret illet a teljesítményedért. Remélem, ez rutinná válik számodra, $N, a Deathstalkereknek mindig szükségük van egy jó emberre.' WHERE ID=1978;
UPDATE quest_offer_reward SET RewardText='Jól végezted a dolgod, $N. Eszembe jut, hogy már sok szolgálatot tettél a Deathstalkereknek, bebizonyítva az értékedet, és talán ideje továbbfejleszteni a képzésedet az árnyékművészetekben.' WHERE ID=1998;
UPDATE quest_offer_reward SET RewardText='Nagyon jó, $N! Jól elsajátítottad a zárnyitás finom művészetét, ráadásul gyorsabban, mint ahogy vártam volna.$B$BLátom, jól tettem, hogy megbíztam benned. Hidd el, fiam, azt jósolom, hogy messzire fogsz jutni ebben a szakmában.' WHERE ID=1999;
UPDATE quest_offer_reward SET RewardText='Nagy szolgálatot tettél a mozgalomnak, $N. A troggok és a leprás gnómok, akik ellepték Gnomereganet, hamarosan érezni fogják egy gnóm légitámadás súlyát!' WHERE ID=2038;
UPDATE quest_offer_reward SET RewardText='Szóval Gnoarn nem bízik a felderítő képességeimben? Vajon miért...$b$bMindegy is, szükségem van a segítségedre! Nem! A mozgalomnak van szüksége a segítségedre!' WHERE ID=2039;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N. Neked köszönhetően Gnomeregan egy lépéssel közelebb került a felszabadulás napjához!' WHERE ID=2040;
UPDATE quest_offer_reward SET RewardText='Hírt hozol a főparancsnokságtól?' WHERE ID=2041;
UPDATE quest_offer_reward SET RewardText='Yarrr... Többnek bizonyulsz egy nyavalyás tengeri kutyánál, te szárazföldi patkány.$B$BA Kapitány talán még előléptet tatfedélzeti mosogatófiúvá, ha így folytatod...' WHERE ID=2078;
UPDATE quest_offer_reward SET RewardText='Állj meg, te ronda tengeri kutya! Sikerült! Hamarosan az első tisztem újra működik, és azok a szörnyetegek nem is fogják tudni, mi csapott le rájuk!$B$BHrm, láttad az első tisztemet?' WHERE ID=2098;
UPDATE quest_offer_reward SET RewardText='A munkánk csak most kezdődött, $N. Készen állsz a következő feladatra?' WHERE ID=2118;
UPDATE quest_offer_reward SET RewardText='Nagy szolgálatot tettél Auberdine-nak, $N, de a feladatod még nincs befejezve.' WHERE ID=2138;
UPDATE quest_offer_reward SET RewardText='Bátorsággal és becsülettel harcoltál Auberdine-ért, $N. A háború sújtotta földjeinken a halál és a kétségbeesés mindennapos. Sokan nem lesznek képesek szembenézni az új otthonunkban rájuk váró kihívásokkal, inkább otthonaikba zárkóznak, vagy a Szövetség jobban megerősített földjeire menekülnek.$b$bKöszönöm, $N. Talán hamarosan bajtársként harcolunk együtt egy másik ellenség ellen.' WHERE ID=2139;
UPDATE quest_offer_reward SET RewardText='Pihenés és kikapcsolódás a fáradtaknak és a fázóknak - ez a mottónk! Kérlek, ülj le a tűz mellé, és pihentesd fáradt csontjaidat.$B$BSzeretnél kóstolót kapni a finom ételeinkből és italainkból?' WHERE ID=2158;
UPDATE quest_offer_reward SET RewardText='Ah, igen, a Shadowglenből érkező gyógynövény-szállítmány. Kár, hogy Porthannius nem hozhatta el személyesen, mert sok mindent kell megbeszélnünk, ő és én.$B$BDe mindenesetre örülök, hogy megkaptam a gyógynövényeket, és örülök, hogy eljöttél.$B$BAmíg itt vagy, kérlek, pihend ki magad. A hősöknek magasan kell tartaniuk erejüket és szellemüket, és meg kell találniuk a pihenést és a vigaszt, amikor csak lehet. Mert ha valaki elhanyagolja a test és a lélek békéjét, az biztos út a kudarchoz.$B$BSzóval... pihenj.' WHERE ID=2159;
UPDATE quest_offer_reward SET RewardText='Ah, végre, a Handsből érkező készletek! Már kezdtem aggódni, alig kaptunk hírt Anvilmarból, mióta a troggok elárasztották a hágót.$b$bKöszönöm, hogy elhoztad, $N. És kérlek, érezd magad otthon. Biztos fáradt vagy az utazás után.' WHERE ID=2160;
UPDATE quest_offer_reward SET RewardText='Ah, ez az étel, amit Ukor hozott a Valley of Trials-be. Nem volt rá szükségük? Nos, gondolom szeretik éheztetni titeket, kiképzés alatt álló hősöket. Azt mondják, ez erősíti a lelket!$b$bKöszönöm, hogy visszahoztad az élelmet. Visszateszem a polcokra... de előbb, engedd meg, hogy felkínáljak egy kis frissítőt!$b$bÉs ne felejts el pihenni itt a fogadóban. Lehet, hogy bátor $c vagy, kész meghódítani a világot, de ha kimerül az energiád, sem magadnak, sem a Hordának nem teszel jó szolgálatot.' WHERE ID=2161;
UPDATE quest_offer_reward SET RewardText='Fantasztikus! Próbáld ki, és mondd el, mit gondolsz róla, $N!' WHERE ID=2178;
UPDATE quest_offer_reward SET RewardText='Igen... én vagyok az ékszerész, aki ezt a nyakláncot készítette. Nem szoktam ingyen osztogatni az információt sem. Az információ sosem ingyenes, barátom. Ha segíteni akarok neked, előbb neked kell segítened NEKEM.' WHERE ID=2198;
UPDATE quest_offer_reward SET RewardText='Az én könyvem szerint rendben vagy; nem érdekel, mit mondanak mások... Csak vicceltem!$B$BKomolyan, köszönöm, barátom.$B$BSzóval, a nyaklánc, ami nálad van, az egyik legjobb alkotásom, de hiányzik belőle három drágakő, amelyek segítenek megkötni a mágikus erőt. Egy paladinnak készítettem valamikor. Ő önjelölt küldetésbe kezdett, hogy megtisztítsa a Badlands egy Uldaman nevű ásatási helyén jelen lévő „gonosz fertőzést”.$B$BNos... az a paladin meghalt Uldamanban, és ez csak a bajaim kezdete volt.' WHERE ID=2199;
UPDATE quest_offer_reward SET RewardText='Egy paladin maradványai: A napló elolvasásából kiderül, hogy sok erőfeszítés után a paladin megtalálta mindhárom hiányzó drágakő helyét:$b$bA Shadowforge törpék a rubint elbarikádozott területükön rejtették el, miközben a troggokkal harcoltak Uldaman irányításáért.$b$bA troggok a topázt egy urnában rejtették el, Uldaman néhány szokatlan lakója közelében - Szövetséges törpék!$b$bVégül a trogg vén magának tartotta meg a zafírt.' WHERE ID=2200;
UPDATE quest_offer_reward SET RewardText='Igen, ez valóban a három drágakő. Szép munka! Sajnos a munkád még nem egészen ért véget.$B$BNe, nem próbálok átverni, te buta $c. Ez mágikus ékszerek készítéséről szól - Talvash del Kissel minőségű ékszerekről! Erős energiaforrásra van szükséged, hogy legyen benne lendület. Nos, ennek a nyakláncnak már nincs több lendülete.' WHERE ID=2201;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N, ismét bebizonyítottad az értékedet! A kupakok érdekes tanulmány lesznek, arra mérget vehetsz.$B$BÉs most, ahogy ígértem, kóstolj bele az egyik erősebb regeneráló főzetembe a saját készletemből...$B$BHa ügyes alkimista vagy, talán tudunk további üzletet kötni. Mindenesetre köszönöm a segítségedet!' WHERE ID=2202;
UPDATE quest_offer_reward SET RewardText='Alkimistától alkimistának, tisztelgek előtted. Tessék, fogadd el ezt a receptet, és véss az emlékezetedbe. Hozzon neked annyi sikert és jutalmat, mint amennyit nekem hozott az évek során.' WHERE ID=2203;
UPDATE quest_offer_reward SET RewardText='Nahát - nagyon örülök, hogy téged és ezt az energiaforrást is egyben látlak. Egy pillanat, és mágikusan összeolvasztom az energiaforrást a nyaklánccal, most hogy a drágakövek is visszakerültek rá. Amint kész, a nyaklánc a tiéd lesz!$B$BIzgatott vagy, ugye? Egészen bizsereg a várakozástól? Most hova is tettem azt a varázsfókuszt...' WHERE ID=2204;
UPDATE quest_offer_reward SET RewardText='Megtaláltál - és ránézve azt mondanám, a futás és az azt követő keresés komoly megterhelést jelentett számodra, mind lelkileg, mind fizikailag.$B$BSzeretnéd, hogy Renzik megmutassa az utat egy fogadóhoz, vagy készen állsz egy kis munkára?' WHERE ID=2205;
UPDATE quest_offer_reward SET RewardText='Elámulok... Elámulok, hogy Keryn végre talált egy újoncot, akiben megvan a lehetőség, hogy igazi $c váljon belőle. Fogadd el ezt a pengét, $N. Eljön a nap, amikor újra hívnak majd, hogy szolgáld az SI:7-et. Csiszold a képességeidet, tartsd nyitva a szemed, és tartsd élesen azt a pengét.$B$BNem fogsz minket jönni látni, de érezni fogod, amikor megérkezünk...' WHERE ID=2206;
UPDATE quest_offer_reward SET RewardText='Szóval azt hiszed, igazi gazfickó vagy? Arra rendeltetve, hogy Blackbeard kiválasztottjai közé tartozz - a Hidden Circle tisztje légy?$B$BCsak egy semmirekellő csirkefogó gondolna ilyen nagyra magáról.$B$BPontosan ezt keressük! Üdvözlünk a fedélzeten, $N!' WHERE ID=2218;
UPDATE quest_offer_reward SET RewardText='Csssss! Halkabban, te bolond. Meg fognak hallani minket.' WHERE ID=2238;
UPDATE quest_offer_reward SET RewardText='Hosszú útvonal? A saját szakállamra mondom!$B$BJól végezted a dolgod, $N. Fogd ezt a tőrt, és tűnj innen. A Circle újra hívni fog, amikor a harmadik lépés készen áll a beindításra.$B$BMi a harmadik lépés? Rögtön a második lépés után jön - amikor a csizmámat a hátsódba rúgom.$B$BÉrdekel?' WHERE ID=2239;
UPDATE quest_offer_reward SET RewardText='Láttad a Khaz''mul Kamráját? Elképesztő! Baelog biztos volt benne, hogy létezik, de bevallom, nekem kétségeim voltak.$B$BKöszönöm, $N. Szerencsével a felfedezésed arra ösztönzi majd a vezetőinket, hogy megújított erőfeszítéseket tegyenek Uldaman visszafoglalására. És ha valaha újra Ironforge irányítása alá kerül, a Khaz''mul Kamrájának titkai a mieink lesznek!' WHERE ID=2240;
UPDATE quest_offer_reward SET RewardText='Ha megtartottam volna minden virágot, amit az a bolond Jannok küldött nekem, lenne miből boltot nyitnom. Mindenesetre úgy tűnik, Jannok legújabb futára hasznosnak bizonyulhat. Érdekel egy kis munka, $c?' WHERE ID=2241;
UPDATE quest_offer_reward SET RewardText='Ez komor hír, $N. Úgy tűnik, a betegség, amely megragadta Darkshore erdeit és folyóit, elkezdte megfertőzni az otthonunkat is.$B$BJól szolgáltál minket, de itt már nincs több teendőd. Fogadd el ezt a pengét jutalmul a Teldrassilnak tett szolgálataidért.' WHERE ID=2242;
UPDATE quest_offer_reward SET RewardText='Ah, szép munka! Ezek legalább egy darabig kitartanak nekem. Íme a fizetséged, ahogy ígértem.$B$BHa érdekel, van még pár alapanyag, amire szükségem lenne. Ezek azonban csak az Uldaman ásatás mélyén találhatók. Nem lesz könnyű megszerezni őket, de megéri majd, ha újra segítesz nekem.$B$BTalán valami több, mint csillogó érmék, igaz?' WHERE ID=2258;
UPDATE quest_offer_reward SET RewardText='Ideje kiterjeszkedni, $R - a világ vár rád.' WHERE ID=2259;
UPDATE quest_offer_reward SET RewardText='Válaszoltál az SI:7 hívására, $N, és távoli partokról utaztál ide, hogy csatlakozz soraink közé, azonban még sok mindent kell tanulnod.' WHERE ID=2260;
UPDATE quest_offer_reward SET RewardText='A kővigyázó utasításait követve újra hozzáférsz a Norgannon Korongjaihoz, most hogy megismerted az Earthen, a troggok és a törpék történetét. Halk, rövid zümmögés hallatszik a korongok belsejéből. A kővigyázó ezután megszólal:$b$b„A korongok most szintetizálva lettek. Férj hozzá újra a Norgannon Korongjaihoz, hogy megkapd a saját példányodat.”' WHERE ID=2278;
UPDATE quest_offer_reward SET RewardText='Mi van nálad... jaj nekem. Hol találtad ezt?$B$BNe, tényleg?$B$BKivel beszéltél, és miről?$B$BNE, TÉNYLEG?!$B$BDrága $c-om, lehet, hogy épp most tetted meg az év régészeti felfedezését! Kit áltatok, az évszázad felfedezését! Ha ezek a korongok azok, aminek gondolom, akkor ez lehet pontosan az a kulcs, amit kerestünk! Ez egyszer s mindenkorra bizonyíthatja a törpék elvarázsolt alkotásának valódiságát!' WHERE ID=2279;
UPDATE quest_offer_reward SET RewardText='Hát ezek meg mik?$b$bLenyűgöző, ifjú! Ezekben a korongokban titkokat érzek, amelyeket a föld sokáig szorosan őrzött. Nagyon bölcsen tetted, hogy idehoztad őket nekem.' WHERE ID=2280;
UPDATE quest_offer_reward SET RewardText='Ah, szóval kicsit vaskosak az ujjaid, mi? Ne aggódj, $N, már több haszontalan tolvajból csináltam ügyes gazembert nálad.' WHERE ID=2281;
UPDATE quest_offer_reward SET RewardText='Feltörted, ugye? Szép munka, $N.$B$BHa most meghalsz, nyugodtan alhatunk, tudva, hogy a saját ostobaságod okozta, nem a tapasztalatlanságod.' WHERE ID=2282;
UPDATE quest_offer_reward SET RewardText='Mmm, roncsanyag! Innen is érzem a nyaklánc illatát. Most nézzük meg azt a szépséget...$B$BHé, mit gondolsz, mit próbálsz itt csinálni? Ebből a nyakláncból hiányoznak a drágakövek! Azt hitted, nem vesszük észre? Még Malton is látta, hogy hiányoznak a kövek.$B$BNos, talán nem te loptad el őket... de a nyaklánc értéktelen azok nélkül a drágakövek nélkül! A munkád itt még koránt sincs befejezve!' WHERE ID=2283;
UPDATE quest_offer_reward SET RewardText='Úgy tűnik, megtaláltad a paladin maradványait, akit Dran korábban említett. A maradványok átkutatása során előkerül, ami a naplójának tűnik. A könyv rossz állapotban van, mivel a beszáradt vér elmosta a szöveg nagy részét. Amit el tudsz olvasni, az azonban érthetetlen; legjobb tudomásod szerint az emberek anyanyelvén íródott.$b$bLe kell fordíttatnod a könyvet, ha bármi tudást akarsz kinyerni belőle.' WHERE ID=2284;
UPDATE quest_offer_reward SET RewardText='Mindig jó, ha Hulfdan gazemberei közül valaki a soraink között van!' WHERE ID=2298;
UPDATE quest_offer_reward SET RewardText='Halkabban, $N, meghallhatnak az őrök.' WHERE ID=2299;
UPDATE quest_offer_reward SET RewardText='Készen állsz munkához látni, vagy szükséged van egy kis szunyókálásra, mielőtt elkezdenénk?' WHERE ID=2300;
UPDATE quest_offer_reward SET RewardText='Hatalmas $c, tudom, mit csinálsz itt a Badlandsben. Tudom, hogy a nyelvek ajándékát keresed nálam. Annak a nyakláncnak a darabjai után kutatsz, amit Uldamanban találtál.$b$bMeglepődtél? Ne lepődj meg - az én dolgom, hogy ilyesmit tudjak. Ehelyett beszéljük meg, mit teszel majd a lefordított naplóért. Bízz bennem - én vagyok az egyetlen, akit találsz, aki le tudja fordítani.$b$bSőt, jobb ajánlatot teszek neked, mint Dran Droffers, és így még be tudod fejezni velük is az üzletet. Most már érdekel, igaz?' WHERE ID=2318;
UPDATE quest_offer_reward SET RewardText='Tudod, mi a jó üzlet, ha meglátod - tudtam, hogy számíthatok rád.$b$bCsak egy pillanat, amíg elmondok egy varázslatot, hogy gyorsan lefordítsam az emberi nyelvet olyan formára, amit megértesz. Én egy szavatartó troll vagyok; kérdezz meg bárkit a Hordában Jarkal Mossmeldről. Most pedig kezdjük...' WHERE ID=2338;
UPDATE quest_offer_reward SET RewardText='Nagyon szép munka, $c. Most az átirányításunk gyümölcsei bőségesen megtérülnek. Elkészültem magával a nyaklánccal, és biztos vagyok benne, hogy következetesen meg tudom ismételni az elkészítési folyamatot.$B$BDe előbb egy speciálisan előkészített varázsigét használok, hogy gyorsan megvizsgáljam ezeket a drágaköveket, mielőtt visszaviszed őket a nyaklánccal együtt Orgrimmarba. Ez csak egy rövid pillanatig fog tartani.' WHERE ID=2339;
UPDATE quest_offer_reward SET RewardText='Igen, minden megvan. Mondd, nem baj, ha a táskát is megtartjuk? Nem? Köszi, nagyra értékelem! Har!$b$bEz a nyaklánc lesz eddigi legnagyobb fogásunk! Ne érezd magad rosszul emiatt; biztos vagyok benne, hogy úgysem állt volna jól rajtad. Megint har!$b$bAz üzlet az üzlet, szóval itt a fizetséged a roncsanyagért. Az üzletünk egyelőre lezárult; nézz vissza később, hátha akad még munkánk. Addig is, tűnés!' WHERE ID=2340;
UPDATE quest_offer_reward SET RewardText='Az energiaforrás, amit adtál, minden várakozásomat felülmúlta. Sikerült neked is és nekem is nyakláncot készítenem, és még maradt is elég legalább három továbbihoz. Szép összeget hoznak majd, és a Droffers and Son Salvage semmit sem sejt majd.$b$bTessék, barátom. Köszönetet mondok a remek munkáért... és valami egészen különlegeset a fáradozásodért.' WHERE ID=2341;
UPDATE quest_offer_reward SET RewardText='Végre - egy Garretthez méltó seprű. Minden fikarcnyi ezüstöt megértél, amit rád költöttem!$B$BHalljátok, undorító denevérek? Most már a Garrett család választott fegyverét forgatom! Reszkessetek, denevérek, reszkessetek!!' WHERE ID=2342;
UPDATE quest_offer_reward SET RewardText='Megtagadni Ravenholdttól az ereklyét annyi lenne, mint megtagadni saját létezésünket. Szép munka, $c. Immár Ravenholdt orgyilkosai között járhatsz.$B$B Fiatal gazemberként, Darkshore-ban kalandozva fedeztem fel egy teát, amely harc közben visszaadja az energiát. Az évek során jól szolgált, és most átadok neked egy kortyot ebből a bogáncsteából. Igyál belőle, ha elfáradsz, $N, és harcolj újra teljes erővel!$B$B' WHERE ID=2358;
UPDATE quest_offer_reward SET RewardText='Ez megmagyarázná a Defias-drónokat, amiket te és Kearnen láttatok a torony előtt, $N. Azt is megmagyarázná, miért van kapcsolat a Venture Company és a Defias között, valamint a Duskwoodból kiinduló furcsa szállítmányokat.$B$BE könyv szerint a Stranglethornban élő Zanzil trollok módot találtak arra, hogy főzetekkel - pontosabban méreggel - életre keltsék a holtakat.$B$BAz SI:7-nek hasznavehetetlen leszel a mérgek alapos ismerete nélkül, $N - főleg most, hogy kezünkben a holtidézés receptje.' WHERE ID=2359;
UPDATE quest_offer_reward SET RewardText='Mathias végre küldött egy másik ügynököt, hogy segítsen nekem, mi? Nos, remélem, kész néhány rossz hírt hallani.' WHERE ID=2360;
UPDATE quest_offer_reward SET RewardText='Örömmel adom neked ezt a nyakláncot, hatalmas $c. Felbecsülhetetlen szolgálatot tettél nekem, és ezért köszönetet mondok. Viseld büszkén, és ne felejtsd el hangosan és gyakran megemlíteni, ki készítette neked!$B$BÉs ha még azt is hozzátennéd, hogy valójában nincs megátkozva, az remek lenne.' WHERE ID=2361;
UPDATE quest_offer_reward SET RewardText='Szóval te vagy, akit hatalmas szövetségeseink küldtek Shenthulnak? Mennyire nem lelkesítő...' WHERE ID=2378;
UPDATE quest_offer_reward SET RewardText='Talán Zando''zan tévedett. Zando''zan bocsánatot kér.' WHERE ID=2379;
UPDATE quest_offer_reward SET RewardText='Fontos, hogy a Shattered Hand éber maradjon a Thrall által a Hordában bevezetni kívánt változásokkal szemben. Puszta létszámunk nem lesz elég uralmának megdöntéséhez - el kell sajátítanunk a rejtőzködést és a megtévesztést.' WHERE ID=2380;
UPDATE quest_offer_reward SET RewardText='Hihetetlen! Valószínűtlen! Egyszerűen elképesztő! Van tehetséged, $N. Vagy ez, vagy te vagy a legszerencsésebb élő $gférfi:nő;!$b$bItt a részesedésed. Biztos vagyok benne, hogy jobb hasznát veszed ennek a cuccnak, mint én tudnám.$b$b' WHERE ID=2381;
UPDATE quest_offer_reward SET RewardText='Már megint egy? Az utolsó öt, akit az az őrült troll küldött, cápaeledel lett belőle. Reméljük, neked jobban sikerül, mi?$b$b' WHERE ID=2382;
UPDATE quest_offer_reward SET RewardText='Ah, ez az én pergamenem. Hallottam, hogy jönni fogsz a Valley-be, $N. Örülök, hogy sikerült - reméljük, túléled az előtted álló próbákat. Ahogy mondtam, ahogy erősödsz, gyere hozzám - megteszek mindent, hogy kiképezzelek a $c útján.$b$bSok szerencsét, $N, és gyere vissza hozzám, amikor készen állsz.' WHERE ID=2383;
UPDATE quest_offer_reward SET RewardText='Épp ideje volt, hogy felbukkanj! Már majdnem elvesztettem egy fogadást Olaffal!$B$BArra fogadott, hogy a szakálla a térdéig fog nőni, mielőtt újra lát egy élő $R-t. Nos, itt vagy, és amint látod, Olaf szakállának még van pár centije hátra.$B$BKöszönöm, $N. Megosztom veled a nyereményt.' WHERE ID=2398;
UPDATE quest_offer_reward SET RewardText='A levelek, amiket Denalan a kertjében ültetett, kihajtottak és megnőttek. Remegnek, alig várják, hogy leszedjék őket...' WHERE ID=2399;
UPDATE quest_offer_reward SET RewardText='Ez remek, találtál néhányat! Nagyon köszönöm, $N. Te vagy a legmegbízhatóbb $r, akivel valaha találkoztam!$B$BAlig várom, hogy kipróbáljam néhány szerkezeten, amivel bajlódtam. Fogadok, hogy megfelelő körülmények között az ezekkel a kövekkel meghajtott szerkezetek örökké mennek, mennek, mennek...' WHERE ID=2418;
UPDATE quest_offer_reward SET RewardText='A smaragd álomfogóm rendkívül fontos nekem. Csak keveseknek adott ajándék volt. Köszönöm, hogy visszahoztad, $N.' WHERE ID=2438;
UPDATE quest_offer_reward SET RewardText='Ah igen, egy utalvány az Explorers'' League-től... és hozzátenném, egészen értékes darab.$B$BAz Explorers'' League felhatalmazást ad nekem, hogy közvetlenül a kincstárukból kínáljak neked választási lehetőséget a jutalmadra. Megkapod ezt a tárgyat, és választhatsz öt kiváló gyógyitalt vagy öt nagyobb mana-főzetet jutalmul.' WHERE ID=2439;
UPDATE quest_offer_reward SET RewardText='Nos, $N, biztosan nagyon elégedett veled Sage Truthseeker, ha ezt a tárgyat adta neked. Ráadásul egy ajándékot is kapsz a főzet-készletéből; választhatsz 5 kiváló gyógyitalt vagy 5 nagyobb mana-főzetet jutalmul.' WHERE ID=2440;
UPDATE quest_offer_reward SET RewardText='Jó látni egy másik Shattered Hand-ügynököt errefelé, bár a fényjelzés talán kicsit túlzás volt!$B$BLegközelebb, ha beszélned kell velem, fújj kétszer ebbe a sípba, és tudni fogom, hogy szövetséges vagy.' WHERE ID=2458;
UPDATE quest_offer_reward SET RewardText='Most már megjavíthatom az álomfogómat. Köszönöm, $N.' WHERE ID=2459;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N. Most már készen állsz a folytatásra.' WHERE ID=2460;
UPDATE quest_offer_reward SET RewardText='Szegény Fizzule, jó ügynök volt - az egyik legjobbunk. Sajnos, ez az az ár, amit fizetnünk kell, $N. A Shattered Hand terepügynökének lenni veszélyes munka.$B$BJól végezted a kötelességedet, $c. Kár lenne, ha nem élnéd túl, hogy újra szolgálj minket.' WHERE ID=2478;
UPDATE quest_offer_reward SET RewardText='Csábítóan sápadtnak tűnsz, $c. És mi ez az undorító illat, amit árasztasz? Tudnom kell!' WHERE ID=2479;
UPDATE quest_offer_reward SET RewardText='A gyógyszer elkészült! Idd meg ezt az ellenmérget, és a terjedő őrület megáll, viszont a szagon nem tudok segíteni.' WHERE ID=2480;
UPDATE quest_offer_reward SET RewardText='Ah, szóval Rellian küldött, hogy segíts nekem. Örülök, hogy ilyen hamar ideértél.$b$bValami egészen nyugtalanítót fedeztem fel!' WHERE ID=2498;
UPDATE quest_offer_reward SET RewardText='Tudtam, hogy több mint képes vagy megszabadítani a tavat attól a szörnyű fenevadtól.$B$BEz egy nyugtalanító helyzet; Oakenscowl valaha nagy vezető volt a maga fajtájából... de a romlás nem tesz különbséget alacsonyrendű és nemes között.$B$BEnnek a daganatnak a mérete meglehetősen nyugtalanító, de tanulmányoznom kell, hogy többet tudjak meg a betegségről, amely a timberlingek populációját sújtja.$B$BKöszönöm, $N.' WHERE ID=2499;
UPDATE quest_offer_reward SET RewardText='Ah, szép munka, $N! Ezek legalább egy darabig kitartanak nekem. Íme a fizetséged, ahogy ígértem.$B$BHa érdekel, van még pár alapanyag, amire szükségem lenne. Ezek azonban csak az Uldaman ásatás mélyén találhatók. Nem lesz könnyű megszerezni őket, de megéri majd, ha újra segítesz nekem.$B$BTalán valami több, mint csillogó érmék, igaz?' WHERE ID=2500;
UPDATE quest_offer_reward SET RewardText='Alkimistától alkimistának, tisztelgek előtted. Tessék, fogadd el ezt a receptet, és véss az emlékezetedbe. Hozzon neked annyi sikert és jutalmat, mint amennyit nekem hozott az évek során!' WHERE ID=2501;
UPDATE quest_offer_reward SET RewardText='Az erdő gyászolja Lady Sathrah-t, de ezt meg kellett tenni.$B$BKöszönöm, $N.' WHERE ID=2518;
UPDATE quest_offer_reward SET RewardText='Szóval Sister Aquinne küldött?' WHERE ID=2519;
UPDATE quest_offer_reward SET RewardText='Lady Sathrah elvesztése fájdalmas, de csak így születhet újjá megújult lélekkel.$b$bBárcsak Elune szívesen elfogadná az áldozatot, amit felajánlottál neki.' WHERE ID=2520;
UPDATE quest_offer_reward SET RewardText='Csal a szemem? Lehetetlen! Honnan... Hogyan...$B$BTalán most már megnyitható egy szakadék, amely visszavisz minket a hazánkba.' WHERE ID=2521;
UPDATE quest_offer_reward SET RewardText='Egyszerűen elképesztő. Kételkedtem benne, hogy találsz még egy szférát, mégis itt van, lüktetve a kezemben.$B$BSzép munka, $N!$B$BHa találsz még - és úgy hiszem, ez lehetetlen -, hozd vissza őket nekem, és újra megjutalmazlak.' WHERE ID=2522;
UPDATE quest_offer_reward SET RewardText='Cenarion növénykenőcsöt kensz a dalvirágra. Azonnal elkezdi levetni megrontott formáját, és élénk, egészséges növénnyé bomlik ki.' WHERE ID=2523;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N.$b$bMilyen furcsa csecsebecse ez... érzem a belőle áradó ocsmány aurát; ez egy nagyon erős varázslat.' WHERE ID=2541;
UPDATE quest_offer_reward SET RewardText='Végre szabad vagyok a Gnarlpine uralma alól. Köszönöm, $N.$b$bA lelkem most már örökre békében nyugodhat az Emerald Dreamben.$b$bTalán egy nap újra találkozunk, ifjú $c. De most kérlek, fogadd el ezt a jutalmat hálám jeléül.' WHERE ID=2561;
UPDATE quest_offer_reward SET RewardText='Hogy érzed magad, $N? A snickerfang aurájával sugárzol - erőd felülmúlhatatlan a halandók között!$b$bSajnos a hozott alapanyagokból csak egy tablettához elegendő próbaanyagot tudtam készíteni. További alapanyagokra lesz szükségem, ha még egy tablettát szeretnél.' WHERE ID=2581;
UPDATE quest_offer_reward SET RewardText='Tessék! Ne feledd, takarékosan használd. Ha még egyre szükséged van, keress fel, miután elhasználtad, ami most nálad van.' WHERE ID=2582;
UPDATE quest_offer_reward SET RewardText='A vadkan szelleme átjárja a lényedet, $N! Vajon sebezhetetlennek hiszed magad, mint ezek a vadállatok?' WHERE ID=2583;
UPDATE quest_offer_reward SET RewardText='Figyelmeztetnem kell, $N, ne próbáld összekeverni az általam készített formulákat. A legutóbb elfogyasztott formula kémiai tulajdonságai mindig felülírják a korábbi varázslatokat; így a másik formula hatástalanná válik.' WHERE ID=2584;
UPDATE quest_offer_reward SET RewardText='Lenyűgöző. Ez volt az összes próbaanyag közül a legnehezebben elemezhető.$b$bVégy egy csipet ebből a maradék sóból, és tedd a nyelved alá. Enyhe eufóriaérzést kell tapasztalnod, amit egy eddig nem tapasztalt fürgeség és gyorsaság állapota követ.' WHERE ID=2585;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N. Itt van egy minta a próbaanyagból neked, a maradék kilencet pedig a kutatásomhoz használom.$b$bBármikor, ha még kell a darált scorpok próbaanyagból, keress fel, és megegyezünk.' WHERE ID=2586;
UPDATE quest_offer_reward SET RewardText='Ez csodálatos, $N! Az ajándékom neked egy ízelítő a vörös kőbazilliszkusz belső működéséből.$B$BHa a keverék elnyeri a tetszésedet, mindig készíthető még belőle... egy árért.' WHERE ID=2601;
UPDATE quest_offer_reward SET RewardText='Igen, igen, adj egy percet, és több keverék is készen áll majd a fogyasztásra, $N.$B$BFogadd el... és $N, ne próbáld ezeket a kísérleti főzeteket gyors egymásutánban elfogyasztani. A következmények katasztrofálisak lehetnek.' WHERE ID=2602;
UPDATE quest_offer_reward SET RewardText='Nagyszerű! Azonnal munkához látok. Talán megtaláljuk a világ számos betegségének gyógymódját!$B$BAh igen, a jutalmad - természetesen, ha még kell a gumiból, keress fel, és kapsz egy újabb feladatot.' WHERE ID=2603;
UPDATE quest_offer_reward SET RewardText='Talán egy nap sikerül izolálnom ennek a próbaanyagnak az aktív enzimjeit, és sokkal hatékonyabb végterméket állítok elő. Sajnos most be kell érned azzal, amit jelenleg elő tudok állítani. Keress fel, ha még kell a zúzógyomor-gumi.' WHERE ID=2604;
UPDATE quest_offer_reward SET RewardText='Ó, csodálatos! Add ide - hadd igyam meg!' WHERE ID=2605;
UPDATE quest_offer_reward SET RewardText='Marin jó fej, félre ne érts - csak egy kicsit... hát, excentrikus, mondanám.$B$BÉs persze megint szüksége van a segítségemre.' WHERE ID=2606;
UPDATE quest_offer_reward SET RewardText='Épp ideje! Csak tedd le a sajtot az asztalra, és tűnés. Osborne kifizet, kifelé menet.' WHERE ID=2607;
UPDATE quest_offer_reward SET RewardText='Adj egy percet, hogy megbeszéljem a kollégáimmal, $N. Dr. Montgomery, Mr. Noarm, tartsunk megbeszélést!' WHERE ID=2608;
UPDATE quest_offer_reward SET RewardText='Mit csinálok? Mit gondolsz, mit csinálok? Gyógymódot dolgozok ki a ''gyulladásodra''! Ne háborodj fel most rám, $N!$b$bMég néhány másodperc. Így! Csak fújd magadra ezt a, hm, fantasztikus illatú gyógyszert, és olyan leszel, mint újkorodban.' WHERE ID=2609;
UPDATE quest_offer_reward SET RewardText='Thrall''s Grasp... A történet még friss az emlékezetemben.$b$b<Commander Ruag megrázza a fejét>$b$bBorzalmas dolog történt azzal az ezreddel. A Horda néhány legjobb katonáját vesztette el, amikor az a zászlóalj megsemmisült.' WHERE ID=2621;
UPDATE quest_offer_reward SET RewardText='Swamp tal... beszé... beszélő...$b$b' WHERE ID=2622;
UPDATE quest_offer_reward SET RewardText='Rosszabb, mint amit elképzeltem. Tizenkilenc emberemet megkímélhettem volna attól a gyötrelemtől, amivel szembe kellett nézniük. Bárcsak ne cselekedtem volna ilyen meggondolatlanul.$b$bSegítened kell nekik, $N! Nekem nincs hatalmam cselekedni.' WHERE ID=2623;
UPDATE quest_offer_reward SET RewardText='Ez az, $N!$B$BOlyan jól néz ki, hogy talán csak...  Haha, becsaptalak!' WHERE ID=2641;
UPDATE quest_offer_reward SET RewardText='Violet Powder, mi? Próbáljuk ki - rosszabb biztos nem lehet tőle, az egyszer biztos!' WHERE ID=2661;
UPDATE quest_offer_reward SET RewardText='Idd meg ezt! Egyszerűen csodálatos!!!$B$BTudtam, hogy megvan bennem... Ó, még egyszer köszönöm a segítséged, $N, de kérlek, állj kicsit oldalra, jó? Az üzletemet akadályozod! Milliókat fogok keresni a fantasztikus Noggenfogger Elixírrel, milliókat!$B$BMit mondasz? Sprinkle szerint tartozom neki egy szívességgel? Ó, az a Sprinkle, micsoda tréfamester!' WHERE ID=2662;
UPDATE quest_offer_reward SET RewardText='Sikerült, $N! A szegény, gyötört lelkek végre megpihenhetnek.$b$bA munkánk még nem ért véget, $N. Sok mindent kell megbeszélnünk, és még többet kell elérnünk.' WHERE ID=2681;
UPDATE quest_offer_reward SET RewardText='Átmenetileg elvakít a csillogás és a ragyogás.' WHERE ID=2701;
UPDATE quest_offer_reward SET RewardText='Valóban, megtiszteltél mindannyiunkat. Puszta köszönetünk nem elegendő.' WHERE ID=2702;
UPDATE quest_offer_reward SET RewardText='Trebor? Trebor küldött?' WHERE ID=2721;
UPDATE quest_offer_reward SET RewardText='Beteszed a hippogriff tojást a gépbe. Egy sor sípoló hang következik néhány furcsa mechanikus zajjal együtt.$B$BÚgy tűnik, az Eggometer lemérte, megmérte és becsomagolta a tojásodat. Ez aztán a gyors kiszolgálás!' WHERE ID=2741;
UPDATE quest_offer_reward SET RewardText='Ez a trolltábla lehet az a „titok”, amiről Rin''ji beszélt.$B$BFurcsa jelekkel borítva, nem tudod megfejteni, mit ír a tábla.' WHERE ID=2742;
UPDATE quest_offer_reward SET RewardText='A démonúr ravaszsága szinte olyan kiszámított, mint a brutalitása, $N.' WHERE ID=2743;
UPDATE quest_offer_reward SET RewardText='Segítek neked. Bár nem hiszem, hogy teljesen felfogod, mivel állsz szemben.' WHERE ID=2744;
UPDATE quest_offer_reward SET RewardText='Mi a...?! Ne lopakodj így mögém! És halkabban! Az Árnyék nevében, miért osonsz mögém? Nem látod, hogy elfoglalt vagyok, te bolond?$b$bHogy érted, mit csinálok? A következő Dark Portal megnyílására várok, mégis mit gondolsz, mit csinálok? Mondd el, amit akarsz, aztán tűnés... mielőtt az őrök észreveszik, hogy ketten bujkálunk együtt a bokrokban. Van egy hírnevem, amit meg kell őriznem.' WHERE ID=2745;
UPDATE quest_offer_reward SET RewardText='Ezek pont jók lesznek, $N. Remek munka.$b$bA maradék felszerelés megvan a táskámban... hála a Fénynek, hogy egy szabó barátom csinált nekem egy selyemtáskát. Kezdett elfogyni a hely, ahogy cipeltem magammal az összes felszerelést.$b$bMielőtt Spybot bemegy, tisztázzuk a részleteket, hogy tudd, mit kell tenned.' WHERE ID=2746;
UPDATE quest_offer_reward SET RewardText='Nos, van egy neked - elképesztő!$B$BRemélem, mindig emlékezni fogsz a jóra, amit ma tettél.' WHERE ID=2747;
UPDATE quest_offer_reward SET RewardText='Nagyon jó, $N. Elküldöm ezt a tojást Darnassusba, ahol remélem, hamarosan kikel!$B$BKérlek, fogadd el ezt hálám jeléül.' WHERE ID=2748;
UPDATE quest_offer_reward SET RewardText='Szóval találtál egy hétköznapi tojást, $N? Kérlek, add ide nekem... És csak reménykedhetünk a legjobbakban.$B$BNincs sok mindenem, de kérlek, fogadd el ezt a jutalmat. Ha valaha újra Feralasban jársz, tudd, hogy mindig itt vagyok, hogy átvegyem az ott talált tojásokat.' WHERE ID=2749;
UPDATE quest_offer_reward SET RewardText='Attól tartok, rossz hírem van számodra, $N. Ez a tojás már túl romlott. Elveszem tőled, hogy megfelelően megsemmisíthessük.$B$BKérlek, ne csüggedj; nem menthetünk meg mindet. Ha újra Feralasban jársz, kérlek, próbálkozz újra. Hozz még egy tojást a Super Egg-O-Matic-hoz!' WHERE ID=2750;
UPDATE quest_offer_reward SET RewardText='A vérvonal elhalványul, de talán Omosh legendája tovább él!$B$BBebizonyítottad, hogy kovács vagy, $N. A kovács jutalma az az elégedettség, amit akkor érez, amikor fegyvereit és páncélzatát ellenségeinek vérével borítva látja!$B$BLegyenek a mellvértek, amiket az eljövendő generációknak készítesz, átitatva ellenségeid vérével!' WHERE ID=2751;
UPDATE quest_offer_reward SET RewardText='Büszkévé teszed Orokkot, $N. Olvasd, tanuld a vasvállak titkát!' WHERE ID=2752;
UPDATE quest_offer_reward SET RewardText='Orokk nagyapjára, Omosh törzsfőnökére, Gorokkra emlékeztetsz! Olvasd, tanuld a vascsizma titkát.' WHERE ID=2753;
UPDATE quest_offer_reward SET RewardText='Elképesztő! Elsajátítottad az Omosh útját, $N!' WHERE ID=2754;
UPDATE quest_offer_reward SET RewardText='<Orokk zihál.>$B$BNagyon régen volt már, hogy Orokk eltáncolta az Omosh örömtáncot. Tanuld meg most, $N!' WHERE ID=2755;
UPDATE quest_offer_reward SET RewardText='Úgy tűnik, te is csak egy újabb önelégült lemmingje vagy a Hadfőnöknek, $N. Milyen csalódást keltő.$b$bMennyire vágyom egy dicsőséges halálra a csatatéren. Ehelyett itt ragadtam, Thrall parancsára, hogy csecsemőknek tanítsam a mesterséget! Figyelj és tanulj, gyermek!' WHERE ID=2756;
UPDATE quest_offer_reward SET RewardText='Blackhoof hátsó szőrzetére - végre valaki, aki méltó a Mithril Rendhez!$b$b' WHERE ID=2757;
UPDATE quest_offer_reward SET RewardText='Nagyon jó, $N! Figyelj és tanulj.$B$BA kovácsmesterség sosem innen ered! <Hank a kalapácsára mutat.>$B$BA kovácsmesterség sosem innen ered! <Hank az üllőre mutat.>$B$BA kovácsmesterség csakis innen ered! <Hank a szívére mutat.>$B$BÉs most már tudod a kovácsmesterség eredetét.' WHERE ID=2758;
UPDATE quest_offer_reward SET RewardText='Blackhoof hátsó szőrzetére - végre valaki, aki méltó a Mithril Rendhez!' WHERE ID=2759;
UPDATE quest_offer_reward SET RewardText='Ah, sok év telt el, mióta valaki méltó volt a mithril rend beavatására. Most kezdjük!' WHERE ID=2760;
UPDATE quest_offer_reward SET RewardText='Munkaerkölcsöd kifogástalan, $N! Kezded megérteni Galvan ásványtanának módszereit! Fogadd el ezt, és tanulj belőle, amennyit csak tudsz.' WHERE ID=2761;
UPDATE quest_offer_reward SET RewardText='Kegyetlen úrnő, nem igaz, $N? A truesilverről beszélek, természetesen. Igen, Galvan több mint egy évtizedet töltött Alterac hegyeiben, hogy megtanulja ezt a leckét. Fogadd el ezt, és tanulj belőle, amennyit csak tudsz!' WHERE ID=2762;
UPDATE quest_offer_reward SET RewardText='Az ember alig tudja levenni a szemét a pompájáról, $N. Igen, a citrin egy dicsőséges drágakő.$B$BFigyelj, és tanuld meg, mire taníthat minket egy ilyen felfedezés!' WHERE ID=2763;
UPDATE quest_offer_reward SET RewardText='Galvan the Ancient küldött téged??$B$B<Trenton meghajol.>$B$BNagy megtiszteltetés találkozni a mester egy másik tanítványával!' WHERE ID=2764;
UPDATE quest_offer_reward SET RewardText='Csak méltányos, hogy egy sokkal nagyobb erejű csecsebecsét kapj, mint amit feláldoztál, hogy idáig eljuss. Használd egészséggel, $N.' WHERE ID=2765;
UPDATE quest_offer_reward SET RewardText='Beteszed a tojást... a vészjelzőt... a csirkébe... az irányított robotba.$b$bZümmögés és zúgás hallatszik a robot belsejéből, ahogy megpróbál felállni. Miután a robot életre kel, Oglethorpe hangja hallatszik újra, de most a robot belsejéből:$b$b„Az OOX-22/FE legalább működik, de komoly javításra szorul! Túl nehéz ahhoz, hogy elcipeld... de azt hiszem, van egy ötletem. Van kedved még egy kicsit vigyázni rá?”' WHERE ID=2766;
UPDATE quest_offer_reward SET RewardText='Ó, TE vagy az OOX-22/FE nagy megmentője! El sem tudom mondani, mennyire hálás vagyok a segítségedért! Az irányított robot sorozatomnak még sok fejlesztésre van szüksége, de a megmentésed rengeteg órányi újjáépítési időt és sok aranypénzt takarított meg a gyártási költségekben!$b$bKérlek, válassz bármelyiket ezekből a tárgyakból, amik nálam vannak. Még egyszer köszönöm a nagylelkű segítséged, $N, a robotjaim és én is az adósaid vagyunk!' WHERE ID=2767;
UPDATE quest_offer_reward SET RewardText='Megtaláltad! Szép munka, $N! Meg kellett küzdened érte Blyval? Remélem, alaposan móresre tanítottad őt és a bandáját!' WHERE ID=2768;
UPDATE quest_offer_reward SET RewardText='Ah, segíteni akarsz nekem? Remek!$B$BVan egy alkatrész, ami kell egy kísérlethez, amin dolgozom, és egy hozzád hasonló bátor $c-ra van szükségem, hogy megszerezze nekem!' WHERE ID=2769;
UPDATE quest_offer_reward SET RewardText='Wow, megszerezted a pikkelyt! Köszönöm, $N. Alig várom, hogy elkezdjek dolgozni ezen a dolgon!$B$BSzóval láttad Gahz''rillát? Tényleg olyan nagy, mint mondják??' WHERE ID=2770;
UPDATE quest_offer_reward SET RewardText='Kitűnő! Tisztességes csere, ha magam mondom. Figyelj és tanulj, $N!' WHERE ID=2771;
UPDATE quest_offer_reward SET RewardText='A világ a lábaid előtt fog heverni, $N! Jöjjenek csak mind a lábad elé, hiszen most már elsöpörhetetlen vagy!' WHERE ID=2772;
UPDATE quest_offer_reward SET RewardText='Köszönöm mindazt, amire megtanítottál, $N. A díszes mithril készlet mestere és parancsnoka hamarosan a birtokodban lesz.$B$BÍmé!' WHERE ID=2773;
UPDATE quest_offer_reward SET RewardText='Végre - igazságot szolgáltattunk! Hatalmas csapást mértél azokra az aljas nomádokra! Scorpidsting halálával talán végre sikerül eltávolítani azokat a betolakodókat Gadgetzan vízkútjairól!$B$BA Gadgetzan Water Company felhatalmazásával örömmel adományozom neked ezt a vérdíjat. Nagy szolgálatot tettél mindannyiunknak.' WHERE ID=2781;
UPDATE quest_offer_reward SET RewardText='Ez a tábla... egészen szokatlan... Hol találtad ezt, $N?' WHERE ID=2782;
UPDATE quest_offer_reward SET RewardText='A Szövetség segíteni kíván?$B$BAzt hittem, sosem látok még egy ilyen napot. Egy napot, amikor a Szövetség vállvetve harcol a Hordával egy közös ellenség ellen.$B$BÍgy lesz... egyesülünk.' WHERE ID=2783;
UPDATE quest_offer_reward SET RewardText='Szellemként hatalom nélkül vagyok, $N. Segíts nekem. Engedd, hogy visszaszerezzem a becsületemet.' WHERE ID=2784;
UPDATE quest_offer_reward SET RewardText='Itt az ideje cselekedni, $N.' WHERE ID=2801;
UPDATE quest_offer_reward SET RewardText='Megálltál, hogy megvizsgáld ezeknek a bőröknek a szövetét? Megfelelően kezelve ezek a bőrök akár erősebbek is lehetnek a vasnál. Nem sokan tudnak ezekről a bőrökről, és ez, a rengeteg kezelési eljárással kombinálva, amit ismerek, lehetővé teszi, hogy valódi minőségjelzésű tárgyakat készítsek... neked köszönhetően, persze!$B$BÉs most kérlek, válassz abból, amit fel tudok ajánlani a szolgálatodért!' WHERE ID=2821;
UPDATE quest_offer_reward SET RewardText='Ah, kitűnő! Ezek a bőrök, ha speciális kezelést kapnak, mondom neked, olyan ellenállóak, mint a vas! Sok próbálkozásra lesz szükség, hogy megtaláljam a cserzéshez megfelelő keveréket, de biztos vagyok benne, hogy a következő szintre emelik majd a minőségjelzésemet.$b$bAmi téged illet, $N... a segítséged felbecsülhetetlennek bizonyult számomra. Kérlek, válassz ezekből a tárgyakból, amiket készítettem.' WHERE ID=2822;
UPDATE quest_offer_reward SET RewardText='Tudtam, hogy menni fog, $N! Soviknak viszont voltak kétségei.$B$B<Nogg megköszörüli a torkát.>$B$BMost hogy birtokunkban vannak a tervrajzok, csak idő kérdése, hogy kitaláljuk az összes gnóm innovációt, ami a szerkezet létrehozásába került, és goblin innovációkká alakítsuk őket az új tépőgép modelljeinkhez.' WHERE ID=2841;
UPDATE quest_offer_reward SET RewardText='Gyönyörű, nem igaz? A goblin szállítási technológia csúcsa - mindössze egy tucatszor robbant fel.$b$bNe aggódj, $N, teljesen megjavítottam. Nem fog felrobbanni veled - és ha mégis, gyors és fájdalommentes lesz.' WHERE ID=2842;
UPDATE quest_offer_reward SET RewardText='Minden kész! Ha készen állsz, csak lépj rá a lapra.' WHERE ID=2843;
UPDATE quest_offer_reward SET RewardText='Ó, nagyon örülök, hogy megtaláltál! Be kell vallanom, kicsit eltévedtem... De hát nem gyönyörű ez a hely?' WHERE ID=2844;
UPDATE quest_offer_reward SET RewardText='Mi? Azt mondod, ez a csengő működni fog, ha Shay elszalad? Nahát, ki gondolta volna!$B$BMivel ennyit tettél értem, tessék, $N.' WHERE ID=2845;
UPDATE quest_offer_reward SET RewardText='Csodálatos! Megtaláltad! És ami ugyanolyan fontos - Velrathánál már nincs meg! Köszönöm, $N. Örökre adósod vagyok!$B$BÉs ha kicsit... gorombának tűntem korábban, ne törődj vele. Sokkal kedvesebb ember vagyok azokkal, akik nem loptak tőlem.' WHERE ID=2846;
UPDATE quest_offer_reward SET RewardText='Nos, $N, örülök, hogy csatlakoztál hozzánk. Okos döntést hoztál bőrművesként; akik bőrpáncélt viselnek, tolongani fognak nálad, amint megtanulod, hogyan készítsd el bármelyik Vad bőr páncéldarabot.$B$BLássunk munkához - hol szeretnéd kezdeni?' WHERE ID=2847;
UPDATE quest_offer_reward SET RewardText='Ezek a páncélkészletek szilárd minőségűek, $N. Ha van egy dolog, amit megkövetelek nemcsak a saját munkámban, hanem azokéban is, akiket alkalmazok, az a minőség.$B$BJól tetted, hogy kiérdemelted ezt a mintát; remélem, ugyanannyi jutalmat hoz neked, mint amennyit nekem hozott.' WHERE ID=2848;
UPDATE quest_offer_reward SET RewardText='Ezek nagyon szép darabok, $N. Az elkészítésükbe fektetett mesterségbeli tudás és gondosság önmagában is több ezüstöt érne, mint egy átlagos darab.$B$BTeljesítetted a megrendelésemet, és ezzel jár a jutalmad is. A Vad bőr mellények készítésének tudása most már a tiéd!' WHERE ID=2849;
UPDATE quest_offer_reward SET RewardText='Ez a Nightscape felszerelés, amit szállítottál, tökéletesen kielégíti a megrendelést, $N. Nem is várnék kevesebbet egy hozzád hasonló képességű bőrművestől.$B$BHatározottan kiérdemelted ezt a mintát. Szívesen odaadom neked, és remélem, megfelelően hasznodra válik majd.' WHERE ID=2850;
UPDATE quest_offer_reward SET RewardText='Ismét egy összetett megrendelést teljesítettél egy tapasztalt szakember ügyességével. Kiérdemelted ezt a mintát, valamint a köszönetemet.' WHERE ID=2851;
UPDATE quest_offer_reward SET RewardText='Megint egy hibátlan megrendelés. Talán egy nap majd ÉN jövök hozzád tudásért, mi, $N?$B$BItt a minta a lábvértekhez, valamint a köszönetem. Véss ezt a tudásba, és hagyd, hogy a kész termékeid tükrözzék lenyűgöző ügyességedet!' WHERE ID=2852;
UPDATE quest_offer_reward SET RewardText='Ah igen, Pratt küldött. Bár ember, néha minket, éjszaka tündéreket juttat eszembe. Odaadása és a bőrökhöz való tehetsége lenyűgöző. Az, hogy ennyire dicsért téged ebben a levélben, olyan tisztelet jele, amit elismerek.$B$BTudom, hogy megtanította neked a Vad bőr művészetét. Engedd, hogy befejezzem a kiképzésedet ezzel a mintával. Használd jól; kevesen ismerik a világon a Vad bőr köpenyek titkait.' WHERE ID=2853;
UPDATE quest_offer_reward SET RewardText='Nos, $N, örülök, hogy tanoncomként csatlakoztál hozzám. Bölcs döntést hoztál bőrművesként; akik bőrpáncélt használnak, tolongani fognak nálad, amint elsajátítod a Vad bőr művészetét.$b$bLássunk munkához - hol szeretnéd kezdeni?' WHERE ID=2854;
UPDATE quest_offer_reward SET RewardText='Ezek a páncélkészletek szilárd minőségűek, $N. Ha van egy dolog, amit megkövetelek nemcsak a saját munkámban, hanem azokéban is, akiket tanítok, az a minőség.$b$bJól tetted, hogy kiérdemelted ezt a mintát; remélem, ugyanannyi jutalmat hoz neked, mint amennyit nekem hozott.' WHERE ID=2855;
UPDATE quest_offer_reward SET RewardText='Ezek nagyon szép darabok, $N. Az elkészítésükbe fektetett mesterségbeli tudás és gondosság mutatja, hogy teljesen elkötelezted magad e feladatok mellett.$b$bTeljesítetted a kéréseimet, és ezzel jár a jutalmad. A Vad bőr mellények készítésének tudása most már a tiéd!' WHERE ID=2856;
UPDATE quest_offer_reward SET RewardText='Ez a Nightscape felszerelés, amit szállítottál, tökéletesen megfelel az elvárásaimnak, $N. Nem is várnék kevesebbet egy hozzád hasonló képességű bőrművestől.$b$bKiérdemelted a megtiszteltetést, hogy Vad bőr sisakokat készíthess. Szívesen odaadom neked ezt a mintát, és remélem, megfelelően hasznodra válik majd.' WHERE ID=2857;
UPDATE quest_offer_reward SET RewardText='Ismét egy tapasztalt szakember ügyességével készítettél tárgyakat. Kiérdemelted ezt a mintát, valamint a gratulációmat.' WHERE ID=2858;
UPDATE quest_offer_reward SET RewardText='Megint hibátlanul teljesítetted a feladatomat. Talán egy nap majd ÉN jövök hozzád tudásért, mi, $N?$b$bItt a minta a lábvértekhez, valamint a köszönetem. Véss ezt a tudásba, és hagyd, hogy a kész termékeid tükrözzék lenyűgöző ügyességedet!' WHERE ID=2859;
UPDATE quest_offer_reward SET RewardText='Ah igen, Jangdor küldött. Örömmel látom, hogy az egyik legjobb tanítványomnak most már saját tanítványa van.$b$bOdaadása és a bőrökhöz való tehetsége lenyűgöző. Az, hogy ennyire dicsért téged ebben a levélben, olyan tisztelet jele, amit elismerek.$b$bTudom, hogy megtanította neked a Vad bőr művészetét. Engedd, hogy befejezzem a kiképzésedet ezzel a mintával. Használd jól; kevesen ismerik a világon a Vad bőr köpenyek titkait.' WHERE ID=2860;
UPDATE quest_offer_reward SET RewardText='Így van. Van némi elintéznivalóm egy trollal. Egész pontosan az összes csontjával!$b$bSegítesz nekem?' WHERE ID=2861;
UPDATE quest_offer_reward SET RewardText='Ez egy jó kezdet bizonyítéka, $N. Katonai képességeid dicséretet érdemelnek.$B$BNem te vagy az egyetlen, akit erre a feladatra kértem. Sokan harcoltak ellenük előtted, és korábban erőfeszítéseink távol tartották őket. Mostanában azonban jelentősen megnőttek az északra, a mi befolyási területünkre irányuló előretörési kísérleteik. A támadásaik is vadabbá váltak... szinte mintha kétségbeesettek lennének.$B$BVan azonban egy tervem, $N, ami talán egyszer s mindenkorra rendezheti a velük szembeni helyzetet...' WHERE ID=2862;
UPDATE quest_offer_reward SET RewardText='Megtetted, amit kértem, és ezért tisztelgek előtted. Fogadd el ezt a kis jutalmat erőfeszítéseidért, $N.$B$BLétszámuk megfogyatkozásával és vezetőik megölésével a gnollok kétszer is meggondolják majd, hogy megrohamozzák-e a tábort. Ez azonban nem zárja le az ügyet...$B$BValamilyen oknak kell lennie annak, hogy a gnollokat ilyen tomboló állapotba korbácsolták. Mielőtt esélyük lenne újraszerveződni, ki akarom deríteni, mi okozza ezt.' WHERE ID=2863;
UPDATE quest_offer_reward SET RewardText='Helló!$B$BÓ, beszéltél az unokatestvéremmel, Krazekkel? Hogy van? Remélem, Booty Bay jól bánik vele...$B$BScarab-héjak, mondod? Nos... hadd meséljek egy történetet...' WHERE ID=2864;
UPDATE quest_offer_reward SET RewardText='Ó, remek! Megszerezted őket!$B$BKöszönöm, $N. Igazi életmentő vagy!' WHERE ID=2865;
UPDATE quest_offer_reward SET RewardText='A pavilon vizsgálata néhány érdekes és szokatlan dolgot tár fel a körülötte lévő romokhoz képest.$B$BElőször is, a pavilon egyértelműen újabb építmény, mint a romok többi tárgya. Másodszor, a pavilon oldalaiba egy rövid glifasort véstek; a glifák mintázata ismétlődik, de eredetük és jelentésük egyébként ismeretlen. Harmadszor, maga a pavilon köve meleg érintésre.$B$BEz mindenképp „kirívónak” számít a romok kutatása során!' WHERE ID=2866;
UPDATE quest_offer_reward SET RewardText='Üdvözöllek újra, $N. A jelentésed erről a pavilonról meglehetősen... nyugtalanító. Úgy tűnik, még ha a naga ott nem is tervezett támadást, folyamatos jelenlétük rosszat sejtet a Feralasba való előretörésünk szempontjából. Mindenesetre itt a fizetséged a nyomozásodért.$B$BÚgy tűnik, Feathermoon Stronghold sürgősen további segítségre szorul a Hatecrest naga ügyében. Szeretném felajánlani neked ezt a feladatot, ha van kedved hozzá. Sok a tennivaló.' WHERE ID=2867;
UPDATE quest_offer_reward SET RewardText='Igen, igen, ezek a pikkelyek több mint megfelelőek. Valójában azt hiszem, leküldöm őket Prattnak, hogy megnézze őket. Talán tud belőlük valami hasznosat készíteni.$B$BAmi téged illet, van egy másik küldetésem, amire szeretnélek elküldeni. De előbb itt a fizetséged a pikkelyekért. A tábornoknak és Feathermoon Stronghold-nak tett folyamatos szolgálatod áldás a nehézségek közepette.' WHERE ID=2869;
UPDATE quest_offer_reward SET RewardText='Szépen csináltad, $N! Lord Shalzaru halála egy időre, ha nem véglegesen, zűrzavarba taszítja a nagát. Az általuk jelentett fenyegetés most jobban a kontrollunk alatt van, mint valaha, és ezt neked köszönhetjük.$B$BItt van még jutalompénz az erőd kincstárából - minden rézpénzt kiérdemeltél. Te és a tieid bármikor szívesen látott vendégek vagytok Feathermoon Strongholdban, barátom.$B$BMég egy dolog, mielőtt elindulnál, $N... ha lehetne...' WHERE ID=2870;
UPDATE quest_offer_reward SET RewardText='Érdekes... azt mondod, ez a Solarsal-romokból származik? Nos, Latrónak igaza van, meg kell néznem. Első pillantásra úgy tűnik, nem őshonos a romoknak. Másrészt viszont ez nem naga tervezés... nem valami ennyire idegen.$B$BEgy ideig fog tartani a tárgy kutatása. Amint elkészülök a kutatással, talán hasznát veszem a tehetségednek, ha a közelben leszel.$B$BTessék, vidd el az egyik extra tárgyunkat; remélem, hasznát veszed!' WHERE ID=2871;
UPDATE quest_offer_reward SET RewardText='Ah, szóval MacKinley-vel beszélgettél, ugye?$B$BEz nem az, aminek ő gondolja! Nem félek adni neki Steamwheedle Bilge Rumot...$B$BCsak épp nincs rumom, amit adhatnék neki!' WHERE ID=2872;
UPDATE quest_offer_reward SET RewardText='Remek, köszönöm a szállítmányt! Most már MacKinley-vel végre rendezhetjük a fogadásunkat.' WHERE ID=2873;
UPDATE quest_offer_reward SET RewardText='Hm, próbáljuk ki...$b$bEl sem hiszem! Ez a cucc... szörnyű! Ez remek!$b$bNos, gondolom Stoley megtarthatja a pénzt, amivel tartozik nekem. Igazat mondott a Steamwheedle bilge rumról. Az a cucc olyan sűrű, mint a kavics, és úgy éget, mint a láva!' WHERE ID=2874;
UPDATE quest_offer_reward SET RewardText='Ah, Andre feje. Szóval mégiscsak eljut a tárgyalásra!$B$BNagyra értékelem, $N. Most ha csak aláírnád itt, kifizethetem a nyújtott szolgáltatásokért.$B$BNe aggódj az apróbetűs rész miatt. Ártalmatlan, és... szerintem úgysincs elég kicsi nagyító, amivel elolvasható lenne.' WHERE ID=2875;
UPDATE quest_offer_reward SET RewardText='Te jó ég, ez úgy néz ki, mint egy lista a hajók indulásairól és érkezéseiről, pontos dátumokkal és időpontokkal, mindennel együtt! Ha egy kalózhajó kapitánya kezébe kerülne, alaposan kiélvezhetné!$B$BAzt mondod, egy kalóztól szerezted? Nos, ez nyugtalanító hír...$B$BKöszönöm, $N. Örülök, hogy elvetted tőle, és örülök, hogy az a kalóz most a föld alatt van!' WHERE ID=2876;
UPDATE quest_offer_reward SET RewardText='Nézd csak, hogy segítesz a Wildhammereknek! Cselekvő $c vagy, és a cselekvést tiszteljük errefelé.$B$BEz a kis takarítási küldetésed sokkal fontosabb, mint gondolnád. Ahogy az emberek ritkítják a nyálkákat és iszapokat, hamarosan kiterjeszthetjük a befolyási körünket. Tessék - kapj valamit azon kívül, hogy új barátokra tettél szert itt, Aerie Peak-en!' WHERE ID=2877;
UPDATE quest_offer_reward SET RewardText='Cenarion növénykenőcsöt kensz a dalvirágra. Azonnal elkezdi levetni megrontott formáját, és élénk, egészséges növénnyé bomlik ki.' WHERE ID=2878;
UPDATE quest_offer_reward SET RewardText='A feltöltött botot szinte lehetetlen tartani. Ereje végigdübörög a testeden.$B$BKinyúlsz az Equinex Monolit hideg felszíne felé...$B$BEgy kis ajtó nyílik ki, lehetővé téve, hogy benyúlj, és elvedd a bent lévő ereklyét.$B$BFénysugarak töltik be az Equinex Monolit körüli területet.' WHERE ID=2879;
UPDATE quest_offer_reward SET RewardText='Ez az, amiről beszélek! Látod - ezek a nyakláncok bizonyítják, hogy hajlandó vagy beszennyezni a kezed. Mi, Wildhammerek, nagyra értékeljük ezt azokban, akikkel kapcsolatban állunk.$B$BFolytasd így, és hamarosan a kegyeinkbe kerülsz.' WHERE ID=2880;
UPDATE quest_offer_reward SET RewardText='Ez az, amiről beszélek! Látod - ezek a nyakláncok bizonyítják, hogy hajlandó vagy beszennyezni a kezed. Mi, Wildhammerek, nagyra értékeljük ezt azokban, akikkel kapcsolatban állunk.$B$BFolytasd így, és hamarosan a kegyeinkbe kerülsz.' WHERE ID=2881;
UPDATE quest_offer_reward SET RewardText='Cuergo kapitány elrejtett kincse vár rád!' WHERE ID=2882;
UPDATE quest_offer_reward SET RewardText='A térkép vizsgálata felfedi, hogy ezek azok a csatatervek, amiket Hadoken Swiftstrider akar. Számos nyíl, ami talán csapatmozgásokat jelöl, van a térképre rajzolva, bár a legtöbb inkább dél felé mutat, nem észak felé, ahol Camp Mojache található.$B$BA térkép egy másik részén egy kép látható, ami szerinted valamiféle nagy rovart ábrázol, alatta különféle jelölésekkel. A gnollok kinézete alapján ez talán az ismeretlen bogarak elleni veszteségeiket jelöli...' WHERE ID=2902;
UPDATE quest_offer_reward SET RewardText='Ah, pontosan erre volt szükségünk. Bár nem vagyok túl ügyes a térképen lévő legtöbb firka megfejtésében, elég csatatervet láttam már életemben ahhoz, hogy megértsem, mi történik a gnollokkal. Úgy tűnik, jelenleg két fronton harcolnak. Az egyik velünk... de úgy tűnik, fő erejüket egy tőlük délre lévő ellenség ellen fordítják.$B$BTöbb rejlik ebben, mint amennyi elsőre látszik. Talán ideje kideríteni, ki is valójában ez a másik ellenség, akivel szemben állnak.' WHERE ID=2903;
UPDATE quest_offer_reward SET RewardText='Gondolom, jutalmat érdemelsz azért, hogy egyben hoztad vissza Kernobee-t hozzánk, $N. Ha visszamész Gnomereganbe, ezek talán megadják neked azt az előnyt, amire szükséged lesz, hogy legyőzd azt a semmirekellő hátbaszúrót, Mekgineer Thermaplugg-ot.' WHERE ID=2904;
UPDATE quest_offer_reward SET RewardText='Ó, ez csodálatos! Köszönöm, $N! Azonnal munkához látok!!$B$BSzegény, szegény Techbot... Ne érezd rosszul magad. Megjavítunk.$B$BMost hova is tettem azt a dugót a hidraulikus forgó csavarkulcsomhoz...' WHERE ID=2922;
UPDATE quest_offer_reward SET RewardText='Igen, ez igaz. Techbot $c lett! Kérlek, tudsz segíteni nekem?' WHERE ID=2923;
UPDATE quest_offer_reward SET RewardText='Megszerezted őket! Most már elkezdhetem az új kísérleteimet!$B$BNem tudok eléggé köszönetet mondani, $N! A bátorságod hatalmas ugrással vitte előre a gnóm kutatást!' WHERE ID=2924;
UPDATE quest_offer_reward SET RewardText='Igen! Segítségre van szükségem egy Gnomereganba vezető küldetéshez. És pont te vagy a megfelelő $c erre!' WHERE ID=2925;
UPDATE quest_offer_reward SET RewardText='Kitűnő munka! Eljött az ideje, hogy teszteljük az új formulát. Ha bejön, nemcsak az a foglyul ejtett leprás gnóm gyógyul meg, hanem nekem is dús hajkoronám lesz! Állj hátrébb!' WHERE ID=2926;
UPDATE quest_offer_reward SET RewardText='Azt hittem, az a kiváló hajkorona elvesztése biztosan a végét jelenti majd neki, de túlélte!$B$BPont mellette álltam, amikor eltalálta a sugárzási lövedék. Azok a gyönyörű barna hajtincsek csomókban hullottak a padlóra! Fürtökben! Az egész borzalmát csak fokozta, hogy Gnoarn teljesen kiakadt! Ó igen, kiakadt, mondom! Gnoarn hitetlenkedve tapogatta kopasz fejét, a szeme bosszúért kiáltott, $N! Aztán a troggok felé fordította a dühét!$B$B<Ozzie összerezzen.>' WHERE ID=2927;
UPDATE quest_offer_reward SET RewardText='Ez pont jó lesz, $N. Egy gyrofúrós ásógép megjavítva; még 398 van hátra.' WHERE ID=2928;
UPDATE quest_offer_reward SET RewardText='Szeretem azt hinni, hogy az utolsó dolog, ami átfutott a fején, mielőtt összeesett, a te lábad volt, $R. Thermaplugg halálával a Gnomeregan visszafoglalására szőtt terveink egy lépéssel közelebb kerültek a megvalósuláshoz.' WHERE ID=2929;
UPDATE quest_offer_reward SET RewardText='Sikerült! Megtaláltad a prizmatikus lyukkártyát, és visszaszerezted az elveszett adatokat! Létfontosságú, kritikus, felmérhetetlenül fontos adatokat, amelyek nélkül egy pillanatig sem élhettünk volna tovább!$B$BA gnómoknak tett szolgálatodat sokáig emlegetni fogjuk, $N.' WHERE ID=2930;
UPDATE quest_offer_reward SET RewardText='Adatkinyerő küldetéseket szervezek Gnomereganba. Ha ezért vagy itt, figyelj!' WHERE ID=2931;
UPDATE quest_offer_reward SET RewardText='Hírét vettem a tettednek. Komor tett, de becsületes. Reméljük, a Witherbarkok megszívlelik az üzeneted.' WHERE ID=2932;
UPDATE quest_offer_reward SET RewardText='Ah, és ez meg mi? Úgy tűnik, méreg... valamiféle pókszerű lényből, gondolom. És honnan szerezted?' WHERE ID=2933;
UPDATE quest_offer_reward SET RewardText='Ó, remek! A méreg egészen friss, és biztos vagyok benne, hogy nagyon halálos. Köszönöm!' WHERE ID=2934;
UPDATE quest_offer_reward SET RewardText='Ah, szóval friss mérget akarsz a witherbark-pókoktól, igaz? Nos, ülj le... nem fog tetszeni, amit mondani fogok.' WHERE ID=2935;
UPDATE quest_offer_reward SET RewardText='Ah, Elortha no Shadra... ezt a nevet csak suttogva mondd ki, mert kiejtése nagy súllyal bír a szellemi birodalmakban.$b$bPergamenre vetem, és készítek neked egy idéző varázslatot...' WHERE ID=2936;
UPDATE quest_offer_reward SET RewardText='Remek, megvan!' WHERE ID=2937;
UPDATE quest_offer_reward SET RewardText='Ah, nagyon jó. Lydon megemlítette, hogy az ebben a csomagban lévő méreg a legerősebb, amivel valaha találkozott, és éppen új alkalmazásokon dolgozik vele.$b$bSzerencsével sokat fogunk találni.$b$bKöszönöm, $N. A Royal Apothecary Societynek tett szolgálatod vitathatatlan.' WHERE ID=2938;
UPDATE quest_offer_reward SET RewardText='Ó, szóval Troyas Moonbreeze küldött?$b$b<mormol>...folyton azzal zaklat, hogy vad elképzelései szerint valami fontosat talált...$b$bNézd, $N, őszinte leszek. Troyas mindig azt hiszi, hogy talált valami fontosat azokban a romokban. Az igazság az, hogy ami valóban értékes volt, azt valószínűleg már régen elhalmozták az ogrék vagy a hárpiák, akik most ott laknak.$b$bSzívesen nézz körül, de nem tudom, találsz-e itt olyan könyveket, amik segítenének.' WHERE ID=2939;
UPDATE quest_offer_reward SET RewardText='Szóval kölcsön szeretnéd kérni a Feralas: egy történelem című könyvet?$b$bHadd gondolkodjam...$b$bMegengedem, hogy kölcsönvedd ezt a könyvet, $N, de csak ha előbb teszel valamit értem.' WHERE ID=2940;
UPDATE quest_offer_reward SET RewardText='Te is Daryn egyik gyakornoka vagy? Ő egy igen tudós történész, $N. Hálásnak kell lenned, hogy az ő vezetése alatt tanulhatsz.$b$bMost pedig hadd hozzam a Super Snapper FX-et. Imádni fogod!' WHERE ID=2941;
UPDATE quest_offer_reward SET RewardText='Azóta olvasok, hogy elmentél, $N. Ezt a követ, amit találtál, Morrow-kőnek hívják. Bár még nem vagyok teljesen biztos benne, mi a rendeltetése, biztos lehetsz benne, hogy jelentős dolog, ha így elrejtették az Equinex Monolitban.$B$BFolytatom a tanulmányaimat, és remélem, számíthatok rád a jövőben, $N. Köszönöm minden segítségedet.' WHERE ID=2942;
UPDATE quest_offer_reward SET RewardText='Hoztál magaddal egy könyvet. Kitűnő!' WHERE ID=2943;
UPDATE quest_offer_reward SET RewardText='Nos! Curgle találmánya beváltotta a hozzá fűzött reményeket.$B$BNe örülj túlságosan, de tudd meg, elégedett vagyok a munkáddal, $N.$B$BMost hova is tettem azt a könyvet...' WHERE ID=2944;
UPDATE quest_offer_reward SET RewardText='Beteszed a gyűrűt a Sparklematic 5200-ba, és bedobsz egy ezüstérmét a nyílásba.$B$BFájdalmas csikorgó hangok szűrődnek ki a gépből, ahogy hevesen rángatózni kezd. Csak találgatni lehet, mi történik a gyűrűvel a gép belsejében...$B$BA gép hirtelen megáll, egy egyszerű „Csing!” hanggal jelezve a leállást. A tárolórekesz kinyílik, felfedve egy kis dobozt, ami szépen be van csomagolva egy piros masnival. Úgy tűnik, a Sparklematic 5200 ajándékba is csomagol!' WHERE ID=2945;
UPDATE quest_offer_reward SET RewardText='Ahogy megérinted a talapzatot, az Uldamanból származó miniatűr korongok zümmögni és izzani kezdenek a hátizsákodban. Egy ismerős bizsergés fut végig a kezeiden, ahogy egy másik Kővigyázó képe kel életre Uldum kapui előtt.$b$b„Üdvözlet. Én egy belépési őrző vagyok. A belépéshez használt korongokból hiányoznak a megfelelő belépő korongok, az Uldum Lemezei. Kérlek, illeszd be ezeket a lemezeket a korongstruktúrába, és ismételd meg a belépési sorrendet. Köszönöm.”' WHERE ID=2946;
UPDATE quest_offer_reward SET RewardText='Egy gyűrű, mondod? Lássuk csak... igen, én csináltam azt a gyűrűt, azt meghiszem.$B$BMielőtt Gnomeregan felrobbant, volt ott egy kis boltom. Talán ez egy azok közül, amit otthagytam, amikor a dombok felé menekültem; egyszerű a mintázata, és többet is csináltam belőle. Talán valakié volt, aki nem jutott ki élve.$B$BDark Iron törpéknél volt ez? Nos, ez egy újabb réteget ad a már így is kilenc réteg összeesküvéshez. Talán a hatóságok szívesen hallanák; rám pazarolt lenne az információ.$B$BDe térjünk vissza a gyűrűre...' WHERE ID=2947;
UPDATE quest_offer_reward SET RewardText='Ah, pontosan erre volt szükségem! Egy nap, amikor kikerülök ebből a gödörből, amibe jogtalanul kerültem, neked, MINDENKINEK a legfinomabb csecsebecséket fogom készíteni egész Azerothban! Addig is köszönöm, hogy sportszerű voltál az alapanyagokkal kapcsolatban. Általában tízszer annyit kérnék egy ilyen minőségű gyűrűért, mint amennyit tőled kértem...$B$BApropó, gyűrűk, itt az új gyűrűd!' WHERE ID=2948;
UPDATE quest_offer_reward SET RewardText='Egy gyűrű Gnomereganból? Lássuk csak... nem az enyém, de érdekes.$B$BA Gnomeregan-ügy - nem is történhetett volna kedvesebb tökfejekkel. Évekig ők voltak a vicc, most meg szinte egyik napról a másikra jobb szerkezeteket gyártanak, mint mi?$B$BA Dark Iron törpéknél volt a gyűrű? Ez még érdekesebb! Tudod, talán a gnómok ellopták az őrült gólem-terveiket, és módosították azokat. Azok a Dark Ironok biztosan komoly bosszút akarnának. Mindenképp érdemes lenne kivizsgálni.$B$BTudod, ami azt a gyűrűt illeti...' WHERE ID=2949;
UPDATE quest_offer_reward SET RewardText='Itt a gyűrűd, jobb, mint korábban. Még egyszer köszönöm az információt azokról a Dark Iron törpékről. Ez egészen ésszerű nyomnak tűnik arra nézve, hogyan is csapott le hirtelen a gnómokra a goblinokéhoz hasonló ihlet.' WHERE ID=2950;
UPDATE quest_offer_reward SET RewardText='Beteszed a szennyel borított tárgyat és három ezüstérmét a Sparklematic 5200-ba. A gép tomboló igyekezettel kel életre, hogy eltávolítsa a szennyet az ismeretlen tárgyról. Hangos, heves kavargó zajok dübörögnek a gép szívéből. A szörnyeteg fémváza nyikorog és nyög, ahogy oldalról oldalra dülöngél...' WHERE ID=2951;
UPDATE quest_offer_reward SET RewardText='Amilyen gyorsan elkezdődött, olyan hirtelen le is áll a Sparklematic 5200. Egy egyszerű „csing” hallatszik a gépből, és a gép szája felfelé csavarodik. A Sparklematic 5200 belsejében egy kis, masnival díszített doboz van. Úgy tűnik, a gép becsomagolja a tárgyat, miután megszűnteti a szennyezettségét. Még ha a gép nem is működött, legalább a tárgy most egy szép dobozba van csomagolva.$B$BNos, van egy módja annak, hogy kiderítsük, megtisztította-e a tárgyat vagy sem...' WHERE ID=2952;
UPDATE quest_offer_reward SET RewardText='A Sparklematic 5200 életre kel, ide-oda dülöngélve. Belsejében a beletett tárgyat borító tehetetlen szennyet a gép gnóm tisztítószere porrá zúzza.$B$BA Sparklematic 5200 megáll, egy ismerős „csing!” hang kíséretében. A gép tárolórekesze kicsavarodva kinyílik, felfedve egy szépen becsomagolt dobozt.' WHERE ID=2953;
UPDATE quest_offer_reward SET RewardText='A kővigyázó hangja erővel és tekintéllyel zeng:$b$b„A korongjaidat visszakapod, amint hozzáférsz a talapzathoz. Ha megszerezted az Uldum Lemezeit, és beillesztetted őket a meglévő korongkészletedbe, akkor beléphetsz a komplexumba.”' WHERE ID=2954;
UPDATE quest_offer_reward SET RewardText='<Ozzie megvizsgál téged.> Lenyűgöző, még mindig megvan minden végtagod. Most pedig nézzük, mire képes ez a cucc!' WHERE ID=2962;
UPDATE quest_offer_reward SET RewardText='Örülök, hogy fenntartod az érdeklődésedet a felfedezés iránt, $N! Természetes tehetségeddel és merészségeddel olyan titkokat fedezhetnénk fel, amikről sosem gondoltuk volna, hogy lehetségesek!$B$BAz Uldamanban lévő Norgannon Korongjai hatalmas információtár volt; csak az ott tárolt információ felső rétegeihez férhettél hozzá, hogy úgy mondjam. A Teremtők állítólag több raktárral is rendelkeztek szerte Azerothban. Ez pedig elvezet minket Uldumhoz...' WHERE ID=2963;
UPDATE quest_offer_reward SET RewardText='Akkor mindannyian egyetértünk - a legjobb terv az, ha felfüggesztjük ezt, amíg le nem szűkítjük azokat a területeket, ahol ezek a lemezek rejtőzhetnek. Idáig eljuttattál minket, $N, és remélem, te leszel az, aki visszatér a terepre, hogy feltárja Uldumot mindannyiunk számára!$B$BAddig is engedd meg, hogy adjak neked ezt a tiszteletdíjat; ennek fedeznie kell minden felmerült költségedet, valamint egy kis extrát is. Nézz vissza hozzánk hamarosan... Uldum hív!' WHERE ID=2964;
UPDATE quest_offer_reward SET RewardText='Van egy hely mélyen a Tanaris sivatagban, amit az Őrzők Völgyének hívnak. A korongok, amiket visszaszereztél... lefordított glifáik említést tesznek egy Uldum nevű helyről. A legtöbben úgy gondolják, ez a hely mítosz.$B$BÉn tudom, hogy ez hamis; Uldum létezik. Jártam ott. Nos... legalábbis kívül, mindenesetre.$B$BA lényeg ez, $N: úgy gondoljuk, kapcsolat van a korongok és Uldum között, és azt szeretnénk, hogy odautazz.' WHERE ID=2965;
UPDATE quest_offer_reward SET RewardText='Ahogy megérinted a talapzatot, az Uldamanból származó miniatűr korongok zümmögni és izzani kezdenek a hátizsákodban. Egy ismerős bizsergés fut végig a kezeiden, ahogy egy másik Kővigyázó képe kel életre Uldum kapui előtt.$B$B„Üdvözlet. Én egy belépési őrző vagyok. A belépéshez használt korongokból hiányoznak a megfelelő belépő korongok, az Uldum Lemezei. Kérlek, illeszd be ezeket a lemezeket a korongstruktúrába, és ismételd meg a belépési sorrendet. Köszönöm.”' WHERE ID=2966;
UPDATE quest_offer_reward SET RewardText='Hiányoztak néhány korongjaid? Érdekes módon úgy tűnik, Norgannon korongjai csak részei a teljes készletnek - mint kulcsok egy kulcskarikán, hogy úgy mondjam.$B$BHa megtaláljuk Uldum Lemezeit, akkor valóban hozzáférhetünk magához az Uldum-komplexumhoz. Nem tudom, izgatott legyek-e ettől a lehetőségtől, vagy rettegjek tőle.$B$BTalán mindent kockára kell tennünk, hogy biztosítsuk, azok a titkok, amiket a föld őriz, és amik mindannyiunkat elpusztítanának, titkok is maradjanak.' WHERE ID=2967;
UPDATE quest_offer_reward SET RewardText='Akkor mindannyian egyetértünk - a legjobb megoldás, ha várunk, amíg le nem szűkítjük azokat a területeket, ahol ezek a lemezek rejtőzhetnek. Idáig eljuttattál minket, $N, és remélem, te leszel az, aki visszatér a terepre, hogy szembenézzen Uldum titkaival.$B$BAddig is engedd meg, hogy adjak neked ezt a tiszteletdíjat; ennek fedeznie kell minden felmerült költségedet, valamint egy kis extrát is. Nézz vissza hozzánk hamarosan... Uldum mindannyiunkat hív, ifjú.' WHERE ID=2968;
UPDATE quest_offer_reward SET RewardText='Hála Elune-nak, $N! Nagy áldás vagy számunkra és a megmentett vízisárkányok számára is. Jer''kai és én magunktól sosem tudtunk volna segíteni a sárkányoknak - beavatkozásodat a Grimtotem ügyeibe emlékezetben tartjuk majd.$B$BBeszélj most Jer''kaival... nekem fel kell készülnöm a megtorlásunkra. Attól, hogy a tündérsárkányok szabadok, még nem biztos, hogy azok is maradnak. Jer''kai és én most támadásba lendülünk.' WHERE ID=2969;
UPDATE quest_offer_reward SET RewardText='Kindalnak igaza volt veled kapcsolatban, $N - tényleg van érzéked ehhez. Sokkal tapasztaltabb kalandozó vagy nálunk kettőnknél, és ezért köszönetet mondunk.$B$BA Grimtotem klán sokkal ellenségesebb, mint a legtöbb tauren... Vajon a saját fajtájuk is rosszallja a tetteiket? Nem lepődnék meg rajta. Ahogy valószínűleg tudod, sok azerothi faj kapcsolatban áll kevésbé kedves társaikkal.$B$BDe ez egy másik napra való beszélgetés.' WHERE ID=2970;
UPDATE quest_offer_reward SET RewardText='Ez egy elképesztő történet, $N. Örömünkre szolgál, hogy nemcsak a sárkányfajtának segítettél, hanem az egyik saját papnőnknek is. Jer''kai jól tette, hogy hozzám küldött. Gondoskodom róla, hogy visszakapja a gyűrűjét - hamarosan felderítőket küldök Feralas irányába. Ez lesz még egy dolog, amit kivizsgálhatnak a küldetésük során.$B$BMég egyszer köszönöm, és kérlek, érezd otthon magad, amíg itt vagy.' WHERE ID=2972;
UPDATE quest_offer_reward SET RewardText='Csodálatos, $c! Ezek pont jók lesznek. Elég van itt ahhoz, hogy köpenyt készítsünk Korrinnak, talán még többet is! Köszönöm.$b$bRemélem, az út nem volt túl veszélyes? Feralas vidéke nem híres arról, hogy megbocsátó lenne, de nyilvánvalóan jól boldogultál.$b$bMég egyszer köszönöm, $c.' WHERE ID=2973;
UPDATE quest_offer_reward SET RewardText='Ezek jó szarvak, $c. Szép munka. Elveszem tőled, és biztosan elmondom Belgromnak, amint visszatérünk Orgrimmarba. Már kétszer segítettél nekem, és ezért kiérdemelted a jelemet. Talán a jövőben én is segíthetek neked! Sok szerencsét.' WHERE ID=2974;
UPDATE quest_offer_reward SET RewardText='Kitűnő, $N. Idővel a föld meggyógyul. Nem szabad feladnunk.' WHERE ID=2975;
UPDATE quest_offer_reward SET RewardText='A Grimtotem!? Ez érdekes. Azt mondod, rájuk bukkantál, miközben Feralasban vadásztál? Tényleg?$b$bA társaim hallani akarják majd a híreidet, $c. Mondj el mindent, és közben leszámolom az érméidet.$b$bÉs mielőtt elmész, tudd, hogy hálás vagyok a mai napon átadott információért.' WHERE ID=2976;
UPDATE quest_offer_reward SET RewardText='Hiányoztak néhány korongjaid? Érdekes módon úgy tűnik, Norgannon korongjai csak részei a teljes készletnek - mint kulcsok egy kulcskarikán, hogy úgy mondjam.$B$BHa megtaláljuk Uldum Lemezeit, akkor valóban hozzáférhetünk magához az Uldum-komplexumhoz! Képzeld el, ahogy valóban felfedezed azt a helyet, ahol a Teremtők dolgoztak, anélkül, hogy hatalmas ásót kellene hoznod!$B$BNem mintha bármi baj lenne az ásókkal... vagy az ásással...' WHERE ID=2977;
UPDATE quest_offer_reward SET RewardText='Ez a tekercs... Ezt a Gordunni Előőrsön találtad?' WHERE ID=2978;
UPDATE quest_offer_reward SET RewardText='Ez a gömb több információt fog adni nekünk a Gordunniról... amit aztán a bukásuk megtervezésére fogunk használni, $N.' WHERE ID=2979;
UPDATE quest_offer_reward SET RewardText='Bebizonyítottad, hogy megbízható és számítható szövetséges vagy, $N.' WHERE ID=2980;
UPDATE quest_offer_reward SET RewardText='Szóval Belgrom küldött. Épp jókor jöttél, $R.$B$BHadd magyarázzam el a helyzetet, aztán eldöntheted, hogy készen állsz-e a kihívásra... De ha Belgrom küldött, biztos vagyok benne, hogy a bátorságod megkérdőjelezhetetlen.' WHERE ID=2981;
UPDATE quest_offer_reward SET RewardText='Nagyon hálás vagyok, hogy meg tudtad ezt tenni értem.$B$BMost pedig, kérlek, egy szót se szólj erről Troyasnak...' WHERE ID=2982;
UPDATE quest_offer_reward SET RewardText='Hmmm, szóval Swart küldött hozzám?$B$BNos, Swartban mindig meg lehetett bízni, szóval ez azt jelenti, hogy készen állsz részt venni a következő saptán - a tűz saptáján.$B$BMár látom a szemedben, az égést, a vágyat. Megízlelted a hatalmat, és most többre vágysz belőle. Türelem, $N. Emlékezz arra, amit a föld tanított neked. A hatalom és a pusztítás könnyen jön majd, de tudnod kell, mikor kell visszafognod magad.' WHERE ID=2983;
UPDATE quest_offer_reward SET RewardText='Hmmm, szóval Narm küldött hozzám?$b$bNos, Narmban mindig meg lehetett bízni, szóval ez azt jelenti, hogy készen állsz részt venni a következő saptán - a tűz saptáján.$b$bMár látom a szemedben, az égést, a vágyat. Megízlelted a hatalmat, és most többre vágysz belőle. Türelem, $N. Emlékezz arra, amit a föld tanított neked. A hatalom és a pusztítás könnyen jön majd, de tudnod kell, mikor kell visszafognod magad.' WHERE ID=2984;
UPDATE quest_offer_reward SET RewardText='A szél gyorsan közeledik feléd a horizonton; a föld szilárdan áll lábad alatt; és lelked már felmelegedett a tűztől - azt mondanám, ideje megismerned a víz tisztaságát.$B$BUtad idáig vezetett, és lelked erőt ad, hogy még tovább folytasd. De az első lépést neked kell megtenned.' WHERE ID=2985;
UPDATE quest_offer_reward SET RewardText='A szél gyorsan közeledik feléd a horizonton; a föld szilárdan áll lábad alatt; és lelked már felmelegedett a tűztől - azt mondanám, ideje megismerned a víz tisztaságát.$B$BUtad idáig vezetett, és lelked erőt ad, hogy még tovább folytasd. De az első lépést neked kell megtenned.' WHERE ID=2986;
UPDATE quest_offer_reward SET RewardText='Tökéletes! Ezeket magammal viszem, ahogy folytatom az utamat, $N. Biztos vagyok benne, hogy találok valakit, aki szép summát fizet ezért a kobaltért.$b$bTessék, fogadd el ezt a fáradozásodért.' WHERE ID=2987;
UPDATE quest_offer_reward SET RewardText='Sharpbeak nem volt a falvakban? Hm... ez komor hír. Az a griff arra hivatott, hogy a griffek következő generációját vezesse. Ha elveszik, akkor flottánk ereje és szelleme rendkívül sokat szenved majd.' WHERE ID=2988;
UPDATE quest_offer_reward SET RewardText='Sharpbeak nem volt ott? Ez rossz hír, de jó hír is egyben...$B$BJó, hogy nem volt a Zul Oltáránál, mivel a Vilebranch trollokról ismert, hogy áldozatokat mutatnak be.$B$BKöszönöm minden segítségedet, de attól tartok, egy még nagyobb feladat vár rám.' WHERE ID=2989;
UPDATE quest_offer_reward SET RewardText='Ah, igen. Ez a toll egy remek griffhez tartozik. Egyhez, aki nagy dolgokra hivatott... ha sértetlenül eléri a felnőttkort.$B$BMeg akarod találni? Akkor figyelj jól, bátor $c...' WHERE ID=2990;
UPDATE quest_offer_reward SET RewardText='Ah, Nekrum medálja. Állítólag természetellenesen hosszú életet adott a trollnak, de nem ingyen. Remélem, találok módot arra, hogy learassam a medál erejét, elkerülve annak... kellemetlen mellékhatásait.$B$BSzolgálatot tettél nekem, $N. Most betartom a magam részét az alkunak.' WHERE ID=2991;
UPDATE quest_offer_reward SET RewardText='A szertartás sikeres volt. Láttam Sharpbeaket, és el tudom mondani, hogyan találhatod meg.' WHERE ID=2992;
UPDATE quest_offer_reward SET RewardText='Beszéltél Grimshade-del? Mit mondott?$B$B...Micsoda? A Vilebranch trolloknál van Sharpbeak? Ez elviselhetetlen! Erőt kell szerveznünk, hogy visszaszerezzük!' WHERE ID=2993;
UPDATE quest_offer_reward SET RewardText='Swiftwind és Keenclaw néhány pillanattal ezelőtt tért vissza a gyermekükkel, és úgy aggódnak érte, mint a friss szülők. Ahogy újra együtt látom őket, ez elég ahhoz, hogy még ennek az öreg törpének is könnybe lábadjon a szeme...$B$BSosem tudjuk eléggé meghálálni, amit tettél, $N. Aerie Peak griffjei és lovasaik sokáig, nagyon sokáig énekelni fogják majd a nevedet.' WHERE ID=2994;
UPDATE quest_offer_reward SET RewardText='Tökéletes, $N. Amíg a Highvale azon dolgozik, hogy visszaszerezze elveszett információikat, mi tovább tudjuk zárni a vonalakat...' WHERE ID=2995;
UPDATE quest_offer_reward SET RewardText='Mozgalmas nap ez Ratchetben, nem igaz? Mennyire élvezem nézni egy kikötőváros nyüzsgését. Annyi rejtély, annyi kaland... annyi tudatlanság.$B$BEz gyűlölet, amit a szemedben látok, $N? Jó, jó hasznát vesszük majd.' WHERE ID=2996;
UPDATE quest_offer_reward SET RewardText='Üdvözöllek, $N. Remélem, a Fény megmutatja neked az igaz utat, és megvéd a gonosztól.' WHERE ID=2997;
UPDATE quest_offer_reward SET RewardText='Gyönyörű itt Stormwindben, nem igaz?$B$BAz időzítésed valójában nem is lehetett volna jobb, $N.' WHERE ID=2998;
UPDATE quest_offer_reward SET RewardText='Üdvözöllek, $N. Remélem, a Fény megmutatja neked az igaz utat, és megvéd a gonosztól.' WHERE ID=2999;
UPDATE quest_offer_reward SET RewardText='Üdvözöllek, és köszöntelek, $N.' WHERE ID=3000;
UPDATE quest_offer_reward SET RewardText='Mozgalmas nap ez Ratchetben, nem igaz? Mennyire élvezem nézni egy kikötőváros nyüzsgését. Annyi rejtély, annyi kaland... annyi tudatlanság.$B$BEz gyűlölet, amit a szemedben látok, $N? Jó, jó hasznát vesszük majd.' WHERE ID=3001;
UPDATE quest_offer_reward SET RewardText='Lenyűgöző, $N...$b$bEz a gömb nagyon erős, de nagyon veszélyes is.' WHERE ID=3002;
UPDATE quest_offer_reward SET RewardText='Köszönöm a segítséged, $N. A hippogriff-populáció egyszerűen nem virágozna, ha nem lennénk itt. Ah, de biztos vagyok benne, hogy nagyon is jól érted, hiszen magad is jártál Feralasban, és láttad a Gordunni okozta pusztítást ott.$B$BNos, ahogy látod, itt keményen dolgozom, szóval jobb, ha indulsz.$B$BMég egyszer köszönöm, $N.' WHERE ID=3022;
UPDATE quest_offer_reward SET RewardText='Ah, ez tényleg nagyon jó edzőanyag! És ennyi belőle! Napokig fogok dolgozni, mire mindet felhasználom!$B$BKöszönöm, $N. Kérlek, fogadd el ezt fizetségként.' WHERE ID=3042;
UPDATE quest_offer_reward SET RewardText='Most már tudom, hogy Edana valóban halott. Ezt a szívet megőrzöm annak emlékére, amit itt tettél értem, $N. Köszönöm.' WHERE ID=3062;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Megnyugtattad egy öreg tauren elméjét.' WHERE ID=3063;
UPDATE quest_offer_reward SET RewardText='Ez a hely megfelelőnek bizonyul majd, ahogy folytatod a $c útjának gyakorlását. Ha bármi kérdésed van, nyugodtan kérdezz bárkit a környéken, és amikor készen állsz, gyere vissza hozzám kiképzésért. Annyit sajátítottam el, mint bármelyik $c itt a Völgyben, és át tudom adni neked ezt a tudást... egy árért.' WHERE ID=3065;
UPDATE quest_offer_reward SET RewardText='Most mi tanítjuk nekik ezeket a dolgokat, ők meg nekünk másokat. Egy fajjá válunk... majdnem. Már régóta szövetségesek vagyunk. Szóval ne feledd, segíts nekik. És Jen''shan sem felejti el, hogy segítsen neked.$b$bJen''shan megtanítja neked a $c útjait - jól megtanítja. Sose felejtsd, a $c-eket nagyra becsüli a törzs. Nagy szereped lesz a jövőben... ezt sose felejtsd el.$b$bAmikor szükségét érzed, gyere Jen''shanhoz. Annyit tanít neked, amennyit csak tud, amikor úgy érzi, készen állsz.' WHERE ID=3082;
UPDATE quest_offer_reward SET RewardText='Amíg eljön az az idő, az én felügyeletem alatt leszel. Megmutatom a fortélyokat, ahogy egyesek mondanák. Amikor felkészültnek érzed magad, gyere hozzám, és meglátom, hogyan képezhetlek tovább. Addig gyakorold a képességeidet, és tartsd őket borotvaélesen. Sosem tudhatod, mikor lesz szükséged akár a legjelentéktelenebb képességre is.' WHERE ID=3083;
UPDATE quest_offer_reward SET RewardText='Ahogy valószínűleg tudod, az elemek adják erőnket. Tűz, föld, víz és levegő - ezek az eszközeink.$b$bErőnk őseink szellemeiből ered. Mi vagyunk népünk vezetői. Ahogy Thrall a Hordának, úgy leszünk mi a falvaknak és városoknak, amiket meglátogatunk. Ránk fognak nézni bölcsességért és védelemért. Hogy jobban felkészülj, gyakran kell edzened. Amikor úgy érzed, több erőre tettél szert, gyere hozzám, és megtanítalak arra, amit tudok.' WHERE ID=3084;
UPDATE quest_offer_reward SET RewardText='Ahogy próbára teszed magad, egyre jobban uralod majd a szellemeket - egyre nagyobb dolgokra hívod majd őket... itt jön a képbe az öreg Ken''jai. Gyere, beszélj az öreg Ken''jaival, amikor készen állsz. Ha a szellemek beleegyeznek, meglátjuk, taníthatunk-e neked erősebb képességeket... de csak ha a szellemek beleegyeznek.$B$BMenj most, beszélj a Völgy többi népével. Beszélj velem később újra.' WHERE ID=3085;
UPDATE quest_offer_reward SET RewardText='A bolygó legerősebb lényei közé tartozol, $N... ezt nem lehet vitatni. És mindenki tudja... jól is tudja!$B$BDe légy óvatos! Mert nem az orkoktól, elfektől vagy törpéktől kell félned... hanem azoktól a dolgoktól, amiket nem látsz. A mágia erős. Olyan dolgokat tetet veled, amiket talán nem is akarsz. Erősebbnek hiteti el veled magad, mint amilyen valójában vagy. Légy türelmes. Légy okos.$B$BAmikor úgy gondolod, készen állsz a kiképzésre, gyere vissza Mai''ahhoz. Megtanít mindent, amire készen állsz, semmi gond.' WHERE ID=3086;
UPDATE quest_offer_reward SET RewardText='Miután befejeztük a beszélgetést, beszélj a Völgy többi polgárával. Olyan dolgokat kérnek majd tőled, amik próbára teszik a képességeidet, és megtanítanak néhány dologra ennek a földnek a veszélyei közül.$B$BAhogy tapasztalatban és bölcsességben növekedsz, szükséged lesz Jen''shanra, hogy jobb technikákat és képességeket mutasson neked. Gyere vissza Jen''shanhoz gyakran. Elmondom majd, mit taníthatok neked.' WHERE ID=3087;
UPDATE quest_offer_reward SET RewardText='Most hogy tudod, hol tartózkodom, tudnod kell: a Shattered Hand megkért, hogy figyeljek rád. Azt akarják, hogy kiképezzelek, és tájékoztassalak mindenről, amire szükségük lehet. Még ha még nem is érdekel, hogy segíts nekik - amiben ostoba lennél, ha nem tennéd -, megteszek mindent, hogy kiképezzelek... egy kis díjért. Gyere vissza hozzám bármikor, amikor úgy érzed, készen állsz, és meglátjuk, mit vagy készen tanulni.' WHERE ID=3088;
UPDATE quest_offer_reward SET RewardText='Te leszel a csatorna, amelyen keresztül őseink kommunikálnak. Az elemek ereje a parancsodra fog állni. Ellenségeid szétzúzása gyerekjáték lesz; szövetségeseid gyógyítása olyan könnyű, mint a légzés. Tartsd ezeket észben, ahogy új kihívásokkal nézel szembe, és gyere vissza hozzám, amilyen gyakran csak szeretnél. Itt maradok, hogy új varázslatokra tanítsalak, és a helyes útra állítsalak, amikor készen állsz.' WHERE ID=3089;
UPDATE quest_offer_reward SET RewardText='És most te is csatlakoztál a soraink közé. Ne érts félre, $n. Csak mert hozzáférsz olyan hatalomhoz, amire sokan irigykedni fognak, ez nem jelenti azt, hogy könnyen elfogadnak majd. Thrall megengedi, hogy a fajtánk Orgrimmarba jöjjön, mert még mindig a rokonai vagyunk - nem fordíthat hátat nekünk, különben olyan szánalmasak lennénk, mint azok az emberek, akik leigázták. A lényeg: légy óvatos. Lehetsz erős, de ha ostoba vagy, akkor éppúgy meghalhatsz.$B$BHa varázslatkiképzésre van szükséged, gyere vissza hozzám.' WHERE ID=3090;
UPDATE quest_offer_reward SET RewardText='Mindannyiunknak megvan a szerepe a törzsünkben. Mindannyiunknak ugyanazokon a szertartásokon kell átesnie. Sose engedd, hogy büszkeséged mást mondjon.$b$bItt maradok, hogy kiképezzem az új harcosokat, akik a csata dicsőségét keresik, és legrégebbi őseink útját követik. Amikor készen állsz, gyere vissza hozzám, és megteszek mindent, hogy tovább kiképezzelek. Menj a törzs áldásával, $N.' WHERE ID=3091;
UPDATE quest_offer_reward SET RewardText='És az én feladatom, hogy felkészítselek azzal, hogy megtanítom a szakmánk alapjait - hogyan szelídítsd meg a kísérődet, hogyan süsd el a puskádat, és sok más képességet, amikre szükséged lesz.$b$bA vadászok erős részét képezik hagyományunknak és történelmünknek, $N. Jól teszed, ha emlékszel, mennyire fontos vagy a törzs számára. Tisztelni és becsülni fognak, ha jól szolgálod népünket.' WHERE ID=3092;
UPDATE quest_offer_reward SET RewardText='Sokszor fogunk találkozni az elkövetkező napokban. Remélhetőleg minden alkalommal egy kicsit erősebben, egy kicsit felkészültebben hagyod el a társaságomat. Mint az Örök Láng, a lelked fényesen és forrón fog égni.$b$bMenj most, $N. Menj, és próbáld ki magad. Itt leszek neked, amikor szükséged van rám.' WHERE ID=3093;
UPDATE quest_offer_reward SET RewardText='Bár közös köteléket osztunk, ne várj nagy fogadtatást az éjszaka tündéreitől. Büszkeségük még mindig korlátozza a látásukat, de ez nem a mi gondunk. Csak az Anyaföld tanításaival kell foglalkoznod, és megtanítalak arra, amit tudok, ahogy bölcsességben növekedsz.$b$bGyere vissza hozzám gyakran, $N. Rájössz majd, hogy az Anyaföld hihetetlen képességeket ad azoknak, akik a leginkább elkötelezettek.' WHERE ID=3094;
UPDATE quest_offer_reward SET RewardText='Itt leszek, hogy kiképezzelek, ahogy tapasztalatot szerzel... keress meg, amilyen gyakran csak akarsz. Minimális díjat számítok fel, de mindent, amire megtaníthatlak, hasznosnak fogsz találni.$B$BMenj most, és próbáld ki a képességeidet. Sok minden más is ismertté válik számodra, ahogy tapasztalatot szerzel, ezek némelyikéről itt nem tudok beszélni veled. Csak tudd, hogy Sylvanasnak szüksége lesz a jövőben a hozzád hasonló erejű harcosokra. Te leszel a megváltásunk gerince. Ne felejtsd el.' WHERE ID=3095;
UPDATE quest_offer_reward SET RewardText='Az időm nagy részét itt töltöm a fogadóban, új arcokat figyelve, és nyomon követve a feltörekvő tehetségeket. Maradj tiszta, és megteszek mindent, hogy megtanítsalak néhány dologra. Csak gyere vissza hozzám, amikor akarsz, és meglátjuk, készen állsz-e egy-két új képességre.' WHERE ID=3096;
UPDATE quest_offer_reward SET RewardText='Csak egy dolgot kell tudnod: pusztán akaraterővel maradtunk fenn. Az önmagunkba vetett hit különböztet meg minket másoktól, és erőnkkel nagy változást hozunk majd egész Azerothban. A gyengék rád fognak támaszkodni. A leprások Uruknak fognak hívni. És a tudatlanok tőled kérnek majd útmutatást. Az én feladatom, hogy gondoskodjam róla, hogy megkapd a szükséges eszközöket, hogy amikor eljön az idő, felkészült legyél. Ahogy tapasztalatban növekedsz, keress fel engem. Nagyobb hatalmakra taníthatlak, ha készen állsz.' WHERE ID=3097;
UPDATE quest_offer_reward SET RewardText='Gyakran vissza kell térned hozzám, ha elég erőssé akarsz válni, hogy elpusztítsd azokat, akik ellenünk fordulnak. A mágia szabályai továbbra is érvényesek rád, $N. Azt tapasztalod majd, hogy a romlás úgy követ, mint éhes farkasok az éjszakában. Simogatása nem különbözik a függőségtől, egy régi szeretőtől, aki még mindig melletted akar lenni. De ezeket a dolgokat távol lehet tartani. Ezek a dolgok csak akkor uralnak majd, ha hagyod nekik.$b$bMenj most, gyere vissza, ha erősebbé váltál.' WHERE ID=3098;
UPDATE quest_offer_reward SET RewardText='Megemlítettem, hogy egy rabszolga rabszolga marad, akárki is az ura. Emlékszel? Mindketten tudjuk, hogy pontosan ez a fajta uralom - ez a fajta hatalom - hajt minket most. Azt akarjuk, hogy lények szolgáljanak minket. Tudjuk, hogy erősebbek vagyunk, és több tiszteletet érdemlünk, mint amennyit mások adnak nekünk... és ezért most meg akarjuk szerezni azt.$b$bA szövetségesed leszek ebben a küzdelemben - a saját szabadságunkért folytatott küzdelemben. A szabadságért, hogy saját szövetségeinket kereshessük. Amikor készen állsz, gyere vissza hozzám, és megtanítalak mindenre, amit tudok.' WHERE ID=3099;
UPDATE quest_offer_reward SET RewardText='Rendezd be magad, ismerd meg a vidék elrendezését, és gyere vissza hozzám, amikor kiképzésre van szükséged. Itt leszek éjjel-nappal.$B$BA Silver Hand lovagjai jó munkát végeztek, hogy ezt a helyet elég biztonságossá tegyék, de ahogy megismered a többi polgárt, azt hiszem, azt tapasztalod majd, hogy mindegyiküknek vannak problémái, amikben segítségre szorulnak - olyan segítségre, amit egy $c adhat nekik. Sok szerencsét.' WHERE ID=3100;
UPDATE quest_offer_reward SET RewardText='Addig is, tudnod kell még egy-két dolgot. Sokak számára szimbólum vagy ezen a vidéken - ennek megfelelően viselkedj. A Szent Fény ragyog benned, és ez nyilvánvaló lesz mind szövetségeseidnek, mind ellenségeidnek.$B$BEmellett, ahogy bölcsességben és hatalomban növekedsz, gyakorolnod kell, hogy új képességeket tanulj. Itt jövök képbe én. Amikor úgy érzed, szereztél némi tapasztalatot itt, Northshire-ben, gyere vissza hozzám, és megtanítalak arra, amire szerintem készen állsz. Sok szerencsét... $c!' WHERE ID=3101;
UPDATE quest_offer_reward SET RewardText='Rá fogsz jönni, hogy jó néhány csoport szeretné megszerezni a képességeinket, Cailel. Kalandorok, SI:7... a fenébe, még a Defias Brotherhood sem bánná egy-két kém Stormwindben. De ezt jegyezd meg, a saját magad ura vagy. Ne hagyd, hogy bárki ráerőltessen olyasmit, amit nem akarsz csinálni! Emellett, a mienk minden lap... legalábbis addig, amíg a játék véget nem ér. Érted, mire gondolok?$b$bMindegy is, csak be akartam mutatkozni, és tudatni veled, hogy itt vagyok, ha bármilyen kiképzésre van szükséged. Nézz be bármikor.' WHERE ID=3102;
UPDATE quest_offer_reward SET RewardText='Ahogy tapasztalatban növekedsz, gyere vissza hozzám, és megteszek mindent, hogy átadjam neked a tudásomat. Addig is, menj együttérzéssel a szívedben, és hagyd, hogy a bölcsesség vezessen. Ne feledd, a világ csak akkor válik jobb hellyé, ha te teszed azzá.' WHERE ID=3103;
UPDATE quest_offer_reward SET RewardText='Haha, tudtam, hogy az üzenetem nem térít el az utadtól. Szóval felkészültél, ugye? Felkészültél elfogadni a sorsodat? Felkészültél szembeszállni az istenekkel és bármilyen más erővel, amely a tudás és a hatalom keresésében utadba áll?$B$BNem hazudok, $N, éppúgy félni fognak tőled, mint amennyire tisztelnek. De tudd azt is, itt leszek neked, amikor kiképzésre van szükséged. Csak keress fel, ahogy erősebbé válsz.' WHERE ID=3104;
UPDATE quest_offer_reward SET RewardText='Ahogy hatalomban növekedsz, kísértést fogsz érezni - mindig emlékezned kell, hogy uralkodj magadon. Nem hazudok - a romlás bármely arkánus gyakorlót elérheti, különösen azt, aki a Twisting Netherből származó lényekkel foglalkozik. Légy türelmes, és légy körültekintő... de ne hagyd, hogy ez elfojtsa a becsvágyadat.$B$BAhogy erősebbé válsz, gyere vissza hozzám, és többet tanítalak a mi módszereinkről.' WHERE ID=3105;
UPDATE quest_offer_reward SET RewardText='Más dolgokat is valószínűleg látni fogsz, csak hogy tudd: törpék, akik puska helyett mágiát használnak a harcban. Némelyikünk elkezdte imádni a Szent Fényt, mint néhány ember, és nem utolsósorban a troggok. Később többet tanulsz róluk, de amit most tudnod kell, hogy itt vagyok, hogy segítsek.$b$bItt vagyok, hogy megtanítsalak, hogyan legyél igazi $c. Amikor úgy érzed, több kiképzésre van szükséged, gyere vissza hozzám, és meglátom, mit tehetek.' WHERE ID=3106;
UPDATE quest_offer_reward SET RewardText='Az emberek sokat tanítottak nekünk a Szent Fényről, és arról, mennyire fontos nekik a rendjük... és egész Azeroth védelme szempontjából. Nagy tisztelettel vagyunk aziránt, mennyire áthatja a hagyomány, és hogy egyetlen alak, egyetlen áldozat mekkora különbséget tehet fájdalom és megváltás között.$B$BMi ketten egy ideig együtt fogunk dolgozni. Amikor úgy érzed, készen állsz, gyere vissza hozzám, és meglátjuk, hogyan képezhetlek ki. Nem engedhetjük, hogy felkészületlenül menj ki a világba, igaz?' WHERE ID=3107;
UPDATE quest_offer_reward SET RewardText='Egy dolgot mindig jegyezz meg: tisztelned kell a világot, amiben élsz. A vadállatok, akik melletted harcolnak; fegyvered csillogása; lőszered súlya; a metsző szél harapása; mindezeket alaposan ismerned kell.$B$BMegteszek mindent, hogy segítsek, de a munka nagy része rajtad múlik. Amikor úgy érzed, készen állsz, gyere vissza, és beszélj velem. Kiképezlek, amikor csak tudlak.' WHERE ID=3108;
UPDATE quest_offer_reward SET RewardText='Mindegy is, ahogy elkezdesz körülnézni Coldridge-ben, valószínűleg szükséged lesz kiképzésre egyszer. Csak gyere vissza hozzám, amikor úgy érzed, szükséged van rá, és megtanítalak mindenre, amit tudok - egy trükköt itt, egy manővert ott. Tudod, azokra a dolgokra, amik életben tartanak, és egy kis plusz pénzt hoznak.$B$BFigyelj a gnóm barátainkra is... elég rosszul jártak azzal, hogy Gnomeregan... elpusztult. Szükségük lesz a segítségünkre, hogy jól érezzék magukat.' WHERE ID=3109;
UPDATE quest_offer_reward SET RewardText='Én vagyok az, aki kiképezhet, ahogy elkezded megtalálni az utad a Coldridge-völgyben. Amikor készen állsz, gyere vissza hozzám, és meglátjuk, taníthatunk-e neked egy-két új varázslatot, hogy megvédd a völgyet azoktól az átkozott troggoktól.$B$BOtt van veled a Fény, és egész Ironforge, $N... semmi nyomás rajtad, hogy valami különlegessé válj.' WHERE ID=3110;
UPDATE quest_offer_reward SET RewardText='Nos, látva, hogy ez a te elsődleges célod, vagy akárhogy is hívjátok manapság, adtam a szavam, hogy megteszek mindent, hogy te és a tieid készen álljatok visszaszerezni az otthonotokat... és pontosan ezt fogom tenni.$B$BAmikor úgy érzed, készen állsz, gyere vissza a jó öreg Thranhoz, és szívesen megosztom veled a tudásomat. Van némi költsége a kiképzésnek, de nem lesz túl drága. Sok szerencsét.' WHERE ID=3112;
UPDATE quest_offer_reward SET RewardText='Nagyjából magamnak tartom itt, hogy ne kapjunk rossz hírnevet az eltűnt dolgok miatt, de ha bármire szükséged van, kiképzésre vagy bármi másra, csak gyere vissza bármikor.$B$BTe meg én megértjük egymást. Tudjuk, hogy végső soron csak a családban lehet megbízni... és pontosan ez van itt közöttünk, nem igaz? Attól függetlenül, hogy Gnomeregant... elárasztották, és bármi mást is ránk dobnak, egymásra tudunk támaszkodni. Igaz?' WHERE ID=3113;
UPDATE quest_offer_reward SET RewardText='Ó, igen! Az Arkánus Művészetek... persze.$b$bItt van, amit tudnod kell, $N: ne keveredj túl sok bajba. Spórolj egy kis pénzt, hogy vegyél nekem egy sört... vagy bármilyen varázslatot, amit szeretnél. És maradj a fenébe is távol Gnomeregantől. Ezen kívül szép napot! Itt leszek, ha szükséged van rám, vagy kiképzést akarsz... vagy bármi mást.' WHERE ID=3114;
UPDATE quest_offer_reward SET RewardText='De semmi ebből nem számít. Ami számít, hogy megláttad a saját Szent Fényedet! Tudod, honnan is ered valójában a hatalom. Rájössz, hogy saját szövetségeseink sokkal... körültekintőbb dolog. Különleges szövetségesek. Olyan szövetségesek, akik a feladattól függetlenül az utolsó leheletükig engedelmeskednek.$b$bÉs itt jövök képbe én, $N. Kiképezhetlek ezeknek a különleges erőknek a kezdeteire. Keress fel gyakran, és megteszek mindent, hogy több varázslatra megtanítsalak.' WHERE ID=3115;
UPDATE quest_offer_reward SET RewardText='Hamarosan más fajokból származókat is látsz majd otthonunk ágai közt - ne engedd, hogy ez előítéletet keltsen benned. Szívesen látjuk őket. Segítenek nekünk, amikor tudnak. Nem mindegyikük altruista, de valamennyi bizalmat érdemelnek.$b$bDe most semmi ebből nem számít. Most rád kell összpontosítanunk, és arra, hogyan segíthetsz népünknek. Pontosan ezért vagyok itt. Kiképezlek a $c útjaira, ahogy erősödsz. Gyere vissza hozzám, amikor csak akarsz, és megteszek mindent, hogy segítsek.' WHERE ID=3116;
UPDATE quest_offer_reward SET RewardText='Ahogy megtapasztalod, mit taníthat neked Shadowglen, gyere el hozzám - segíthetek jobban megérteni a $c szerepedet és azt, mire vagy képes.$B$BVeszélyes idők ezek, $N, ne vedd magától értetődőnek kísérőid ügyességét - vannak ebben a világban dolgok, amik veszélyesebbek, mint amit el tudsz képzelni. Menj Elune-nal, és gyere vissza hozzám újra.' WHERE ID=3117;
UPDATE quest_offer_reward SET RewardText='Addig is tudd, hogy a mi fajtánkra ebben a bizonytalan időben nagyobb szükség van, mint valaha. A béke a többi fajjal bármelyik pillanatban megbomolhat, és sokat beszélnek arról, hogy a Horda tagjai még nagyobb bizalmatlanság magvait akarják elvetni. Ne feledd ezt.$b$bAhogy hatalomban növekedsz, és felkészültebbnek érzed magad, gyere vissza hozzám ide, és meglátom, hogyan képezhetlek ki. Fontos, hogy tudd, hogyan kell bánnod a választott fegyvereddel, egyéb dolgok mellett.' WHERE ID=3118;
UPDATE quest_offer_reward SET RewardText='Ne foglalkozz most a Teldrassil alatti világgal. Arra később is lesz idő. Menj most, és beszélj a többiekkel Shadowglenben - ők többet elmondhatnak neked a történtekről. Segíts nekik, ahogy csak tudsz, és amikor úgy érzed, több kiképzésre van szükséged, gyere vissza hozzám, és megtanítalak arra, amit tudok.' WHERE ID=3119;
UPDATE quest_offer_reward SET RewardText='Most én leszek a mentorod és vezetőd. Az én feladatom megtanítani, hogyan értelmezd nemcsak azt, amit a szellemek üzennek nekünk, hanem az Emerald Dream összetettségét és titkait is.$b$bAhogy tanulsz és hatalomban növekedsz, többet tudsz meg majd az alvó transzunkról. De addig gyere vissza hozzám, amilyen gyakran csak akarsz, és megtanítalak arra, amit tudok a fajtánk módszereiről.' WHERE ID=3120;
UPDATE quest_offer_reward SET RewardText='Vártam, hogy Uzer''i elhozza ezt...$b$bHadd adjam neked a gyógynövénykeveréket, amit az ő... nos, kísérleteihez készítettem...' WHERE ID=3121;
UPDATE quest_offer_reward SET RewardText='Pontosan erre van szükségem a muisek-edény elkészítéséhez, $N. Hamarosan kiderül, hogy legújabb varázsigéim olyan erősek-e, mint reméltem.$b$bKérlek, egy pillanat. El kell végeznem a szertartást, és fel kell használnom a gyógynövényeket.' WHERE ID=3122;
UPDATE quest_offer_reward SET RewardText='Erőszakos halál esetén egy lény muisekje megszökhet, és bosszút állhat. A lények zsugorítása, ahogy te tetted, $N, megakadályozza a muisek szökését. Most már úgy használhatjuk, ahogy nekünk tetszik!' WHERE ID=3123;
UPDATE quest_offer_reward SET RewardText='Egy állat megölése után, ha hagynánk a muiseket megszökni, egy még nagyobb lény formáját öltheti magára. Sosem lennénk biztonságban a bosszújától.$b$bVeszélyes feladatot adtam neked, $N. Ismét kiválóan teljesítetted.' WHERE ID=3124;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. Most már a tündérsárkány szellemi ereje elérhető lesz számunkra.$b$bRemélem, hajlandó vagy elvégezni még egy feladatot nekem.' WHERE ID=3125;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. A muisek-gyűjteményünk már majdnem teljes.' WHERE ID=3126;
UPDATE quest_offer_reward SET RewardText='Csak képzeld el, milyen lehetőségek rejlenek abban, amivel most rendelkezünk, $N. Az általad összegyűjtött alapanyagokkal örökre csapdába ejthetem ezeknek a lényeknek a muisekjét, bármibe, amit csak akarok.' WHERE ID=3127;
UPDATE quest_offer_reward SET RewardText='Kitűnő! Ezek az alapanyagok a muisekkel kombinálva pontosan azt az eredményt hozzák majd, amit szerettünk volna.' WHERE ID=3128;
UPDATE quest_offer_reward SET RewardText='Ahogy ígértem, választhatsz, $N. A lények muisekje örökre bezárva maradt ezeknek a fegyvereknek az erejébe.$b$bMost már sajátodként forgathatod az energiájukat. Használd jól.' WHERE ID=3129;
UPDATE quest_offer_reward SET RewardText='Kitűnő, $N - nagyra értékelem a „meg lehet oldani” hozzáállást azokban, akikkel dolgozom.$B$BGeneral Feathermoon megbízott, hogy közvetlenül lépjek fel a naga ellen. Terveim kettősek: egyrészt, gyengítjük az erőiket létszámban és parancsnokságban egyaránt, másrészt, kiderítjük, mire készülnek a romok között. A segítségeddel ellensúlyozhatjuk a naga jelenlétét anélkül, hogy feláldoznánk az erőd általános biztonságát.' WHERE ID=3130;
UPDATE quest_offer_reward SET RewardText='Legyen hát...' WHERE ID=3141;
UPDATE quest_offer_reward SET RewardText='Tökéletes; ezek a díszek tökéletesek a tanulmányaimhoz. Nagyon köszönöm a segítséged, $N.$B$BÓ, visszakaphatnám a sisakomat?' WHERE ID=3161;
UPDATE quest_offer_reward SET RewardText='Mit hoztál? Nyilvánvalóan egy hamisítvány!$B$BSzemtől szemben álltam Margollal, és biztosan tudom, hogy a szarva legalább nyolcszor akkora, mint amit a kezedben tartasz, $N. Valószínűleg egy stormsnout-tól szerezted a Barrensben. Nem, kisasszony, Pebblebittyt nem lehet becsapni!' WHERE ID=3181;
UPDATE quest_offer_reward SET RewardText='Ez meg mi?$B$BJaj nekem, el sem hiszem! Tudod, mid van itt, $R? Ez Margol the Rager szarva! Margol, minden régész rémálma, aki valaha is betette a lábát a Searing Gorge-ba.$B$BMegtarthatom?' WHERE ID=3182;
UPDATE quest_offer_reward SET RewardText='Nem tudom, hogyan győzött le egy hozzád hasonlóan gyenge valaki Margolt, de az üzlet az üzlet. Itt a kulcs.$B$BHa ezután bármi történik veled, az a saját hibád lesz.' WHERE ID=3201;
UPDATE quest_offer_reward SET RewardText='Ah, nagyon jó. Van egy ügy a korábban hozott farkasszívekkel kapcsolatban, ami figyelmet igényel.' WHERE ID=3221;
UPDATE quest_offer_reward SET RewardText='Üdvözöllek, ifjú. Azért jöttél, hogy a vadász útját járd?$B$BNagyon jó. Kezdjük el.' WHERE ID=3261;
UPDATE quest_offer_reward SET RewardText='Aha! Szóval a raptorok tényleg elrejtették az ezüstöt a fészkükben. Nehéz elhinni, hogy ezeknek a vadállatoknak vágyuk lenne az ezüst iránt. Talán az intelligenciájukról szóló történetek nem is állnak olyan távol az igazságtól, mint gondoltam!$B$BKöszönöm, $N. Fogadd el ezt jutalmul a szolgálatodért, és tudd, hogy a keresztút őrei neked köszönhetik a következő havi fizetésüket.' WHERE ID=3281;
UPDATE quest_offer_reward SET RewardText='Ah, ez meg mi? Ennek a kagylónak belső ragyogása van, mintha még mindig lüktetne benne az élet. Elképesztő! Alaposabban meg kell vizsgálnom.$B$BKöszönöm, $N. Szerencsével ez a kagyló olyan titkot rejt, amit felhasználhatok Silverpine szegény földjének megsegítésére.' WHERE ID=3301;
UPDATE quest_offer_reward SET RewardText='Emelkedj fel, és légy elismert, $N, a Mithril Rend kovácsa.' WHERE ID=3321;
UPDATE quest_offer_reward SET RewardText='Egy Lich hűsége rendíthetetlen, $N. Add tudtukra, hogy az ilyen hűség csak pusztulást hoz rájuk.' WHERE ID=3341;
UPDATE quest_offer_reward SET RewardText='Hurrá, megtaláltad őket! Igazi megmentő vagy, barátom. Tessék, nem sok, de valami a fáradozásodért, amit okoztam! Köszönöm!' WHERE ID=3361;
UPDATE quest_offer_reward SET RewardText='Ilyen nagyok? Talán át kell gondolnom a tervemet...$b$bDe betartottad az alku rád eső részét, szóval tessék, amit ígértem.' WHERE ID=3362;
UPDATE quest_offer_reward SET RewardText='Cenarion növénykenőcsöt kensz a dalvirágra. Azonnal elkezdi levetni megrontott formáját, és élénk, egészséges növénnyé bomlik ki.' WHERE ID=3363;
UPDATE quest_offer_reward SET RewardText='Ah, remek, ez most pont jólesik majd. Engedd meg, hogy tartsak egy kis szünetet, amíg élvezem ezt a forró mornbrew-t!' WHERE ID=3364;
UPDATE quest_offer_reward SET RewardText='Kitűnő, $N! Meglepődnél, hány futárral találkozom, akik elfelejtenek olyan egyszerű dolgot, mint a bögre visszahozása. A bögrék nem a fán teremnek, vagy legalábbis ezt mondják!$b$bTessék egy kis valami a fáradozásodért. Még egyszer köszönöm a segítséged.' WHERE ID=3365;
UPDATE quest_offer_reward SET RewardText='Ezt a levelet Dorius ejtette el, amikor lelőtték.' WHERE ID=3367;
UPDATE quest_offer_reward SET RewardText='<Thorius szárazra törli az arcát.>$B$BA Fény nevében, teljesül a kívánsága. Ezt esküszöm.' WHERE ID=3368;
UPDATE quest_offer_reward SET RewardText='Falla küldött hozzám? Nos, lássuk azt a szilánkot, amiről állítólag olyan vonakodva beszélt...$B$B<Hamuul beletekint a szilánkba>$B$BÓ... nem is... Nos.$B$B$N, köszönöm, hogy eljuttattad hozzám. Nem bölcs dolog ilyesmiről beszélni, ezt tanácsolom. Ezek olyan ügyek, amikkel neked nem kell foglalkoznod.$B$BAnnyit mondjunk csak, hogy az Emerald Dream dolgai nem úgy állnak, ahogy gondoltuk...$B$BTalán a jövőben újra keresztezik egymást az útjaink.$B$B' WHERE ID=3369;
UPDATE quest_offer_reward SET RewardText='Falla küldött hozzám? Nos, lássuk azt a szilánkot, amiről állítólag olyan vonakodva beszélt...$B$B<Mathrengyl beletekint a szilánkba>$B$BÓ... nem is... Nos.$B$B$N, köszönöm, hogy eljuttattad hozzám. Nem bölcs dolog ilyesmiről beszélni, ezt tanácsolom. Ezek olyan ügyek, amikkel csakis a Cenarion druidáknak kell foglalkozniuk.$B$BAnnyit mondjunk csak, hogy az Emerald Dream dolgai nem úgy állnak, ahogy gondoltuk...$B$BTalán a jövőben újra keresztezik egymást az útjaink.' WHERE ID=3370;
UPDATE quest_offer_reward SET RewardText='Felejts el engem, segíts a többieknek.' WHERE ID=3371;
UPDATE quest_offer_reward SET RewardText='Elhelyezed a titokzatos ereklyét Suntara oltárán.' WHERE ID=3372;
UPDATE quest_offer_reward SET RewardText='Elhelyezed a drágakövet az esszenciakútban.$B$B„Köszönöm, halandó, te - nem... ez, ez nem lehet igaz! Ne! Ennek az átkozott istennek a romlása még a Zöld Sárkányraj esszenciakútjának szentségét is beszennyezi! Ne, kérlek, érzem, ahogy az esszenciám kiszakad belőlem! A FÁJDALOM! Érzem, ahogy egy örök rémálom szorítása kerít hatalmába...”$B$B„Halandó, könyörgöm! Találj egy Zöld Sárkányrajbélit, hogy megállítsa ezt... segíts... sötétségbe vagyok láncolva... örök gyötrelemben... kérlek, ne kínozz...”' WHERE ID=3373;
UPDATE quest_offer_reward SET RewardText='Meghoztad a döntésed, és így hát elkezdődik. A döntéseid mindeddig, úgy vélem, helyesek voltak; ezentúl a tetteid és cselekedeteid döntik el, hogy ez így is marad-e.' WHERE ID=3374;
UPDATE quest_offer_reward SET RewardText='A hatalmas kalandozó szállít. Hurrá nekem. Amúgy hazudtam - volt még egy fiolám. Ugh, fogd.$B$BNos, mit vártál?! „Ó, tessék, itt van még egy! Csak egy bugyuta alak vagyok, akinek nincs jobb dolga, mint mágikus kommunikációs eszközöket osztogatni a kalandozóknak!” De légy nyugodt, amit adtál nekem, elég lesz még egy fiola elkészítéséhez, amikor azt is elveszíted.$B$BKérlek, cáfolj meg, és ne veszítsd el az újat, jó?' WHERE ID=3375;
UPDATE quest_offer_reward SET RewardText='Igazságot szolgáltattál ma gyors cselekedeteddel, $N. Szolgáljon ez a tett figyelmeztetésül mindazoknak, akik veszélyeztetnék otthonunkat.$b$bKiérdemelted ezt a jutalmat, hogy segítsen utadon, ifjú $c.' WHERE ID=3376;
UPDATE quest_offer_reward SET RewardText='Elfogadtam a sorsomat itt, ebben a ketrecben, de az imát meg kell találni.' WHERE ID=3377;
UPDATE quest_offer_reward SET RewardText='Elune ma este rád mosolyog, $N. Egy elveszett lelket adtál vissza neki. Kérlek, fogadd el ezt hálánk jeléül.' WHERE ID=3378;
UPDATE quest_offer_reward SET RewardText='Kitűnő munka, $N.$B$BBiztos vagyok benne, hogy ez egy olyan darab árnyékszövetből van, amit még nem láttál.' WHERE ID=3379;
UPDATE quest_offer_reward SET RewardText='Igen, a Süllyedt Templom, elmondhatom, hogy saját szememmel láttam. Talán szeretnél többet hallani róla?$b$bKalandvágyó típusnak tűnsz - olyan dolgokat tudok, amik érdekelhetnek...' WHERE ID=3380;
UPDATE quest_offer_reward SET RewardText='Két toll, pontosan ahogy kértem. És egyáltalán nem rosszak.$b$bKészen állsz? Csak szólj egy szót, és útnak indulhatsz.$b$bÓ, és még egyszer, vigyázz magadra... a mesterem nem kedveli az ostobákat, de nagyon nagylelkű azokhoz, akik elnyerik a tetszését.' WHERE ID=3381;
UPDATE quest_offer_reward SET RewardText='Sikerült! Köszönöm! Ez biztosan az egyik legbrutálisabb csata volt, amiben valaha részt vettem. Nem tudok eléggé köszönetet mondani.$B$BCsak azt kívánom, bár a legénységem több tagja túlélhette volna ezt a próbát.$B$BArra kérnélek, beszélj bármelyik túlélő utassal a Horizon Scoutról. Néhányuknak ügyes-bajos dolga volt a környéken, és talán van egy-két kérésük hozzád, ha hajlandó vagy rá. Még egyszer köszönöm minden segítséged.' WHERE ID=3382;
UPDATE quest_offer_reward SET RewardText='Döntő csapást mértél az Undermarketre. A vezetőik kétszer is meggondolják majd, mielőtt újabb csicskásokat küldenek a szurdokba.$B$BÓ, és semmi hasznosat nem találtam a kereskedő tarisznyájában sem. Megtarthatod, amit odabent találsz.' WHERE ID=3385;
UPDATE quest_offer_reward SET RewardText='Kovicot megölted??! Dicsőséges nap ez, $N! Évek óta az a gazember gyanús alvilági üzleteket bonyolított, aláásva a becsületes, keményen dolgozó kereskedőket szerte a világon.$b$bMegérdemelsz egy szép jutalmat ezért a teljesítményért! És szép jutalmat is kapsz!' WHERE ID=3402;
UPDATE quest_offer_reward SET RewardText='Most visszaviszlek Sanath táborába.$B$BNe törődj a modortalanságával - mindenkivel goromba, kivéve a mesterét. Talán egy nap megtanulja a leckét.' WHERE ID=3421;
UPDATE quest_offer_reward SET RewardText='Eleget hallottál? Készen állsz cselekedni?' WHERE ID=3441;
UPDATE quest_offer_reward SET RewardText='Szép munka, $N. Már majdnem készen állunk.' WHERE ID=3442;
UPDATE quest_offer_reward SET RewardText='Kivételes munkás vagy, $N. Fontolgattál már szakmaváltást? Talán nyomozó? Ócskagyűjtő? Ó, tudom már, olyan buta gnóm, aki fémdetektoraival mászkál Azeroth partjain, elveszett kincseket keresve. Igen, az ideális pozíció lenne számodra.' WHERE ID=3443;
UPDATE quest_offer_reward SET RewardText='Igen... ez a kő.$b$bMost már minden visszatér az emlékezetembe, $N...' WHERE ID=3444;
UPDATE quest_offer_reward SET RewardText='Igen, a Süllyedt Templom, elmondhatom, hogy saját szememmel láttam. Talán szeretnél többet hallani róla?$b$bKalandvágyó típusnak tűnsz - olyan dolgokat tudok, amik érdekelhetnek...' WHERE ID=3445;
UPDATE quest_offer_reward SET RewardText='Betolod a kőkört a nyílásba, és hallod, ahogy a helyére kattan.$b$bMost hogy a kő a helyén van, folytathatod... de mit kellene tenned ezután?$b$bTalán alaposabban meg kellene vizsgálnod ezt az oltárt...$b$b' WHERE ID=3446;
UPDATE quest_offer_reward SET RewardText='A bálvány szeme fényesen csillog még a templom félhomályában is. Átlátszósága valami fényeset tár fel mögötte. Oldalra csúsztatva benyúlsz, és megragadod, ami a szoborban rejlik.$B$BAz Atal''ai kincs most már a tiéd.' WHERE ID=3447;
UPDATE quest_offer_reward SET RewardText='Ah, szóval Karnik küldött? Hamarosan vártam tőle hírt. Olyan csodálatos dolgokat fedeztem fel Azsharáról... Tudom, hogy az éjszaka tündéreinek hihetetlen élettartamuk van, de mindenki elfelejt néha néhány... szerencsétlenebb eseményt az életükből. Ezt nem kritikaként mondom, csak megfigyelésként.$B$BRégen az elfek olyan városokat építettek, amik tele voltak mágiával és más elveszett művészetekkel kapcsolatos tudással. Mivel ezeknek a dolgoknak a tanulmányozója vagyok, elkezdtem a kutatásomat. Amit találtam, egészen izgalmas volt.' WHERE ID=3448;
UPDATE quest_offer_reward SET RewardText='Jó látni, hogy épségben visszatértél, $N. Remélem, nem volt túl nehéz dolgod.$B$BAzonnal elviszem ezeket Tymornak. Izgatottan fogja megnézni ezeket a dolgokat.$B$BCsak dobd el a fényjelző pisztolyt... valószínűleg úgysem lesz hasznod belőle, és már van egy újam.' WHERE ID=3449;
UPDATE quest_offer_reward SET RewardText='Mit tehetek érted, $N? Épp elég elfoglalt vagyok, a hajómat készítem elő egy hosszú útra. Csak átjöttem, hogy megnézzem néhány tank pilótát - néhány wendigo-sörényre van szükségem a pilótafülkém bélésének, és általában van náluk felesleg.$B$BAdhatok egy percet, ha rövid leszel... az egyik fiú épp most indult Steelgrill''s Depotba, hogy megnézze, van-e a pilótáknak felesleges sörényük számomra.' WHERE ID=3450;
UPDATE quest_offer_reward SET RewardText='Itt a szabványos fényjelző pisztolyom, és légy türelmes, miután elsütöd - csak néhány töltet van ezekben, és eltarthat egy percig, mire odaérek hozzád, attól függően, milyen messze vagyok a tengeren. Csak nézz ki a tengerre, miután elsütötted a jelzőrakétát.' WHERE ID=3451;
UPDATE quest_offer_reward SET RewardText='A szimbólum aljas mágiát áraszt; tökéletesen megfelel a feladatunkhoz.' WHERE ID=3452;
UPDATE quest_offer_reward SET RewardText='Van még egy utolsó feladat, amit teljesítened kell.\\n' WHERE ID=3453;
UPDATE quest_offer_reward SET RewardText='Két kézzel megragadod a fáklyát; gyűlölet és düh hullámai lüktetnek végig a lényeden.' WHERE ID=3454;
UPDATE quest_offer_reward SET RewardText='Csodálatos! Nagyon örülök, hogy ezt hallom.$B$BIgazán izgatott vagyok, hogy visszaérjek a tornyomba, és átnézzem azokat a dörzsöléseket. Nagyon irigyellek... egy olyan helyre eljutni, mint Azshara. Ez minden arkánus tanítvány álma lehet, gondolom.$B$BNos, sosem beszéltünk semmiféle jutalomról, mivel csak az Explorer''s League-nek dolgoztál, de megérdemelsz valamit.' WHERE ID=3461;
UPDATE quest_offer_reward SET RewardText='Készen állsz lecsapni?\\n' WHERE ID=3462;
UPDATE quest_offer_reward SET RewardText='Ez dicsőséges! Nem dicsőséges ez, mester?' WHERE ID=3463;
UPDATE quest_offer_reward SET RewardText='A láda kinyílik az érintésedre. Vajon mennyi sajt lehet idebent? Csak egy módon lehet megtudni.' WHERE ID=3481;
UPDATE quest_offer_reward SET RewardText='Ah, még egy fényjelző pisztoly, mi? Azt meg tudom oldani.$B$BÉs ne feledd, Azshara déli csücske. Egy kis szigetecske, amit leszállópályává alakítottak. Nem tévesztheted el, ha a megfelelő helyen vagy.' WHERE ID=3483;
UPDATE quest_offer_reward SET RewardText='Igazán undorítasz, $r. Egy felnőtt $g férfi : nő;, aki nyáladzik egy kacathalmaz felett? Szánalmas! Fogd a jutalmad, és tűnj a szemem elől.' WHERE ID=3501;
UPDATE quest_offer_reward SET RewardText='Igazán undorítasz, $r. Egy felnőtt $g férfi : nő;, aki nyáladzik egy kacathalmaz felett? Szánalmas! Fogd a jutalmad, és tűnj a szemem elől.$B$BIsmerősen hangzik? Ismerősnek kell hangoznia, mert ezerszer mondom ezt naponta.$B$BÓ, mennyire utálom ezt a világot.' WHERE ID=3502;
UPDATE quest_offer_reward SET RewardText='Volt idő, amikor bármit kérhettem azoktól, akik a mesteremet keresték. De most csak kérned kell, és elküldelek hozzá.$b$bEz felzaklat, de nem kérdőjelezem meg a parancsait. Csak abban lelem örömömet, hogy kigúnyolom a nevetséges ruháidat vagy a szánalmas arckifejezésedet. De még ez is untat...$b$bMég ez a fecsegés is untat! Látni akarod a mesteremet vagy sem?' WHERE ID=3503;
UPDATE quest_offer_reward SET RewardText='Mindent bevetettünk, amink volt ellene és a munkásai ellen, de erősek a csatában. Senki sem tért vissza. Feltételezem, néhányan meghaltak, de biztos vagyok benne, hogy mások egyszerűen elmenekültek... gyávák.$b$bDe most, hogy megérkeztek az erősítések, talán még tehetünk valamit. Talán még megbüntethetjük azért, hogy hazudott, és elárulta Belgromot.$b$bMit szólsz, benne vagy?' WHERE ID=3504;
UPDATE quest_offer_reward SET RewardText='Átlapozol néhány oldalt, míg el nem érsz egy oldalhoz, amit egy vékony, fekete selyemcsík jelöl.$b$bAhogy megpróbálod megfejteni az írást, egy ábrát látsz az egyik oldal alján. Egy gyors pillantás a jelenetre magad előtt, és rájössz, hogy a kristályok, a kör, és még néhány más elem is a földön az ábrához hasonló mintázatban van elrendezve.' WHERE ID=3505;
UPDATE quest_offer_reward SET RewardText='RÁÁ!! Elképesztő!$b$bSikerült! Belgrom elégedett lesz! Végre tucatnyi harcosunk szelleme nyugalomra lelhet. Köszönöm, $N.' WHERE ID=3506;
UPDATE quest_offer_reward SET RewardText='HAHA! Nézzenek oda most, te szánalmas nő! Köpök a maradványaidra!$b$bKöszönöm, $N. Szívem mélyéből köszönöm! Ez valóban nagyszerű nap!$b$bKirályságot adnék neked, ha hatalmamban állna! De talán beéred ezzel.$b$b<Belgrom lenéz a mágus fejére, aki elárulta.>$b$bHaha! Ostoba vérelf, nézzenek oda most... egy zsákban, test nélkül! Sosem lett volna szabad elárulnod Belgromot!' WHERE ID=3507;
UPDATE quest_offer_reward SET RewardText='A fenevad nevét meg kell találni.' WHERE ID=3508;
UPDATE quest_offer_reward SET RewardText='Egy démonúr?$b$b<Lord Arkkoroc nevet.>$b$bTalán az Egy segíthet neked ezzel az információval; de előbb neked kell segítened az Egynek.$b$b' WHERE ID=3509;
UPDATE quest_offer_reward SET RewardText='Végre, valaki, aki méltó Arkkoroc bölcsességére!' WHERE ID=3510;
UPDATE quest_offer_reward SET RewardText='Az edzőanyag hozzáadja a szükséges maró anyagot, amire a fegyverek kovácsolásához szükségünk van. Már csak egy lépés van hátra az elkészítésükhöz.' WHERE ID=3511;
UPDATE quest_offer_reward SET RewardText='Itharius bölcsen tette, hogy hozzám küldött. Bár nincs halott úgy, ahogy te érted a halált, Eranikus hamarosan tanácsot ad majd nekünk a saját szavaival. Egyelőre azonban nem tudok közvetlenül segíteni neked... legalábbis még nem.$b$bKölcsönadom neked a halottakkal való beszéd tudományát, de előbb szükségem van egy olyan valaki segítségére, aki - ellentétben velem - nincs az öregkor gyengeségei által korlátozva. A legerősebb jóseszközömet elvették tőlem az akaratom ellenére, és amíg nem kapom vissza, nem tudunk segíteni Eranikusnak.' WHERE ID=3512;
UPDATE quest_offer_reward SET RewardText='Nos... Hol találtad ezt?' WHERE ID=3513;
UPDATE quest_offer_reward SET RewardText='Kemény legény vagy! A Rynthariel Barlangjának megtisztítása nagy lépés, $N. Lassan fognak újraszerveződni, így kevesebb szövetséges futárral kell számolnunk a Barrensben. Kétszer is meggondolják majd, mielőtt megint küldenek valakit erre.$B$BKöszönöm.' WHERE ID=3514;
UPDATE quest_offer_reward SET RewardText='Tökéletes, $N, és még jó állapotban is. Ezek jó árat hoznak majd mindenkinél, akit érint.$b$bNe álldogáljunk itt tovább, mint kell. Van pénz, amit keresnünk kell.' WHERE ID=3517;
UPDATE quest_offer_reward SET RewardText='Ah, végre, Beth''Amara Táblája. Már azon tűnődtem, vajon a Jedigával kötött szövetségem kudarcot vallott-e, vagy a szegény ork lelte halálát Azsharában. Örülök, hogy sikerrel járt.$b$bBeth''Amara a Highborne egyik legbefolyásosabb alkimistája volt. A varázsló állítólag egyedülállóan elsajátította a fémek átalakítását, egyéb dolgok mellett.' WHERE ID=3518;
UPDATE quest_offer_reward SET RewardText='Ó jaj; épp azon gondolkoztam, miért nem láttam még ma Iverront. Pedig mindig figyelmeztettem azokra a pókokra...' WHERE ID=3519;
UPDATE quest_offer_reward SET RewardText='Jól teljesítettél, $N. Talán ideje most többet felfedni...$B$BLétezik egy ősi prófécia a trollok között, mely szerint a halott isten, Hakkar, a Lélekfosztó, egy napon visszatér erre a földre. Egyesek szerint Hakkar eljövetele örömöt és dicsőséget hoz a trollfajnak, míg mások úgy hiszik, feltámadása minden dolog végét jelzi.$B$BÉn nem hiszek ebben a mítoszban, de tudom, hogy Hakkar esszenciája hatalmas erőt hordoz, és ezt az erőt távol kell tartani azoktól, akik visszaélnének vele...' WHERE ID=3520;
UPDATE quest_offer_reward SET RewardText='Hála Elune-nak, hogy ilyen gyorsan összegyűjtötted ezeket az alapanyagokat!$b$bEgy pillanat, és elkészítem az ellenmérget.' WHERE ID=3521;
UPDATE quest_offer_reward SET RewardText='Ez meg mi, $N?$b$bÓ, tudtam, hogy Dirania segíteni tud rajtam!$b$b<Iverron megissza az ellenmérget>$b$bMindig bajba keveredem, és Dirania, hát, mindig sikerül kihoznia belőle.$b$bSokkal jobban érzem magam, de azt hiszem, még egy ideig itt ülök, amíg teljesen jobban nem leszek. Nos, ez, és reméltem, hogy nyitsz nekem egy utat azok között a vad Webwood-pókok között...' WHERE ID=3522;
UPDATE quest_offer_reward SET RewardText='Fantasztikus, gondoltam, hogy hősies típusnak tűnsz! Sok munka vár ránk, $N, nem hazudok neked. Ha a kéznél lévő feladatra koncentrálunk, sikerrel kell járnunk.$B$BMost pedig hadd tájékoztassalak arról, mi történt eddig...' WHERE ID=3523;
UPDATE quest_offer_reward SET RewardText='Remélem, a murloc nem okozott sok gondot, amíg ezt összegyűjtötted nekünk! Gondoskodom róla, hogy a következő hippogriffel eljusson Darnassusba. A Temple of the Moon adott nekem némi pénzt segítségnyújtásra; kérlek, fogadd el köszönetünk jeléül.$B$BItteni sikered arra bátorít, hogy felajánljak egy lehetőséget, hogy tovább segítsd a Temple of the Moont, ha érdekel...' WHERE ID=3524;
UPDATE quest_offer_reward SET RewardText='Belnistrasz hirtelen távozása egy égő parazsat hagyott hátra. Ahogy a lángba bámulsz, egy hatalmas szárnyú vörös sárkány képe tölti be az elméd. Belnistrasz hangjának egy reszelősebb változata szól közvetlenül hozzád.$B$B„Valóban, halandók, ti vagytok azok a hősök, akiknek reméltem, hogy lesztek. Nektek köszönhetően a mészárlás, amit ezek a vadállatok folytattak, immár a múlté. A halandókba vetett hitem ismét megújult. Fogadjátok ezt egy hőshöz méltó jutalomként.”' WHERE ID=3525;
UPDATE quest_offer_reward SET RewardText='Nos, $N, bölcsen tetted, hogy a tanítványom kerestél! Bárki lehet szakértő a mérnöki alapokban - a gnómok és sugárfertőzött otthonuk, Gnomeregan, bizonyítja ezt. De erős elme és biztos kéz kell (hangsúlyozom: BIZTOS) a Goblin Mérnökség elsajátításához.$B$BTartsd nyitva a füled, $N, és talán tanulsz valamit.' WHERE ID=3526;
UPDATE quest_offer_reward SET RewardText='Ah, ez jó. Össze tudom olvasztani ezeket az ősi táblákat, és tanulmányozhatom rejtett titkaikat.$b$bAz irántad való adósságom nő, $N. És még tovább fog nőni.' WHERE ID=3527;
UPDATE quest_offer_reward SET RewardText='Hakkar esszenciáját összegyűjtöttük! Már most is élettel telik meg a tojás! Vajon igazak lehetnek a Hakkarról szóló mítoszok?$b$bEnnek nem szabad igaznak lennie, mert akkor félek attól, mit tehetne Hakkar, ha újra megszületne. Biztonságban tartom ezt a tojást, és gondoskodom róla, hogy ne kerüljön gonosz kezekbe.$b$bA velem végzett munkád véget ért, $N. Egy legendát érintettél meg, és tetteid egy napon megváltoztathatják a világunk arcát.' WHERE ID=3528;
UPDATE quest_offer_reward SET RewardText='Ahhh, Jediga küldi a csomagját egészen Azsharából. Jó. Erre vártam.$B$BJediga, most az aztán egy remek nő... halálos is. Mi lehetne jobb ennél?$B$BNézd csak... a tábla tökéletes állapotban van. Jó hírnök vagy, $N.' WHERE ID=3541;
UPDATE quest_offer_reward SET RewardText='Tessék, fogj némi pénzt... szerezz magadnak... <hik>... valami új páncélt vagy ilyesmit....$b$bEz csillogó aranyat hoz majd a megfelelő... <hik> embereknek.' WHERE ID=3542;
UPDATE quest_offer_reward SET RewardText='Ah, Sael''hai Táblája... mennyire vágytam már tanulmányozni.$b$bKöszönöm, $N. Elmondhatod Jedigának, hogy jól teljesített. Ez határozottan megéri majd a fizetséget, amit kért.' WHERE ID=3561;
UPDATE quest_offer_reward SET RewardText='Ah, jó. Sokkal ésszerűbb volt, mint vártam... legalábbis veled szemben. Félig arra számítottam, hogy megbüntettet téged a szemtelenségemért, amiért valaki mást küldtem magam helyett. Biztosan nagyon akarja azt a táblát. Érdekes.$b$bEz még egy másik alkalommal is elgondolkodtat.' WHERE ID=3562;
UPDATE quest_offer_reward SET RewardText='Látom, jegyzete alapján több mint elégedett volt... egy kicsit túl elégedett.$B$BTalán egy nap majd rászánok időt, hogy megtudja, mennyire értékelem a közeledését is. Nos, legalább van egy okom, hogy örömmel várjam a több időt Azsharában.$B$BItt van a részed a fizetségünkből.' WHERE ID=3563;
UPDATE quest_offer_reward SET RewardText='Tökéletes... várj csak.$b$bHaha! Mit mondtál neki, amikor átadtad a táblát, $N? Rengeteget túlfizetett minket! Nem mintha panaszkodnék. Elmondtad neki, hogy megváltozott az üzlet? Vagy megint részeg volt?$b$bMindegy is... tessék, fogj egy extra részt is.' WHERE ID=3564;
UPDATE quest_offer_reward SET RewardText='Semmi probléma? Egyáltalán semmi? Nos, ez mond valamit... arra számítottam, hogy valamiféle vonakodást mutat, vagy legalább elárulja az üzletünket. Hmm, talán mégis megbízható.$b$bNos, nem kell ezen sokat rágódni. Itt a részed. Köszönöm a segítséged.' WHERE ID=3565;
UPDATE quest_offer_reward SET RewardText='<Thorius arca elsápad.>$B$BEz... ez nem lehet. A saját testvérem? Ő állt e mögött az egész mögött?$B$B<Thorius arca dühtől eltorzul.>$B$BElárult engem, elárulta Ironforge-ot! Úgy tűnik, a Régi Istenek befolyása még mindig erős ezeken a földeken. Attól félek, ha a testvérem - egykor nemes és becsületes ember - ilyen könnyen Ragnaros akaratának eszközévé vált, akkor senki sincs biztonságban.' WHERE ID=3566;
UPDATE quest_offer_reward SET RewardText='Szeretnéd látni a kilátást a két kolosszus egyikének tetejéről? El tudlak oda küldeni, $R.$B$BDe gondold át, hogyan jutsz majd le. Ez csak egyirányú út.' WHERE ID=3567;
UPDATE quest_offer_reward SET RewardText='Csodálatos. Visszaértél, mielőtt meghalt volna. Jó, jó.$B$BAkkor kezdjünk is neki, rendben?$B$BEgy ideje már tanulmányozom a tüneteit, és eléggé csúnya a helyzet. Meglepődöm, hogy még mindig áll. Háromszor-négyszer is hányt mindenfelé... elég kellemes illat.$B$BAdj egy pillanatot, hogy összeállítsak valamit, amit letesztelhetünk a... barátunkon.' WHERE ID=3568;
UPDATE quest_offer_reward SET RewardText='Chemist Cuely nagyon segítőkész volt... zavaróan az. De ha azt mondja, ez segíteni fog rajtam, akkor nincs más választásom. Nincs időm más megoldást keresni. Már beszéltem papokkal és sámánokkal is, egyikük sem tudott segíteni.$B$BReméljük, az Anyaföld vigyáz a lelkemre.' WHERE ID=3569;
UPDATE quest_offer_reward SET RewardText='Sosem álmodtam volna, hogy az elixír ilyen gyorsan hat majd. Köszönöm, $N. Azonnal munkához látok a maradék mintákkal. Biztos vagyok benne, hogy hamarosan hasznukat veszi majd Lady Sylvanas és a Forsaken.' WHERE ID=3570;
UPDATE quest_offer_reward SET RewardText='Haha! Alaposan móresre tanítottad őket, ugye?!$b$bEz remek! Ez megtanítja azoknak a vérelfeknek, hogy ne áruljanak el a partnereiket... főleg egy olyan hűséges valakit, mint egy goblin kereskedő! Bah, vérelfek...!$b$bNos, a legkevesebb, amit tehetek érted, hogy kifizetlek az idődért... ahogy mondtam, hogy fogom.$b$bTessék... ezeknek hasznát kell venned.' WHERE ID=3601;
UPDATE quest_offer_reward SET RewardText='A feladataid Azsharában befejeződtek, halandó. Most el kell készítenem a szükséges alkatrészeket kalandod következő lépéséhez.' WHERE ID=3602;
UPDATE quest_offer_reward SET RewardText='Te jó ég, csak elképzelni tudom, min mentél keresztül ezeknek az alapanyagoknak a megszerzéséért. Kevesen merészkednek Azsharába, és térnek vissza élve, hát még azok, akik félistenekkel és óriásokkal néznek szembe!$b$b' WHERE ID=3621;
UPDATE quest_offer_reward SET RewardText='<Galvan letörli a verejtéket a homlokáról.>$b$bFinomabb démonölő sosem létezett, $N.' WHERE ID=3625;
UPDATE quest_offer_reward SET RewardText='Csataedzettnek tűnsz, $N. Készen állsz szembenézni Razelikh-el és szolgáival?' WHERE ID=3626;
UPDATE quest_offer_reward SET RewardText='Razelikh the Defiler amulettje ismét teljes, de érzi a zavart a parancsláncában. Tudja, hogy érte jössz...' WHERE ID=3627;
UPDATE quest_offer_reward SET RewardText='Ez a nap örökre emlékezetes marad. A Blasted Lands démoni uralkodója végre elbukott!' WHERE ID=3628;
UPDATE quest_offer_reward SET RewardText='Nos, $N, bölcsen tetted, hogy a tanítványom kerestél! Bárki lehet szakértő a mérnöki alapokban - a gnómok és sugárfertőzött otthonuk, Gnomeregan, bizonyítja ezt. De erős elme és biztos kéz kell (hangsúlyozom: BIZTOS) a Goblin Mérnökség elsajátításához.$B$BTartsd nyitva a füled, $N, és talán tanulsz valamit.' WHERE ID=3629;
UPDATE quest_offer_reward SET RewardText='Ah, egy fiatal mérnök, aki érdeklődik az egyetlen igazi mérnöki tudomány iránt! Bocsásd meg a melodrámámat, barátom. Bár helyzetünk továbbra is válságos, mindig jó nap az, amikor egy újabb mérnök válaszol az igazi mérnökség hívó szavára!' WHERE ID=3630;
UPDATE quest_offer_reward SET RewardText='Sok szerencsét, $N. Várom, hogy a jövőben újra találkozzunk.' WHERE ID=3631;
UPDATE quest_offer_reward SET RewardText='Ah, egy fiatal mérnök, aki érdeklődik az egyetlen igazi mérnöki tudomány iránt! Bocsásd meg a melodrámámat, barátom. Bár helyzetünk továbbra is válságos, mindig jó nap az, amikor egy újabb mérnök válaszol az igazi mérnökség hívó szavára!' WHERE ID=3632;
UPDATE quest_offer_reward SET RewardText='Nos, $N, bölcsen tetted, hogy a tanítványom kerestél! Bárki lehet szakértő a mérnöki alapokban - a gnómok és sugárfertőzött otthonuk, Gnomeregan, bizonyítja ezt. De erős elme és biztos kéz kell (hangsúlyozom: BIZTOS) a Goblin Mérnökség elsajátításához.$B$BTartsd nyitva a füled, $N, és talán tanulsz valamit.' WHERE ID=3633;
UPDATE quest_offer_reward SET RewardText='Ah, egy fiatal mérnök, aki érdeklődik az egyetlen igazi mérnöki tudomány iránt! Bocsásd meg a melodrámámat, barátom. Bár helyzetünk továbbra is válságos, mindig jó nap az, amikor egy újabb mérnök válaszol az igazi mérnökség hívó szavára!' WHERE ID=3634;
UPDATE quest_offer_reward SET RewardText='Azért jöttél, hogy megtanuld a gnóm mérnökséget, mi? Nos, a megfelelő gnómhoz jöttél. Bár Gnomeregan uralkodó frakciója politikát használhat, hogy kirekessze azokat, akiket értelmi fenyegetésnek tekintenek, tudják, hogy a tudást nem tudják irányítani.$B$BŐk is, én is tudjuk, hogy amikor elhagytam Gnomeregant, elvesztették az egyik legnagyobb élő gnóm mérnöküket. Ha képes tanuló vagy, megtanítalak arra, amit tudok.' WHERE ID=3635;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N. A Csapás most kétszer is meggondolja majd, mielőtt újra erősíteni próbálja sorait.$B$BÁldjon meg a Fény.' WHERE ID=3636;
UPDATE quest_offer_reward SET RewardText='Azért jöttél, hogy megtanuld a gnóm mérnökséget, mi? Nos, a megfelelő gnómhoz jöttél. Bár Gnomeregan uralkodó frakciója politikát használhat, hogy kirekessze azokat, akiket értelmi fenyegetésnek tekintenek, tudják, hogy a tudást nem tudják irányítani.$B$BŐk is, én is tudjuk, hogy amikor elhagytam Gnomeregant, elvesztették az egyik legnagyobb élő gnóm mérnöküket. Ha képes tanuló vagy, megtanítalak arra, amit tudok.' WHERE ID=3637;
UPDATE quest_offer_reward SET RewardText='Üdvözöllek a fedélzeten, $N, Goblin Mérnök! Hamarosan hozzáférsz Azeroth legerősebb mérnöki tervrajzaihoz.$b$bMost hogy elköteleződtél e tudás keresése mellett, itt az ideje megvizsgálni a goblin-orientált mérnöki munkádat. Innentől segítünk felépíteni egy tervet, hogy maximalizáld goblin mérnöki tehetségedet!' WHERE ID=3638;
UPDATE quest_offer_reward SET RewardText='Íme az első Goblin Mérnök Tagsági Kártyád!$b$bEz a kártya tizennégy napra előre kifizetve; minden kártya két hét aktivitás után lejár. Amikor lejár, fizesd be a következő tagdíjat bármelyik goblin mérnök oktatónál, hogy új kártyát kapj; kártya nélkül a tagságod átmenetileg megszűnik, és nem férsz hozzá új tervrajzokhoz.$b$bEz sosem érinti azt, amit már tudsz; aki egyszer goblin mérnök, az mindig az marad.' WHERE ID=3639;
UPDATE quest_offer_reward SET RewardText='Üdvözöllek a fedélzeten, $N! Hamarosan hozzáférsz Azeroth legfejlettebb mérnöki tervrajzaihoz.$B$BMost hogy elköteleződtél e tudás keresése mellett, itt az ideje megvizsgálni a gnóm-orientált mérnöki munkádat. Innentől segítünk felépíteni egy tervet, hogy maximalizáld gnóm mérnöki tehetségedet!' WHERE ID=3640;
UPDATE quest_offer_reward SET RewardText='Íme az első Gnóm Mérnök Tagsági Kártyád!$B$BEz a kártya tizennégy napra előre kifizetve; minden kártya két hét aktivitás után lejár. Amikor lejár, fizesd be a következő tagdíjat bármelyik gnóm mérnök oktatónál, hogy új kártyát kapj; kártya nélkül a tagságod átmenetileg megszűnik, és nem férsz hozzá új tervrajzokhoz.$B$BEz sosem érinti azt, amit már tudsz; aki egyszer gnóm mérnök, az mindig az marad.' WHERE ID=3641;
