UPDATE quest_offer_reward SET RewardText='Nos, $c... mivel tájékoztattak, hogy én magam vezetem ezt a kutatást, nyilvánvalóan olyan gyorsan jöttél, amilyen gyorsan csak tudtál.$B$BMost hogy itt vagy, figyelj alaposan, amikor elmondom a részleteket; nincs kedvem megismételni magam.' WHERE ID=3789;
UPDATE quest_offer_reward SET RewardText='Nos, $c... mivel tájékoztattak, hogy én magam vezetem ezt a kutatást, nyilvánvalóan olyan gyorsan jöttél, amilyen gyorsan csak tudtál.$B$BMost hogy itt vagy, figyelj alaposan, amikor elmondom a részleteket; nincs kedvem megismételni magam.' WHERE ID=3790;
UPDATE quest_offer_reward SET RewardText='Gah, ezek a morrowgrainek furán... éreztetnek magam. Elune nevében, mit forral Staghelm ezekkel a dolgokkal?$B$BMindenesetre, még egyszer köszönöm a segítséged. Itt egy kis valami... tudod, a fáradozásért. A morrowgrainnel kapcsolatos kutatásom eltart még egy ideig, és kétségtelenül több kell majd. Amíg csinálom, gondolom, ráérek megnézni, van-e valamilyen alkimiai felhasználásuk. Mégis kényelmetlenül érzem magam, ha csak a közelükben vagyok is.' WHERE ID=3791;
UPDATE quest_offer_reward SET RewardText='Köszönöm, $N; egyelőre csak félreteszem ezeket. Bár nem rendelkezem olyan erőforrásokkal, mint Staghelm, tudok adni neked valami keveset a fáradozásodért. Mindenesetre ki tudja, mi történik, ha Staghelm folyamatosan Morrowgraint kap Morrowgrain után. Valami bűzlik itt, jegyezd meg a szavaimat.$B$BNe feledd, mindig keresek több Morrowgraint. Ötös adagokban veszem át.' WHERE ID=3792;
UPDATE quest_offer_reward SET RewardText='Akár a mohóság hozott ide, akár egy önzetlen odaadás tette, amire készülsz, mindannyiunk javát szolgálja.' WHERE ID=3801;
UPDATE quest_offer_reward SET RewardText='A kalapács szilárdan a helyére csúszik, a hatalmas Dark Iron emlékmű markában. Egy apró rekesz nyílik a szobor talapzatánál. Odabent találsz...' WHERE ID=3802;
UPDATE quest_offer_reward SET RewardText='Kitűnő - ez a morrowgrain kétségtelenül tetszeni fog az Arch Druidnak. Be kell vallanom viszont... már a közelükben lenni is kissé kényelmetlenné tesz. Csak elképzelni tudom, mennyire nehéz lehet az Arch Druidnak elviselni őket ilyen nagy mennyiségben!$B$BEz a tiéd, $N. A Cenarion Circle köszöni a folyamatos támogatásodat.' WHERE ID=3803;
UPDATE quest_offer_reward SET RewardText='Kitűnő - ez a morrowgrain kétségtelenül segít majd, amikor eljön az ideje. Tudjuk, hogy az éjszaka tündérei hasonló kutatást folytatnak ezekkel a gyógynövényekkel kapcsolatban, bár nem világos, milyen célra használnák fel, ha bármit is felfedeznének. Az Arch Druid úgy véli, a morrowgrain iránti igényünk fennmarad, amíg meg nem fejtjük a gyógynövény mögötti rejtélyeket.$B$BEz a tiéd, $N. A Cenarion Circle köszöni a folyamatos támogatásodat.' WHERE ID=3804;
UPDATE quest_offer_reward SET RewardText='Szegény Thal''trakom.$B$BArra készültünk, hogy a szüleimhez költözünk a Hinterlandsbe, miután befejeztük a szolgálatunkat. Most ezek a tervek romba dőltek!' WHERE ID=3821;
UPDATE quest_offer_reward SET RewardText='<Thal''trak összeomlik.>$B$BA Hinterlandsbe készültünk költözni. Mondta neked? Ez lett volna az utolsó küldetése.$B$B<Thal''trak zokog.>$B$BNem akarom, $N. Tartsd meg, dobd el, nem érdekel! A gyűrű most már semmit sem jelent nekem. Nélküle nem...' WHERE ID=3822;
UPDATE quest_offer_reward SET RewardText='Kiváló, katona! Az orkok és ogrék percekig, talán órákig is szédelegni fognak ettől a csapástól!' WHERE ID=3823;
UPDATE quest_offer_reward SET RewardText='Csak nézd meg, katona. Undorító! Amikor a megmaradt Firegut ogrék meglátják ezt a kövér pofát karóra tűzve a hegyük tetején, tömeges hisztéria fog kitörni!$B$B<Oralius vadul kacag.>' WHERE ID=3824;
UPDATE quest_offer_reward SET RewardText='Kiváló munka, katona! Egyszerűen elképesztő! Ó, én kapom majd a bátorsági érdemrendet ezért, öö, úgy értem, te leszel bőségesen megjutalmazva ezért!' WHERE ID=3825;
UPDATE quest_offer_reward SET RewardText='Ah, egy tündérsárkány-tojás, és ha nem tévedek, majdnem érésben van. Figyelemre méltó, hogy találtál egyet, hát még ilyen jó állapotban. Mostanában ritkán látni őket Feralasban. Tudomásom szerint különféle vadorzók járnak a környéken, akik sok okból próbálják elfogni és megölni őket. Igazán kár... milyen gyönyörű lények, ha elérik a felnőttkort.$B$BHogyan bukkantál ilyen leletre?' WHERE ID=3841;
UPDATE quest_offer_reward SET RewardText='Csodálatos. Ezek pont jók lesznek. Adj egy pillanatot, hogy összekeverjem az alapanyagaimat, és meglátjuk, hogy boldogul majd ez a tojás.' WHERE ID=3842;
UPDATE quest_offer_reward SET RewardText='Nocsak, nocsak, nocsak... egy sárkány életkora óta nem láttam ilyet. Tündérsárkány, ha nem tévedek... úgy tűnik, sprite darter fajtájú. Kitűnő, valóban kitűnő.$B$BNos, ha ez a kis fickó ki fog kelni, és erős, egészséges felnőtté válik, akkor szereznünk kell neki némi táplálékot. Jó, hogy időben idehoztad.' WHERE ID=3843;
UPDATE quest_offer_reward SET RewardText='Egy átázott csomag hever a tó fenekén.' WHERE ID=3844;
UPDATE quest_offer_reward SET RewardText='Ó... Igen, ezek a dolgok tényleg ismerősnek tűnnek... hát, valahogy...' WHERE ID=3845;
UPDATE quest_offer_reward SET RewardText='„KOTKODÁCS!!!”$B$BA csirke elkezdi felfalni az eledelt, amit leraktál.$B$BEgy pillanat múlva a csirke ijedten körülnéz. Kényelmetlenül ide-oda csoszog. Vajon vemhes ez a csirke? Úgy gondolod, jobb, ha megnézed alatta.' WHERE ID=3861;
UPDATE quest_offer_reward SET RewardText='Visszaszerezted az élelmiszerkészletünket ÉS a kutatási felszerelésünket is! Nemcsak az expedíciót mentetted meg, hanem az életünket is. A csapatom többi tagjával együtt nem tudunk eléggé köszönetet mondani; most talán egy ideig kihúzzuk itt neked köszönhetően.$B$BBár nincs sok mindenünk, biztosan nem hagylak cserben azért a felbecsülhetetlen segítségért, amit adtál nekünk. Köszönöm, $N - barátod van a Marshal Expeditionsnál!\\n' WHERE ID=3881;
UPDATE quest_offer_reward SET RewardText='Kitűnő, ezek megteszik. És most, ha megengeded...$B$BKÖSZÖNJÜK, HOGY KIÁSTAD NEKÜNK EZEKET A CSONTOKAT A FÖLDBŐL, ÉS EGYÁLTALÁN NEM BÁNTOTTAD A HELYI VADÁLLATOKAT.$B$BHogy tényleg így volt-e vagy sem, nem akarom tudni. Maradjunk is ennyiben, jó? Tessék - talán ez segít befogni a szád az egész ügyben. Bármit, hogy élve kijussunk innen, mondom én!' WHERE ID=3882;
UPDATE quest_offer_reward SET RewardText='Igen, ez pont jó lesz. Nagy segítség voltál... bárcsak adhatnék többet ennél, de mivel gyakorlatilag megrekedtem egy vad föld közepén, ez korlátozza, mit tudok és mit nem tudok adni. Nyugodj meg viszont - az itt végzett kutatás nem lett volna lehetséges a segítséged nélkül!' WHERE ID=3883;
UPDATE quest_offer_reward SET RewardText='Nézd csak - a naplóm! Azt hittem, elveszett, ahogy szinte minden más is, amit Un''Goróba hoztunk. Szívből köszönöm, hogy visszahoztad nekem!' WHERE ID=3884;
UPDATE quest_offer_reward SET RewardText='Végeztem veled, $N - bebizonyítottad, hogy méltó vagy a szabadságra, amit kaptál. Sokan fognak ellened fordulni azért, amivé váltál, de tudd, bármit is próbálnak tenni ellenünk, szabadok vagyunk, és nem láncolnak meg minket újra.$b$bFogd ezeket, és indulj utadra. Sok mindent kell még elérned, $c.' WHERE ID=3901;
UPDATE quest_offer_reward SET RewardText='Remek munka, $N, tudtam, hogy nem vagy haszontalan. Tessék - fogd az egyik jobb tárgyat, amit az eddig összegyűjtött darabok közül találtam.' WHERE ID=3902;
UPDATE quest_offer_reward SET RewardText='Ó, Deputy Willem mondta, hogy beszélj velem? Bátor ember, és mindig kész segíteni, de a kötelességei a Northshire Abbeyhez kötik, és attól tartok, a mai problémám túlmutat rajta.$b$bTalán te tudsz segíteni nekem?' WHERE ID=3903;
UPDATE quest_offer_reward SET RewardText='Ó, köszönöm, $N! Megmentetted a termésemet! És remélem, megmutattad néhány Defias-tagnak, hogy nem okozhatnak itt bajt.$b$bLehet, hogy mostanában kevés az őrünk, de szerencsénk van, hogy hozzád hasonló hősök védenek minket!' WHERE ID=3904;
UPDATE quest_offer_reward SET RewardText='Lássuk csak...$b$bTe jó ég! Milly szőlője megmentve! Amikor elmondta, hogy rablók lepték el a szőlőit, majdnem kétségbeestem, de a Fénybe vetett hitem nem ingott meg!$b$bÉs a bátorságodnak köszönhetően most van szőlőnk további borhoz! Áldjon meg a Fény, $N, és tartson biztonságban!' WHERE ID=3905;
UPDATE quest_offer_reward SET RewardText='Ez nem lehet... nem szabad, hogy így legyen. Pyron elpusztítása csak fellebbentette a fátylat. Blackrock mélyén sokkal alattomosabb romlásforrás rejlik.' WHERE ID=3906;
UPDATE quest_offer_reward SET RewardText='<Thunderheart megragadja Kurniya Tábláját.>$b$bRagnaros... itt...$b$bAz öregek igazuk volt, amikor féltek a Blackrock Mountainből áradó romlástól. A Régi Istenek egy tábornoka! A MI VILÁGUNKBAN! Újra kell értékelnünk a helyzetünket itt, Kargathban. El kell döntenünk, maradunk-e és harcolunk, vagy elmenekülünk egy újabb szakadástól tartva.$b$bLégy óvatos minden további felfedezéssel a Blackrock Mountainben, $N. Sokkal nagyobb gonoszság lakozik azokban a tüzes mélységekben, mint bármi más, ami ebben a világban létezik.' WHERE ID=3907;
UPDATE quest_offer_reward SET RewardText='Nos, természetesen meg tudom edzeni ezt a kardot. Amíg dolgozom, elmagyarázhatod, mi tartotta ilyen sokáig Linkent, mire elhozta ezt nekem. Általában nem szokott elfelejteni dolgokat...' WHERE ID=3908;
UPDATE quest_offer_reward SET RewardText='Kell egy fiola, hogy megbizonyosodjak róla, hogy ez tényleg az az elixír... Igen... Ez az.' WHERE ID=3909;
UPDATE quest_offer_reward SET RewardText='Csodálatos! Azonnal elküldetem ezeket futárral az Undercitybe!$B$BAmi téged illet - itt a fizetség, ahogy ígértem. Tartsd meg az aprót, te mocskos fenevad!' WHERE ID=3911;
UPDATE quest_offer_reward SET RewardText='Régóta nem jött hozzám senki beszélgetni...' WHERE ID=3912;
UPDATE quest_offer_reward SET RewardText='Határozottan megnyomod a követ, és az elcsúszik, felfedve egy kis mélyedést alatta.$B$BLinken Kardját a mélyedésbe helyezve rájössz, hogy tökéletesen illik...' WHERE ID=3913;
UPDATE quest_offer_reward SET RewardText='A kardom... Elkészült!$b$bMost, ha csak emlékeznék, miért is volt szükségem erre...$b$bTessék, hadd fizessek legalább a munkádért.' WHERE ID=3914;
UPDATE quest_offer_reward SET RewardText='Ó, ez meg mi? Egy samophlange, mondod? Mi az a samophlange??$B$BAh... de nézd, hogyan mozog, amikor megfogod. És hallani belül a bonyolult fogaskerekek hangját. Te jó ég! Meg akarom javítani, és látni, mit csinál, te nem??' WHERE ID=3921;
UPDATE quest_offer_reward SET RewardText='Remek, megszerezted őket! Most munkához láthatok...' WHERE ID=3922;
UPDATE quest_offer_reward SET RewardText='Ez meg mi? Hiszen ez egy samophlange! Honnan szerezted ezt a dolgot? A Venture Company birtokai körül szaglásztál a Barrensben?$B$BVagy nagyon bátor lehetsz, vagy nagyon ostoba.' WHERE ID=3923;
UPDATE quest_offer_reward SET RewardText='Megszerezted a kézikönyvet! Alig várom, hogy elolvassam, és kiderítsem, hogyan javítsam meg a Samophlange-ot! Beszéltem Sputtervalve-vel Ratchetben - meg akarta köszönni a segítséged, és jutalmazni akarta a fáradozásod.$B$BÉn is köszönetet akarok mondani, és ha valaha megjavítom ezt a dolgot, tudatni fogom veled...' WHERE ID=3924;
UPDATE quest_offer_reward SET RewardText='Maradj, ahol vagy, egy pillanatra... egy új kristálykombinációt tesztelek...' WHERE ID=3941;
